-- Reference-length revision: insert new versions; never rewrite old papers or attempts.
begin;
create table academy_tcf_reading.published_papers(test_id text primary key,version text not null,foreign key(test_id,version) references academy_tcf_reading.papers(id,version));
alter table academy_tcf_reading.published_papers enable row level security;
revoke all on academy_tcf_reading.published_papers from public,anon,authenticated,service_role;
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-02','tcf-reading-2026-11-reference-v3',$paper${"id":"tcf-reading-02","version":"tcf-reading-2026-11-reference-v3","title":"TCF Reading · Test 02","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"Avis aux locataires : la cour sera nettoyée mercredi matin. Merci de retirer vos vélos mardi soir. Le local à vélos restera accessible.\n\nLes objets oubliés seront placés sous l'abri. L'entreprise doit pouvoir circuler librement avec son matériel de lavage.","question":"Que faut-il faire mardi soir ?","options":["Nettoyer les escaliers","Retirer les vélos de la cour","Fermer le local à vélos","Rapporter les clés"],"correct":"B","explanation":"Le passage indique : « Avis aux locataires : la cour sera nettoyée mercredi matin. Merci de retirer vos vélos mardi soir. Le local à vélos restera accessible. » Cela justifie la réponse : Retirer les vélos de la cour."},{"number":2,"points":3,"passage":"Le gardien sera absent vendredi. Pour une fuite urgente, appelez le numéro affiché dans le hall ; les demandes ordinaires attendront lundi.\n\nUn message vocal précisera la nature du problème.","question":"Quand faut-il appeler le numéro affiché ?","options":["En cas de fuite urgente","Pour changer de boîte aux lettres","Pour réserver une visite","Pour payer le loyer"],"correct":"A","explanation":"Le passage indique : « Le gardien sera absent vendredi. Pour une fuite urgente, appelez le numéro affiché dans le hall ; les demandes ordinaires attendront lundi. » Cela justifie la réponse : En cas de fuite urgente."},{"number":3,"points":3,"passage":"La permanence logement change d'adresse : dès lundi, les rendez-vous auront lieu au 8, rue des Tilleuls. Les horaires restent identiques.\n\nL'ancienne adresse accueillera des travaux. Les dossiers déjà ouverts seront transférés automatiquement, sans nouvelle inscription des habitants concernés.","question":"Qu'est-ce qui change ?","options":["Le lieu des rendez-vous","Le prix du service","Les pièces à fournir","Les jours d'ouverture"],"correct":"A","explanation":"Le passage indique : « La permanence logement change d'adresse : dès lundi, les rendez-vous auront lieu au 8, rue des Tilleuls. Les horaires restent identiques. » Cela justifie la réponse : Le lieu des rendez-vous."},{"number":4,"points":3,"passage":"Le jardin de la résidence ferme à vingt heures cet été. Les habitants peuvent y déjeuner, mais les barbecues sont interdits.\n\nCette règle s'applique aussi aux invités. Le portail sera fermé chaque soir par le responsable de permanence, après vérification des lieux.","question":"Quelle activité est autorisée ?","options":["Entrer après vingt heures","Allumer un barbecue","Organiser un feu de bois","Prendre son déjeuner au jardin"],"correct":"D","explanation":"Le passage indique : « Le jardin de la résidence ferme à vingt heures cet été. Les habitants peuvent y déjeuner, mais les barbecues sont interdits. » Cela justifie la réponse : Prendre son déjeuner au jardin."},{"number":5,"points":9,"passage":"Salut Nora, j'ai trouvé une chambre moins chère, mais elle est loin de mon travail. Je préfère encore chercher près du tram, même si je dois payer un peu plus.\n\nUne collègue m'a parlé d'un immeuble bien situé où une chambre se libère bientôt.","question":"Quel critère Nora doit-elle comprendre comme prioritaire ?","options":["La taille de la chambre","La présence d'un balcon","Le prix le plus bas possible","La facilité des trajets"],"correct":"D","explanation":"Le passage indique : « Salut Nora, j'ai trouvé une chambre moins chère, mais elle est loin de mon travail. Je préfère encore chercher près du tram, même si je dois payer un peu plus. » Cela justifie la réponse : La facilité des trajets."},{"number":6,"points":9,"passage":"Chers voisins, notre installation samedi risque d'être bruyante entre neuf heures et midi. Nous laisserons l'ascenseur libre en dehors des déplacements de meubles. Merci de votre patience.\n\nLe camion restera devant notre entrée pendant le déchargement.","question":"Pourquoi ce message est-il envoyé ?","options":["Annoncer une panne durable","Demander un changement d'étage","Prévenir d'une gêne temporaire","Interdire l'usage de l'ascenseur"],"correct":"C","explanation":"Le passage indique : « Chers voisins, notre installation samedi risque d'être bruyante entre neuf heures et midi. Nous laisserons l'ascenseur libre en dehors des déplacements de meubles. Merci de votre patience. » Cela justifie la réponse : Prévenir d'une gêne temporaire."},{"number":7,"points":9,"passage":"Je te rends les clés dimanche après avoir relevé le compteur. Le propriétaire accepte que nous fassions l'état des lieux par vidéo, car il est en déplacement.\n\nJe filmerai chaque pièce et lui transmettrai les photographies des relevés. Il vérifiera ensuite le document avant que nous le signions ensemble.","question":"Comment le propriétaire participera-t-il ?","options":["À distance","Par courrier uniquement","En venant dimanche soir","En passant chez un voisin"],"correct":"A","explanation":"Le passage indique : « Je te rends les clés dimanche après avoir relevé le compteur. Le propriétaire accepte que nous fassions l'état des lieux par vidéo, car il est en déplacement. » Cela justifie la réponse : À distance."},{"number":8,"points":9,"passage":"L'association propose un atelier pour comprendre un bail. Apportez une copie sans vos coordonnées personnelles. Les animateurs expliqueront les clauses ; ils ne chercheront pas de logement à votre place.\n\nDeux séances sont proposées samedi pour les personnes qui travaillent en semaine.","question":"Quel service est proposé ?","options":["Collecter les coordonnées des participants","Aider à comprendre un contrat","Signer un bail pour le locataire","Trouver un appartement garanti"],"correct":"B","explanation":"Le passage indique : « L'association propose un atelier pour comprendre un bail. Apportez une copie sans vos coordonnées personnelles. Les animateurs expliqueront les clauses ; ils ne chercheront pas de logement à votre place. » Cela justifie la réponse : Aider à comprendre un contrat."},{"number":9,"points":9,"passage":"Annonce : chambre meublée chez une retraitée, contre une présence deux soirs par semaine. Il ne s'agit pas d'un emploi d'aide à domicile. Les tâches médicales sont exclues.\n\nUne rencontre préalable permettra de discuter des habitudes de chacun.","question":"Quelle obligation accompagne l'hébergement ?","options":["Verser un salaire à l'hôte","Assurer des soins quotidiens","Être présent certains soirs","Travailler toutes les nuits"],"correct":"C","explanation":"Le passage indique : « Annonce : chambre meublée chez une retraitée, contre une présence deux soirs par semaine. Il ne s'agit pas d'un emploi d'aide à domicile. Les tâches médicales sont exclues. » Cela justifie la réponse : Être présent certains soirs."},{"number":10,"points":9,"passage":"Nous avons avancé la réunion de copropriété à dix-huit heures pour permettre aux parents d'y assister avant la sortie des activités des enfants. L'ordre du jour reste inchangé.\n\nLes documents seront envoyés auparavant pour que chacun puisse les lire.","question":"Pourquoi l'horaire a-t-il été modifié ?","options":["Faciliter la participation des parents","Terminer des travaux urgents","Réduire le nombre de participants","Ajouter un vote supplémentaire"],"correct":"A","explanation":"Le passage indique : « Nous avons avancé la réunion de copropriété à dix-huit heures pour permettre aux parents d'y assister avant la sortie des activités des enfants. L'ordre du jour reste inchangé. » Cela justifie la réponse : Faciliter la participation des parents."},{"number":11,"points":15,"passage":"Dans cet immeuble, une buanderie commune remplace les machines individuelles. Chaque foyer réserve un créneau. Les appareils sont mieux utilisés, mais les retards créent parfois des tensions entre voisins.\n\nLe conseil a donc installé un tableau rappelant les heures de début et de fin. Les habitants peuvent échanger leur réservation s'ils préviennent la personne suivante. Une réunion permettra de discuter des incidents après un mois d'essai. Plusieurs familles apprécient déjà de ne plus devoir entretenir une grosse machine dans leur appartement. La réussite du service dépend cependant des petites attentions de chacun, notamment du nettoyage après utilisation.","question":"Quelle difficulté est signalée ?","options":["L'interdiction de laver chez soi","L'absence totale de réservation","La consommation excessive de papier","Le non-respect des créneaux"],"correct":"D","explanation":"Le passage indique : « Dans cet immeuble, une buanderie commune remplace les machines individuelles. Chaque foyer réserve un créneau. Les appareils sont mieux utilisés, mais les retards créent parfois des tensions entre voisins. » Cela justifie la réponse : Le non-respect des créneaux."},{"number":12,"points":15,"passage":"La mairie prête des outils aux résidents après une courte démonstration. Les bénévoles ne réalisent pas les travaux : ils montrent comment utiliser le matériel en sécurité. Les emprunteurs rapportent les outils propres.\n\nUne carte d'adhésion permet d'emprunter jusqu'à trois outils pour une semaine. Les appareils les plus délicats ne sont remis qu'après vérification des consignes. L'association a choisi de demander une participation annuelle modeste plutôt que de facturer chaque prêt.","question":"Quel est le rôle des bénévoles ?","options":["Vérifier les déclarations fiscales","Vendre les outils aux habitants","Expliquer l'utilisation du matériel","Rénover gratuitement les logements"],"correct":"C","explanation":"Le passage indique : « La mairie prête des outils aux résidents après une courte démonstration. Les bénévoles ne réalisent pas les travaux : ils montrent comment utiliser le matériel en sécurité. Les emprunteurs rapportent les outils propres. » Cela justifie la réponse : Expliquer l'utilisation du matériel."},{"number":13,"points":15,"passage":"Un ancien hôtel devient une résidence étudiante. Les chambres sont petites, mais chaque étage dispose d'une cuisine et d'un salon. La transformation conserve la structure du bâtiment au lieu de le démolir.\n\nLes architectes ont aussi gardé le grand escalier et créé des rangements individuels. Une association étudiante animera quelques soirées pendant les premiers mois, sans rendre la présence obligatoire. Les futurs locataires pourront visiter un étage témoin avant de déposer leur dossier. La ville espère ainsi proposer des chambres moins coûteuses tout en limitant la consommation de nouveaux matériaux.","question":"Quel choix guide le projet ?","options":["Réserver l'hôtel aux touristes","Construire des maisons séparées","Réutiliser un bâtiment existant","Supprimer les espaces communs"],"correct":"C","explanation":"Le passage indique : « Un ancien hôtel devient une résidence étudiante. Les chambres sont petites, mais chaque étage dispose d'une cuisine et d'un salon. La transformation conserve la structure du bâtiment au lieu de le démolir. » Cela justifie la réponse : Réutiliser un bâtiment existant."},{"number":14,"points":15,"passage":"Sarah a emménagé sans voiture. Elle a choisi un appartement près de la gare, puis vendu plusieurs meubles trop grands. Elle constate qu'un logement plus petit lui demande moins d'entretien.\n\nElle a d'abord craint de manquer de place pour recevoir ses proches. Elle a finalement choisi une table pliante et utilise une chambre d'amis partagée dans la résidence lorsque sa famille reste dormir. Son budget de transport a également diminué. Elle ne présente pas son choix comme une solution convenant à tout le monde, mais comme un équilibre adapté à sa situation actuelle.","question":"Quel avantage Sarah découvre-t-elle ?","options":["Une pièce supplémentaire","Des meubles plus volumineux","Un garage gratuit","Un entretien moins important"],"correct":"D","explanation":"Le passage indique : « Sarah a emménagé sans voiture. Elle a choisi un appartement près de la gare, puis vendu plusieurs meubles trop grands. Elle constate qu'un logement plus petit lui demande moins d'entretien. » Cela justifie la réponse : Un entretien moins important."},{"number":15,"points":15,"passage":"Le comité de quartier organise une marche avec les nouveaux habitants. Les participants repèrent ensemble les commerces, les arrêts de bus et les services publics. Aucun circuit touristique payant n'est prévu.\n\nLes départs se font depuis le centre social et les circuits restent assez courts. Un bénévole répond aux questions pratiques, tandis que des commerçants présentent leurs services habituels. Les participants reçoivent une petite carte sur laquelle ils peuvent ajouter leurs propres repères. Le comité veut faciliter les premiers échanges entre voisins, sans demander aux nouveaux arrivants de connaître déjà quelqu'un.","question":"À quoi sert cette marche ?","options":["Collecter une taxe locale","Visiter seulement des monuments","Découvrir les services du quotidien","Vendre des abonnements touristiques"],"correct":"C","explanation":"Le passage indique : « Le comité de quartier organise une marche avec les nouveaux habitants. Les participants repèrent ensemble les commerces, les arrêts de bus et les services publics. Aucun circuit touristique payant n'est prévu. » Cela justifie la réponse : Découvrir les services du quotidien."},{"number":16,"points":15,"passage":"Une agence met en ligne les dépenses de chauffage des logements proposés. Les chiffres correspondent à une occupation habituelle ; ils ne garantissent pas une facture identique pour chaque locataire.\n\nLa température choisie, les absences et le nombre d'occupants modifient les besoins. Un logement montré vide peut aussi avoir été chauffé différemment. L'agence précise donc la période mesurée et la méthode utilisée. Les visiteurs sont invités à poser des questions sur l'isolation, plutôt qu'à retenir le seul montant affiché en tête de l'annonce.","question":"Comment faut-il interpréter ces chiffres ?","options":["Comme une indication dépendant de l'usage","Comme un prix fixe garanti","Comme le montant du dépôt","Comme une consommation toujours nulle"],"correct":"A","explanation":"Le passage indique : « Une agence met en ligne les dépenses de chauffage des logements proposés. Les chiffres correspondent à une occupation habituelle ; ils ne garantissent pas une facture identique pour chaque locataire. » Cela justifie la réponse : Comme une indication dépendant de l'usage."},{"number":17,"points":15,"passage":"Lors des fortes chaleurs, la salle commune reste ouverte jusqu'à vingt-deux heures. Les résidents isolés peuvent s'y retrouver et boire de l'eau. L'accès ne nécessite pas de réservation.\n\nDes bénévoles passent proposer cet accueil aux personnes qui le souhaitent, sans les inscrire d'office. Une petite bibliothèque et des jeux sont disponibles, mais chacun peut simplement rester assis dans un lieu moins chaud. Le conseil des résidents évaluera le dispositif après l'été. Il regardera notamment si les horaires correspondent réellement aux besoins et si les personnes ayant du mal à marcher peuvent rejoindre facilement la salle commune.","question":"À qui cette mesure peut-elle particulièrement servir ?","options":["Aux propriétaires vendant leur logement","Aux résidents isolés pendant la chaleur","Aux touristes réservant une chambre","Aux automobilistes cherchant un parking"],"correct":"B","explanation":"Le passage indique : « Lors des fortes chaleurs, la salle commune reste ouverte jusqu'à vingt-deux heures. Les résidents isolés peuvent s'y retrouver et boire de l'eau. L'accès ne nécessite pas de réservation. » Cela justifie la réponse : Aux résidents isolés pendant la chaleur."},{"number":18,"points":15,"passage":"La fête des voisins aura lieu dans le hall si la pluie persiste. Les organisateurs ont renoncé à installer une tente, car elle bloquerait l'accès des secours dans la cour.\n\nLa fête se tiendra donc près de l'entrée, où les tables peuvent être déplacées rapidement. Les voisins sont invités à apporter des plats froids pour éviter un équipement de cuisson encombrant. Une équipe vérifiera que les portes restent dégagées. Les organisateurs préfèrent modifier quelques habitudes plutôt que renoncer à accueillir tout le monde, y compris les personnes utilisant un fauteuil ou une poussette.","question":"Pourquoi la tente a-t-elle été écartée ?","options":["Elle gênerait un passage de sécurité","Elle empêcherait toute musique","Elle coûterait plus que le repas","Elle manquerait de places assises"],"correct":"A","explanation":"Le passage indique : « La fête des voisins aura lieu dans le hall si la pluie persiste. Les organisateurs ont renoncé à installer une tente, car elle bloquerait l'accès des secours dans la cour. » Cela justifie la réponse : Elle gênerait un passage de sécurité."},{"number":19,"points":15,"passage":"Après plusieurs plaintes sur le bruit, les habitants ont choisi une médiatrice. Elle reçoit séparément les personnes concernées avant de proposer un échange commun. Elle ne peut pas imposer une amende.\n\nLa première séance permettra surtout de préciser les horaires et les situations qui provoquent les désaccords. Chaque voisin pourra expliquer ce qu'il entend depuis son appartement et proposer un arrangement réaliste. Un document commun ne sera rédigé que si les personnes l'acceptent.","question":"Quelle est sa mission ?","options":["Décider du montant des loyers","Remplacer le gardien de nuit","Faciliter un accord entre voisins","Sanctionner immédiatement les habitants"],"correct":"C","explanation":"Le passage indique : « Après plusieurs plaintes sur le bruit, les habitants ont choisi une médiatrice. Elle reçoit séparément les personnes concernées avant de proposer un échange commun. Elle ne peut pas imposer une amende. » Cela justifie la réponse : Faciliter un accord entre voisins."},{"number":20,"points":21,"passage":"Une coopérative d'habitation achète un terrain pour y construire des logements et une salle partagée. Les futurs habitants participeront aux décisions. Leur contribution financière ne leur donnera pas davantage de voix lors des assemblées. Les membres prépareront ensemble les règles d'utilisation des espaces partagés. Certaines dépenses seront mutualisées, mais chaque ménage conservera son logement privé. Des réunions ouvertes permettront aux nouveaux participants de comprendre le fonctionnement avant de confirmer leur engagement. Le groupe cherche une solution durable plutôt qu'un simple placement immobilier individuel. Les comptes seront présentés régulièrement à tous les membres du groupe.","question":"Quel principe est retenu ?","options":["La suppression des assemblées","Des votes proportionnels à la richesse","Une participation sans domination financière","La réservation des décisions aux investisseurs"],"correct":"C","explanation":"Le passage indique : « Une coopérative d'habitation achète un terrain pour y construire des logements et une salle partagée. Les futurs habitants participeront aux décisions. Leur contribution financière ne leur donnera pas davantage de voix lors des assemblées. » Cela justifie la réponse : Une participation sans domination financière."},{"number":21,"points":21,"passage":"Un quartier teste la livraison des courses à pied depuis ses commerces. Le service vise surtout les personnes qui se déplacent difficilement. Les commerçants restent responsables des commandes ; les livreurs ne choisissent pas les produits à la place des clients. Les personnes passent leur commande auprès de leur boutique habituelle et choisissent un horaire de réception. La commune prend en charge une partie du transport pendant l'expérimentation. Une permanence téléphonique est maintenue pour celles qui n'utilisent pas internet.","question":"Que permet principalement ce service ?","options":["Remplacer les achats par des dons","Faciliter l'accès aux commerces locaux","Décider des menus des clients","Fermer les boutiques de proximité"],"correct":"B","explanation":"Le passage indique : « Un quartier teste la livraison des courses à pied depuis ses commerces. Le service vise surtout les personnes qui se déplacent difficilement. Les commerçants restent responsables des commandes ; les livreurs ne choisissent pas les produits à la place des clients. » Cela justifie la réponse : Faciliter l'accès aux commerces locaux."},{"number":22,"points":21,"passage":"Dans une résidence rénovée, des capteurs signalent les fuites d'eau sans enregistrer les habitudes détaillées des occupants. Le conseil des locataires a demandé cette limitation avant d'accepter le dispositif. Les alertes sont envoyées au service technique. Le système indique seulement le secteur où une intervention semble nécessaire. Les données sont effacées après un délai annoncé. Le bailleur souhaite limiter les dégâts matériels tout en évitant qu'un outil d'entretien devienne un moyen de surveiller la vie domestique.","question":"Quelle préoccupation a influencé le dispositif ?","options":["La suppression de l'entretien","L'augmentation du débit d'eau","Le contrôle des visiteurs","La protection de la vie privée"],"correct":"D","explanation":"Le passage indique : « Dans une résidence rénovée, des capteurs signalent les fuites d'eau sans enregistrer les habitudes détaillées des occupants. Le conseil des locataires a demandé cette limitation avant d'accepter le dispositif. Les alertes sont envoyées au service technique. » Cela justifie la réponse : La protection de la vie privée."},{"number":23,"points":21,"passage":"Une commune réserve des appartements aux travailleurs saisonniers. Les locations touristiques avaient rendu leur recherche difficile. Les logements seront occupés l'hiver par des stagiaires, afin d'éviter qu'ils restent vides plusieurs mois. Les associations de commerçants ont soutenu le projet après avoir constaté plusieurs recrutements abandonnés faute de logement. La mairie ne promet pas une réponse à toutes les demandes : les places disponibles seront attribuées selon des critères publiés. Un bilan annuel précisera si l'alternance des publics correspond effectivement aux besoins recensés.","question":"Quelle logique suit la commune ?","options":["Adapter l'occupation à différents besoins annuels","Interdire toutes les locations touristiques","Fermer les appartements après l'été","Réserver les logements aux retraités"],"correct":"A","explanation":"Le passage indique : « Une commune réserve des appartements aux travailleurs saisonniers. Les locations touristiques avaient rendu leur recherche difficile. Les logements seront occupés l'hiver par des stagiaires, afin d'éviter qu'ils restent vides plusieurs mois. » Cela justifie la réponse : Adapter l'occupation à différents besoins annuels."},{"number":24,"points":21,"passage":"Un collectif transforme un parking inutilisé en place de quartier. Les habitants pourront déplacer les bancs avant l'aménagement définitif. La commune veut observer les usages plutôt que choisir immédiatement une configuration permanente. Les premiers essais auront lieu pendant plusieurs semaines, en dehors des grands événements. Les personnes âgées et les parents pourront notamment indiquer les zones trop bruyantes ou trop exposées. Les agents observeront aussi les passages nécessaires aux livraisons.","question":"Pourquoi les bancs seront-ils mobiles ?","options":["Pour tester plusieurs aménagements","Pour éviter toute observation","Pour les louer chaque soir","Pour empêcher les rencontres"],"correct":"A","explanation":"Le passage indique : « Un collectif transforme un parking inutilisé en place de quartier. Les habitants pourront déplacer les bancs avant l'aménagement définitif. La commune veut observer les usages plutôt que choisir immédiatement une configuration permanente. » Cela justifie la réponse : Pour tester plusieurs aménagements."},{"number":25,"points":21,"passage":"Un bailleur propose de remplacer certaines réunions par un questionnaire. Les locataires acceptent le questionnaire, mais demandent de conserver un échange oral pour les sujets complexes. Ils estiment qu'une case cochée n'explique pas toujours une difficulté. Les représentants soulignent aussi que certaines personnes ont besoin de faire préciser une question avant d'y répondre. Ils proposent donc un document court envoyé à l'avance, puis un échange collectif sur les points les plus discutés.","question":"Que souhaitent les locataires ?","options":["Combiner plusieurs formes de consultation","Interdire les réponses écrites","Supprimer toutes les réunions","Confier les décisions à un logiciel"],"correct":"A","explanation":"Le passage indique : « Un bailleur propose de remplacer certaines réunions par un questionnaire. Les locataires acceptent le questionnaire, mais demandent de conserver un échange oral pour les sujets complexes. Ils estiment qu'une case cochée n'explique pas toujours une difficulté. » Cela justifie la réponse : Combiner plusieurs formes de consultation."},{"number":26,"points":21,"passage":"La rénovation d'une rue inclut des arbres, mais leurs racines ne disposeront pas partout du même espace. Des habitants demandent de revoir le sous-sol avant la plantation. Ils craignent que des arbres mal installés dépérissent rapidement. Le service technique a accepté de présenter les emplacements des conduites et les volumes de terre disponibles. Plusieurs solutions seront comparées, dont le déplacement de quelques places de stationnement. Les riverains souhaitent éviter une succession de plantations coûteuses suivies de remplacements.","question":"Quelle priorité défendent-ils ?","options":["Remplacer tous les trottoirs par du gravier","Choisir uniquement des arbres artificiels","Planter davantage sans étude","Préparer des conditions durables de plantation"],"correct":"D","explanation":"Le passage indique : « La rénovation d'une rue inclut des arbres, mais leurs racines ne disposeront pas partout du même espace. Des habitants demandent de revoir le sous-sol avant la plantation. Ils craignent que des arbres mal installés dépérissent rapidement. » Cela justifie la réponse : Préparer des conditions durables de plantation."},{"number":27,"points":21,"passage":"Une résidence supprime les petites poubelles individuelles dans ses espaces communs. Les déchets sont triés à un point unique. Le volume collecté baisse, mais le conseil rappelle qu'un déplacement du problème vers la rue annulerait ce bénéfice. Des observations seront réalisées autour du point de collecte pour repérer ce déplacement éventuel. Les habitants recevront un rappel sur les emballages acceptés et sur les horaires.","question":"Quelle réserve accompagne le bilan ?","options":["Les habitants doivent acheter plus d'emballages","Les espaces communs doivent fermer","Les déchets ne doivent pas être abandonnés ailleurs","Le tri doit devenir payant"],"correct":"C","explanation":"Le passage indique : « Une résidence supprime les petites poubelles individuelles dans ses espaces communs. Les déchets sont triés à un point unique. Le volume collecté baisse, mais le conseil rappelle qu'un déplacement du problème vers la rue annulerait ce bénéfice. » Cela justifie la réponse : Les déchets ne doivent pas être abandonnés ailleurs."},{"number":28,"points":21,"passage":"Dans un quartier en pente, un service municipal accompagne les personnes âgées au marché. Les bénévoles portent les sacs, mais laissent les bénéficiaires choisir leurs achats et leur rythme. L'autonomie compte autant que l'aide matérielle. Avant la première sortie, le centre social demande quels commerces et quels jours conviennent à chaque personne. Les accompagnateurs peuvent aider à traverser ou à porter, mais ne gèrent pas le budget des courses.","question":"Quelle idée caractérise l'accompagnement ?","options":["Réserver le marché aux bénévoles","Aider sans décider à la place des personnes","Faire les courses sans rencontrer les bénéficiaires","Imposer un trajet unique et rapide"],"correct":"B","explanation":"Le passage indique : « Dans un quartier en pente, un service municipal accompagne les personnes âgées au marché. Les bénévoles portent les sacs, mais laissent les bénéficiaires choisir leurs achats et leur rythme. L'autonomie compte autant que l'aide matérielle. » Cela justifie la réponse : Aider sans décider à la place des personnes."},{"number":29,"points":21,"passage":"Une cour d'école devient accessible aux riverains le week-end. La convention prévoit un partage des frais de nettoyage. L'association de parents y voit une ouverture utile, à condition que les élèves retrouvent un lieu propre le lundi. Les premières ouvertures se feront sur un nombre limité de week-ends. Les riverains disposeront de poubelles supplémentaires et d'un numéro pour signaler un problème.","question":"Quelle condition les parents posent-ils ?","options":["Fermer l'école le lundi","Réserver la cour aux adultes","Préserver la qualité du lieu pour les élèves","Supprimer tous les frais d'entretien"],"correct":"C","explanation":"Le passage indique : « Une cour d'école devient accessible aux riverains le week-end. La convention prévoit un partage des frais de nettoyage. L'association de parents y voit une ouverture utile, à condition que les élèves retrouvent un lieu propre le lundi. » Cela justifie la réponse : Préserver la qualité du lieu pour les élèves."},{"number":30,"points":26,"passage":"On présente souvent les immeubles partagés comme une réponse automatique à la solitude. Pourtant, un salon commun ne crée pas à lui seul des relations. Dans une résidence récente, les rencontres ont commencé lorsque des habitants ont proposé des activités souples, auxquelles chacun pouvait refuser de participer. Ces activités n'étaient pas obligatoirement longues : partager un café ou arroser les plantes a parfois suffi à commencer une conversation. Le dispositif a fonctionné parce qu'il laissait une marge de choix aux personnes les plus réservées.","question":"Quelle idée l'auteur remet-il en cause ?","options":["L'utilité de toute activité collective","L'idée qu'un espace commun suffit à créer des liens","Le droit de refuser une invitation","La possibilité de vivre seul volontairement"],"correct":"B","explanation":"Le passage indique : « On présente souvent les immeubles partagés comme une réponse automatique à la solitude. Pourtant, un salon commun ne crée pas à lui seul des relations. Dans une résidence récente, les rencontres ont commencé lorsque des habitants ont proposé des activités souples, auxquelles chacun pouvait refuser de participer. » Cela justifie la réponse : L'idée qu'un espace commun suffit à créer des liens."},{"number":31,"points":26,"passage":"La ville mesure la réussite de ses rénovations par le nombre de façades refaites. Un urbaniste demande d'ajouter le confort d'été et les charges des occupants. Une façade plus belle peut masquer un appartement encore coûteux à chauffer. L'apparence ne suffit donc pas à apprécier les effets d'une intervention. Des entretiens avec les habitants pourraient compléter les relevés techniques.","question":"Quel changement d'évaluation propose-t-il ?","options":["Abandonner toute mesure de résultat","Intégrer les conditions réelles d'habitation","Compter uniquement les logements vendus","Évaluer la couleur des façades seulement"],"correct":"B","explanation":"Le passage indique : « La ville mesure la réussite de ses rénovations par le nombre de façades refaites. Un urbaniste demande d'ajouter le confort d'été et les charges des occupants. Une façade plus belle peut masquer un appartement encore coûteux à chauffer. L'apparence ne suffit donc pas à apprécier les effets d'une intervention. » Cela justifie la réponse : Intégrer les conditions réelles d'habitation."},{"number":32,"points":26,"passage":"Un café de quartier accueille les réunions associatives sans exiger de consommation. Cette ouverture attire des habitants qui ne fréquentaient pas le lieu. Pour financer les soirées, le gérant répartit les coûts entre location ponctuelle de salle et recettes habituelles. La gratuité pour les participants repose ainsi sur un équilibre économique précis. Le gérant examine régulièrement cet équilibre, car un événement réussi ne couvre pas nécessairement ses dépenses directes.","question":"Que comprend-on de cette gratuité ?","options":["Elle supprime les activités commerciales","Elle dépend d'autres sources de financement","Elle oblige chaque visiteur à commander","Elle signifie que le café n'a aucune dépense"],"correct":"B","explanation":"Le passage indique : « Un café de quartier accueille les réunions associatives sans exiger de consommation. Cette ouverture attire des habitants qui ne fréquentaient pas le lieu. Pour financer les soirées, le gérant répartit les coûts entre location ponctuelle de salle et recettes habituelles. La gratuité pour les participants repose ainsi sur un équilibre économique précis. » Cela justifie la réponse : Elle dépend d'autres sources de financement."},{"number":33,"points":26,"passage":"Les petites surfaces sont parfois vantées pour leur sobriété. Ce raisonnement oublie les activités déplacées hors du logement : laverie, stockage ou déplacements supplémentaires. Un logement compact peut être économe si le quartier fournit des services accessibles. Sans cette proximité, la réduction de surface ne garantit pas une réduction des dépenses. Il faut donc regarder où se trouvent les services et qui peut les utiliser.","question":"Quelle nuance le texte apporte-t-il ?","options":["La sobriété dépend aussi des services environnants","Une laverie remplace tous les services publics","Les grands logements sont toujours moins chers","La surface n'a aucun effet sur le quotidien"],"correct":"A","explanation":"Le passage indique : « Les petites surfaces sont parfois vantées pour leur sobriété. Ce raisonnement oublie les activités déplacées hors du logement : laverie, stockage ou déplacements supplémentaires. Un logement compact peut être économe si le quartier fournit des services accessibles. Sans cette proximité, la réduction de surface ne garantit pas une réduction des dépenses. » Cela justifie la réponse : La sobriété dépend aussi des services environnants."},{"number":34,"points":26,"passage":"Pour attribuer des jardins familiaux, une ville utilisait uniquement l'ancienneté de la demande. Elle réserve désormais quelques parcelles aux personnes sans espace extérieur et organise un renouvellement partiel. Cette modification rend l'accès moins prévisible pour les anciens inscrits, mais élargit les profils des bénéficiaires. Elle souhaite conserver une certaine stabilité pour les jardiniers déjà engagés, sans transformer une liste ancienne en droit permanent excluant toutes les nouvelles demandes.","question":"Quel arbitrage est décrit ?","options":["Supprimer l'accès aux personnes sans balcon","Attribuer tous les jardins au hasard chaque semaine","Favoriser exclusivement les premiers inscrits","Équilibrer continuité des demandes et ouverture à d'autres besoins"],"correct":"D","explanation":"Le passage indique : « Pour attribuer des jardins familiaux, une ville utilisait uniquement l'ancienneté de la demande. Elle réserve désormais quelques parcelles aux personnes sans espace extérieur et organise un renouvellement partiel. Cette modification rend l'accès moins prévisible pour les anciens inscrits, mais élargit les profils des bénéficiaires. » Cela justifie la réponse : Équilibrer continuité des demandes et ouverture à d'autres besoins."},{"number":35,"points":26,"passage":"Les commerces au rez-de-chaussée participent à l'animation d'une rue. Pourtant, certaines activités gênent les riverains par leurs livraisons ou leurs horaires. Une association refuse de choisir entre une rue vide et une activité sans règles. Elle défend des accords locaux qui maintiennent les services tout en limitant les nuisances. Les horaires de livraison et les équipements d'isolation peuvent faire partie des solutions.","question":"Quelle position l'association adopte-t-elle ?","options":["Éloigner systématiquement les habitants","Fermer tous les commerces","Rechercher une coexistence négociée","Accepter toute nuisance commerciale"],"correct":"C","explanation":"Le passage indique : « Les commerces au rez-de-chaussée participent à l'animation d'une rue. Pourtant, certaines activités gênent les riverains par leurs livraisons ou leurs horaires. Une association refuse de choisir entre une rue vide et une activité sans règles. Elle défend des accords locaux qui maintiennent les services tout en limitant les nuisances. » Cela justifie la réponse : Rechercher une coexistence négociée."},{"number":36,"points":33,"passage":"Une ville annonce des logements « abordables » en comparant leurs loyers à ceux des annonces privées les plus récentes. Une chercheuse remarque que cette comparaison ignore les revenus des ménages visés. Un prix inférieur au marché peut encore absorber une part excessive du budget d'une famille. Elle ne rejette pas le programme, mais demande de préciser pour qui il devient accessible. L'abordabilité doit donc être appréciée par rapport aux ressources des occupants, et pas seulement aux prix voisins. Pour les promoteurs du programme, le prix inférieur reste un progrès par rapport aux offres voisines. La chercheuse leur propose de publier également plusieurs exemples de budgets, avec les charges et les trajets quotidiens. Une famille peut en effet accepter un loyer modéré puis supporter des dépenses importantes pour rejoindre son travail.","question":"Quelle limite de l'annonce est soulignée ?","options":["La chercheuse exige l'arrêt immédiat du programme","Les revenus empêchent toute comparaison de logements","Un loyer inférieur au marché est nécessairement accessible","La comparaison des prix ne suffit pas à mesurer l'accessibilité"],"correct":"D","explanation":"Le passage indique : « L'abordabilité doit donc être appréciée par rapport aux ressources des occupants, et pas seulement aux prix voisins. » Cela justifie la réponse : La comparaison des prix ne suffit pas à mesurer l'accessibilité."},{"number":37,"points":33,"passage":"Une résidence organise chaque semaine un repas partagé. Au début, le conseil souhaitait rendre la présence obligatoire pour lutter contre l'isolement. Plusieurs habitants ont expliqué qu'ils travaillaient le soir ou préféraient des rencontres moins nombreuses. Le projet a été revu : chacun peut proposer un autre créneau ou participer autrement. L'objectif de convivialité est conservé, mais il ne justifie plus une obligation identique pour tous. Au départ, les promoteurs de la résidence craignaient que les logements privés ne favorisent le repli de chacun. Ils ont ensuite constaté que les échanges étaient plus faciles lorsque les habitants pouvaient choisir leurs moments de présence. Des personnes peu disponibles ont proposé de préparer une liste de courses ou de participer à une sortie occasionnelle. Ces formes de contribution ont enrichi le projet.","question":"Que révèle l'évolution du projet ?","options":["L'impossibilité de modifier une décision collective","L'abandon complet de toute activité commune","Le refus des habitants de se rencontrer un jour","La participation collective doit tenir compte des situations individuelles"],"correct":"D","explanation":"Le passage indique : « L'objectif de convivialité est conservé, mais il ne justifie plus une obligation identique pour tous. » Cela justifie la réponse : La participation collective doit tenir compte des situations individuelles."},{"number":38,"points":33,"passage":"À l'occasion d'une rénovation, un quartier reçoit une nouvelle image dans les brochures touristiques. Ses commerces et ses places deviennent plus attractifs. Cependant, plusieurs ateliers anciens quittent les lieux après une hausse des loyers. Les responsables célèbrent la fréquentation, tandis que des habitants regrettent la disparition de services familiers. Le renouvellement urbain peut améliorer l'attractivité tout en fragilisant certaines fonctions qui faisaient vivre le quartier. Les responsables des ateliers ne contestent pas que la place soit devenue plus agréable. Ils expliquent cependant que leur clientèle habituelle et leurs réseaux d'entraide s'étaient formés sur une longue période. Un départ à quelques kilomètres peut déjà rompre ces relations. La commune étudie donc des locaux à loyer encadré et un accompagnement des activités menacées. Le débat porte moins sur le choix entre amélioration et immobilité que sur la manière de répartir les bénéfices du changement entre visiteurs, nouveaux investisseurs et habitants déjà présents.","question":"Quel paradoxe le texte met-il en évidence ?","options":["Les habitants refusent toute amélioration des places","Le succès d'un quartier peut évincer des activités utiles à ses habitants","Les loyers diminuent lorsque les commerces partent","La rénovation empêche toujours l'arrivée de visiteurs"],"correct":"B","explanation":"Le passage indique : « Le renouvellement urbain peut améliorer l'attractivité tout en fragilisant certaines fonctions qui faisaient vivre le quartier. » Cela justifie la réponse : Le succès d'un quartier peut évincer des activités utiles à ses habitants."},{"number":39,"points":33,"passage":"Pour construire plus vite, une municipalité veut uniformiser les plans de ses futurs logements. Des architectes reconnaissent que certains éléments techniques peuvent être répétés. Ils contestent toutefois l'idée qu'une même distribution conviendrait à un étudiant, à une famille et à une personne qui travaille chez elle. Leur proposition conserve des composants communs tout en permettant des transformations. L'économie de moyens devient pertinente lorsqu'elle rend l'adaptation possible au lieu d'effacer la diversité des usages. L'équipe travaille par exemple sur des cloisons faciles à déplacer et des pièces capables de changer de fonction. Elle demande aussi de prévoir les accès techniques avant la construction, car une transformation devient vite coûteuse lorsque toutes les installations sont fixées au même endroit. Les élus souhaitent comparer le coût initial et celui des adaptations futures.","question":"Quelle solution ces architectes défendent-ils ?","options":["Dessiner un logement strictement identique pour chaque occupant","Renoncer à toute technique répétable","Interdire l'évolution des logements après leur construction","Associer des éléments communs à des aménagements adaptables"],"correct":"D","explanation":"Le passage indique : « L'économie de moyens devient pertinente lorsqu'elle rend l'adaptation possible au lieu d'effacer la diversité des usages. » Cela justifie la réponse : Associer des éléments communs à des aménagements adaptables."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-03','tcf-reading-2026-11-reference-v3',$paper${"id":"tcf-reading-03","version":"tcf-reading-2026-11-reference-v3","title":"TCF Reading · Test 03","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"L'accueil du centre de formation ferme à midi vendredi. Les cours de l'après-midi auront lieu normalement ; les stagiaires entreront par la porte latérale.\n\nUne affiche devant la réception rappellera le parcours d'accès.","question":"Qu'est-ce qui est maintenu ?","options":["L'accueil toute la journée","Les cours de l'après-midi","Les inscriptions du soir","L'entrée principale ouverte"],"correct":"B","explanation":"Le passage indique : « L'accueil du centre de formation ferme à midi vendredi. Les cours de l'après-midi auront lieu normalement ; les stagiaires entreront par la porte latérale. » Cela justifie la réponse : Les cours de l'après-midi."},{"number":2,"points":3,"passage":"Atelier CV : apportez une offre d'emploi qui vous intéresse. Aucun ordinateur personnel n'est nécessaire ; des postes seront disponibles.\n\nL'animateur vous aidera à sélectionner les expériences pertinentes.","question":"Que faut-il apporter ?","options":["Un contrat signé","Une offre d'emploi","Une lettre de recommandation","Un ordinateur"],"correct":"B","explanation":"Le passage indique : « Atelier CV : apportez une offre d'emploi qui vous intéresse. Aucun ordinateur personnel n'est nécessaire ; des postes seront disponibles. » Cela justifie la réponse : Une offre d'emploi."},{"number":3,"points":3,"passage":"Le vestiaire du personnel sera repeint lundi. Les casiers doivent être vidés avant dimanche soir ; des sacs temporaires seront fournis.\n\nUn agent ouvrira une pièce de stockage pour les effets personnels.","question":"Quand faut-il libérer les casiers ?","options":["Lundi après les travaux","Mardi matin","À la fin du mois","Avant dimanche soir"],"correct":"D","explanation":"Le passage indique : « Le vestiaire du personnel sera repeint lundi. Les casiers doivent être vidés avant dimanche soir ; des sacs temporaires seront fournis. » Cela justifie la réponse : Avant dimanche soir."},{"number":4,"points":3,"passage":"La réunion d'équipe passe en visioconférence demain. Le lien sera envoyé une heure avant ; la durée prévue reste trente minutes.\n\nLes personnes sans caméra pourront participer avec le son seulement. Les documents de travail seront transmis avec l'invitation à tous les collègues.","question":"Quel changement est annoncé ?","options":["La durée de la réunion","Le jour de la réunion","Le nom du responsable","Le mode de participation"],"correct":"D","explanation":"Le passage indique : « La réunion d'équipe passe en visioconférence demain. Le lien sera envoyé une heure avant ; la durée prévue reste trente minutes. » Cela justifie la réponse : Le mode de participation."},{"number":5,"points":9,"passage":"Bonjour Malik, je peux échanger mon service de samedi contre ton mercredi. En revanche, je dois garder mon vendredi pour accompagner mon fils. Dis-moi si cela te convient.\n\nJ'ai déjà vérifié avec le responsable que cet échange ne désorganiserait pas l'équipe. Merci de me répondre rapidement.","question":"Quel service l'auteur veut-il conserver ?","options":["Celui du mercredi","Celui du samedi","Celui du vendredi","Tous les services du matin"],"correct":"C","explanation":"Le passage indique : « Bonjour Malik, je peux échanger mon service de samedi contre ton mercredi. En revanche, je dois garder mon vendredi pour accompagner mon fils. Dis-moi si cela te convient. » Cela justifie la réponse : Celui du vendredi."},{"number":6,"points":9,"passage":"Nous cherchons une personne pour classer des archives pendant six semaines. L'expérience n'est pas indispensable ; la précision et le respect de la confidentialité comptent davantage.\n\nLes dossiers seront traités dans un bureau calme avec un petit groupe.","question":"Quelle qualité est particulièrement recherchée ?","options":["La discrétion","Une expérience de direction","La maîtrise d'un camion","La connaissance de trois langues"],"correct":"A","explanation":"Le passage indique : « Nous cherchons une personne pour classer des archives pendant six semaines. L'expérience n'est pas indispensable ; la précision et le respect de la confidentialité comptent davantage. » Cela justifie la réponse : La discrétion."},{"number":7,"points":9,"passage":"J'ai refusé la promotion proposée. Le salaire augmentait, mais le poste impliquait des déplacements chaque semaine. Je préfère pour l'instant rester près de ma famille.\n\nJ'apprécie pourtant l'équipe et les missions annoncées. Peut-être pourrai-je envisager ce type de poste plus tard, lorsque l'organisation familiale sera différente.","question":"Pourquoi cette personne refuse-t-elle ?","options":["Le salaire serait réduit","Le poste disparaît prochainement","Les déplacements ne lui conviennent pas","Elle souhaite travailler à l'étranger"],"correct":"C","explanation":"Le passage indique : « J'ai refusé la promotion proposée. Le salaire augmentait, mais le poste impliquait des déplacements chaque semaine. Je préfère pour l'instant rester près de ma famille. » Cela justifie la réponse : Les déplacements ne lui conviennent pas."},{"number":8,"points":9,"passage":"La visite de l'atelier est ouverte aux candidats avant leur entretien. Elle permet de découvrir les tâches réelles ; elle n'entre pas dans l'évaluation du recrutement.\n\nUn salarié expliquera les équipements et les horaires.","question":"À quoi sert cette visite ?","options":["Remplacer l'entretien","Signer immédiatement le contrat","Mieux comprendre le travail proposé","Noter la vitesse des candidats"],"correct":"C","explanation":"Le passage indique : « La visite de l'atelier est ouverte aux candidats avant leur entretien. Elle permet de découvrir les tâches réelles ; elle n'entre pas dans l'évaluation du recrutement. » Cela justifie la réponse : Mieux comprendre le travail proposé."},{"number":9,"points":9,"passage":"Chère équipe, le nouveau planning tient compte des demandes reçues avant lundi. Les demandes plus tardives seront examinées pour le mois suivant, sauf urgence familiale.\n\nLe planning sera affiché dans le vestiaire et envoyé aux personnes absentes.","question":"Quelles demandes peuvent encore être traitées ce mois-ci ?","options":["Toutes les demandes tardives","Les demandes sans justification professionnelle","Les urgences familiales","Seulement les demandes de congés d'été"],"correct":"C","explanation":"Le passage indique : « Chère équipe, le nouveau planning tient compte des demandes reçues avant lundi. Les demandes plus tardives seront examinées pour le mois suivant, sauf urgence familiale. » Cela justifie la réponse : Les urgences familiales."},{"number":10,"points":9,"passage":"L'atelier de couture recrute un apprenti. La formation sera partagée entre le centre et l'entreprise ; les débutants seront accompagnés par une salariée expérimentée.\n\nLes candidats découvriront plusieurs étapes du travail avant de choisir une spécialité. L'école et l'entreprise feront régulièrement le point sur les progrès réalisés.","question":"Comment l'apprentissage sera-t-il organisé ?","options":["Uniquement à domicile","Entre formation et travail accompagné","Sans présence en entreprise","Par un examen quotidien éliminatoire"],"correct":"B","explanation":"Le passage indique : « L'atelier de couture recrute un apprenti. La formation sera partagée entre le centre et l'entreprise ; les débutants seront accompagnés par une salariée expérimentée. » Cela justifie la réponse : Entre formation et travail accompagné."},{"number":11,"points":15,"passage":"Après une longue interruption professionnelle, Éva suit un stage court pour actualiser ses outils de gestion. Elle ne change pas de métier : elle prépare son retour dans le même secteur.\n\nElle connaît déjà les dossiers et les habitudes des clients, mais les logiciels ont beaucoup changé pendant son absence. Le centre lui a proposé une évaluation préalable pour identifier ses priorités. Elle suit maintenant deux séances par semaine et s'exerce entre les cours sur des cas proches de son ancien travail. Cette progression lui permet de retrouver confiance sans devoir recommencer toutes ses études depuis le début.","question":"Quel est son objectif ?","options":["Devenir formatrice immédiatement","Ouvrir une agence de voyages","Abandonner son secteur","Mettre ses compétences à jour"],"correct":"D","explanation":"Le passage indique : « Après une longue interruption professionnelle, Éva suit un stage court pour actualiser ses outils de gestion. Elle ne change pas de métier : elle prépare son retour dans le même secteur. » Cela justifie la réponse : Mettre ses compétences à jour."},{"number":12,"points":15,"passage":"Une entreprise de maintenance remet à chaque nouvelle recrue un carnet de situations fréquentes. Les techniciens peuvent y ajouter leurs observations après validation. Le document évolue avec les interventions.\n\nLes nouveaux employés y trouvent des exemples concrets, avec les causes possibles d'une panne et les vérifications à effectuer avant de remplacer une pièce. Les remarques doivent être relues par un collègue pour éviter de diffuser une consigne imprécise.","question":"Qu'est-ce qui caractérise ce carnet ?","options":["Il est réservé aux clients","Il reste définitivement inchangé","Il remplace toutes les formations","Il s'enrichit de l'expérience du terrain"],"correct":"D","explanation":"Le passage indique : « Une entreprise de maintenance remet à chaque nouvelle recrue un carnet de situations fréquentes. Les techniciens peuvent y ajouter leurs observations après validation. Le document évolue avec les interventions. » Cela justifie la réponse : Il s'enrichit de l'expérience du terrain."},{"number":13,"points":15,"passage":"Un artisan montre ses gestes en direct à un petit groupe. Les participants essaient ensuite et discutent de leurs erreurs. Pour lui, regarder une démonstration ne remplace pas la pratique.\n\nLe groupe travaille d'abord sur des chutes de matière afin de pouvoir recommencer sans gaspiller une pièce coûteuse. L'artisan observe la position des mains et demande à chacun d'expliquer son choix. Les échanges révèlent souvent qu'un geste apparemment simple combine plusieurs décisions. À la fin, les participants rédigent quelques repères personnels. Ils savent qu'une fiche ne remplacera pas l'expérience, mais qu'elle pourra leur rappeler les points essentiels lorsqu'ils pratiqueront seuls dans leur propre atelier.","question":"Quelle approche privilégie-t-il ?","options":["L'essai accompagné","L'observation sans exercice","La mémorisation des tarifs","Le travail sans retour"],"correct":"A","explanation":"Le passage indique : « Un artisan montre ses gestes en direct à un petit groupe. Les participants essaient ensuite et discutent de leurs erreurs. Pour lui, regarder une démonstration ne remplace pas la pratique. » Cela justifie la réponse : L'essai accompagné."},{"number":14,"points":15,"passage":"La médiathèque prête des ordinateurs pour les formations du soir. Les demandeurs n'ont pas à justifier leur recherche d'emploi. Le dispositif vise aussi les salariés souhaitant apprendre un nouvel outil.\n\nLe prêt dure tout le cycle et comprend une courte présentation du matériel. Les apprenants peuvent ainsi reprendre les exercices entre les séances, même si leur ordinateur familial est partagé ou ancien. Une permanence permet de signaler un problème technique. La bibliothèque ne demande pas aux participants de détailler leurs revenus ; elle souhaite simplement que les conditions matérielles ne décident pas à elles seules de la possibilité de suivre le cours.","question":"Qui peut bénéficier du prêt ?","options":["Seulement les formateurs","Les entreprises achetant un abonnement","Uniquement des chômeurs inscrits","Des personnes aux situations professionnelles variées"],"correct":"D","explanation":"Le passage indique : « La médiathèque prête des ordinateurs pour les formations du soir. Les demandeurs n'ont pas à justifier leur recherche d'emploi. Le dispositif vise aussi les salariés souhaitant apprendre un nouvel outil. » Cela justifie la réponse : Des personnes aux situations professionnelles variées."},{"number":15,"points":15,"passage":"Dans une usine, la pause peut être prise à plusieurs horaires pour éviter l'affluence au réfectoire. Chaque équipe doit néanmoins garantir une présence suffisante sur la ligne.\n\nLes salariés s'organisent avec leurs collègues et indiquent leur créneau sur un tableau. Un changement est possible si les personnes concernées se mettent d'accord. La direction évaluera l'essai après plusieurs semaines, en regardant les files au restaurant et le fonctionnement de l'atelier. Certains employés apprécient de pouvoir déjeuner plus tôt ; d'autres préfèrent attendre un moment calme. La règle commune permet cette diversité sans laisser une équipe entière quitter son poste simultanément.","question":"Quelle limite encadre cette souplesse ?","options":["L'obligation de manger ensemble","Le maintien du fonctionnement de la ligne","La suppression de toutes les pauses","L'autorisation préalable des clients"],"correct":"B","explanation":"Le passage indique : « Dans une usine, la pause peut être prise à plusieurs horaires pour éviter l'affluence au réfectoire. Chaque équipe doit néanmoins garantir une présence suffisante sur la ligne. » Cela justifie la réponse : Le maintien du fonctionnement de la ligne."},{"number":16,"points":15,"passage":"Un cabinet propose un entretien de recrutement sans nom d'école sur le dossier initial. Les candidats réalisent d'abord un exercice lié au poste. Le diplôme peut être discuté plus tard.\n\nL'exercice est court et utilise des documents fictifs pour ne pas transformer le recrutement en travail gratuit pour l'entreprise. Deux personnes relisent les résultats avec la même grille. Le cabinet souhaite donner leur chance à des parcours moins connus, sans promettre que l'origine scolaire n'aura jamais d'importance.","question":"Que cherche ce procédé ?","options":["Examiner d'abord les compétences en situation","Éliminer toute personne diplômée","Choisir les candidats les plus jeunes","Supprimer l'entretien avec le candidat"],"correct":"A","explanation":"Le passage indique : « Un cabinet propose un entretien de recrutement sans nom d'école sur le dossier initial. Les candidats réalisent d'abord un exercice lié au poste. Le diplôme peut être discuté plus tard. » Cela justifie la réponse : Examiner d'abord les compétences en situation."},{"number":17,"points":15,"passage":"Une salariée apprend la réparation de cycles en soirée. Elle conserve son emploi administratif durant la formation pour vérifier progressivement son projet avant une éventuelle reconversion.\n\nElle rencontre également des professionnels pour connaître les horaires, les charges et les périodes plus calmes de cette activité. Une journée d'observation lui a permis de voir le travail derrière le comptoir, au-delà des réparations les plus intéressantes. Elle constitue progressivement un budget et vérifie les débouchés dans sa ville. Ses proches l'encouragent, mais elle préfère décider à partir de ces informations plutôt que quitter son poste après quelques cours seulement.","question":"Pourquoi garde-t-elle son emploi ?","options":["Parce que la formation est déjà terminée","Pour avancer prudemment dans son projet","Pour devenir responsable du cours","Parce qu'elle renonce au métier envisagé"],"correct":"B","explanation":"Le passage indique : « Une salariée apprend la réparation de cycles en soirée. Elle conserve son emploi administratif durant la formation pour vérifier progressivement son projet avant une éventuelle reconversion. » Cela justifie la réponse : Pour avancer prudemment dans son projet."},{"number":18,"points":15,"passage":"Le service des ressources humaines ouvre une permanence sans rendez-vous. Les questions individuelles seront reçues dans un bureau fermé, afin que les collègues n'entendent pas les échanges.\n\nLes responsables souhaitent réduire les questions restées sans réponse parce qu'il était difficile de trouver un moment disponible. Les sujets collectifs feront l'objet d'une réunion séparée. Le service rappelle que cette organisation ne change pas les règles applicables, mais doit rendre leur explication plus accessible aux personnes qui hésitent à poser une question devant toute l'équipe.","question":"Quelle précaution est prise ?","options":["Préserver la confidentialité des échanges","Diffuser les questions à toute l'équipe","Enregistrer toutes les conversations publiquement","Recevoir uniquement des groupes"],"correct":"A","explanation":"Le passage indique : « Le service des ressources humaines ouvre une permanence sans rendez-vous. Les questions individuelles seront reçues dans un bureau fermé, afin que les collègues n'entendent pas les échanges. » Cela justifie la réponse : Préserver la confidentialité des échanges."},{"number":19,"points":15,"passage":"Un restaurant forme ses serveurs à reconnaître les principaux allergènes. Ils doivent consulter la cuisine en cas de doute, plutôt que promettre un plat adapté sans vérification.\n\nLes fiches seront mises à jour lorsque les recettes ou les fournisseurs changent. L'équipe apprend aussi à transmettre clairement une demande particulière, sans l'interpréter de mémoire. Il précise qu'il vaut mieux prendre quelques minutes pour obtenir une confirmation que donner une assurance que la cuisine ne peut pas réellement tenir.","question":"Quel comportement est demandé ?","options":["Vérifier les informations incertaines","Rassurer le client sans consulter personne","Éviter toute conversation avec la cuisine","Supprimer tous les plats du menu"],"correct":"A","explanation":"Le passage indique : « Un restaurant forme ses serveurs à reconnaître les principaux allergènes. Ils doivent consulter la cuisine en cas de doute, plutôt que promettre un plat adapté sans vérification. » Cela justifie la réponse : Vérifier les informations incertaines."},{"number":20,"points":21,"passage":"Un centre propose des formations modulaires que les adultes peuvent étaler sur deux ans. Les compétences déjà acquises sont évaluées pour éviter de refaire certains modules. Le parcours reste exigeant, mais il s'adapte aux contraintes des participants. Les participants peuvent interrompre temporairement leur parcours et reprendre les éléments déjà validés. Un entretien régulier permet de vérifier si le rythme reste compatible avec leur emploi. Le centre souhaite rendre la formation accessible sans réduire les compétences attendues à la fin. Il demande donc un engagement réaliste plutôt qu'une présence intensive impossible à maintenir pour certaines personnes.","question":"Quel avantage offre l'évaluation initiale ?","options":["Garantir le diplôme sans formation","Imposer le même calendrier à chacun","Supprimer tous les examens","Éviter des apprentissages déjà maîtrisés"],"correct":"D","explanation":"Le passage indique : « Un centre propose des formations modulaires que les adultes peuvent étaler sur deux ans. Les compétences déjà acquises sont évaluées pour éviter de refaire certains modules. Le parcours reste exigeant, mais il s'adapte aux contraintes des participants. » Cela justifie la réponse : Éviter des apprentissages déjà maîtrisés."},{"number":21,"points":21,"passage":"Dans une entreprise de livraison, les conducteurs proposent de modifier les tournées. La direction accepte un essai sur deux secteurs avant une généralisation. Les délais et la fatigue seront étudiés ensemble, car une tournée rapide peut aussi être épuisante. Les conducteurs ont identifié des arrêts où les attentes sont longues et des itinéraires qui imposent de nombreuses manœuvres. Leurs propositions seront comparées sur des journées semblables. La direction souhaite éviter qu'un meilleur délai annoncé se traduise simplement par davantage de pression sur les mêmes personnes.","question":"Quels critères seront comparés ?","options":["Uniquement le prix des véhicules","La performance et les conditions de travail","Le nombre de publicités affichées","Les préférences musicales des conducteurs"],"correct":"B","explanation":"Le passage indique : « Dans une entreprise de livraison, les conducteurs proposent de modifier les tournées. La direction accepte un essai sur deux secteurs avant une généralisation. Les délais et la fatigue seront étudiés ensemble, car une tournée rapide peut aussi être épuisante. » Cela justifie la réponse : La performance et les conditions de travail."},{"number":22,"points":21,"passage":"Une association accompagne les personnes qui souhaitent faire reconnaître une expérience bénévole. Elle aide à décrire les activités réalisées, sans promettre automatiquement une certification. La décision dépend ensuite de l'organisme compétent. Les bénévoles apportent des exemples, des documents et des descriptions de situations. Un accompagnateur les aide à distinguer une responsabilité précise d'une participation occasionnelle. Ils n'effacent pas les exigences du diplôme demandé, mais peuvent aider une personne à présenter des acquis jusque-là difficiles à formuler.","question":"Quelle limite du service est précisée ?","options":["Seuls les salariés sont reçus","L'accompagnement ne garantit pas la certification","Le bénévolat ne peut jamais être décrit","L'association délivre tous les diplômes"],"correct":"B","explanation":"Le passage indique : « Une association accompagne les personnes qui souhaitent faire reconnaître une expérience bénévole. Elle aide à décrire les activités réalisées, sans promettre automatiquement une certification. La décision dépend ensuite de l'organisme compétent. » Cela justifie la réponse : L'accompagnement ne garantit pas la certification."},{"number":23,"points":21,"passage":"Le bureau partagé d'un service était censé faciliter les échanges. Les appels fréquents y ont pourtant gêné les tâches de concentration. L'équipe réserve maintenant des créneaux silencieux et des espaces pour les conversations. Les nouvelles règles ont été dessinées avec les salariés après une semaine d'observation. Chacun peut signaler une difficulté sans demander l'interdiction de tous les échanges. Les responsables savent que les dossiers ne demandent pas tous le même environnement.","question":"Pourquoi l'organisation a-t-elle évolué ?","options":["Pour concilier échange et concentration","Pour interdire tout travail collectif","Pour augmenter le bruit des appels","Pour réduire le nombre de clients"],"correct":"A","explanation":"Le passage indique : « Le bureau partagé d'un service était censé faciliter les échanges. Les appels fréquents y ont pourtant gêné les tâches de concentration. L'équipe réserve maintenant des créneaux silencieux et des espaces pour les conversations. » Cela justifie la réponse : Pour concilier échange et concentration."},{"number":24,"points":21,"passage":"Un hôtel préfère former plusieurs salariés à l'accueil de nuit plutôt que dépendre d'une seule personne. Les volontaires bénéficieront d'un accompagnement et de repos adaptés. La polyvalence doit réduire la fragilité du service, pas multiplier les heures de chacun. Les premiers essais concerneront des périodes courtes, avec une personne expérimentée disponible pour répondre aux questions. Les volontaires apprendront aussi les procédures à suivre en cas d'incident. La direction souhaite limiter les remplacements improvisés au dernier moment.","question":"Quel objectif poursuit l'hôtel ?","options":["Imposer des nuits à tous les clients","Remplacer tout le personnel par une machine","Rendre le service moins dépendant d'une personne","Supprimer les repos"],"correct":"C","explanation":"Le passage indique : « Un hôtel préfère former plusieurs salariés à l'accueil de nuit plutôt que dépendre d'une seule personne. Les volontaires bénéficieront d'un accompagnement et de repos adaptés. La polyvalence doit réduire la fragilité du service, pas multiplier les heures de chacun. » Cela justifie la réponse : Rendre le service moins dépendant d'une personne."},{"number":25,"points":21,"passage":"Les salariés d'une petite entreprise choisissent les sujets de leur journée annuelle de formation. Certains demandent des outils immédiatement utiles, d'autres un temps de réflexion sur leur métier. Le programme final conserve les deux approches. Les responsables ont demandé aux participants de préciser leurs attentes avant la journée. Les ateliers pratiques seront suivis d'un échange sur les situations où les outils pourraient réellement servir. Le service ne veut pas accumuler des présentations sans lien avec les missions.","question":"Quel compromis est trouvé ?","options":["Choisir uniquement des sujets théoriques","Reporter toutes les formations","Associer utilité immédiate et réflexion professionnelle","Réserver la journée aux cadres"],"correct":"C","explanation":"Le passage indique : « Les salariés d'une petite entreprise choisissent les sujets de leur journée annuelle de formation. Certains demandent des outils immédiatement utiles, d'autres un temps de réflexion sur leur métier. Le programme final conserve les deux approches. » Cela justifie la réponse : Associer utilité immédiate et réflexion professionnelle."},{"number":26,"points":21,"passage":"Une école professionnelle invite d'anciens élèves ayant changé plusieurs fois de métier. Elle veut montrer des parcours rarement linéaires, plutôt que présenter une seule trajectoire idéale. Les témoignages portent aussi sur les hésitations et les échecs. Certains racontent une première orientation abandonnée, d'autres une formation reprise après plusieurs années de travail. Les élèves pourront interroger les intervenants sur les ressources qui les ont aidés à rebondir. L'école souhaite présenter des expériences concrètes plutôt que transformer chaque témoignage en leçon de réussite personnelle.","question":"Que souhaitent montrer les organisateurs ?","options":["L'inutilité de toute formation","Une réussite sans difficulté pour tous","La nécessité de garder toujours le même poste","La diversité des parcours professionnels"],"correct":"D","explanation":"Le passage indique : « Une école professionnelle invite d'anciens élèves ayant changé plusieurs fois de métier. Elle veut montrer des parcours rarement linéaires, plutôt que présenter une seule trajectoire idéale. Les témoignages portent aussi sur les hésitations et les échecs. » Cela justifie la réponse : La diversité des parcours professionnels."},{"number":27,"points":21,"passage":"Un atelier réserve du temps à la transmission avant le départ d'un salarié expérimenté. Des vidéos seront réalisées, mais elles seront accompagnées de séances pratiques. Certaines décisions dépendent de sensations que l'image seule explique mal. Le technicien partant à la retraite a proposé de commenter des interventions réelles avec les nouveaux salariés. L'équipe réservera quelques heures à ces échanges avant son départ.","question":"Pourquoi les vidéos ne suffisent-elles pas ?","options":["Les nouveaux employés refusent de regarder","Une partie du savoir exige une expérience pratique","Le salarié ne connaît pas son métier","Les vidéos sont interdites dans l'atelier"],"correct":"B","explanation":"Le passage indique : « Un atelier réserve du temps à la transmission avant le départ d'un salarié expérimenté. Des vidéos seront réalisées, mais elles seront accompagnées de séances pratiques. Certaines décisions dépendent de sensations que l'image seule explique mal. » Cela justifie la réponse : Une partie du savoir exige une expérience pratique."},{"number":28,"points":21,"passage":"Une enquête interne révèle que des employés n'utilisent pas leur droit à la formation. Les horaires proposés coïncident avec leurs obligations familiales. La direction ajoute des créneaux différents plutôt que conclure à un manque de motivation. Les employés expliquent qu'ils doivent parfois choisir entre une séance et un rendez-vous déjà prévu pour leurs enfants. D'autres travaillent sur des rotations qui varient d'une semaine à l'autre. Le service propose désormais plusieurs dates et un court accompagnement individuel pour les absences justifiées.","question":"Quelle interprétation est privilégiée ?","options":["Les formations sont inutiles par nature","Les employés refusent tous d'apprendre","Les familles doivent financer les cours","L'organisation peut empêcher la participation"],"correct":"D","explanation":"Le passage indique : « Une enquête interne révèle que des employés n'utilisent pas leur droit à la formation. Les horaires proposés coïncident avec leurs obligations familiales. La direction ajoute des créneaux différents plutôt que conclure à un manque de motivation. » Cela justifie la réponse : L'organisation peut empêcher la participation."},{"number":29,"points":21,"passage":"Un espace de travail propose des bureaux à la journée. Plusieurs indépendants apprécient la souplesse, mais demandent une formule stable pour retrouver les mêmes voisins. La liberté de venir ponctuellement ne répond pas à tous les besoins de relation professionnelle. Le gestionnaire ajoute donc quelques tables réservables plusieurs semaines de suite, sans imposer cette formule à tous. Les indépendants occasionnels peuvent toujours venir à la journée.","question":"Quel besoin supplémentaire apparaît ?","options":["Des horaires toujours plus courts","Une continuité dans les rencontres","Une fermeture des bureaux partagés","L'absence totale de collègues"],"correct":"B","explanation":"Le passage indique : « Un espace de travail propose des bureaux à la journée. Plusieurs indépendants apprécient la souplesse, mais demandent une formule stable pour retrouver les mêmes voisins. La liberté de venir ponctuellement ne répond pas à tous les besoins de relation professionnelle. » Cela justifie la réponse : Une continuité dans les rencontres."},{"number":30,"points":26,"passage":"Une entreprise compte les heures de connexion pour évaluer le travail à distance. Une représentante du personnel remarque qu'une présence numérique longue ne dit rien de la difficulté des dossiers traités. Elle propose d'étudier les résultats avec les salariés, tout en tenant compte du temps nécessaire pour les obtenir. Elle suggère également de suivre les difficultés rencontrées dans les dossiers. Un temps long peut refléter un problème complexe plutôt qu'une mauvaise organisation du salarié.","question":"Quelle critique formule-t-elle ?","options":["Les dossiers difficiles demandent toujours moins de temps","Le travail à distance interdit toute évaluation","La durée de connexion est un indicateur insuffisant","Les résultats ne doivent jamais être examinés"],"correct":"C","explanation":"Le passage indique : « Une entreprise compte les heures de connexion pour évaluer le travail à distance. Une représentante du personnel remarque qu'une présence numérique longue ne dit rien de la difficulté des dossiers traités. Elle propose d'étudier les résultats avec les salariés, tout en tenant compte du temps nécessaire pour les obtenir. » Cela justifie la réponse : La durée de connexion est un indicateur insuffisant."},{"number":31,"points":26,"passage":"Les appels à la « passion du métier » peuvent soutenir l'engagement. Mais lorsqu'ils servent à justifier des heures non reconnues, ils masquent un déséquilibre. Un collectif de soignants défend la qualité du service tout en demandant des moyens et des horaires soutenables. Leur demande ne traduit pas un désintérêt pour leur travail. Les représentants proposent de discuter des effectifs et des interruptions qui ralentissent le service.","question":"Quelle opposition le texte refuse-t-il ?","options":["Opposer deux méthodes de prise de notes","Opposer engagement professionnel et bonnes conditions de travail","Distinguer salaire et coût des transports","Comparer deux spécialités médicales"],"correct":"B","explanation":"Le passage indique : « Les appels à la « passion du métier » peuvent soutenir l'engagement. Mais lorsqu'ils servent à justifier des heures non reconnues, ils masquent un déséquilibre. Un collectif de soignants défend la qualité du service tout en demandant des moyens et des horaires soutenables. Leur demande ne traduit pas un désintérêt pour leur travail. » Cela justifie la réponse : Opposer engagement professionnel et bonnes conditions de travail."},{"number":32,"points":26,"passage":"Un diplôme décrit des acquis, mais ne résume pas toutes les aptitudes nécessaires dans une équipe. Un recruteur combine donc exercice technique, entretien et période d'observation rémunérée. Aucun de ces éléments n'est considéré comme infaillible. Leur intérêt vient du croisement des informations qu'ils apportent. Les observations seront discutées avec le candidat afin qu'il puisse préciser son raisonnement. Le cabinet veut éviter qu'une seule impression, favorable ou défavorable, décide de tout le recrutement sans possibilité de vérification.","question":"Quelle conception du recrutement est défendue ?","options":["Éclairer la décision par plusieurs observations","Choisir sans rencontrer les candidats","Écarter toute preuve technique","Se fier exclusivement au diplôme"],"correct":"A","explanation":"Le passage indique : « Un diplôme décrit des acquis, mais ne résume pas toutes les aptitudes nécessaires dans une équipe. Un recruteur combine donc exercice technique, entretien et période d'observation rémunérée. Aucun de ces éléments n'est considéré comme infaillible. Leur intérêt vient du croisement des informations qu'ils apportent. » Cela justifie la réponse : Éclairer la décision par plusieurs observations."},{"number":33,"points":26,"passage":"La spécialisation rend certains services très efficaces, jusqu'au jour où une personne indispensable s'absente. Pour limiter ce risque, une entreprise organise des échanges de savoirs. Elle ne demande pas à chacun de tout maîtriser : elle veut que les collègues comprennent suffisamment les tâches voisines pour assurer une continuité. Les échanges se font pendant le temps de travail et portent d'abord sur les opérations fréquentes.","question":"Quel équilibre recherche-t-elle ?","options":["Conserver l'expertise tout en réduisant la dépendance individuelle","Rendre toutes les compétences identiques","Supprimer les congés des spécialistes","Multiplier les tâches sans formation"],"correct":"A","explanation":"Le passage indique : « La spécialisation rend certains services très efficaces, jusqu'au jour où une personne indispensable s'absente. Pour limiter ce risque, une entreprise organise des échanges de savoirs. Elle ne demande pas à chacun de tout maîtriser : elle veut que les collègues comprennent suffisamment les tâches voisines pour assurer une continuité. » Cela justifie la réponse : Conserver l'expertise tout en réduisant la dépendance individuelle."},{"number":34,"points":26,"passage":"Une formation courte promet des débouchés rapides. Des anciens stagiaires saluent la qualité des exercices, tout en signalant le manque de contacts avec les employeurs locaux. Ils distinguent l'apprentissage d'une technique de l'accès effectif à un emploi. Améliorer le second suppose un accompagnement que le seul contenu des cours ne remplace pas. Les stagiaires suggèrent des visites d'entreprises et des rencontres avec des recruteurs.","question":"Quelle distinction est faite ?","options":["Une formation pratique empêche de travailler","Les employeurs doivent supprimer les exercices","Savoir faire un travail ne garantit pas d'obtenir un poste","Les stagiaires refusent tout accompagnement"],"correct":"C","explanation":"Le passage indique : « Une formation courte promet des débouchés rapides. Des anciens stagiaires saluent la qualité des exercices, tout en signalant le manque de contacts avec les employeurs locaux. Ils distinguent l'apprentissage d'une technique de l'accès effectif à un emploi. Améliorer le second suppose un accompagnement que le seul contenu des cours ne remplace pas. » Cela justifie la réponse : Savoir faire un travail ne garantit pas d'obtenir un poste."},{"number":35,"points":26,"passage":"Un service accorde aux équipes le choix de leurs méthodes, mais maintient des objectifs de sécurité communs. Cette autonomie exige de discuter les décisions et d'expliquer les écarts. Elle ne consiste donc pas à laisser chaque salarié agir sans règle. Les responsables doivent davantage accompagner et moins contrôler chaque geste. Des réunions courtes permettent de partager les solutions testées et de demander de l'aide.","question":"Comment l'autonomie est-elle présentée ?","options":["Comme l'absence de toute règle","Comme un retour au contrôle permanent","Comme une suppression du rôle des responsables","Comme une responsabilité encadrée par des exigences partagées"],"correct":"D","explanation":"Le passage indique : « Un service accorde aux équipes le choix de leurs méthodes, mais maintient des objectifs de sécurité communs. Cette autonomie exige de discuter les décisions et d'expliquer les écarts. Elle ne consiste donc pas à laisser chaque salarié agir sans règle. Les responsables doivent davantage accompagner et moins contrôler chaque geste. » Cela justifie la réponse : Comme une responsabilité encadrée par des exigences partagées."},{"number":36,"points":33,"passage":"Le terme de compétence « transférable » laisse parfois croire qu'une aptitude passe sans effort d'un métier à un autre. Une organisatrice d'événements sait gérer des imprévus, mais doit apprendre les règles particulières du secteur hospitalier où elle souhaite travailler. Son expérience constitue un appui, pas une équivalence totale. Reconnaître les acquis et identifier ce qui reste à apprendre sont deux démarches complémentaires. Son accompagnatrice lui propose de décrire plusieurs situations de son ancien emploi et d'identifier ce qui peut être réutilisé. Elle devra ensuite découvrir les contraintes du soin, les responsabilités et les limites propres au nouveau poste. Ce travail évite deux erreurs opposées : prétendre qu'elle repart de zéro ou supposer que son expérience lui permet déjà de tout maîtriser. Les employeurs rencontrés apprécient cette manière de présenter à la fois des ressources et des besoins de formation.","question":"Quelle nuance est apportée à la notion de transfert ?","options":["Une aptitude utile doit être adaptée au nouveau contexte","Toute expérience antérieure devient inutile","Un changement de secteur dispense de formation","Les règles professionnelles sont identiques partout"],"correct":"A","explanation":"Le passage indique : « Reconnaître les acquis et identifier ce qui reste à apprendre sont deux démarches complémentaires. » Cela justifie la réponse : Une aptitude utile doit être adaptée au nouveau contexte."},{"number":37,"points":33,"passage":"Un logiciel réduit le temps consacré aux tâches administratives. La direction veut utiliser tout le temps libéré pour augmenter le nombre de dossiers. Les salariés proposent d'en consacrer une partie à l'accueil des cas complexes, jusqu'alors traités trop vite. Ils ne contestent pas l'outil, mais la seule définition quantitative de son bénéfice. Un gain de temps peut améliorer la qualité du travail sans se traduire intégralement par une hausse du volume. La direction avait d'abord présenté le changement comme une manière évidente de traiter davantage de demandes avec les mêmes moyens. Les équipes ont apporté des exemples où quelques minutes supplémentaires éviteraient un rappel, une erreur ou une démarche inutile au client. Elles proposent de mesurer ces effets avant de fixer de nouveaux objectifs.","question":"Quel débat le logiciel fait-il apparaître ?","options":["La nécessité d'interdire tout outil numérique","Le remplacement immédiat des salariés","La manière de répartir les bénéfices de la productivité","La disparition de tous les cas complexes"],"correct":"C","explanation":"Le passage indique : « Un gain de temps peut améliorer la qualité du travail sans se traduire intégralement par une hausse du volume. » Cela justifie la réponse : La manière de répartir les bénéfices de la productivité."},{"number":38,"points":33,"passage":"Dans un atelier, le meilleur réparateur devient responsable d'équipe. Il découvre que transmettre une consigne et résoudre un conflit demandent d'autres aptitudes que réparer une machine. L'entreprise avait considéré la promotion comme une récompense suffisante, sans prévoir de formation. L'expertise technique ne prépare pas automatiquement à l'accompagnement des personnes, même si elle peut en faciliter la compréhension du travail. Le salarié doit désormais distribuer les tâches, suivre les délais et accompagner des collègues dont les difficultés ne sont pas les siennes. Il continue parfois à reprendre les réparations lui-même, au risque de ne plus avoir de temps pour son nouveau rôle. Ses responsables organisent finalement un tutorat avec une personne d'un autre atelier. Ils souhaitent que la promotion reste une évolution choisie, et non une mise en difficulté présentée comme une récompense.","question":"Quelle erreur d'organisation est mise en évidence ?","options":["Confondre maîtrise technique et préparation au management","Maintenir des machines en état de fonctionnement","Considérer les conflits comme toujours utiles","Promouvoir un salarié connaissant l'atelier"],"correct":"A","explanation":"Le passage indique : « L'expertise technique ne prépare pas automatiquement à l'accompagnement des personnes, même si elle peut en faciliter la compréhension du travail. » Cela justifie la réponse : Confondre maîtrise technique et préparation au management."},{"number":39,"points":33,"passage":"Une organisation souhaite diversifier ses recrutements. Elle affiche cet objectif, puis conserve des entretiens à une heure inaccessible aux personnes déjà en poste et exige des stages non rémunérés. Une association souligne le décalage entre l'intention et les conditions concrètes. L'ouverture réelle du recrutement suppose de revoir les procédures qui excluent des candidats, même quand elles semblent ordinaires aux recruteurs. Elle propose des créneaux alternatifs et une épreuve courte réalisée sur des documents fictifs. Les recruteurs craignent de perdre un moyen de comparaison habituel, mais acceptent d'observer les résultats. Le groupe de travail vérifiera notamment quels profils peuvent aller au bout des démarches. Il ne s'agit pas d'abaisser les compétences attendues pour le poste : il s'agit d'éviter que des conditions sans rapport direct avec ces compétences servent de filtre.","question":"Que faut-il changer selon cette association ?","options":["Les objectifs de sécurité des postes","Les compétences de tous les anciens salariés","Uniquement le graphisme des annonces","Les obstacles pratiques intégrés au recrutement"],"correct":"D","explanation":"Le passage indique : « L'ouverture réelle du recrutement suppose de revoir les procédures qui excluent des candidats, même quand elles semblent ordinaires aux recruteurs. » Cela justifie la réponse : Les obstacles pratiques intégrés au recrutement."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-04','tcf-reading-2026-11-reference-v3',$paper${"id":"tcf-reading-04","version":"tcf-reading-2026-11-reference-v3","title":"TCF Reading · Test 04","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"Le car pour Valmont partira du quai 6 au lieu du quai 2. L'heure de départ reste fixée à huit heures.\n\nUne équipe sera présente dans le hall pour orienter les passagers. Les billets déjà achetés restent valables sur ce départ.","question":"Que doit vérifier le voyageur ?","options":["Le numéro de sa place","Un nouvel horaire","Le prix du billet","Le nouveau quai"],"correct":"D","explanation":"Le passage indique : « Le car pour Valmont partira du quai 6 au lieu du quai 2. L'heure de départ reste fixée à huit heures. » Cela justifie la réponse : Le nouveau quai."},{"number":2,"points":3,"passage":"Le musée maritime accepte les billets de la veille après sa fermeture exceptionnelle. Aucun échange au guichet n'est nécessaire.\n\nLe personnel a été informé de cette mesure et vous indiquera les espaces ouverts.","question":"Comment utiliser un billet acheté pour la veille ?","options":["Acheter un second billet","Demander un remboursement obligatoire","Le présenter directement à l'entrée","L'envoyer par courrier"],"correct":"C","explanation":"Le passage indique : « Le musée maritime accepte les billets de la veille après sa fermeture exceptionnelle. Aucun échange au guichet n'est nécessaire. » Cela justifie la réponse : Le présenter directement à l'entrée."},{"number":3,"points":3,"passage":"La passerelle du port sera fermée aux cyclistes cet après-midi. Ils pourront emprunter le pont situé deux cents mètres plus loin.\n\nElle ajoute quelques minutes au trajet mais reste praticable avec une remorque pour enfant.","question":"Quel itinéraire est proposé aux cyclistes ?","options":["Prendre un bateau obligatoire","Traverser la passerelle à vélo","Attendre le lendemain","Passer par le pont voisin"],"correct":"D","explanation":"Le passage indique : « La passerelle du port sera fermée aux cyclistes cet après-midi. Ils pourront emprunter le pont situé deux cents mètres plus loin. » Cela justifie la réponse : Passer par le pont voisin."},{"number":4,"points":3,"passage":"Les bagages trouvés dans le train sont conservés au bureau de la gare, et non dans les consignes automatiques.\n\nLe service demande une description précise de l'objet et du trajet effectué. Une vérification sera faite avant toute restitution au propriétaire.","question":"Où chercher un bagage oublié ?","options":["Dans une consigne automatique","Au bureau de la gare","À l'arrêt du tramway","Dans le train suivant"],"correct":"B","explanation":"Le passage indique : « Les bagages trouvés dans le train sont conservés au bureau de la gare, et non dans les consignes automatiques. » Cela justifie la réponse : Au bureau de la gare."},{"number":5,"points":9,"passage":"Léa, n'achète pas encore le billet de retour. La famille qui m'accueille peut me recevoir deux jours de plus, mais je dois confirmer mon congé.\n\nJe préfère vérifier cette possibilité plutôt que changer deux fois la réservation et payer des frais inutiles.","question":"Pourquoi l'achat doit-il attendre ?","options":["Les billets sont tous gratuits","Le trajet est annulé définitivement","La durée du séjour reste incertaine","La famille refuse la visite"],"correct":"C","explanation":"Le passage indique : « Léa, n'achète pas encore le billet de retour. La famille qui m'accueille peut me recevoir deux jours de plus, mais je dois confirmer mon congé. » Cela justifie la réponse : La durée du séjour reste incertaine."},{"number":6,"points":9,"passage":"Notre auberge prête des draps, mais ne fournit pas de serviettes. La cuisine collective est ouverte jusqu'à vingt et une heures.\n\nLes voyageurs doivent aussi libérer leur lit avant dix heures le jour du départ.","question":"Que doit apporter le client ?","options":["Un réfrigérateur","Des draps","Une serviette","Une clé de cuisine"],"correct":"C","explanation":"Le passage indique : « Notre auberge prête des draps, mais ne fournit pas de serviettes. La cuisine collective est ouverte jusqu'à vingt et une heures. » Cela justifie la réponse : Une serviette."},{"number":7,"points":9,"passage":"Je préfère le train de nuit : il arrive tôt et m'évite une nuit d'hôtel. Il est plus lent que l'avion, mais cela ne me gêne pas.\n\nJe pourrai dormir pendant le trajet et commencer ma visite après le petit déjeuner.","question":"Quel avantage motive ce choix ?","options":["Arriver en soirée","Voyager sans réservation","Économiser une nuit d'hébergement","Atteindre la vitesse maximale"],"correct":"C","explanation":"Le passage indique : « Je préfère le train de nuit : il arrive tôt et m'évite une nuit d'hôtel. Il est plus lent que l'avion, mais cela ne me gêne pas. » Cela justifie la réponse : Économiser une nuit d'hébergement."},{"number":8,"points":9,"passage":"L'office propose une visite à pied gratuite, limitée à douze personnes. L'inscription est obligatoire pour éviter de refuser des visiteurs au départ.\n\nLes départs ont lieu devant l'office et durent environ une heure.","question":"Pourquoi faut-il s'inscrire ?","options":["La visite nécessite un passeport","Le nombre de participants est limité","L'entrée de la ville est payante","Le guide travaille uniquement en ligne"],"correct":"B","explanation":"Le passage indique : « L'office propose une visite à pied gratuite, limitée à douze personnes. L'inscription est obligatoire pour éviter de refuser des visiteurs au départ. » Cela justifie la réponse : Le nombre de participants est limité."},{"number":9,"points":9,"passage":"Chers voyageurs, votre arrêt habituel sera déplacé pendant le marché. Retrouvez le bus devant la poste, dans le même sens de circulation.\n\nLes voyageurs sont invités à prévoir quelques minutes de marche supplémentaires depuis leur arrêt habituel.","question":"Quel effet le marché a-t-il sur le trajet ?","options":["Tous les arrêts deviennent payants","Le bus circule en sens inverse","Le lieu d'embarquement change","Le service cesse pour la journée"],"correct":"C","explanation":"Le passage indique : « Chers voyageurs, votre arrêt habituel sera déplacé pendant le marché. Retrouvez le bus devant la poste, dans le même sens de circulation. » Cela justifie la réponse : Le lieu d'embarquement change."},{"number":10,"points":9,"passage":"Nous louerons des vélos à l'arrivée plutôt que transporter les nôtres. La location est un peu chère, mais évite les changements de train avec du matériel.\n\nLe magasin près de la gare garde les vélos réservés jusqu'à notre arrivée.","question":"Quelle contrainte veut-on éviter ?","options":["Réserver un hébergement","Transporter les vélos pendant les correspondances","Pédaler sur place","Acheter des boissons"],"correct":"B","explanation":"Le passage indique : « Nous louerons des vélos à l'arrivée plutôt que transporter les nôtres. La location est un peu chère, mais évite les changements de train avec du matériel. » Cela justifie la réponse : Transporter les vélos pendant les correspondances."},{"number":11,"points":15,"passage":"Une gare transforme un ancien guichet en salle d'attente chauffée. La vente de billets reste possible sur les bornes et auprès d'un agent mobile.\n\nL'espace dispose de bancs et d'une prise pour recharger un téléphone. Les voyageurs ont demandé cet aménagement après plusieurs hivers passés à attendre sur un quai exposé au vent. L'agent mobile circulera surtout pendant les heures d'affluence, avec un appareil permettant de consulter les horaires et les tarifs. La municipalité souhaite conserver une présence utile dans la gare sans rouvrir exactement l'ancien service. Un bilan sera réalisé après les premiers mois pour vérifier les besoins.","question":"Quel service subsiste malgré la transformation ?","options":["Une aide humaine pour acheter un billet","La vente de repas chauds","La gratuité de tous les billets","Un guichet ouvert sans interruption"],"correct":"A","explanation":"Le passage indique : « Une gare transforme un ancien guichet en salle d'attente chauffée. La vente de billets reste possible sur les bornes et auprès d'un agent mobile. » Cela justifie la réponse : Une aide humaine pour acheter un billet."},{"number":12,"points":15,"passage":"Le village limite les groupes guidés dans ses ruelles étroites. Il accueille toujours les visiteurs individuels et cherche surtout à éviter des blocages devant les maisons.\n\nLes visites accompagnées devront désormais respecter un horaire et s'arrêter sur quelques emplacements plus larges. Les guides recevront une carte des zones sensibles afin de préparer leur parcours. La mairie souhaite maintenir les rencontres avec les commerçants, sans empêcher les résidents de sortir de chez eux.","question":"Pourquoi limiter les groupes ?","options":["Supprimer les visites culturelles","Réserver les rues aux voitures","Interdire tout tourisme","Faciliter la circulation dans les ruelles"],"correct":"D","explanation":"Le passage indique : « Le village limite les groupes guidés dans ses ruelles étroites. Il accueille toujours les visiteurs individuels et cherche surtout à éviter des blocages devant les maisons. » Cela justifie la réponse : Faciliter la circulation dans les ruelles."},{"number":13,"points":15,"passage":"Pour découvrir la région, Adam choisit une carte valable plusieurs jours sur les bus locaux. Elle coûte davantage qu'un trajet simple, mais couvre ses excursions successives.\n\nIl a repéré plusieurs villages accessibles sans voiture, ainsi qu'un sentier dont le départ se trouve près d'un arrêt. Les horaires de retour lui permettent de rester assez longtemps sur place. Il a aussi prévu une journée libre pour adapter son programme à la météo. La carte ne comprend pas les activités touristiques, mais il estime que la simplicité des déplacements lui sera déjà très utile.","question":"Pourquoi cette carte lui convient-elle ?","options":["Elle inclut un hôtel","Il ne prendra jamais le bus","Il prévoit plusieurs déplacements","Elle interdit les correspondances"],"correct":"C","explanation":"Le passage indique : « Pour découvrir la région, Adam choisit une carte valable plusieurs jours sur les bus locaux. Elle coûte davantage qu'un trajet simple, mais couvre ses excursions successives. » Cela justifie la réponse : Il prévoit plusieurs déplacements."},{"number":14,"points":15,"passage":"Une association teste un pédibus scolaire. Des adultes accompagnent les enfants à pied selon un parcours fixe ; les familles rejoignent le groupe aux arrêts indiqués.\n\nLe parcours évite les rues les plus circulées et comporte plusieurs points de rassemblement clairement indiqués. Les accompagnateurs vérifient les présences avant de repartir, mais les parents restent responsables d'amener les enfants au bon endroit. L'école soutient l'essai pendant quelques semaines. Elle souhaite savoir si les familles peuvent s'organiser régulièrement, car une initiative agréable le premier jour ne devient pas automatiquement une solution fiable pour toute l'année.","question":"Qu'est-ce qu'un pédibus dans ce texte ?","options":["Un autocar touristique","Un prêt de bicyclettes","Un trajet à pied accompagné","Un cours de conduite"],"correct":"C","explanation":"Le passage indique : « Une association teste un pédibus scolaire. Des adultes accompagnent les enfants à pied selon un parcours fixe ; les familles rejoignent le groupe aux arrêts indiqués. » Cela justifie la réponse : Un trajet à pied accompagné."},{"number":15,"points":15,"passage":"Un refuge de montagne demande de réserver le dîner avant midi. Les produits sont acheminés en quantité limitée ; les randonneurs non inscrits peuvent dormir sans bénéficier du repas.\n\nLe responsable indique le menu prévu lors de la réservation et demande de signaler les besoins particuliers. Les quantités sont préparées selon le nombre annoncé, car il est difficile de se réapprovisionner rapidement à cette altitude. Le refuge préfère expliquer cette organisation avant l'arrivée plutôt que laisser croire qu'un repas supplémentaire peut toujours être improvisé à la fin d'une longue journée de marche.","question":"Pourquoi anticiper la réservation du dîner ?","options":["Réserver toutes les chambres","Éviter les frais de transport des clients","Adapter des provisions limitées","Permettre un service nocturne permanent"],"correct":"C","explanation":"Le passage indique : « Un refuge de montagne demande de réserver le dîner avant midi. Les produits sont acheminés en quantité limitée ; les randonneurs non inscrits peuvent dormir sans bénéficier du repas. » Cela justifie la réponse : Adapter des provisions limitées."},{"number":16,"points":15,"passage":"Le guide enregistre les témoignages des habitants pour une promenade sonore. Les lieux sont présentés par ceux qui y vivent, et pas seulement par des informations historiques officielles.\n\nDes récits décrivent par exemple le travail au port, les jeux dans une ancienne cour et les commerces disparus. Les visiteurs suivent une carte et déclenchent les enregistrements devant les lieux concernés. Les témoignages sont présentés avec leur date et leur contexte. L'équipe ne veut pas remplacer toute recherche historique par des souvenirs : elle souhaite ajouter une perspective quotidienne à la découverte.","question":"Quelle particularité offre cette promenade ?","options":["La parole des habitants enrichit la visite","Les informations historiques sont interdites","Le visiteur doit devenir guide","Les monuments sont tous reconstruits"],"correct":"A","explanation":"Le passage indique : « Le guide enregistre les témoignages des habitants pour une promenade sonore. Les lieux sont présentés par ceux qui y vivent, et pas seulement par des informations historiques officielles. » Cela justifie la réponse : La parole des habitants enrichit la visite."},{"number":17,"points":15,"passage":"Après l'ouverture d'une piste cyclable, la commune interroge aussi ceux qui ne l'utilisent pas. Leurs réponses peuvent révéler des obstacles que les cyclistes réguliers ne remarquent plus.\n\nCertaines personnes évoquent un manque de stationnement sûr à l'arrivée, d'autres un carrefour qui leur fait peur. Ces réponses ne demandent pas toutes le même investissement. Le service technique les comparera aux observations faites sur le terrain. La commune veut éviter de conclure trop vite qu'une piste peu fréquentée serait inutile ou que tous les habitants devraient simplement changer leurs habitudes.","question":"Pourquoi consulter les non-utilisateurs ?","options":["Les obliger à acheter un vélo","Comprendre ce qui freine l'usage","Fixer le prix des voitures","Remplacer les cyclistes dans l'enquête"],"correct":"B","explanation":"Le passage indique : « Après l'ouverture d'une piste cyclable, la commune interroge aussi ceux qui ne l'utilisent pas. Leurs réponses peuvent révéler des obstacles que les cyclistes réguliers ne remarquent plus. » Cela justifie la réponse : Comprendre ce qui freine l'usage."},{"number":18,"points":15,"passage":"Un hôtel proche de la gare garde gratuitement les sacs après le départ des clients. Le service ne prolonge pas l'accès aux chambres, qui doivent être libérées à onze heures.\n\nLes sacs seront étiquetés et rangés dans une pièce fermée, accessible avec l'aide du personnel. Les voyageurs pourront ainsi poursuivre leur visite avant de rejoindre leur train. L'hôtel rappelle toutefois que les objets précieux doivent rester avec leurs propriétaires. Il souhaite rendre ce service pratique sans créer de confusion sur l'heure de départ.","question":"Quelle distinction faut-il faire ?","options":["Les chambres deviennent des consignes publiques","Les sacs doivent quitter l'hôtel à onze heures","Le dépôt inclut une nouvelle nuit","Déposer ses sacs ne permet pas de garder sa chambre"],"correct":"D","explanation":"Le passage indique : « Un hôtel proche de la gare garde gratuitement les sacs après le départ des clients. Le service ne prolonge pas l'accès aux chambres, qui doivent être libérées à onze heures. » Cela justifie la réponse : Déposer ses sacs ne permet pas de garder sa chambre."},{"number":19,"points":15,"passage":"La ville ajoute des plans lisibles à hauteur des enfants dans les stations. Ils indiquent des repères simples, sans remplacer la signalisation générale.\n\nLes enfants ont participé au choix des dessins, après avoir essayé plusieurs versions dans une station témoin. Les adultes peuvent également utiliser ces repères lorsqu'ils découvrent le réseau. Les noms des lignes et les règles de sécurité restent communs à tous ; l'objectif est d'ajouter une manière de lire l'espace, sans créer deux réseaux d'informations contradictoires.","question":"Quel objectif est poursuivi ?","options":["Rendre l'orientation plus accessible aux jeunes","Réserver les stations aux familles","Augmenter le nombre de correspondances","Supprimer les noms des lignes"],"correct":"A","explanation":"Le passage indique : « La ville ajoute des plans lisibles à hauteur des enfants dans les stations. Ils indiquent des repères simples, sans remplacer la signalisation générale. » Cela justifie la réponse : Rendre l'orientation plus accessible aux jeunes."},{"number":20,"points":21,"passage":"Les excursions vers une île dépendaient d'un seul bateau matinal. Un second départ tardif a réparti les visiteurs dans la journée. Les commerçants observent moins d'affluence simultanée, mais souhaitent mesurer le résultat sur toute la saison. Les habitants espèrent aussi que cette répartition limitera les files devant les petites attractions de l'île. Des informations seront recueillies auprès des visiteurs ayant choisi chaque départ. Les responsables veulent notamment vérifier si le nouveau service permet des séjours plus agréables ou déplace simplement l'affluence vers une autre heure, sans résoudre les difficultés signalées.","question":"Quelle prudence accompagne le premier bilan ?","options":["Attendre une observation plus longue","Conclure à une baisse certaine des visiteurs","Fermer les commerces le matin","Supprimer immédiatement le second bateau"],"correct":"A","explanation":"Le passage indique : « Les excursions vers une île dépendaient d'un seul bateau matinal. Un second départ tardif a réparti les visiteurs dans la journée. Les commerçants observent moins d'affluence simultanée, mais souhaitent mesurer le résultat sur toute la saison. » Cela justifie la réponse : Attendre une observation plus longue."},{"number":21,"points":21,"passage":"Une entreprise rembourse une partie des déplacements professionnels en train, même lorsque le billet dépasse légèrement le prix d'un vol. Elle intègre au calcul le temps consacré aux transferts et aux attentes. Elle compare donc la durée entre les lieux de travail, plutôt qu'entre deux points de départ seulement. Les salariés doivent préciser les correspondances nécessaires et les possibilités de travailler pendant le trajet. Cette méthode n'impose pas une solution identique dans chaque cas, mais rend la décision moins dépendante d'une différence de tarif isolée.","question":"Quelle comparaison pratique-t-elle ?","options":["Elle exclut tout temps d'attente","Elle compare uniquement les repas","Elle retient seulement le prix affiché","Elle considère le trajet dans son ensemble"],"correct":"D","explanation":"Le passage indique : « Une entreprise rembourse une partie des déplacements professionnels en train, même lorsque le billet dépasse légèrement le prix d'un vol. Elle intègre au calcul le temps consacré aux transferts et aux attentes. » Cela justifie la réponse : Elle considère le trajet dans son ensemble."},{"number":22,"points":21,"passage":"Un circuit propose de rencontrer un artisan dans son atelier. Les visites sont suspendues pendant les commandes urgentes. L'activité touristique doit compléter le métier de l'artisan, pas empêcher sa production. Les petits groupes sont prévenus que les horaires peuvent changer et qu'ils ne verront pas toujours la même étape de fabrication. L'artisan préfère expliquer un travail réel plutôt que répéter une démonstration à la demande. L'office de tourisme accepte cette souplesse et propose d'autres visites lorsque l'atelier doit se concentrer sur sa production.","question":"Quel principe organise ces visites ?","options":["Respecter l'activité principale de l'atelier","Garantir une ouverture touristique permanente","Transformer toutes les commandes en visites","Remplacer le métier par des spectacles"],"correct":"A","explanation":"Le passage indique : « Un circuit propose de rencontrer un artisan dans son atelier. Les visites sont suspendues pendant les commandes urgentes. L'activité touristique doit compléter le métier de l'artisan, pas empêcher sa production. » Cela justifie la réponse : Respecter l'activité principale de l'atelier."},{"number":23,"points":21,"passage":"Dans une vallée, les navettes estivales sont devenues gratuites pour les visiteurs munis d'une réservation d'hébergement. Les habitants demandent un accès identique : ils utilisent les mêmes routes et subissent aussi la circulation touristique. La commune avait conçu l'offre pour réduire les trajets automobiles des vacanciers, mais les associations locales estiment que les besoins permanents ne doivent pas être oubliés. Les responsables souhaitent trouver un financement stable avant d'étendre la gratuité, afin de ne pas annoncer un droit qui disparaîtrait après une seule saison.","question":"Que revendiquent les habitants ?","options":["Un traitement équitable pour les trajets locaux","Une priorité pour les touristes étrangers","Le rétablissement des embouteillages","La fermeture des hébergements"],"correct":"A","explanation":"Le passage indique : « Dans une vallée, les navettes estivales sont devenues gratuites pour les visiteurs munis d'une réservation d'hébergement. Les habitants demandent un accès identique : ils utilisent les mêmes routes et subissent aussi la circulation touristique. » Cela justifie la réponse : Un traitement équitable pour les trajets locaux."},{"number":24,"points":21,"passage":"Une application conseille les itinéraires les plus rapides, mais ignore les escaliers. Une voyageuse avec poussette indique qu'un trajet légèrement plus long peut lui éviter un obstacle impossible à franchir seule. Les utilisateurs ont notamment besoin de savoir si un passage comporte des marches ou un trottoir difficile. La voyageuse demande que ces informations apparaissent avant le choix du trajet. Elle souhaite pouvoir décider elle-même du compromis acceptable entre durée et effort, plutôt que recevoir un itinéraire présenté comme idéal sur un seul critère.","question":"Quelle limite de l'application est montrée ?","options":["La poussette empêche tout déplacement","Tous les itinéraires sont trop longs","Les escaliers accélèrent chaque trajet","La rapidité ne garantit pas l'accessibilité"],"correct":"D","explanation":"Le passage indique : « Une application conseille les itinéraires les plus rapides, mais ignore les escaliers. Une voyageuse avec poussette indique qu'un trajet légèrement plus long peut lui éviter un obstacle impossible à franchir seule. » Cela justifie la réponse : La rapidité ne garantit pas l'accessibilité."},{"number":25,"points":21,"passage":"Un village réduit le stationnement au centre et ouvre un parking extérieur relié à pied. Les recettes du stationnement financent l'entretien du chemin. La mesure associe donc limitation de la voiture et amélioration de l'accès final. Les premiers visiteurs se plaignent d'une marche plus longue, mais les riverains constatent moins de circulation devant les commerces. La mairie prévoit de mieux signaler le parcours et d'y ajouter des bancs.","question":"Comment les recettes sont-elles utilisées ?","options":["Pour supprimer le chemin piéton","Pour faciliter la liaison depuis le parking","Pour distribuer des voitures","Pour agrandir les rues centrales"],"correct":"B","explanation":"Le passage indique : « Un village réduit le stationnement au centre et ouvre un parking extérieur relié à pied. Les recettes du stationnement financent l'entretien du chemin. La mesure associe donc limitation de la voiture et amélioration de l'accès final. » Cela justifie la réponse : Pour faciliter la liaison depuis le parking."},{"number":26,"points":21,"passage":"Une famille choisit deux étapes longues plutôt que sept villes en dix jours. Elle renonce à plusieurs sites célèbres, mais souhaite disposer de temps pour improviser et connaître la vie quotidienne sur place. La famille prévoit de cuisiner quelques repas et d'utiliser les transports locaux. Elle estime qu'un programme moins chargé permet aussi de réagir à une rencontre ou à une recommandation reçue sur place, plutôt que suivre constamment des réservations préparées à l'avance.","question":"Quelle conception du voyage adopte-t-elle ?","options":["Privilégier une découverte moins dispersée","Suivre tous les sites proposés par une agence","Visiter uniquement des aéroports","Multiplier les déplacements rapides"],"correct":"A","explanation":"Le passage indique : « Une famille choisit deux étapes longues plutôt que sept villes en dix jours. Elle renonce à plusieurs sites célèbres, mais souhaite disposer de temps pour improviser et connaître la vie quotidienne sur place. » Cela justifie la réponse : Privilégier une découverte moins dispersée."},{"number":27,"points":21,"passage":"Un organisateur de sorties invite les participants à indiquer leurs besoins avant de s'inscrire. Il précise ce qui peut être adapté et ce qui ne peut pas l'être. Cette transparence évite de confondre accueil bienveillant et accessibilité réellement assurée. Les participants peuvent ensuite discuter d'une aide éventuelle avec l'organisateur. Certaines sorties seront adaptées, tandis que d'autres demanderont un autre parcours ou un accompagnement différent.","question":"Pourquoi fournir ces précisions ?","options":["Refuser toute demande particulière","Réduire les informations avant l'achat","Garantir une adaptation illimitée","Permettre un choix éclairé selon les besoins"],"correct":"D","explanation":"Le passage indique : « Un organisateur de sorties invite les participants à indiquer leurs besoins avant de s'inscrire. Il précise ce qui peut être adapté et ce qui ne peut pas l'être. Cette transparence évite de confondre accueil bienveillant et accessibilité réellement assurée. » Cela justifie la réponse : Permettre un choix éclairé selon les besoins."},{"number":28,"points":21,"passage":"Une ligne rurale de bus semblait peu utilisée d'après les validations électroniques. Une enquête a révélé que plusieurs abonnements n'exigeaient pas de validation. Le comptage devait être corrigé avant de décider une suppression. Des comptages manuels ont été organisés sur plusieurs jours pour compléter les données. L'association d'usagers insiste pour que la décision ne repose pas uniquement sur un chiffre dont le mode de production était mal compris, alors que le service reste important pour des habitants sans voiture.","question":"Que révèle l'enquête ?","options":["Tous les trajets étaient fictifs","L'indicateur initial sous-estimait l'usage","Les abonnements étaient interdits","La ligne n'avait aucun passager"],"correct":"B","explanation":"Le passage indique : « Une ligne rurale de bus semblait peu utilisée d'après les validations électroniques. Une enquête a révélé que plusieurs abonnements n'exigeaient pas de validation. Le comptage devait être corrigé avant de décider une suppression. » Cela justifie la réponse : L'indicateur initial sous-estimait l'usage."},{"number":29,"points":21,"passage":"Une destination met en avant des séjours hors saison. Certains professionnels craignent des recettes plus faibles par semaine ; d'autres espèrent une activité moins concentrée et des emplois plus stables. Les hébergeurs soulignent cependant que l'ouverture prolongée demande du personnel, du chauffage et des services de transport. Le programme devra donc coordonner plusieurs acteurs, plutôt que compter sur une simple campagne de communication.","question":"Quel bénéfice possible est évoqué ?","options":["La disparition de tous les emplois saisonniers","Une meilleure continuité de l'activité","La fermeture définitive des hôtels","Une fréquentation identique chaque jour"],"correct":"B","explanation":"Le passage indique : « Une destination met en avant des séjours hors saison. Certains professionnels craignent des recettes plus faibles par semaine ; d'autres espèrent une activité moins concentrée et des emplois plus stables. » Cela justifie la réponse : Une meilleure continuité de l'activité."},{"number":30,"points":26,"passage":"Les classements touristiques comptent souvent les arrivées. Une commune préfère également regarder la durée des séjours et les dépenses réalisées auprès des entreprises locales. Un passage très bref peut encombrer le centre sans soutenir beaucoup son économie. Elle recueille ces informations auprès des hébergements et des commerçants, sans demander aux visiteurs de détailler toutes leurs dépenses. Elle veut mieux comprendre ce que la fréquentation apporte réellement à la vie économique de la commune.","question":"Quelle réserve porte sur le nombre d'arrivées ?","options":["Il ne décrit pas à lui seul les retombées locales","Il prouve toujours un séjour long","Il mesure exactement chaque dépense","Il ne peut jamais être compté"],"correct":"A","explanation":"Le passage indique : « Les classements touristiques comptent souvent les arrivées. Une commune préfère également regarder la durée des séjours et les dépenses réalisées auprès des entreprises locales. Un passage très bref peut encombrer le centre sans soutenir beaucoup son économie. » Cela justifie la réponse : Il ne décrit pas à lui seul les retombées locales."},{"number":31,"points":26,"passage":"Un billet unique facilite les correspondances entre deux réseaux. Pourtant, les horaires restent mal coordonnés. Les voyageurs gagnent en simplicité d'achat, mais continuent à perdre du temps à attendre. L'intégration tarifaire représente une étape, pas une solution complète. Les deux réseaux préparent maintenant leurs changements ensemble. Les voyageurs demandent notamment des correspondances possibles le soir, car un billet pratique perd beaucoup de son intérêt lorsque le dernier véhicule part avant l'arrivée du premier.","question":"Que manque-t-il principalement ?","options":["Une coordination des horaires","Un troisième moyen de paiement","Une hausse des prix","Une interdiction de changer de réseau"],"correct":"A","explanation":"Le passage indique : « Un billet unique facilite les correspondances entre deux réseaux. Pourtant, les horaires restent mal coordonnés. Les voyageurs gagnent en simplicité d'achat, mais continuent à perdre du temps à attendre. L'intégration tarifaire représente une étape, pas une solution complète. » Cela justifie la réponse : Une coordination des horaires."},{"number":32,"points":26,"passage":"Le terme de voyage « authentique » est parfois utilisé pour vendre une expérience préparée à l'avance. Cela ne la rend pas nécessairement sans intérêt. La difficulté apparaît lorsque les visiteurs croient découvrir une vie quotidienne spontanée alors qu'ils assistent à une mise en scène conçue pour eux. Les visiteurs sauront alors ce qu'ils découvrent et pourront poser des questions sur la vie du lieu au-delà de la scène présentée.","question":"Quel problème l'auteur souligne-t-il ?","options":["Le manque de clarté sur la nature de l'expérience","L'inutilité de toute rencontre organisée","L'impossibilité de préparer une visite utile","L'absence totale de visiteurs intéressés"],"correct":"A","explanation":"Le passage indique : « Le terme de voyage « authentique » est parfois utilisé pour vendre une expérience préparée à l'avance. Cela ne la rend pas nécessairement sans intérêt. La difficulté apparaît lorsque les visiteurs croient découvrir une vie quotidienne spontanée alors qu'ils assistent à une mise en scène conçue pour eux. » Cela justifie la réponse : Le manque de clarté sur la nature de l'expérience."},{"number":33,"points":26,"passage":"Installer une piste cyclable sur un axe isolé améliore un segment du trajet. Si elle s'arrête avant un carrefour dangereux, certaines personnes continueront à éviter le vélo. Pour elles, la sécurité du parcours dépend de son point le plus difficile, et non de sa seule longueur aménagée. Les associations demandent donc de regarder les ruptures du réseau et les lieux d'arrivée.","question":"Quelle priorité se dégage ?","options":["Augmenter seulement la longueur annoncée","Assurer la continuité des trajets sécurisés","Ignorer les carrefours","Réserver les pistes aux habitués"],"correct":"B","explanation":"Le passage indique : « Installer une piste cyclable sur un axe isolé améliore un segment du trajet. Si elle s'arrête avant un carrefour dangereux, certaines personnes continueront à éviter le vélo. Pour elles, la sécurité du parcours dépend de son point le plus difficile, et non de sa seule longueur aménagée. » Cela justifie la réponse : Assurer la continuité des trajets sécurisés."},{"number":34,"points":26,"passage":"Une ville historique fait payer l'accès à un belvédère pour financer sa restauration. Le débat ne porte pas seulement sur le tarif : certains habitants souhaitent pouvoir continuer à fréquenter un lieu qui appartenait à leurs promenades ordinaires. La conservation soulève ainsi une question d'usage local. La commune étudie plusieurs formules, dont un accès gratuit certains jours pour les résidents.","question":"Quel enjeu accompagne le financement ?","options":["Réserver la promenade aux donateurs","Maintenir une place aux usages des habitants","Transformer toutes les rues en musées","Interdire la restauration du monument"],"correct":"B","explanation":"Le passage indique : « Une ville historique fait payer l'accès à un belvédère pour financer sa restauration. Le débat ne porte pas seulement sur le tarif : certains habitants souhaitent pouvoir continuer à fréquenter un lieu qui appartenait à leurs promenades ordinaires. La conservation soulève ainsi une question d'usage local. » Cela justifie la réponse : Maintenir une place aux usages des habitants."},{"number":35,"points":26,"passage":"Des stations indiquent le temps moyen de correspondance. Une association demande d'ajouter une marge pour les personnes se déplaçant lentement. Une moyenne peut être exacte pour l'ensemble des voyageurs et néanmoins trompeuse pour une partie d'entre eux. L'information doit permettre d'anticiper cette variation. L'association ne demande pas que tous les trajets deviennent plus lents, mais que chacun puisse anticiper une correspondance réalisable avec ses capacités et ses bagages.","question":"Quelle amélioration est proposée ?","options":["Supprimer les correspondances","Remplacer tous les horaires par un prix","Rendre visibles les différences de temps de parcours","Annoncer une durée identique pour chacun"],"correct":"C","explanation":"Le passage indique : « Des stations indiquent le temps moyen de correspondance. Une association demande d'ajouter une marge pour les personnes se déplaçant lentement. Une moyenne peut être exacte pour l'ensemble des voyageurs et néanmoins trompeuse pour une partie d'entre eux. L'information doit permettre d'anticiper cette variation. » Cela justifie la réponse : Rendre visibles les différences de temps de parcours."},{"number":36,"points":33,"passage":"Une métropole vante une nouvelle liaison rapide avec son aéroport. Les affiches annoncent quinze minutes de trajet. Pour beaucoup d'usagers, il faut toutefois rejoindre la gare de départ, attendre le train puis parcourir les terminaux. Le chiffre annoncé reste exact entre deux points précis. Il devient trompeur lorsqu'il est compris comme la durée totale du déplacement. Les voyageurs qui connaissent déjà la liaison interprètent souvent correctement l'annonce. Ceux qui viennent pour la première fois peuvent au contraire organiser une correspondance trop courte. Une association propose d'afficher séparément le temps dans le train et des exemples de trajets complets depuis plusieurs quartiers. Le débat porte ainsi sur ce que l'on choisit de mesurer pour informer utilement, et sur l'écart entre une formule publicitaire vraie dans un cadre limité et l'expérience de ceux qui l'utilisent pour décider.","question":"Quel écart le texte met-il en évidence ?","options":["Celui entre les vitesses de deux avions","Celui entre une durée partielle et le trajet réellement vécu","Celui entre les horaires d'été et d'hiver","Celui entre deux prix de billets identiques"],"correct":"B","explanation":"Le passage indique : « Il devient trompeur lorsqu'il est compris comme la durée totale du déplacement. » Cela justifie la réponse : Celui entre une durée partielle et le trajet réellement vécu."},{"number":37,"points":33,"passage":"Une région encourage le tourisme à vélo. Elle finance des itinéraires, mais plusieurs hébergements refusent encore les séjours d'une seule nuit. Les cyclistes qui avancent chaque jour doivent alors s'éloigner de leur parcours ou modifier leurs étapes. Le développement d'un mode de voyage suppose une cohérence entre l'infrastructure et les services qui permettent effectivement de l'utiliser. Les hébergeurs expliquent que l'accueil d'une nuit demande presque autant de préparation qu'un séjour plus long. La région cherche donc des solutions de réservation et de bagagerie qui rendent cette clientèle plus facile à recevoir. Des voyageurs seront invités à tester le parcours complet avant une nouvelle campagne de promotion. Les élus souhaitent éviter de présenter les pistes comme une offre déjà suffisante, alors que les étapes demeurent difficiles à organiser.","question":"Quelle condition manque encore ?","options":["Des voitures pour accompagner chaque cycliste","Des séjours obligatoires d'une semaine","Des services d'hébergement adaptés à l'itinérance","La disparition des parcours balisés"],"correct":"C","explanation":"Le passage indique : « Le développement d'un mode de voyage suppose une cohérence entre l'infrastructure et les services qui permettent effectivement de l'utiliser. » Cela justifie la réponse : Des services d'hébergement adaptés à l'itinérance."},{"number":38,"points":33,"passage":"Un parc naturel limite les réservations estivales pour préserver certains sites. Des prestataires proposent en réponse des horaires très matinaux, hors du créneau réglementé. La fréquentation totale risque de rester inchangée, avec davantage de perturbations pour la faune. Une règle évaluée uniquement sur ses créneaux officiels peut déplacer la pression plutôt que la diminuer. Les gestionnaires vont donc observer l'ensemble de la journée, y compris les départs proposés hors des périodes habituelles. Les professionnels demandent des règles lisibles et applicables à tous, afin que certains ne profitent pas simplement d'un vide dans le calendrier. Le parc souhaite préserver la possibilité de découverte tout en diminuant la pression réelle. Il devra examiner les déplacements des visiteurs, mais aussi les moments où les animaux peuvent rester tranquilles. Cette expérience rappelle qu'une mesure apparemment respectée peut manquer son objectif si les comportements s'organisent autour de ses limites.","question":"Quelle conséquence imprévue est envisagée ?","options":["Une suppression automatique de toute visite","La fermeture de tous les prestataires","Une augmentation certaine de la biodiversité","Le déplacement de la fréquentation vers d'autres heures"],"correct":"D","explanation":"Le passage indique : « Une règle évaluée uniquement sur ses créneaux officiels peut déplacer la pression plutôt que la diminuer. » Cela justifie la réponse : Le déplacement de la fréquentation vers d'autres heures."},{"number":39,"points":33,"passage":"Les voyageurs souhaitent souvent être guidés vers des lieux moins fréquentés. Mais lorsqu'une plateforme recommande simultanément la même petite place à des milliers de personnes, elle transforme ce lieu discret en nouvelle attraction. Les informations qui dispersent individuellement les parcours peuvent ainsi concentrer collectivement les visiteurs. La gestion des flux exige d'observer les effets d'ensemble des recommandations, pas seulement leur utilité pour chaque utilisateur. Les habitants de ces nouveaux lieux peuvent alors subir une augmentation rapide du bruit et des passages, sans avoir été consultés. La plateforme envisage de varier ses suggestions et de travailler avec les responsables locaux. Elle souhaite conserver des conseils utiles sans transformer systématiquement chaque découverte en destination incontournable. Les spécialistes soulignent toutefois qu'une recommandation moins précise peut aussi être moins pratique pour le voyageur.","question":"Quel paradoxe est décrit ?","options":["Une information individuelle reste toujours sans effet collectif","Tous les voyageurs refusent les petites places","Les plateformes empêchent tout déplacement","Une recommandation de détour peut créer un nouveau point de concentration"],"correct":"D","explanation":"Le passage indique : « La gestion des flux exige d'observer les effets d'ensemble des recommandations, pas seulement leur utilité pour chaque utilisateur. » Cela justifie la réponse : Une recommandation de détour peut créer un nouveau point de concentration."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-05','tcf-reading-2026-11-reference-v3',$paper${"id":"tcf-reading-05","version":"tcf-reading-2026-11-reference-v3","title":"TCF Reading · Test 05","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"Déposez les piles usagées dans la boîte de l'accueil. Les ampoules doivent être apportées au magasin de bricolage voisin.\n\nUn agent peut expliquer les autres points de collecte. Merci de ne rien laisser à côté de la boîte.","question":"Où déposer les piles ?","options":["Dans la rue","Au rayon alimentaire","Dans le bac à papier","À l'accueil"],"correct":"D","explanation":"Le passage indique : « Déposez les piles usagées dans la boîte de l'accueil. Les ampoules doivent être apportées au magasin de bricolage voisin. » Cela justifie la réponse : À l'accueil."},{"number":2,"points":3,"passage":"La collecte des feuilles aura lieu jeudi. Les sacs en plastique ne seront pas acceptés ; utilisez les sacs en papier distribués en mairie.\n\nLes distributions de sacs se font aux horaires habituels.","question":"Quel contenant faut-il utiliser ?","options":["Un sac en papier","Un sac en plastique","Une boîte métallique fermée","Un seau de peinture"],"correct":"A","explanation":"Le passage indique : « La collecte des feuilles aura lieu jeudi. Les sacs en plastique ne seront pas acceptés ; utilisez les sacs en papier distribués en mairie. » Cela justifie la réponse : Un sac en papier."},{"number":3,"points":3,"passage":"En période de sécheresse, l'arrosage des pelouses est suspendu. Les jeunes arbres peuvent recevoir de l'eau avant huit heures.\n\nDes contrôles auront lieu pendant toute la période annoncée par la commune.","question":"Quel arrosage reste permis ?","options":["Celui des jeunes arbres tôt le matin","Celui des parkings toute la journée","Celui des routes en soirée","Celui des pelouses à midi"],"correct":"A","explanation":"Le passage indique : « En période de sécheresse, l'arrosage des pelouses est suspendu. Les jeunes arbres peuvent recevoir de l'eau avant huit heures. » Cela justifie la réponse : Celui des jeunes arbres tôt le matin."},{"number":4,"points":3,"passage":"Le café accepte vos tasses réutilisables propres. Les couvercles jetables ne sont plus fournis automatiquement ; demandez-en un si nécessaire.\n\nL'équipe souhaite réduire les petits déchets emportés après chaque vente. Cette organisation sera évaluée avec les clients au cours du mois prochain.","question":"Quelle nouvelle habitude est proposée ?","options":["Acheter un couvercle à chaque visite","Refuser toute boisson chaude","Rapporter des tasses sales","Utiliser sa propre tasse propre"],"correct":"D","explanation":"Le passage indique : « Le café accepte vos tasses réutilisables propres. Les couvercles jetables ne sont plus fournis automatiquement ; demandez-en un si nécessaire. » Cela justifie la réponse : Utiliser sa propre tasse propre."},{"number":5,"points":9,"passage":"Demain, apportons chacun une boîte pour le pique-nique. Je préparerai les boissons dans une grande gourde ; inutile d'acheter des bouteilles individuelles.\n\nNous pourrons tout rapporter après le repas au lieu de remplir les poubelles du parc. J'ai aussi prévu des couverts que nous laverons chez moi.","question":"Que cherche à limiter ce message ?","options":["La quantité de fruits","La durée du pique-nique","Le nombre de participants","Les contenants jetables"],"correct":"D","explanation":"Le passage indique : « Demain, apportons chacun une boîte pour le pique-nique. Je préparerai les boissons dans une grande gourde ; inutile d'acheter des bouteilles individuelles. » Cela justifie la réponse : Les contenants jetables."},{"number":6,"points":9,"passage":"L'atelier réparation accepte les grille-pain et les lampes. Les appareils à gaz sont exclus, car les bénévoles n'ont pas la qualification nécessaire.\n\nUn bénévole examinera d'abord l'objet pour vérifier si l'intervention est possible. Les réparations complexes seront orientées vers un professionnel du secteur.","question":"Pourquoi certains appareils sont-ils refusés ?","options":["Pour respecter les compétences disponibles","Pour limiter les lampes apportées","Parce que tout appareil ancien est interdit","Pour favoriser leur remplacement systématique"],"correct":"A","explanation":"Le passage indique : « L'atelier réparation accepte les grille-pain et les lampes. Les appareils à gaz sont exclus, car les bénévoles n'ont pas la qualification nécessaire. » Cela justifie la réponse : Pour respecter les compétences disponibles."},{"number":7,"points":9,"passage":"Je laisse une partie du jardin sans tonte cette année. Je garderai seulement un passage court pour accéder au cabanon.\n\nCe sera intéressant de voir quelles plantes apparaissent et si les insectes reviennent. Je prendrai quelques photographies pour comparer les changements au fil de la saison.","question":"Comment le jardin sera-t-il entretenu ?","options":["En tondant chaque jour toute la surface","En fermant le cabanon","Avec des zones volontairement non tondues","En supprimant toutes les plantes"],"correct":"C","explanation":"Le passage indique : « Je laisse une partie du jardin sans tonte cette année. Je garderai seulement un passage court pour accéder au cabanon. » Cela justifie la réponse : Avec des zones volontairement non tondues."},{"number":8,"points":9,"passage":"La visite du centre de tri est gratuite. Les enfants de moins de huit ans ne peuvent pas y participer pour des raisons de sécurité.\n\nLes groupes seront accompagnés dans les zones autorisées.","question":"Quelle condition concerne les enfants ?","options":["Acheter un billet spécial","Apporter des déchets dangereux","Venir sans adulte","Avoir au moins huit ans"],"correct":"D","explanation":"Le passage indique : « La visite du centre de tri est gratuite. Les enfants de moins de huit ans ne peuvent pas y participer pour des raisons de sécurité. » Cela justifie la réponse : Avoir au moins huit ans."},{"number":9,"points":9,"passage":"Chers membres, les gobelets consignés devront être rapportés avant la fermeture du festival pour récupérer la consigne. Ils ne sont pas des cadeaux promotionnels.\n\nLe point de retour se trouve près de la sortie principale.","question":"Que faut-il faire pour récupérer la somme déposée ?","options":["Le jeter dans une poubelle","Rapporter le gobelet à temps","Le conserver comme souvenir","Acheter un second billet"],"correct":"B","explanation":"Le passage indique : « Chers membres, les gobelets consignés devront être rapportés avant la fermeture du festival pour récupérer la consigne. Ils ne sont pas des cadeaux promotionnels. » Cela justifie la réponse : Rapporter le gobelet à temps."},{"number":10,"points":9,"passage":"Le concours de jardins récompense cette année les pratiques économes en eau. La présence de fleurs rares ne rapporte pas de points supplémentaires.\n\nLes participants présenteront leurs choix au jury. Des photographies prises à différentes périodes permettront aussi d'expliquer l'évolution du jardin et les difficultés rencontrées.","question":"Quel critère est privilégié ?","options":["Le prix des outils","La gestion de l'eau","La rareté des fleurs","La hauteur des clôtures"],"correct":"B","explanation":"Le passage indique : « Le concours de jardins récompense cette année les pratiques économes en eau. La présence de fleurs rares ne rapporte pas de points supplémentaires. » Cela justifie la réponse : La gestion de l'eau."},{"number":11,"points":15,"passage":"Une épicerie propose des produits en vrac. Les clients peuvent apporter leurs contenants, qui sont pesés vides avant d'être remplis.\n\nLe personnel retire ensuite ce poids du montant utilisé pour calculer le prix. Une démonstration est proposée aux nouveaux clients, car plusieurs personnes hésitent à se servir seules lors de leur première visite. Le magasin accepte des boîtes de tailles différentes, à condition qu'elles soient propres et adaptées au produit choisi. Il souhaite rendre cette formule simple sans promettre que tous les aliments pourront être transportés dans n'importe quel récipient. Les tarifs restent affichés au même endroit.","question":"Pourquoi pèse-t-on le contenant vide ?","options":["Pour fixer le prix du verre","Pour interdire les bocaux lourds","Pour ne facturer que le produit","Pour calculer l'âge du contenant"],"correct":"C","explanation":"Le passage indique : « Une épicerie propose des produits en vrac. Les clients peuvent apporter leurs contenants, qui sont pesés vides avant d'être remplis. » Cela justifie la réponse : Pour ne facturer que le produit."},{"number":12,"points":15,"passage":"Des élèves recensent les oiseaux près de leur école chaque vendredi. Ils observent au même endroit et à la même heure pour rendre les relevés comparables.\n\nLes élèves notent la météo et le nombre de personnes présentes, afin de conserver une trace des circonstances. Une association vérifie les espèces difficiles à identifier sur les photographies. L'école veut surtout apprendre à observer avec régularité, plutôt qu'annoncer un résultat spectaculaire après une seule séance.","question":"Pourquoi répéter les mêmes conditions ?","options":["Éviter toute prise de notes","Modifier le climat du quartier","Attirer de nouveaux oiseaux artificiels","Faciliter la comparaison des observations"],"correct":"D","explanation":"Le passage indique : « Des élèves recensent les oiseaux près de leur école chaque vendredi. Ils observent au même endroit et à la même heure pour rendre les relevés comparables. » Cela justifie la réponse : Faciliter la comparaison des observations."},{"number":13,"points":15,"passage":"Un composteur collectif ferme temporairement après des dépôts inadaptés. Les habitants recevront une démonstration avant sa réouverture.\n\nLes erreurs concernaient notamment les emballages et les restes trop volumineux. L'association installera des indications illustrées à proximité du bac et désignera des personnes de contact dans plusieurs immeubles. Les usagers pourront leur poser une question avant de déposer un produit inhabituel. Le comité souhaite que cette interruption serve à améliorer le fonctionnement, sans faire croire qu'un composteur se gère tout seul. Un premier contrôle sera organisé quelques semaines après la reprise.","question":"Quel problème la démonstration doit-elle résoudre ?","options":["Le manque de place pour les voitures","L'absence de jardin public","Les erreurs de dépôt","Le prix des légumes"],"correct":"C","explanation":"Le passage indique : « Un composteur collectif ferme temporairement après des dépôts inadaptés. Les habitants recevront une démonstration avant sa réouverture. » Cela justifie la réponse : Les erreurs de dépôt."},{"number":14,"points":15,"passage":"La commune remplace ses haies taillées par des espèces locales variées. Elle souhaite offrir des abris à différentes espèces plutôt qu'un décor identique toute l'année.\n\nLes plantations ont été choisies avec une pépinière et une association naturaliste. Certaines fleurissent au printemps, d'autres portent des fruits plus tard. Le calendrier d'entretien tiendra compte des périodes où les animaux utilisent les branches pour se reproduire. Les agents expliquent aux riverains que la haie pourra paraître moins uniforme sans être abandonnée. Une petite visite permettra de découvrir les espèces installées et de comprendre les fonctions recherchées, au-delà de leur seul aspect décoratif.","question":"Quel objectif guide ce remplacement ?","options":["Favoriser la diversité du vivant","Supprimer les abris d'animaux","Accroître la taille des parkings","Uniformiser tous les jardins"],"correct":"A","explanation":"Le passage indique : « La commune remplace ses haies taillées par des espèces locales variées. Elle souhaite offrir des abris à différentes espèces plutôt qu'un décor identique toute l'année. » Cela justifie la réponse : Favoriser la diversité du vivant."},{"number":15,"points":15,"passage":"Un magasin reprend les vêtements abîmés, mais demande de séparer les articles encore utilisables. Ceux-ci pourront être réemployés plutôt que transformés en fibres.\n\nDes bénévoles vérifient l'état des vêtements avant de les orienter vers les associations partenaires. Une petite couture ou un bouton remplacé permet parfois de remettre rapidement un article en circulation. Les tissus vraiment usés seront regroupés pour un autre traitement. Le magasin souhaite éviter que l'ensemble des dons soit considéré comme une matière indistincte. Il indiquera les résultats de la collecte pour expliquer les volumes réutilisés et ceux qui nécessitent une transformation plus importante.","question":"Pourquoi distinguer les deux catégories ?","options":["Refuser tous les tissus anciens","Éviter de trier les vêtements","Préserver la possibilité de réutilisation","Augmenter le prix des dons"],"correct":"C","explanation":"Le passage indique : « Un magasin reprend les vêtements abîmés, mais demande de séparer les articles encore utilisables. Ceux-ci pourront être réemployés plutôt que transformés en fibres. » Cela justifie la réponse : Préserver la possibilité de réutilisation."},{"number":16,"points":15,"passage":"Une association nettoie les berges sans entrer dans les roselières. Ces zones servent de refuge ; retirer les déchets ne doit pas déranger les oiseaux nicheurs.\n\nLes organisateurs ont préparé un parcours et expliqué les zones à éviter avant le départ. Les sacs seront transportés par les passages déjà fréquentés. Si un déchet se trouve dans un endroit sensible, un responsable décidera comment intervenir plus tard. Les bénévoles comprennent ainsi qu'une action de nettoyage ne se juge pas seulement au nombre de sacs remplis.","question":"Quelle précaution est prise ?","options":["Déplacer les nids sur la promenade","Éviter certains habitats pendant le nettoyage","Arracher toutes les plantes aquatiques","Accéder partout sans restriction"],"correct":"B","explanation":"Le passage indique : « Une association nettoie les berges sans entrer dans les roselières. Ces zones servent de refuge ; retirer les déchets ne doit pas déranger les oiseaux nicheurs. » Cela justifie la réponse : Éviter certains habitats pendant le nettoyage."},{"number":17,"points":15,"passage":"Des habitants comparent leurs consommations d'eau après l'installation de mousseurs. Ils relèvent aussi le nombre de personnes présentes pour ne pas attribuer toute variation au matériel.\n\nLes familles comparent des périodes de durée semblable et indiquent les changements de leurs habitudes. Un week-end avec des invités ou une longue absence peut peser sur le résultat. L'association les aide à lire les relevés sans transformer l'expérience en compétition. Elle veut savoir si l'équipement contribue à réduire la consommation dans des conditions ordinaires. Les participants discuteront ensuite des solutions les plus simples à conserver au quotidien, avec ou sans nouvelle installation.","question":"Que veulent-ils éviter ?","options":["Une baisse de la précision des compteurs","Une interprétation trop rapide des chiffres","Un partage des informations techniques","Un remplacement des robinets"],"correct":"B","explanation":"Le passage indique : « Des habitants comparent leurs consommations d'eau après l'installation de mousseurs. Ils relèvent aussi le nombre de personnes présentes pour ne pas attribuer toute variation au matériel. » Cela justifie la réponse : Une interprétation trop rapide des chiffres."},{"number":18,"points":15,"passage":"Une entreprise propose le prêt de vaisselle pour les fêtes. Les clients la rapportent sale ; le lavage collectif est organisé avec une machine adaptée.\n\nLes lots sont comptés avant chaque retour afin de repérer rapidement une pièce manquante. L'entreprise vérifie aussi que le nettoyage correspond au type de vaisselle proposé. Une fiche explique les horaires et les modalités de transport. Le responsable suivra les quantités réellement réutilisées au cours de la saison, ainsi que les déplacements nécessaires pour assurer les prêts, avant de dresser un bilan plus large.","question":"Quel service est inclus ?","options":["Le nettoyage après retour","La préparation des repas","Le transport des invités","La décoration des salles"],"correct":"A","explanation":"Le passage indique : « Une entreprise propose le prêt de vaisselle pour les fêtes. Les clients la rapportent sale ; le lavage collectif est organisé avec une machine adaptée. » Cela justifie la réponse : Le nettoyage après retour."},{"number":19,"points":15,"passage":"Le ramassage des déchets sur une plage se déroule après la marée haute. Les organisateurs vérifient les horaires pour ne pas exposer les participants à la montée des eaux.\n\nUn guide rappelle les limites du parcours et les points de rendez-vous en cas de séparation du groupe. Les zones difficiles d'accès resteront exclues, même si des déchets y sont visibles. Les participants sont invités à porter des chaussures fermées et à ne pas ramasser les objets dangereux à mains nues.","question":"Pourquoi choisir ce moment ?","options":["Éviter tout contact avec du sable","Réduire un risque pour les participants","Observer uniquement les poissons","Garantir la présence de touristes"],"correct":"B","explanation":"Le passage indique : « Le ramassage des déchets sur une plage se déroule après la marée haute. Les organisateurs vérifient les horaires pour ne pas exposer les participants à la montée des eaux. » Cela justifie la réponse : Réduire un risque pour les participants."},{"number":20,"points":21,"passage":"Un supermarché baisse le prix de produits proches de leur date limite. L'association partenaire rappelle que ces promotions ne doivent pas inciter à acheter plus que ce que l'on consommera réellement. Les clients recevront des indications de conservation et pourront acheter une petite quantité seulement. Le magasin souhaite écouler les produits encore utilisables, pas transformer l'urgence de la vente en prétexte à remplir inutilement les paniers. L'association propose de comparer les achats avec les besoins prévus pour les repas. Une réduction importante ne constitue une économie que si les aliments sont consommés dans les conditions nécessaires.","question":"Quelle limite accompagne la promotion ?","options":["Supprimer toutes les réductions","Jeter les produits avant leur date","Éviter de déplacer le gaspillage vers les foyers","Acheter les plus grandes quantités"],"correct":"C","explanation":"Le passage indique : « Un supermarché baisse le prix de produits proches de leur date limite. L'association partenaire rappelle que ces promotions ne doivent pas inciter à acheter plus que ce que l'on consommera réellement. » Cela justifie la réponse : Éviter de déplacer le gaspillage vers les foyers."},{"number":21,"points":21,"passage":"Une forêt accueille des promeneurs sur des chemins stabilisés. Les gestionnaires ferment certains sentiers après de fortes pluies : le sol humide s'abîme davantage sous les passages répétés. Les gardes ont observé des traces profondes dans certains passages très fréquentés. Ils préfèrent fermer quelques secteurs pendant une courte période plutôt que réparer plus tard un sentier fortement dégradé. Les promeneurs sont invités à suivre ces indications même lorsque la pluie a cessé et que la surface commence à sembler sèche.","question":"Quel motif explique les fermetures ?","options":["La fragilité temporaire du sol","L'absence de panneaux publicitaires","Le prix du bois","La volonté de supprimer toutes les promenades"],"correct":"A","explanation":"Le passage indique : « Une forêt accueille des promeneurs sur des chemins stabilisés. Les gestionnaires ferment certains sentiers après de fortes pluies : le sol humide s'abîme davantage sous les passages répétés. » Cela justifie la réponse : La fragilité temporaire du sol."},{"number":22,"points":21,"passage":"Une ville plante des arbres sur une place très minérale. Les habitants demandent aussi des points d'eau et des bancs. L'ombre sera utile, mais prendra plusieurs années à se développer. Les associations du quartier proposent des points de repos temporaires et une information sur les lieux frais déjà accessibles. Le service des espaces verts a présenté le rythme probable de croissance des plantations. La mairie souhaite éviter une promesse de confort immédiat que les arbres ne peuvent pas tenir.","question":"Pourquoi ajouter d'autres équipements ?","options":["Remplacer toute végétation","Empêcher les arbres de grandir","Répondre aux besoins avant la croissance des arbres","Accueillir uniquement les automobilistes"],"correct":"C","explanation":"Le passage indique : « Une ville plante des arbres sur une place très minérale. Les habitants demandent aussi des points d'eau et des bancs. L'ombre sera utile, mais prendra plusieurs années à se développer. » Cela justifie la réponse : Répondre aux besoins avant la croissance des arbres."},{"number":23,"points":21,"passage":"Une cantine réduit les portions servies d'avance et autorise les élèves à se resservir. Les déchets alimentaires diminuent sans limiter la quantité disponible pour ceux qui ont faim. Le personnel observe les retours de plateaux et demande aux enfants ce qui leur permet de se servir plus justement. Certains avaient l'habitude de prendre une grosse portion par crainte de manquer ensuite. Les équipes expliquent donc clairement que le complément reste possible.","question":"Quelle organisation est adoptée ?","options":["Distribuer le même volume obligatoire","Supprimer les seconds services","Adapter le premier service avec possibilité de complément","Réserver les repas aux grands élèves"],"correct":"C","explanation":"Le passage indique : « Une cantine réduit les portions servies d'avance et autorise les élèves à se resservir. Les déchets alimentaires diminuent sans limiter la quantité disponible pour ceux qui ont faim. » Cela justifie la réponse : Adapter le premier service avec possibilité de complément."},{"number":24,"points":21,"passage":"Des pêcheurs participent à un suivi des poissons de rivière. Ils notent également les journées sans capture, car une absence d'observation apporte elle aussi une information utile. Les fiches précisent le lieu, la durée et les conditions de chaque sortie. Une journée sans poisson peut s'expliquer de plusieurs façons, qui seront discutées avec les spécialistes. Le groupe souhaite construire une série cohérente plutôt qu'une collection de belles photographies de captures.","question":"Pourquoi noter les sorties sans prise ?","options":["Pour augmenter artificiellement les captures","Pour rendre les journées plus longues","Pour éviter un relevé limité aux résultats positifs","Pour remplacer les règles de pêche"],"correct":"C","explanation":"Le passage indique : « Des pêcheurs participent à un suivi des poissons de rivière. Ils notent également les journées sans capture, car une absence d'observation apporte elle aussi une information utile. » Cela justifie la réponse : Pour éviter un relevé limité aux résultats positifs."},{"number":25,"points":21,"passage":"Une zone commerciale promet des bâtiments moins énergivores. Une enquête relève toutefois l'allongement des trajets automobiles provoqué par son implantation éloignée. Les économies du bâtiment ne suffisent pas à décrire l'effet global du projet. Les responsables du projet reconnaissent l'intérêt des bâtiments performants, mais demandent une comparaison avec d'autres emplacements possibles. Les distances et les moyens de transport disponibles seront intégrés au dossier. Ils souhaitent éviter qu'un progrès mesuré dans les murs masque une dépense supplémentaire provoquée ailleurs.","question":"Quel élément faut-il aussi considérer ?","options":["La taille des étiquettes","Les déplacements liés à l'emplacement","Uniquement la couleur des murs","Le nombre d'affiches à l'entrée"],"correct":"B","explanation":"Le passage indique : « Une zone commerciale promet des bâtiments moins énergivores. Une enquête relève toutefois l'allongement des trajets automobiles provoqué par son implantation éloignée. Les économies du bâtiment ne suffisent pas à décrire l'effet global du projet. » Cela justifie la réponse : Les déplacements liés à l'emplacement."},{"number":26,"points":21,"passage":"Un agriculteur réserve une bande fleurie près de ses cultures. Elle occupe de la place, mais attire des insectes utiles. Il observe les résultats sur plusieurs saisons plutôt que promettre un bénéfice immédiat chaque année. Il a réservé un secteur témoin pour mieux comparer les évolutions avec les autres parcelles. Les variétés de fleurs ont été choisies selon leur calendrier et les conditions du sol. Certaines poussent moins bien la première année.","question":"Quelle attitude adopte-t-il ?","options":["Évaluer les effets dans la durée","Remplacer toutes les cultures par du béton","Garantir une récolte identique sans observation","Refuser toute présence d'insectes"],"correct":"A","explanation":"Le passage indique : « Un agriculteur réserve une bande fleurie près de ses cultures. Elle occupe de la place, mais attire des insectes utiles. Il observe les résultats sur plusieurs saisons plutôt que promettre un bénéfice immédiat chaque année. » Cela justifie la réponse : Évaluer les effets dans la durée."},{"number":27,"points":21,"passage":"Une bibliothèque d'objets prête des outils rarement utilisés. Son bilan inclut désormais leur entretien : un objet partagé longtemps peut être utile, mais un matériel rapidement cassé ne remplace pas durablement plusieurs achats. Les bénévoles contrôlent désormais les pièces sensibles et expliquent les gestes qui prolongent la durée d'utilisation. Ils enregistrent aussi les réparations pour savoir quels modèles résistent à des prêts fréquents.","question":"Quel facteur devient important dans le bilan ?","options":["La couleur des cartes de prêt","La distance entre les étagères","Le nombre de prospectus imprimés","La durée réelle d'utilisation du matériel"],"correct":"D","explanation":"Le passage indique : « Une bibliothèque d'objets prête des outils rarement utilisés. Son bilan inclut désormais leur entretien : un objet partagé longtemps peut être utile, mais un matériel rapidement cassé ne remplace pas durablement plusieurs achats. » Cela justifie la réponse : La durée réelle d'utilisation du matériel."},{"number":28,"points":21,"passage":"Un collectif installe un récupérateur d'eau pour le jardin partagé. Les réserves sont affectées en priorité aux jeunes plantations pendant les restrictions. La collecte ne signifie pas que l'eau devient illimitée. Les jardiniers suivront les volumes recueillis et les besoins de chaque secteur. Une pluie importante peut remplir le réservoir, mais une période longue sans précipitations le vide rapidement. Le collectif a choisi de prévoir ces variations dans ses règles.","question":"Quel principe de gestion est retenu ?","options":["Remplir les réservoirs avec des déchets","Vendre l'eau comme potable","Arroser toutes les surfaces sans limite","Réserver l'eau aux besoins prioritaires"],"correct":"D","explanation":"Le passage indique : « Un collectif installe un récupérateur d'eau pour le jardin partagé. Les réserves sont affectées en priorité aux jeunes plantations pendant les restrictions. La collecte ne signifie pas que l'eau devient illimitée. » Cela justifie la réponse : Réserver l'eau aux besoins prioritaires."},{"number":29,"points":21,"passage":"Une association propose une promenade nocturne pour observer les chauves-souris. Les participants éteignent les lampes orientées vers les refuges. Mieux voir n'autorise pas à perturber ce qu'ils viennent découvrir. Le guide présentera quelques repères sonores avant de commencer, puis choisira des points d'arrêt suffisamment éloignés des refuges. Les visiteurs pourront poser leurs questions après chaque observation pour limiter les mouvements.","question":"Quelle limite encadre l'observation ?","options":["Transformer les refuges en vitrines","Respecter les animaux même si cela réduit la visibilité","Toucher les animaux pour les identifier","Éclairer les refuges en permanence"],"correct":"B","explanation":"Le passage indique : « Une association propose une promenade nocturne pour observer les chauves-souris. Les participants éteignent les lampes orientées vers les refuges. Mieux voir n'autorise pas à perturber ce qu'ils viennent découvrir. » Cela justifie la réponse : Respecter les animaux même si cela réduit la visibilité."},{"number":30,"points":26,"passage":"Le recyclage est souvent présenté comme la dernière étape évidente d'un produit. Pourtant, certains mélanges de matières sont difficiles à séparer. Un designer travaille donc sur la conception initiale : réduire cette difficulté avant la vente peut rendre le traitement final plus efficace. Des matériaux faciles à identifier et des assemblages démontables peuvent simplifier le travail des centres de traitement. Le projet associe donc les fabricants aux personnes chargées de récupérer et de séparer les produits en fin d'usage.","question":"À quel moment souhaite-t-il agir ?","options":["Après la disparition de toute matière","Après l'abandon des déchets dans la nature","Uniquement pendant la collecte","Lors de la conception du produit"],"correct":"D","explanation":"Le passage indique : « Le recyclage est souvent présenté comme la dernière étape évidente d'un produit. Pourtant, certains mélanges de matières sont difficiles à séparer. Un designer travaille donc sur la conception initiale : réduire cette difficulté avant la vente peut rendre le traitement final plus efficace. » Cela justifie la réponse : Lors de la conception du produit."},{"number":31,"points":26,"passage":"Une entreprise remplace ses emballages par une version plus légère. Elle doit vérifier que les produits restent protégés. Si davantage d'articles arrivent cassés, les économies d'emballage peuvent être dépassées par le coût matériel des remplacements. L'équipe réalisera des essais de transport avant de généraliser le changement. Elle regardera les emballages économisés et les articles remplacés, afin de comparer les effets sur tout le parcours plutôt que sur un seul indicateur.","question":"Quelle relation le texte met-il en avant ?","options":["L'emballage et les pertes de produits doivent être évalués ensemble","Un emballage léger protège toujours mieux","La casse n'a aucun effet sur le bilan","Le remplacement des produits supprime les déchets"],"correct":"A","explanation":"Le passage indique : « Une entreprise remplace ses emballages par une version plus légère. Elle doit vérifier que les produits restent protégés. Si davantage d'articles arrivent cassés, les économies d'emballage peuvent être dépassées par le coût matériel des remplacements. » Cela justifie la réponse : L'emballage et les pertes de produits doivent être évalués ensemble."},{"number":32,"points":26,"passage":"Les arbres d'une avenue ont été choisis pour leur résistance à la chaleur. Un spécialiste demande aussi de varier les espèces. Une plantation homogène peut être vulnérable à une maladie qui touche précisément l'espèce retenue, même si chaque arbre supporte bien le climat. La ville choisira plusieurs variétés adaptées à ses contraintes et suivra leur état au fil des saisons. Le spécialiste veut éviter de remplacer une fragilité climatique par une autre dépendance, cette fois liée à une espèce dominante.","question":"Quel intérêt présente la diversité ?","options":["Accélérer automatiquement la croissance","Supprimer le besoin d'eau","Réduire une vulnérabilité collective","Garantir l'absence de toute maladie"],"correct":"C","explanation":"Le passage indique : « Les arbres d'une avenue ont été choisis pour leur résistance à la chaleur. Un spécialiste demande aussi de varier les espèces. Une plantation homogène peut être vulnérable à une maladie qui touche précisément l'espèce retenue, même si chaque arbre supporte bien le climat. » Cela justifie la réponse : Réduire une vulnérabilité collective."},{"number":33,"points":26,"passage":"Une campagne demande aux ménages de réduire leurs déchets. Elle obtient davantage de résultats lorsqu'elle s'accompagne de solutions pratiques : réparateurs accessibles, commerces acceptant les contenants et collecte adaptée. L'information seule laisse parfois les personnes convaincues sans possibilité d'agir facilement. Ils veulent rendre les options possibles et compréhensibles, au lieu de demander aux habitants une pratique que leur environnement quotidien ne leur permet pas facilement d'adopter.","question":"Quelle condition favorise l'action ?","options":["La répétition exclusive des slogans","La suppression des services de collecte","L'augmentation des emballages imposés","La présence de moyens concrets accessibles"],"correct":"D","explanation":"Le passage indique : « Une campagne demande aux ménages de réduire leurs déchets. Elle obtient davantage de résultats lorsqu'elle s'accompagne de solutions pratiques : réparateurs accessibles, commerces acceptant les contenants et collecte adaptée. L'information seule laisse parfois les personnes convaincues sans possibilité d'agir facilement. » Cela justifie la réponse : La présence de moyens concrets accessibles."},{"number":34,"points":26,"passage":"Un chantier réemploie des portes récupérées. Certaines nécessitent plus de travail qu'un produit neuf. L'intérêt du réemploi ne se mesure donc pas seulement à la rapidité de pose : il dépend aussi des matériaux évités, des compétences mobilisées et de la durée de vie obtenue. Ils souhaitent comprendre quels objets sont réellement remis en service et dans quelles conditions, plutôt que compter tous les éléments récupérés comme des économies déjà assurées.","question":"Quelle approche du réemploi est proposée ?","options":["Une suppression de tout contrôle technique","Un rejet systématique des matériaux anciens","Une comparaison limitée au prix des poignées","Une appréciation dépassant la seule vitesse du chantier"],"correct":"D","explanation":"Le passage indique : « Un chantier réemploie des portes récupérées. Certaines nécessitent plus de travail qu'un produit neuf. L'intérêt du réemploi ne se mesure donc pas seulement à la rapidité de pose : il dépend aussi des matériaux évités, des compétences mobilisées et de la durée de vie obtenue. » Cela justifie la réponse : Une appréciation dépassant la seule vitesse du chantier."},{"number":35,"points":26,"passage":"Une réserve naturelle augmente sa surface protégée. Cependant, une route coupe la liaison entre deux secteurs. Pour certains animaux, la continuité des habitats compte autant que leur superficie. Ajouter des hectares séparés peut donc améliorer un indicateur sans résoudre la principale difficulté écologique. Leur travail porte ainsi sur l'organisation de l'espace, car certains besoins ne peuvent pas être satisfaits par une simple augmentation des surfaces figurant sur la carte.","question":"Quel enjeu complète celui de la superficie ?","options":["La taille des panneaux d'entrée","La connexion entre les habitats","Le nombre de parkings","La longueur des brochures touristiques"],"correct":"B","explanation":"Le passage indique : « Une réserve naturelle augmente sa surface protégée. Cependant, une route coupe la liaison entre deux secteurs. Pour certains animaux, la continuité des habitats compte autant que leur superficie. Ajouter des hectares séparés peut donc améliorer un indicateur sans résoudre la principale difficulté écologique. » Cela justifie la réponse : La connexion entre les habitats."},{"number":36,"points":33,"passage":"Une municipalité propose des sacs recyclables pour ses événements. Une équipe constate que beaucoup sont jetés avec des restes alimentaires, rendant leur traitement difficile. Le choix du matériau n'était qu'une partie du problème. Sans organisation de la collecte et consignes compréhensibles, une possibilité technique de recyclage ne devient pas nécessairement un recyclage effectif. Le service d'entretien doit savoir où déposer les sacs et comment distinguer les déchets acceptés. Les participants reçoivent aussi des consignes au moment où ils utilisent le matériel, plutôt qu'une longue notice uniquement visible avant l'événement. Les organisateurs mesureront donc les quantités effectivement orientées vers le bon traitement. Ils souhaitent comparer plusieurs options, y compris la réduction du nombre de sacs distribués. Le choix d'un matériau reste important, mais le bilan doit tenir compte des gestes et des équipements qui rendent sa récupération possible dans les conditions réelles du festival.","question":"Quelle distinction est essentielle ?","options":["Celle entre des événements gratuits et payants uniquement","Celle entre un matériau recyclable et son traitement réel","Celle entre deux couleurs de logo","Celle entre du matériel neuf et du matériel interdit"],"correct":"B","explanation":"Le passage indique : « Sans organisation de la collecte et consignes compréhensibles, une possibilité technique de recyclage ne devient pas nécessairement un recyclage effectif. » Cela justifie la réponse : Celle entre un matériau recyclable et son traitement réel."},{"number":37,"points":33,"passage":"Pour améliorer un cours d'eau, une association supprime certains obstacles et restaure des berges. Les résultats évoluent lentement et varient selon les saisons. Des financeurs souhaiteraient un chiffre simple chaque mois. L'équipe défend un suivi de plusieurs indicateurs sur plusieurs années. L'absence d'une hausse immédiate et régulière ne suffit pas à conclure à l'échec d'une restauration écologique. Certains effets se manifestent par le retour progressif d'espèces, d'autres par une meilleure circulation de l'eau ou par l'évolution de la végétation. Une crue peut modifier temporairement un relevé sans annuler les progrès réalisés. L'association souhaite expliquer ces variations aux habitants et aux partenaires financiers. Elle ne demande pas d'échapper à toute évaluation : elle veut un suivi capable de distinguer une difficulté durable d'une fluctuation normale.","question":"Pourquoi l'équipe refuse-t-elle un bilan mensuel unique ?","options":["Les saisons n'influencent jamais la rivière","Les effets du projet sont progressifs et variables","Aucune observation ne peut être réalisée","Les financeurs doivent décider sans information"],"correct":"B","explanation":"Le passage indique : « L'absence d'une hausse immédiate et régulière ne suffit pas à conclure à l'échec d'une restauration écologique. » Cela justifie la réponse : Les effets du projet sont progressifs et variables."},{"number":38,"points":33,"passage":"Une marque met en avant une forte baisse de consommation pour chaque appareil vendu. Dans le même temps, elle encourage les clients à multiplier les équipements connectés dans leur logement. Le bilan individuel s'améliore, mais le nombre d'appareils augmente. Une meilleure efficacité par unité ne garantit pas une réduction de la consommation totale. Les équipes commerciales mettent surtout en avant la performance du dernier modèle, sans toujours évoquer les achats supplémentaires qu'elles encouragent. Une association de consommateurs propose de présenter des exemples d'équipement complet d'un logement. Les ménages pourraient alors comparer plusieurs choix à usage semblable. La marque reconnaît qu'une amélioration technique peut être réelle tout en donnant un résultat différent à l'échelle de l'ensemble des ventes. Le débat porte donc à la fois sur les caractéristiques des appareils et sur les pratiques de renouvellement qu'un modèle commercial cherche à installer.","question":"Quelle conclusion peut-on tirer ?","options":["L'efficacité technique est impossible à mesurer","Chaque nouvel appareil réduit toujours la consommation totale","Il faut regarder aussi le volume des équipements utilisés","Le nombre d'appareils reste sans rapport avec l'énergie"],"correct":"C","explanation":"Le passage indique : « Une meilleure efficacité par unité ne garantit pas une réduction de la consommation totale. » Cela justifie la réponse : Il faut regarder aussi le volume des équipements utilisés."},{"number":39,"points":33,"passage":"La plantation d'arbres est parfois proposée comme compensation immédiate d'émissions présentes. Les arbres peuvent contribuer au stockage du carbone, mais leur croissance prend du temps et leur survie dépend des conditions locales. Annoncer une équivalence instantanée efface ces incertitudes et risque de faire passer une promesse future pour un résultat déjà acquis. Une sécheresse, une maladie ou un changement d'usage du terrain peut réduire le stockage attendu. Les responsables d'un programme sérieux doivent donc préciser le suivi, la durée et les hypothèses sur lesquelles reposent leurs estimations. Des plantations peuvent apporter d'autres bénéfices utiles, notamment pour le paysage et la biodiversité. Ces intérêts ne doivent toutefois pas servir à faire disparaître les différences entre une réduction déjà obtenue et un engagement à long terme. Les citoyens ont besoin de ces informations pour comprendre la portée réelle des annonces et comparer des actions différentes.","question":"Quelle critique est formulée ?","options":["Une promesse de stockage futur ne vaut pas un résultat immédiat garanti","Tout projet de plantation doit être abandonné","Les conditions locales n'affectent pas la survie des arbres","Les arbres ne grandissent jamais"],"correct":"A","explanation":"Le passage indique : « Annoncer une équivalence instantanée efface ces incertitudes et risque de faire passer une promesse future pour un résultat déjà acquis. » Cela justifie la réponse : Une promesse de stockage futur ne vaut pas un résultat immédiat garanti."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-06','tcf-reading-2026-11-reference-v3',$paper${"id":"tcf-reading-06","version":"tcf-reading-2026-11-reference-v3","title":"TCF Reading · Test 06","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"Le concert commence à dix-neuf heures, mais les portes ouvrent à dix-huit heures trente. Le placement est libre.\n\nLes spectateurs sont invités à venir assez tôt pour s'installer. Le personnel indiquera les accès sans réserver de fauteuil particulier.","question":"À partir de quand peut-on entrer ?","options":["Vingt heures","Dix-neuf heures trente","Dix-huit heures précises","Dix-huit heures trente"],"correct":"D","explanation":"Le passage indique : « Le concert commence à dix-neuf heures, mais les portes ouvrent à dix-huit heures trente. Le placement est libre. » Cela justifie la réponse : Dix-huit heures trente."},{"number":2,"points":3,"passage":"La galerie ferme lundi pour changer d'exposition. Les visites reprendront mardi, avec les mêmes horaires.\n\nLes œuvres fragiles seront déplacées par l'équipe technique. Aucun accueil de groupe ne sera assuré pendant cette installation.","question":"Pourquoi la galerie ferme-t-elle ?","options":["Pour réduire ses horaires","Pour installer une exposition","Pour organiser un concert","Pour vendre le bâtiment"],"correct":"B","explanation":"Le passage indique : « La galerie ferme lundi pour changer d'exposition. Les visites reprendront mardi, avec les mêmes horaires. » Cela justifie la réponse : Pour installer une exposition."},{"number":3,"points":3,"passage":"Les costumes prêtés doivent être rendus vendredi avant midi. Déposez-les à la réception sans les laver ; un nettoyage adapté est prévu.\n\nUne fiche permettra de signaler une déchirure ou une pièce perdue.","question":"Que faut-il éviter ?","options":["Laver soi-même les costumes","Les rapporter vendredi matin","Les rendre avant midi","Utiliser la réception"],"correct":"A","explanation":"Le passage indique : « Les costumes prêtés doivent être rendus vendredi avant midi. Déposez-les à la réception sans les laver ; un nettoyage adapté est prévu. » Cela justifie la réponse : Laver soi-même les costumes."},{"number":4,"points":3,"passage":"La répétition de la chorale se tient cette semaine dans la petite salle. L'entrée habituelle reste ouverte.\n\nLes partitions et le matériel seront transportés par les bénévoles. Les chanteurs sont invités à consulter le panneau à l'entrée avant de s'installer.","question":"Qu'est-ce qui change ?","options":["Le jour de la répétition","Le groupe de chanteurs","La salle de répétition","La porte d'entrée"],"correct":"C","explanation":"Le passage indique : « La répétition de la chorale se tient cette semaine dans la petite salle. L'entrée habituelle reste ouverte. » Cela justifie la réponse : La salle de répétition."},{"number":5,"points":9,"passage":"Je ne pourrai pas jouer dimanche. Ma remplaçante connaît déjà la partition ; nous répéterons ensemble samedi pour préparer le passage.\n\nElle souhaite surtout revoir les transitions et l'ordre des entrées. Je lui transmettrai aussi mes annotations pour éviter de lui laisser des détails à découvrir au dernier moment.","question":"Pourquoi une répétition supplémentaire est-elle prévue ?","options":["Préparer un remplacement","Vendre les instruments","Choisir la date du concert","Composer une nouvelle œuvre"],"correct":"A","explanation":"Le passage indique : « Je ne pourrai pas jouer dimanche. Ma remplaçante connaît déjà la partition ; nous répéterons ensemble samedi pour préparer le passage. » Cela justifie la réponse : Préparer un remplacement."},{"number":6,"points":9,"passage":"L'atelier de gravure fournit encres et papier. Apportez une blouse : les taches sont difficiles à enlever.\n\nLes manches longues sont recommandées pour protéger les vêtements. L'animateur montrera les gestes à réaliser avant de commencer le premier tirage.","question":"Quel objet doit apporter le participant ?","options":["Du papier","De l'encre","Une blouse","Une presse"],"correct":"C","explanation":"Le passage indique : « L'atelier de gravure fournit encres et papier. Apportez une blouse : les taches sont difficiles à enlever. » Cela justifie la réponse : Une blouse."},{"number":7,"points":9,"passage":"Bonjour, votre réservation est conservée jusqu'à vingt minutes avant le spectacle. Sans confirmation, la place pourra être proposée à une autre personne.\n\nVous pouvez confirmer en ligne ou par téléphone. Cette règle permet à la billetterie de proposer les places non utilisées sans retarder le début de la représentation.","question":"Quel risque existe sans confirmation ?","options":["Le spectacle commence plus tôt","La salle devient privée","La place peut être réattribuée","Le billet est envoyé par courrier"],"correct":"C","explanation":"Le passage indique : « Bonjour, votre réservation est conservée jusqu'à vingt minutes avant le spectacle. Sans confirmation, la place pourra être proposée à une autre personne. » Cela justifie la réponse : La place peut être réattribuée."},{"number":8,"points":9,"passage":"Nous exposons les photographies sans les noms des auteurs pendant la première visite. Les visiteurs pourront ainsi discuter des images avant de lire les biographies.\n\nLes noms seront ensuite présentés avec quelques informations sur le travail de chaque photographe.","question":"Quel est le but de ce choix ?","options":["Vendre les biographies séparément","Interdire les discussions","Cacher définitivement les artistes","Regarder d'abord les œuvres elles-mêmes"],"correct":"D","explanation":"Le passage indique : « Nous exposons les photographies sans les noms des auteurs pendant la première visite. Les visiteurs pourront ainsi discuter des images avant de lire les biographies. » Cela justifie la réponse : Regarder d'abord les œuvres elles-mêmes."},{"number":9,"points":9,"passage":"Le cinéma organise une séance calme : éclairage léger et son réduit. Les spectateurs peuvent sortir puis revenir sans gêner les autres.\n\nL'équipe souhaite accueillir les personnes gênées par les conditions d'une séance ordinaire, sans leur demander d'expliquer publiquement leur situation.","question":"À quel besoin cette séance répond-elle ?","options":["Un film réservé aux critiques","Une projection plus rapide","Une salle entièrement obscure","Un environnement sensoriel plus souple"],"correct":"D","explanation":"Le passage indique : « Le cinéma organise une séance calme : éclairage léger et son réduit. Les spectateurs peuvent sortir puis revenir sans gêner les autres. » Cela justifie la réponse : Un environnement sensoriel plus souple."},{"number":10,"points":9,"passage":"Je t'offre deux places pour la danse, mais pas de date fixe. Tu choisiras une représentation parmi celles du mois prochain.\n\nRéserve assez tôt si tu veux venir un samedi, car ces soirées se remplissent souvent rapidement. Nous pourrons y aller ensemble.","question":"Que peut décider le destinataire ?","options":["L'heure d'ouverture du théâtre","Le programme de la saison","Le nom des danseurs","La représentation à laquelle assister"],"correct":"D","explanation":"Le passage indique : « Je t'offre deux places pour la danse, mais pas de date fixe. Tu choisiras une représentation parmi celles du mois prochain. » Cela justifie la réponse : La représentation à laquelle assister."},{"number":11,"points":15,"passage":"Une troupe joue dans les villages sans salle équipée. Son décor léger se transporte dans une camionnette et s'adapte aux places publiques.\n\nLes comédiens ont construit des éléments qui peuvent changer de fonction et tenir dans un espace réduit. Une répétition sur place permet d'adapter les entrées et les déplacements au lieu du jour. Les habitants viennent parfois installer des chaises avant le spectacle. L'équipe ne cherche pas à reproduire une grande scène partout : elle veut conserver une qualité de jeu tout en acceptant les particularités de chaque village.","question":"Qu'est-ce qui facilite ces déplacements ?","options":["Une absence de répétitions","Un décor facilement transportable","Une scène permanente dans chaque village","Un spectacle sans interprètes"],"correct":"B","explanation":"Le passage indique : « Une troupe joue dans les villages sans salle équipée. Son décor léger se transporte dans une camionnette et s'adapte aux places publiques. » Cela justifie la réponse : Un décor facilement transportable."},{"number":12,"points":15,"passage":"Un musée prête des reproductions tactiles d'œuvres. Elles permettent d'explorer les formes sans toucher les originaux fragiles.\n\nLes objets ont été réalisés à une échelle permettant de sentir les contours et les volumes. Un médiateur explique les différences avec l'œuvre exposée, afin de ne pas présenter la copie comme une expérience identique. Les visiteurs peuvent poser des questions avant de revenir regarder l'original.","question":"Quel est leur intérêt ?","options":["Authentifier les œuvres vendues","Remplacer tous les originaux","Découvrir les formes par le toucher","Supprimer les visites guidées"],"correct":"C","explanation":"Le passage indique : « Un musée prête des reproductions tactiles d'œuvres. Elles permettent d'explorer les formes sans toucher les originaux fragiles. » Cela justifie la réponse : Découvrir les formes par le toucher."},{"number":13,"points":15,"passage":"La bibliothèque accueille un illustrateur en résidence. Il travaille sur son album et rencontre les lecteurs, sans assurer une permanence de dessin à la demande.\n\nL'illustrateur dispose d'une table de travail accessible pendant quelques heures annoncées. Il pourra montrer un carnet ou expliquer un choix de composition, selon l'étape de son projet. La bibliothèque veut rendre le processus de création plus visible, tout en laissant à l'artiste le temps nécessaire pour chercher et recommencer. Les rencontres avec les classes seront préparées séparément. Cette organisation doit éviter que la résidence devienne une succession de commandes rapides empêchant le travail prévu sur l'album.","question":"Quelle activité n'est pas promise ?","options":["Dessiner pour chaque demande individuelle","Rencontrer des lecteurs","Créer un album","Travailler sur place"],"correct":"A","explanation":"Le passage indique : « La bibliothèque accueille un illustrateur en résidence. Il travaille sur son album et rencontre les lecteurs, sans assurer une permanence de dessin à la demande. » Cela justifie la réponse : Dessiner pour chaque demande individuelle."},{"number":14,"points":15,"passage":"Une école de musique propose des instruments en prêt pendant le premier trimestre. Les débutants peuvent essayer avant d'investir dans un achat.\n\nLes enseignants présentent plusieurs modèles et vérifient que leur taille convient à l'élève. Les familles reçoivent des consignes d'entretien et peuvent signaler une difficulté pendant la période d'essai. À la fin du trimestre, un échange permet de décider s'il faut poursuivre ou explorer une autre possibilité. Le conservatoire souhaite éviter qu'un achat important soit réalisé avant que la personne ait découvert les exigences réelles de la pratique.","question":"Quel avantage est offert ?","options":["Tester un instrument avant de l'acheter","Éviter toute pratique personnelle","Recevoir un instrument définitivement gratuit","Choisir sans jamais essayer"],"correct":"A","explanation":"Le passage indique : « Une école de musique propose des instruments en prêt pendant le premier trimestre. Les débutants peuvent essayer avant d'investir dans un achat. » Cela justifie la réponse : Tester un instrument avant de l'acheter."},{"number":15,"points":15,"passage":"Les sous-titres d'un spectacle sont projetés au-dessus de la scène. L'équipe recommande les places centrales pour les lire confortablement.\n\nLors des essais, certaines personnes voyaient bien les comédiens mais devaient tourner constamment la tête pour suivre le texte. La billetterie donnera désormais des informations sur ces différences de visibilité. Les clients pourront choisir selon leurs besoins et les places disponibles. Le théâtre ne présente pas tous les sièges comme équivalents pour chaque usage. Il veut limiter les déceptions qui apparaissent lorsqu'un service annoncé existe techniquement, mais reste difficile à utiliser depuis une partie de la salle.","question":"Quel critère guide cette recommandation ?","options":["Le prix du programme","La proximité du vestiaire","La lisibilité des sous-titres","L'accès aux coulisses"],"correct":"C","explanation":"Le passage indique : « Les sous-titres d'un spectacle sont projetés au-dessus de la scène. L'équipe recommande les places centrales pour les lire confortablement. » Cela justifie la réponse : La lisibilité des sous-titres."},{"number":16,"points":15,"passage":"Une exposition montre les brouillons d'un auteur. Les corrections révèlent des choix successifs plutôt qu'un texte apparu immédiatement sous sa forme finale.\n\nLes visiteurs observent des phrases déplacées, des mots remplacés et parfois des pages presque entièrement abandonnées. Des notes expliquent le contexte de ces modifications. Les commissaires ont voulu rendre sensible le temps de recherche derrière un ouvrage connu. Ils ne présentent pas le brouillon comme un texte moins valable à corriger une dernière fois, mais comme une étape permettant de comprendre des décisions.","question":"Que découvrent les visiteurs ?","options":["Le travail progressif de l'écriture","Les revenus exacts de l'auteur","Une version sans aucune modification","La disparition de tous les manuscrits"],"correct":"A","explanation":"Le passage indique : « Une exposition montre les brouillons d'un auteur. Les corrections révèlent des choix successifs plutôt qu'un texte apparu immédiatement sous sa forme finale. » Cela justifie la réponse : Le travail progressif de l'écriture."},{"number":17,"points":15,"passage":"Un festival réserve des billets à prix réduit aux habitants du quartier. Ils doivent présenter un justificatif de domicile, pas une carte d'association.\n\nLes bénéficiaires pourront présenter une facture ou un document courant, sans remplir un dossier compliqué. L'association de quartier aidera les personnes qui rencontrent une difficulté lors de la réservation. Le festival souhaite retrouver un public qui vit près des salles mais ne les fréquente pas toujours. Les organisateurs vérifieront si les billets sont réellement utilisés, car une réduction annoncée ne suffit pas à créer une habitude de sortie ou à faire connaître le programme aux habitants.","question":"Quelle pièce est demandée ?","options":["Une adhésion associative","Un justificatif de domicile","Une attestation de voyage","Une carte professionnelle"],"correct":"B","explanation":"Le passage indique : « Un festival réserve des billets à prix réduit aux habitants du quartier. Ils doivent présenter un justificatif de domicile, pas une carte d'association. » Cela justifie la réponse : Un justificatif de domicile."},{"number":18,"points":15,"passage":"Pour un film documentaire, les témoins relisent leurs propos avant diffusion. Ils peuvent corriger une erreur factuelle sans imposer le montage final.\n\nLes échanges portent notamment sur les noms, les dates et les faits précis mentionnés à l'oral. Le réalisateur peut expliquer pourquoi certains passages sont raccourcis pour être compris par le public. Il souhaite construire une relation claire avec les témoins sans leur attribuer la responsabilité de tout le film. L'accord sur une citation ne signifie donc pas que chacun approuve l'ensemble du récit.","question":"Quel contrôle leur est accordé ?","options":["Décider de toutes les images","Choisir tous les autres témoins","Remplacer le réalisateur","Vérifier l'exactitude de leurs propos"],"correct":"D","explanation":"Le passage indique : « Pour un film documentaire, les témoins relisent leurs propos avant diffusion. Ils peuvent corriger une erreur factuelle sans imposer le montage final. » Cela justifie la réponse : Vérifier l'exactitude de leurs propos."},{"number":19,"points":15,"passage":"Un atelier d'écriture réunit débutants et auteurs réguliers. Chacun lit s'il le souhaite ; écouter les textes des autres constitue aussi une participation.\n\nLes animateurs proposent d'abord de petites consignes puis laissent un temps d'écriture silencieuse. Les textes ne sont pas classés du meilleur au moins réussi. Les échanges portent sur ce que l'on comprend, sur les effets recherchés et sur les possibilités de reprise. Le groupe veut favoriser des essais sans transformer chaque séance en évaluation publique.","question":"Quelle règle favorise l'accueil ?","options":["Seuls les auteurs expérimentés peuvent écouter","Les débutants doivent se taire","Tous doivent publier un livre","La lecture de son texte reste facultative"],"correct":"D","explanation":"Le passage indique : « Un atelier d'écriture réunit débutants et auteurs réguliers. Chacun lit s'il le souhaite ; écouter les textes des autres constitue aussi une participation. » Cela justifie la réponse : La lecture de son texte reste facultative."},{"number":20,"points":21,"passage":"Une salle diffuse les représentations en ligne pour les personnes éloignées. Elle conserve cependant des rencontres sur place, car les échanges informels après le spectacle comptent pour les habitués. Les captations sont proposées sur une période limitée après les représentations. L'équipe améliore le son et les sous-titres, sans prétendre que l'écran remplace exactement la salle. Elle souhaite toucher les personnes empêchées de se déplacer, tout en maintenant des occasions de discussion pour celles qui peuvent venir. Le bilan distinguera ces usages plutôt que les opposer comme deux publics nécessairement concurrents.","question":"Que veut-elle préserver ?","options":["L'absence de contact avec le public","Une dimension sociale de la sortie","La suppression des échanges spontanés","Une exclusivité complète sur place"],"correct":"B","explanation":"Le passage indique : « Une salle diffuse les représentations en ligne pour les personnes éloignées. Elle conserve cependant des rencontres sur place, car les échanges informels après le spectacle comptent pour les habitués. » Cela justifie la réponse : Une dimension sociale de la sortie."},{"number":21,"points":21,"passage":"Une ville commande une sculpture après une consultation. Les habitants choisissent l'emplacement et discutent des usages du lieu ; ils ne votent pas sur chaque détail artistique. Les réunions commencent par une présentation du travail de l'artiste et des contraintes techniques. Les participants peuvent expliquer comment ils traversent la place et où ils aiment s'arrêter. Le comité veut ainsi éviter qu'une œuvre soit installée sans rapport avec la vie du lieu. L'auteur conserve toutefois la responsabilité de ses choix formels, dans le cadre de la commande discutée.","question":"Quelle est la portée de la consultation ?","options":["Elle supprime le travail de l'artiste","Elle concerne l'insertion de l'œuvre dans l'espace public","Elle fixe tous les gestes du sculpteur","Elle décide du prix des billets"],"correct":"B","explanation":"Le passage indique : « Une ville commande une sculpture après une consultation. Les habitants choisissent l'emplacement et discutent des usages du lieu ; ils ne votent pas sur chaque détail artistique. » Cela justifie la réponse : Elle concerne l'insertion de l'œuvre dans l'espace public."},{"number":22,"points":21,"passage":"Un conservatoire ouvre des ateliers sans examen d'entrée. Les inscriptions augmentent, mais certains créneaux restent inaccessibles aux personnes travaillant le soir. Une enquête est proposée aux familles et aux adultes inscrits, avec une version accessible par téléphone. Le conservatoire étudie aussi des séances ponctuelles le week-end. Il ne veut pas considérer les absences comme la preuve que les personnes ne s'intéressent pas à la musique. Le bilan portera sur les conditions qui permettent effectivement de venir, pas uniquement sur l'absence d'examen annoncée dans la brochure.","question":"Quelle limite subsiste ?","options":["Un examen est obligatoire partout","Les ateliers ne disposent d'aucun enseignant","Les horaires peuvent encore exclure des participants","Aucun adulte ne souhaite apprendre"],"correct":"C","explanation":"Le passage indique : « Un conservatoire ouvre des ateliers sans examen d'entrée. Les inscriptions augmentent, mais certains créneaux restent inaccessibles aux personnes travaillant le soir. » Cela justifie la réponse : Les horaires peuvent encore exclure des participants."},{"number":23,"points":21,"passage":"Une librairie fait découvrir des auteurs peu présents dans les médias. Les ventes sont modestes au début, mais les échanges réguliers créent progressivement un public fidèle. Les lecteurs rencontrent les écrivains plusieurs fois, suivent la préparation d'un livre et recommandent ensuite certains titres à leurs proches. La librairie réserve une petite table à ces découvertes pour qu'elles ne disparaissent pas immédiatement des rayons. Elle sait que les recettes doivent rester suffisantes pour faire vivre le lieu.","question":"Quel effet est décrit ?","options":["Un succès immédiat garanti","Un abandon de tous les petits éditeurs","La disparition des rencontres","La construction lente d'un lectorat"],"correct":"D","explanation":"Le passage indique : « Une librairie fait découvrir des auteurs peu présents dans les médias. Les ventes sont modestes au début, mais les échanges réguliers créent progressivement un public fidèle. » Cela justifie la réponse : La construction lente d'un lectorat."},{"number":24,"points":21,"passage":"Des comédiens improvisent à partir de souvenirs recueillis dans un quartier. Ils préviennent que les scènes sont des créations inspirées des récits, pas des reconstitutions exactes. Les personnes rencontrées sont informées de cette transformation et peuvent assister à une répétition. Certaines reconnaissent un détail, d'autres découvrent une scène qui rassemble plusieurs expériences. Le spectacle sera accompagné d'une discussion sur cette différence, afin que le public puisse apprécier le travail de création et comprendre la manière dont les témoignages l'ont nourri.","question":"Pourquoi cette précision importe-t-elle ?","options":["Distinguer création artistique et fidélité documentaire","Remplacer tous les témoignages","Interdire toute interprétation","Garantir l'exactitude de chaque dialogue"],"correct":"A","explanation":"Le passage indique : « Des comédiens improvisent à partir de souvenirs recueillis dans un quartier. Ils préviennent que les scènes sont des créations inspirées des récits, pas des reconstitutions exactes. » Cela justifie la réponse : Distinguer création artistique et fidélité documentaire."},{"number":25,"points":21,"passage":"Un théâtre réduit son décor pour diminuer les transports. La mise en scène utilise davantage la lumière et les mouvements. La sobriété matérielle devient un choix artistique autant qu'une contrainte logistique. Les artistes ont d'abord testé les possibilités dans une petite salle, avec quelques éléments transformables. Certaines contraintes ont fait apparaître des solutions auxquelles ils n'avaient pas pensé auparavant. Le metteur en scène souhaite conserver cette recherche dans la version finale.","question":"Quelle conséquence dépasse la logistique ?","options":["L'abandon de toute création","L'évolution du langage scénique","La suppression de la mise en scène","L'obligation de jouer sans public"],"correct":"B","explanation":"Le passage indique : « Un théâtre réduit son décor pour diminuer les transports. La mise en scène utilise davantage la lumière et les mouvements. La sobriété matérielle devient un choix artistique autant qu'une contrainte logistique. » Cela justifie la réponse : L'évolution du langage scénique."},{"number":26,"points":21,"passage":"Une médiatrice recueille les impressions avant d'expliquer un tableau. Elle veut que les visiteurs osent regarder sans chercher immédiatement une interprétation autorisée. Les premières remarques sont accueillies sans chercher immédiatement à les corriger. Les explications viennent ensuite apporter des repères historiques ou techniques. Les visiteurs peuvent comparer ce qu'ils avaient ressenti et ce qu'ils comprennent après l'échange. Le musée souhaite ainsi éviter que la peur de se tromper empêche de regarder.","question":"Quel comportement encourage-t-elle ?","options":["Identifier le prix de vente avant tout","Formuler une perception personnelle","Répéter d'abord une réponse officielle","Éviter toute observation"],"correct":"B","explanation":"Le passage indique : « Une médiatrice recueille les impressions avant d'expliquer un tableau. Elle veut que les visiteurs osent regarder sans chercher immédiatement une interprétation autorisée. » Cela justifie la réponse : Formuler une perception personnelle."},{"number":27,"points":21,"passage":"Une collection privée est accessible sur rendez-vous. Son propriétaire publie des images en ligne, mais certaines fragilités matérielles justifient de limiter les visites physiques. Le nombre de visiteurs est adapté aux pièces et à leur capacité d'accueil. Certains documents restent accessibles uniquement sous forme de reproduction pour éviter des manipulations répétées. Les chercheurs peuvent contacter le responsable pour préciser leur demande.","question":"Pourquoi l'accès sur place est-il limité ?","options":["Pour réserver les images aux acheteurs","Pour supprimer toute consultation","Pour préserver les objets","Pour empêcher la recherche"],"correct":"C","explanation":"Le passage indique : « Une collection privée est accessible sur rendez-vous. Son propriétaire publie des images en ligne, mais certaines fragilités matérielles justifient de limiter les visites physiques. » Cela justifie la réponse : Pour préserver les objets."},{"number":28,"points":21,"passage":"Une maison d'édition publie simultanément un livre papier et une version audio. Les deux formats répondent à différents usages ; les éditeurs ne présentent pas l'un comme la disparition de l'autre. Les personnes qui écoutent pendant un trajet ne rencontrent pas les mêmes contraintes que celles qui consultent un passage à une table. Les équipes travaillent donc les deux versions avec des exigences propres, notamment pour la navigation et la qualité de la lecture.","question":"Quelle relation entre les formats est défendue ?","options":["Une hiérarchie juridique","Une opposition obligatoire","Une identité matérielle totale","Une complémentarité"],"correct":"D","explanation":"Le passage indique : « Une maison d'édition publie simultanément un livre papier et une version audio. Les deux formats répondent à différents usages ; les éditeurs ne présentent pas l'un comme la disparition de l'autre. » Cela justifie la réponse : Une complémentarité."},{"number":29,"points":21,"passage":"Un festival mesure aussi la satisfaction des bénévoles. Une organisation épuisante pourrait compromettre les éditions suivantes, même si le public actuel est nombreux. Le questionnaire porte sur la répartition des tâches, les pauses et la clarté des consignes. Les responsables veulent savoir si les nouveaux volontaires ont pu trouver leur place sans dépendre constamment des organisateurs habituels. Les réponses serviront à préparer l'année suivante.","question":"Pourquoi consulter les bénévoles ?","options":["Choisir les ventes de boissons uniquement","Calculer la météo future","Remplacer le public par les organisateurs","Évaluer la capacité à faire durer l'événement"],"correct":"D","explanation":"Le passage indique : « Un festival mesure aussi la satisfaction des bénévoles. Une organisation épuisante pourrait compromettre les éditions suivantes, même si le public actuel est nombreux. » Cela justifie la réponse : Évaluer la capacité à faire durer l'événement."},{"number":30,"points":26,"passage":"Un abonnement culturel donne accès à de nombreux lieux. Pourtant, les personnes qui ne connaissent pas les programmes l'utilisent peu. Un accompagnement à la découverte est ajouté : disposer d'un droit d'entrée ne suffit pas toujours à se sentir invité. Des présentations courtes et des échanges avec des lecteurs familiers sont donc proposés. La bibliothèque souhaite permettre une première visite concrète, sans supposer que tous les bénéficiaires savent déjà où aller ni comment choisir une activité.","question":"Quelle idée est soulignée ?","options":["L'accès matériel doit parfois être accompagné","Les lieux n'ont plus besoin de communiquer","Les programmes doivent rester confidentiels","Un abonnement crée automatiquement des habitudes"],"correct":"A","explanation":"Le passage indique : « Un abonnement culturel donne accès à de nombreux lieux. Pourtant, les personnes qui ne connaissent pas les programmes l'utilisent peu. Un accompagnement à la découverte est ajouté : disposer d'un droit d'entrée ne suffit pas toujours à se sentir invité. » Cela justifie la réponse : L'accès matériel doit parfois être accompagné."},{"number":31,"points":26,"passage":"Les restaurateurs d'une fresque conservent des traces de transformations anciennes. Leur objectif n'est pas de fabriquer une surface paraissant neuve, mais de rendre l'œuvre lisible en respectant son histoire. La restauration suppose donc des choix, pas un simple effacement du temps. Les notices expliquent les interventions anciennes et celles réalisées aujourd'hui. Les visiteurs pourront distinguer une réparation indispensable d'un choix de présentation.","question":"Quelle démarche adoptent-ils ?","options":["Préserver l'histoire matérielle de l'œuvre","Supprimer toutes les traces anciennes","Reproduire une peinture contemporaine","Remplacer la fresque par une photographie"],"correct":"A","explanation":"Le passage indique : « Les restaurateurs d'une fresque conservent des traces de transformations anciennes. Leur objectif n'est pas de fabriquer une surface paraissant neuve, mais de rendre l'œuvre lisible en respectant son histoire. La restauration suppose donc des choix, pas un simple effacement du temps. » Cela justifie la réponse : Préserver l'histoire matérielle de l'œuvre."},{"number":32,"points":26,"passage":"Un succès en ligne conduit un groupe à jouer dans une grande salle. Les musiciens découvrent que l'attention d'un public assis diffère des réactions fragmentées sur une plateforme. La notoriété numérique facilite la rencontre, mais ne dispense pas d'adapter le spectacle. Le groupe essaie plusieurs formats et observe comment les morceaux changent dans l'espace de la salle. Les retours du public aideront à préparer les prochains concerts, sans transformer chaque réaction immédiate en verdict définitif sur leur musique.","question":"Quelle nuance est apportée ?","options":["La scène interdit toute musique connue","La notoriété supprime le besoin de répétition","Le succès numérique ne prépare pas à tous les aspects de la scène","Un public en ligne est toujours identique au public présent"],"correct":"C","explanation":"Le passage indique : « Un succès en ligne conduit un groupe à jouer dans une grande salle. Les musiciens découvrent que l'attention d'un public assis diffère des réactions fragmentées sur une plateforme. La notoriété numérique facilite la rencontre, mais ne dispense pas d'adapter le spectacle. » Cela justifie la réponse : Le succès numérique ne prépare pas à tous les aspects de la scène."},{"number":33,"points":26,"passage":"Une exposition multiplie les écrans pour attirer les jeunes. Certains visiteurs apprécient l'interactivité ; d'autres regrettent de moins voir les objets. L'équipe réaménage des zones plus calmes. Elle ne renonce pas aux outils, mais cherche un équilibre entre médiation et présence des œuvres. Le parcours laisse cependant des moments où l'on peut simplement regarder une œuvre, sans devoir accomplir une action ou lire une nouvelle consigne.","question":"Quelle solution est retenue ?","options":["Remplacer tous les objets par des vidéos","Rééquilibrer les dispositifs et l'observation directe","Supprimer toute information sur les œuvres","Écarter les visiteurs critiques"],"correct":"B","explanation":"Le passage indique : « Une exposition multiplie les écrans pour attirer les jeunes. Certains visiteurs apprécient l'interactivité ; d'autres regrettent de moins voir les objets. L'équipe réaménage des zones plus calmes. Elle ne renonce pas aux outils, mais cherche un équilibre entre médiation et présence des œuvres. » Cela justifie la réponse : Rééquilibrer les dispositifs et l'observation directe."},{"number":34,"points":26,"passage":"Une œuvre participative invite chacun à ajouter un fragment. L'artiste fixe cependant une règle commune afin que les contributions puissent dialoguer. Participer n'équivaut donc pas à agir sans cadre. La liberté s'exerce dans une structure qui rend la création collective possible. La règle n'efface donc pas les différences individuelles : elle leur donne un espace où elles peuvent être perçues ensemble, plutôt que se masquer mutuellement.","question":"Quel rôle joue la règle ?","options":["Donner une cohérence à la participation","Transformer chaque participant en propriétaire exclusif","Supprimer les différences entre les fragments","Interdire toute contribution personnelle"],"correct":"A","explanation":"Le passage indique : « Une œuvre participative invite chacun à ajouter un fragment. L'artiste fixe cependant une règle commune afin que les contributions puissent dialoguer. Participer n'équivaut donc pas à agir sans cadre. La liberté s'exerce dans une structure qui rend la création collective possible. » Cela justifie la réponse : Donner une cohérence à la participation."},{"number":35,"points":26,"passage":"Les statistiques de fréquentation valorisent les grandes expositions. Un musée examine aussi les retours de petits groupes accompagnés sur plusieurs séances. Leur nombre est faible, mais leur relation aux œuvres devient plus approfondie. La quantité des entrées ne décrit pas à elle seule tous les effets culturels. Elles souhaitent mieux comprendre ce que les visiteurs découvrent et conservent de leur expérience, au-delà du simple passage devant une porte d'entrée.","question":"Quelle approche d'évaluation est proposée ?","options":["Supprimer les données sur le public","Exclure les petits groupes du bilan","Associer fréquentation et qualité des expériences","Compter uniquement les billets les plus chers"],"correct":"C","explanation":"Le passage indique : « Les statistiques de fréquentation valorisent les grandes expositions. Un musée examine aussi les retours de petits groupes accompagnés sur plusieurs séances. Leur nombre est faible, mais leur relation aux œuvres devient plus approfondie. La quantité des entrées ne décrit pas à elle seule tous les effets culturels. » Cela justifie la réponse : Associer fréquentation et qualité des expériences."},{"number":36,"points":33,"passage":"Une ville souhaite transformer un atelier d'artistes en attraction permanente. Les créateurs apprécient l'intérêt du public, mais craignent de devoir montrer un travail immédiatement compréhensible à toute heure. Certaines recherches exigent des essais sans résultat présentable. Rendre la création visible ne doit pas obliger à confondre le temps de recherche et celui de la représentation. Les artistes expliquent que des journées entières peuvent être nécessaires pour essayer une matière ou abandonner une piste. Une visite constante risquerait de les conduire à répéter les gestes les plus faciles à montrer, au détriment du travail qui justifie leur présence. Ils proposent des créneaux de rencontre annoncés et des moments protégés. La ville accepte d'observer cette organisation avant de fixer un calendrier permanent. L'intérêt du projet tient alors autant à la qualité des échanges possibles qu'au respect du processus que les visiteurs souhaitent découvrir.","question":"Quel risque les artistes identifient-ils ?","options":["La pression à présenter sans cesse un résultat","L'absence de toute possibilité de rencontre","La disparition de toute curiosité du public","L'obligation de quitter la ville dès l'ouverture"],"correct":"A","explanation":"Le passage indique : « Rendre la création visible ne doit pas obliger à confondre le temps de recherche et celui de la représentation. » Cela justifie la réponse : La pression à présenter sans cesse un résultat."},{"number":37,"points":33,"passage":"Un documentaire donne la parole à des habitants longtemps absents des médias. Le réalisateur refuse pourtant de présenter ces voix comme un groupe parfaitement homogène. Les désaccords font partie de leur expérience commune. Accorder une visibilité ne consiste pas à fabriquer une parole unique qui effacerait les différences internes. Certains témoins ont des intérêts proches mais des souvenirs contradictoires d'un même événement. Le réalisateur les laisse apparaître, en donnant au spectateur les éléments nécessaires pour comprendre leurs positions. Il refuse d'effacer les nuances simplement pour obtenir un récit plus facile à résumer. Les participants sont informés du cadre et peuvent vérifier leurs propres propos avant diffusion. Cette méthode ne prétend pas supprimer tous les choix du montage, mais rend moins plausible l'idée qu'une personne pourrait parler naturellement au nom de toutes celles qui partagent son lieu de vie.","question":"Quel principe de représentation défend-il ?","options":["Éliminer tous les désaccords au montage","Choisir uniquement les récits identiques","Présenter chaque habitant comme un adversaire","Montrer aussi la diversité au sein du groupe"],"correct":"D","explanation":"Le passage indique : « Accorder une visibilité ne consiste pas à fabriquer une parole unique qui effacerait les différences internes. » Cela justifie la réponse : Montrer aussi la diversité au sein du groupe."},{"number":38,"points":33,"passage":"Une plateforme recommande des livres proches de ceux déjà lus. Ce service aide à choisir, mais peut réduire les découvertes inattendues. Une libraire propose à ses clients un titre éloigné de leurs habitudes, en expliquant le lien possible avec leurs intérêts. Découvrir ne suppose pas forcément l'absence de repères, mais parfois un déplacement accompagné de ces repères. Elle demande parfois au lecteur quel passage il avait préféré et ce qui l'avait surpris. À partir de ces éléments, elle propose une autre forme de récit ou une période moins familière, en laissant la possibilité de refuser. Le conseil devient une invitation argumentée, pas un classement établi une fois pour toutes. Les clients peuvent revenir expliquer ce qu'ils ont apprécié ou abandonné. Cette relation permet de varier progressivement les propositions et de comprendre qu'une lecture difficile au début peut aussi ouvrir un intérêt durable, sans que cette issue soit garantie pour chacun.","question":"Quelle conception de la découverte est proposée ?","options":["Choisir sans tenir compte du lecteur","Ouvrir les habitudes grâce à une médiation","Interdire toute recommandation technique","Répéter uniquement les lectures déjà appréciées"],"correct":"B","explanation":"Le passage indique : « Découvrir ne suppose pas forcément l'absence de repères, mais parfois un déplacement accompagné de ces repères. » Cela justifie la réponse : Ouvrir les habitudes grâce à une médiation."},{"number":39,"points":33,"passage":"On associe parfois un grand nombre de visiteurs à la réussite d'un lieu culturel. Dans une petite salle, l'augmentation des entrées a réduit le temps d'échange et rendu certaines personnes moins à l'aise. L'équipe choisit des groupes plus petits malgré une baisse du chiffre annoncé. Le succès dépend ici de la relation rendue possible, et non de la seule capacité à remplir la salle. Les médiateurs pourront désormais adapter le parcours et laisser davantage de temps aux questions. La direction suivra les retours des visiteurs pour vérifier que le changement ne favorise pas seulement les personnes déjà familières des musées. Elle souhaite conserver une ouverture large, même avec moins de passages simultanés. Le choix n'oppose donc pas mécaniquement quantité et qualité : il cherche une organisation qui permette de mieux accueillir les publics visés, avec les moyens réellement disponibles.","question":"Quel arbitrage est assumé ?","options":["Réserver toutes les visites aux artistes","Abandonner les rencontres avec les visiteurs","Privilégier la qualité d'accueil sur le volume des entrées","Mesurer la réussite uniquement par le remplissage"],"correct":"C","explanation":"Le passage indique : « Le succès dépend ici de la relation rendue possible, et non de la seule capacité à remplir la salle. » Cela justifie la réponse : Privilégier la qualité d'accueil sur le volume des entrées."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-07','tcf-reading-2026-11-reference-v3',$paper${"id":"tcf-reading-07","version":"tcf-reading-2026-11-reference-v3","title":"TCF Reading · Test 07","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"Le marché couvert ferme à quatorze heures aujourd'hui. Les commandes déjà payées pourront être retirées jusqu'à quinze heures à l'entrée nord.\n\nPrésentez votre reçu au personnel chargé des retraits. Les stands alimentaires ne reprendront pas de vente après la fermeture annoncée.","question":"Quel service reste disponible après la fermeture ?","options":["L'ouverture de la poissonnerie","Le retrait de commandes payées","La livraison sans commande","L'achat libre sur tous les stands"],"correct":"B","explanation":"Le passage indique : « Le marché couvert ferme à quatorze heures aujourd'hui. Les commandes déjà payées pourront être retirées jusqu'à quinze heures à l'entrée nord. » Cela justifie la réponse : Le retrait de commandes payées."},{"number":2,"points":3,"passage":"Pour l'atelier pain, apportez un saladier. La farine et la levure sont fournies.\n\nLes participants travailleront par petits groupes. Un rangement collectif est prévu à la fin de la séance.","question":"Que doit apporter le participant ?","options":["De la levure","De la farine","Un saladier","Un four"],"correct":"C","explanation":"Le passage indique : « Pour l'atelier pain, apportez un saladier. La farine et la levure sont fournies. » Cela justifie la réponse : Un saladier."},{"number":3,"points":3,"passage":"Le distributeur de lait ne fonctionne qu'avec des bouteilles propres. Des bouteilles neuves sont vendues à côté.\n\nUn membre de l'équipe peut montrer comment remplir le récipient. Merci de laisser l'espace propre après votre passage.","question":"Quelle condition faut-il respecter ?","options":["Utiliser un contenant propre","Apporter un sac en papier","Acheter uniquement en espèces","Réserver une semaine avant"],"correct":"A","explanation":"Le passage indique : « Le distributeur de lait ne fonctionne qu'avec des bouteilles propres. Des bouteilles neuves sont vendues à côté. » Cela justifie la réponse : Utiliser un contenant propre."},{"number":4,"points":3,"passage":"Le menu végétarien doit être demandé lors de l'inscription au repas associatif, pas à l'arrivée.\n\nL'équipe préparera les quantités selon les demandes reçues. Elle ne pourra pas garantir un remplacement de plat au dernier moment.","question":"Quand faut-il signaler ce choix ?","options":["À l'entrée de la salle","Le lendemain du repas","Après le dessert","Au moment de l'inscription"],"correct":"D","explanation":"Le passage indique : « Le menu végétarien doit être demandé lors de l'inscription au repas associatif, pas à l'arrivée. » Cela justifie la réponse : Au moment de l'inscription."},{"number":5,"points":9,"passage":"J'ai remplacé le pique-nique par un déjeuner chez moi : la pluie est annoncée. Apporte toujours la salade, je préparerai le plat chaud.\n\nLes autres invités ont déjà été prévenus et garderont le même horaire. Nous mangerons autour de la grande table, puis pourrons sortir si le temps s'améliore.","question":"Qu'est-ce qui change dans le programme ?","options":["La personne préparant la salade","Le nombre d'invités","Le jour du rendez-vous","Le lieu du repas"],"correct":"D","explanation":"Le passage indique : « J'ai remplacé le pique-nique par un déjeuner chez moi : la pluie est annoncée. Apporte toujours la salade, je préparerai le plat chaud. » Cela justifie la réponse : Le lieu du repas."},{"number":6,"points":9,"passage":"Votre panier contient des légumes moins habituels. Une fiche de préparation est jointe ; vous pouvez aussi échanger un produit au point de retrait.\n\nLes bénévoles indiquent également les quantités habituelles pour éviter de préparer trop de nourriture.","question":"Quelle aide accompagne le panier ?","options":["Un restaurant réservé aux adhérents","Un cours obligatoire de jardinage","Des conseils pour préparer les légumes","Un remboursement de tous les achats"],"correct":"C","explanation":"Le passage indique : « Votre panier contient des légumes moins habituels. Une fiche de préparation est jointe ; vous pouvez aussi échanger un produit au point de retrait. » Cela justifie la réponse : Des conseils pour préparer les légumes."},{"number":7,"points":9,"passage":"Le restaurant ne réserve plus sa terrasse. Les tables sont attribuées sur place ; la réservation reste possible à l'intérieur.\n\nSi le temps reste agréable, vous pourrez demander une table extérieure à votre arrivée. Le personnel expliquera les disponibilités sans pouvoir les promettre à l'avance.","question":"Que garantit une réservation ?","options":["Une place en terrasse","Un repas gratuit","Une table en salle","Une heure de départ libre"],"correct":"C","explanation":"Le passage indique : « Le restaurant ne réserve plus sa terrasse. Les tables sont attribuées sur place ; la réservation reste possible à l'intérieur. » Cela justifie la réponse : Une table en salle."},{"number":8,"points":9,"passage":"Je préfère commander le petit gâteau pour six personnes. Nous serons huit, mais deux invités ne prennent jamais de dessert.\n\nNous partagerons les autres plats sans changer le reste du repas ni demander un format plus grand.","question":"Pourquoi choisir ce format ?","options":["Prévoir deux desserts par personne","Adapter la quantité aux personnes qui en mangeront","Conserver tout le gâteau pour le lendemain","Réduire le nombre d'invités"],"correct":"B","explanation":"Le passage indique : « Je préfère commander le petit gâteau pour six personnes. Nous serons huit, mais deux invités ne prennent jamais de dessert. » Cela justifie la réponse : Adapter la quantité aux personnes qui en mangeront."},{"number":9,"points":9,"passage":"La dégustation permet de goûter trois huiles avant achat. Aucun achat n'est imposé aux participants.\n\nLes organisateurs présenteront l'origine des produits et quelques usages possibles. Le rendez-vous est destiné aux curieux comme aux clients habituels du magasin.","question":"Quelle obligation est absente ?","options":["Acheter une huile","Respecter l'heure du rendez-vous","S'inscrire à la dégustation","Goûter dans le lieu prévu"],"correct":"A","explanation":"Le passage indique : « La dégustation permet de goûter trois huiles avant achat. Aucun achat n'est imposé aux participants. » Cela justifie la réponse : Acheter une huile."},{"number":10,"points":9,"passage":"Merci de ne pas déposer de plats faits maison dans le réfrigérateur solidaire. Seuls les produits dont la composition et la date sont identifiables sont acceptés.\n\nUne affiche rappelle les conditions d'accueil pour éviter que des aliments inutilisables soient déposés à côté du réfrigérateur.","question":"Pourquoi certains dépôts sont-ils exclus ?","options":["Pour réserver les aliments aux commerçants","Pour interdire les dons gratuits","Pour privilégier les emballages décoratifs","Pour disposer d'informations vérifiables sur les produits"],"correct":"D","explanation":"Le passage indique : « Merci de ne pas déposer de plats faits maison dans le réfrigérateur solidaire. Seuls les produits dont la composition et la date sont identifiables sont acceptés. » Cela justifie la réponse : Pour disposer d'informations vérifiables sur les produits."},{"number":11,"points":15,"passage":"Une ferme vend ses légumes selon les récoltes disponibles. Le contenu des paniers change chaque semaine ; un assortiment identique toute l'année n'est pas promis.\n\nLes adhérents choisissent un point de retrait et reçoivent les informations quelques jours avant la livraison. Une récolte abondante peut permettre un produit supplémentaire, tandis qu'un épisode de grêle oblige à revoir l'assortiment. Le producteur explique ces changements au lieu de remplacer systématiquement les légumes par des achats lointains. Le groupe souhaite conserver une relation claire entre ce qui pousse sur les terres et ce qui arrive dans les paniers.","question":"Quelle caractéristique faut-il accepter ?","options":["Un choix toujours identique","La variation saisonnière du panier","Une livraison quotidienne obligatoire","L'absence de légumes locaux"],"correct":"B","explanation":"Le passage indique : « Une ferme vend ses légumes selon les récoltes disponibles. Le contenu des paniers change chaque semaine ; un assortiment identique toute l'année n'est pas promis. » Cela justifie la réponse : La variation saisonnière du panier."},{"number":12,"points":15,"passage":"Une cantine présente un nouvel aliment en petite quantité avant de l'ajouter au menu. Les élèves peuvent le goûter sans devoir finir une grande portion.\n\nLe personnel de cuisine observe les retours et recueille les remarques sans distribuer de note. Les enseignants peuvent préparer la découverte en parlant de l'origine du produit. L'équipe souhaite distinguer le refus d'un goût inconnu et celui d'une préparation particulière.","question":"Quelle approche est choisie ?","options":["Une découverte progressive","Un changement de menu quotidien imposé","Une consommation forcée","La suppression de tout choix"],"correct":"A","explanation":"Le passage indique : « Une cantine présente un nouvel aliment en petite quantité avant de l'ajouter au menu. Les élèves peuvent le goûter sans devoir finir une grande portion. » Cela justifie la réponse : Une découverte progressive."},{"number":13,"points":15,"passage":"Le boulanger conserve une pâte d'une fournée à l'autre. Cette pratique demande un suivi régulier ; elle ne permet pas de laisser la préparation sans surveillance.\n\nLe boulanger vérifie l'odeur, la texture et le temps écoulé avant de préparer la suite. Il ajuste certains gestes selon la température de l'atelier. Les apprentis découvrent qu'une recette écrite ne suffit pas toujours à décider du bon moment. Le responsable leur demande de noter leurs observations et de comparer plusieurs fournées. Il souhaite transmettre cette attention au processus, plutôt que promettre une méthode qui fonctionnerait de manière identique sans aucun contrôle des conditions réelles.","question":"Que nécessite cette méthode ?","options":["Une attention continue à la préparation","Le remplacement de la farine par de l'eau","L'absence de toute organisation","L'arrêt définitif des fournées"],"correct":"A","explanation":"Le passage indique : « Le boulanger conserve une pâte d'une fournée à l'autre. Cette pratique demande un suivi régulier ; elle ne permet pas de laisser la préparation sans surveillance. » Cela justifie la réponse : Une attention continue à la préparation."},{"number":14,"points":15,"passage":"Une association partage une cuisine entre plusieurs petites entreprises. Les utilisateurs réservent des plages distinctes et nettoient après chaque passage.\n\nLes réservations passent par un tableau commun et les produits restent dans des espaces identifiés. Le responsable présente les équipements à chaque nouveau groupe. Il souhaite éviter qu'un gain économique sur le local entraîne des difficultés de propreté ou de rangement. Les utilisateurs ont donc rédigé des règles simples après avoir essayé plusieurs organisations. Un bilan mensuel permettra de revoir les points qui posent problème sans attendre qu'une dispute entre deux entreprises bloque l'ensemble du fonctionnement de la cuisine.","question":"Quelle règle rend le partage possible ?","options":["L'accès sans limite aux stocks des autres","La fermeture aux nouveaux producteurs","Le respect des créneaux et du nettoyage","La préparation simultanée sans réservation"],"correct":"C","explanation":"Le passage indique : « Une association partage une cuisine entre plusieurs petites entreprises. Les utilisateurs réservent des plages distinctes et nettoient après chaque passage. » Cela justifie la réponse : Le respect des créneaux et du nettoyage."},{"number":15,"points":15,"passage":"Le chef ajoute des indications d'allergènes au menu. Il demande néanmoins aux clients concernés d'en parler à l'équipe, car certaines préparations peuvent évoluer.\n\nLes serveurs disposent d'une fiche commune, mais sont invités à demander confirmation lorsqu'une information manque. Le restaurant souhaite que les clients puissent exprimer leurs besoins sans recevoir une assurance improvisée. Les responsables expliquent aussi les limites liées au travail dans une même cuisine. Ils préfèrent donner une réponse précise, même si elle oblige à renoncer à un plat, plutôt que présenter le menu comme une garantie identique pour toutes les situations ou toutes les modifications demandées pendant le service.","question":"Pourquoi un échange reste-t-il nécessaire ?","options":["Les ingrédients peuvent changer","La cuisine refuse toute question","Les allergies disparaissent au restaurant","Les indications sont volontairement fausses"],"correct":"A","explanation":"Le passage indique : « Le chef ajoute des indications d'allergènes au menu. Il demande néanmoins aux clients concernés d'en parler à l'équipe, car certaines préparations peuvent évoluer. » Cela justifie la réponse : Les ingrédients peuvent changer."},{"number":16,"points":15,"passage":"Un jardin pédagogique cultive plusieurs variétés d'une même tomate. Les enfants comparent formes et goûts plutôt que classer toutes les tomates dans une seule catégorie.\n\nChaque groupe suit quelques plants et note leurs changements avant les récoltes. Une dégustation sera organisée lorsque les fruits seront mûrs. Les enseignants demandent aux enfants de décrire ce qu'ils observent avec leurs propres mots. Ils ne souhaitent pas désigner une variété gagnante une fois pour toutes : certaines conviennent mieux à une salade, d'autres à une sauce.","question":"Quel apprentissage est visé ?","options":["Éviter toute dégustation","Mémoriser le prix des serres","Reconnaître une diversité au sein d'un aliment","Choisir uniquement la plus grosse tomate"],"correct":"C","explanation":"Le passage indique : « Un jardin pédagogique cultive plusieurs variétés d'une même tomate. Les enfants comparent formes et goûts plutôt que classer toutes les tomates dans une seule catégorie. » Cela justifie la réponse : Reconnaître une diversité au sein d'un aliment."},{"number":17,"points":15,"passage":"Une conserverie collecte les surplus de plusieurs fermes. Les producteurs récupèrent une partie des bocaux pour les vendre plus tard.\n\nLes volumes sont annoncés par les exploitants avant chaque tournée. L'équipe vérifie l'état des produits et choisit des recettes adaptées aux quantités disponibles. Les agriculteurs ne récupèrent donc pas nécessairement un produit identique à celui qu'ils ont apporté, mais une préparation qu'ils pourront conserver. Une étiquette indique l'origine et la composition. Le projet cherche à donner une valeur aux excédents, sans encourager volontairement une production inutile.","question":"Quel problème cette activité aide-t-elle à résoudre ?","options":["L'absence totale de matières premières","Le besoin d'importer tous les légumes","La perte de récoltes difficiles à écouler immédiatement","Le manque de magasins d'électroménager"],"correct":"C","explanation":"Le passage indique : « Une conserverie collecte les surplus de plusieurs fermes. Les producteurs récupèrent une partie des bocaux pour les vendre plus tard. » Cela justifie la réponse : La perte de récoltes difficiles à écouler immédiatement."},{"number":18,"points":15,"passage":"Un atelier apprend à cuisiner avec des restes. Il distingue les aliments encore utilisables de ceux dont la conservation a été insuffisante.\n\nLes participants apportent des exemples de leur quotidien et discutent des délais au réfrigérateur. Les animateurs insistent sur l'importance de noter les dates et de refroidir correctement certaines préparations. Ils ne présentent pas toute transformation comme une manière d'effacer un défaut de conservation. Les recettes proposées restent simples, afin que les familles puissent les refaire avec leur équipement courant.","question":"Quelle précaution accompagne l'économie ?","options":["Masquer l'origine des produits","Utiliser tous les restes sans distinction","Supprimer les réfrigérateurs","Vérifier la sécurité des aliments"],"correct":"D","explanation":"Le passage indique : « Un atelier apprend à cuisiner avec des restes. Il distingue les aliments encore utilisables de ceux dont la conservation a été insuffisante. » Cela justifie la réponse : Vérifier la sécurité des aliments."},{"number":19,"points":15,"passage":"Un restaurateur raccourcit sa carte pour acheter moins de références et mieux suivre ses stocks. Le nombre de plats diminue, pas celui des services.\n\nLes cuisiniers connaissent mieux les quantités préparées et peuvent utiliser certains ingrédients dans plusieurs recettes. Il suivra les ventes avant de modifier de nouveau la carte. L'objectif est de conserver une offre cohérente avec la taille de l'équipe, plutôt que d'afficher de nombreuses possibilités dont une partie serait souvent indisponible ou préparée sans le soin nécessaire.","question":"Quel objectif guide ce changement ?","options":["Augmenter les pertes en cuisine","Supprimer tous les produits frais","Fermer plusieurs jours par semaine","Simplifier la gestion des approvisionnements"],"correct":"D","explanation":"Le passage indique : « Un restaurateur raccourcit sa carte pour acheter moins de références et mieux suivre ses stocks. Le nombre de plats diminue, pas celui des services. » Cela justifie la réponse : Simplifier la gestion des approvisionnements."},{"number":20,"points":21,"passage":"Un groupement de consommateurs commande directement à des producteurs. Les prix sont discutés à l'avance pour donner de la visibilité aux deux parties. Les acheteurs acceptent en échange un choix moins immédiat qu'au supermarché. Les volumes sont précisés avant la saison, avec les conditions de retrait et les possibilités d'absence. Les producteurs peuvent ainsi préparer certains investissements et les consommateurs comprendre les engagements pris. Le groupe accepte quelques variations liées à la récolte. Il préfère discuter ces aléas dans un cadre connu plutôt que découvrir une nouvelle condition à chaque commande.","question":"Quel compromis est décrit ?","options":["Plus de prévisibilité contre moins de choix instantané","Un prix changeant après chaque livraison","Une suppression de toute relation avec les fermes","Des commandes sans engagement pour les producteurs"],"correct":"A","explanation":"Le passage indique : « Un groupement de consommateurs commande directement à des producteurs. Les prix sont discutés à l'avance pour donner de la visibilité aux deux parties. Les acheteurs acceptent en échange un choix moins immédiat qu'au supermarché. » Cela justifie la réponse : Plus de prévisibilité contre moins de choix instantané."},{"number":21,"points":21,"passage":"Un restaurant privilégie des légumes de proximité. En hiver, il remplace certains plats plutôt que transporter les mêmes ingrédients de très loin. Les clients retrouveront une indication sur les substitutions, afin de comprendre pourquoi une recette connue évolue. Le chef échange régulièrement avec plusieurs fournisseurs pour prévoir les quantités. Il ne promet pas que tout ingrédient pourra toujours venir du même périmètre. Il souhaite surtout que ses choix suivent une logique expliquée, plutôt que conserver à tout prix une carte identique sans regarder les conditions d'approvisionnement.","question":"Quelle conséquence le choix local a-t-il ?","options":["Les mêmes produits restent disponibles partout","Le menu suit davantage les saisons","Les clients doivent apporter tous leurs légumes","Le service devient uniquement estival"],"correct":"B","explanation":"Le passage indique : « Un restaurant privilégie des légumes de proximité. En hiver, il remplace certains plats plutôt que transporter les mêmes ingrédients de très loin. » Cela justifie la réponse : Le menu suit davantage les saisons."},{"number":22,"points":21,"passage":"Une école installe une fontaine à eau dans son réfectoire. La consommation augmente surtout après le déplacement des verres à portée des enfants. Les enfants hésitaient auparavant à demander un verre ou devaient quitter leur table pour le trouver. Le changement ne nécessitait pas une autre fontaine, mais une meilleure organisation du service. L'école vérifiera si cette facilité reste effective pendant les périodes d'affluence et si les plus petits peuvent se servir sans difficulté.","question":"Que suggère cette observation ?","options":["L'aménagement pratique influence les usages","Les enfants refusent tous les verres","La fontaine est inutile","L'eau doit être payante pour être bue"],"correct":"A","explanation":"Le passage indique : « Une école installe une fontaine à eau dans son réfectoire. La consommation augmente surtout après le déplacement des verres à portée des enfants. » Cela justifie la réponse : L'aménagement pratique influence les usages."},{"number":23,"points":21,"passage":"Des agriculteurs accueillent des visiteurs pendant une journée de récolte. Ils expliquent que les volumes varient avec la météo. La rencontre montre un travail soumis à des aléas, et non une production parfaitement prévisible. Les visiteurs voient aussi les préparations et les tâches qui continuent lorsque la météo empêche de travailler dehors. Les agriculteurs expliquent leurs décisions et les possibilités de report. Ils souhaitent éviter qu'une journée agréable à la ferme donne l'image d'un métier toujours prévisible.","question":"Quelle idée la visite aide-t-elle à comprendre ?","options":["L'indépendance complète vis-à-vis du climat","Une quantité identique garantie chaque jour","La disparition du besoin de travail","L'incertitude inhérente à certaines productions"],"correct":"D","explanation":"Le passage indique : « Des agriculteurs accueillent des visiteurs pendant une journée de récolte. Ils expliquent que les volumes varient avec la météo. La rencontre montre un travail soumis à des aléas, et non une production parfaitement prévisible. » Cela justifie la réponse : L'incertitude inhérente à certaines productions."},{"number":24,"points":21,"passage":"Un atelier de cuisine ouvre sans matériel sophistiqué. Les participants refont les gestes avec des ustensiles courants, afin de pouvoir reproduire les recettes chez eux. Les recettes sont choisies pour pouvoir être refaites dans une cuisine ordinaire, avec des quantités faciles à modifier. Les participants discutent de leurs propres contraintes : temps, place et nombre de convives. Le centre préfère une technique réellement réutilisée à une démonstration impressionnante mais impossible à reproduire.","question":"Pourquoi ce choix de matériel ?","options":["Démontrer l'inutilité de tous les outils","Réserver l'activité aux professionnels","Faciliter le réemploi des apprentissages à domicile","Augmenter le coût des recettes"],"correct":"C","explanation":"Le passage indique : « Un atelier de cuisine ouvre sans matériel sophistiqué. Les participants refont les gestes avec des ustensiles courants, afin de pouvoir reproduire les recettes chez eux. » Cela justifie la réponse : Faciliter le réemploi des apprentissages à domicile."},{"number":25,"points":21,"passage":"Une épicerie affiche le prix au kilo à côté des promotions. Cette information aide à comparer des formats différents, car le paquet le plus gros n'est pas toujours le plus économique. Le commerçant affiche la même unité pour chaque référence et explique où la lire. Les clients peuvent ainsi vérifier si une promotion correspond à leur besoin. Un grand paquet peut rester intéressant pour une famille nombreuse, mais devenir inutile pour une personne qui n'en consommera qu'une partie.","question":"Que permet l'affichage ?","options":["Mesurer la qualité gustative","Garantir que tout grand format est moins cher","Remplacer la liste des ingrédients","Comparer les prix sur une même base"],"correct":"D","explanation":"Le passage indique : « Une épicerie affiche le prix au kilo à côté des promotions. Cette information aide à comparer des formats différents, car le paquet le plus gros n'est pas toujours le plus économique. » Cela justifie la réponse : Comparer les prix sur une même base."},{"number":26,"points":21,"passage":"Un traiteur propose des portions modulables selon les convives. Il demande les effectifs définitifs deux jours avant le repas pour ajuster les achats. Les clients peuvent préciser les âges et les habitudes alimentaires de leurs invités. Le traiteur propose ensuite une estimation, sans présenter chaque personne comme une consommation identique. Une petite marge reste prévue pour les imprévus. Les organisateurs souhaitent réduire les restes sans risquer de manquer, et discutent aussi du rangement de ce qui pourrait être conservé après le repas.","question":"Quel lien organise cette pratique ?","options":["Imposer le même menu toute l'année","Relier la quantité préparée aux besoins réels","Commander sans connaître le nombre d'invités","Supprimer les achats de dernière minute pour les clients seulement"],"correct":"B","explanation":"Le passage indique : « Un traiteur propose des portions modulables selon les convives. Il demande les effectifs définitifs deux jours avant le repas pour ajuster les achats. » Cela justifie la réponse : Relier la quantité préparée aux besoins réels."},{"number":27,"points":21,"passage":"Un livre de recettes recueille les plats transmis dans plusieurs familles. Les variantes sont conservées : le comité ne cherche pas une version unique déclarée supérieure aux autres. Ces remarques accompagnent les recettes. Le livre ne cherche pas à séparer une version pure et des copies dégradées, mais à montrer comment une pratique se transmet entre personnes et se transforme avec leurs conditions de vie.","question":"Quelle conception de la transmission apparaît ?","options":["Seules les recettes écrites sont valables","Chaque plat doit avoir une forme identique partout","Une tradition peut comporter plusieurs variantes","Les recettes familiales ne changent jamais"],"correct":"C","explanation":"Le passage indique : « Un livre de recettes recueille les plats transmis dans plusieurs familles. Les variantes sont conservées : le comité ne cherche pas une version unique déclarée supérieure aux autres. » Cela justifie la réponse : Une tradition peut comporter plusieurs variantes."},{"number":28,"points":21,"passage":"Une enquête sur les repas au travail mesure la durée disponible autant que les choix alimentaires. Certains salariés disent manger vite, non par préférence, mais à cause de pauses courtes. Les chercheurs regardent les horaires, la distance du lieu de restauration et les possibilités de conserver un repas. Les réponses aideront à choisir des améliorations concrètes, plutôt qu'à adresser uniquement des conseils généraux sans effet sur les conditions du déjeuner.","question":"Que révèle cette distinction ?","options":["Tous les repas rapides sont librement choisis","Les conditions de travail influencent les pratiques alimentaires","Le goût n'a jamais d'importance","Les salariés disposent tous du même temps"],"correct":"B","explanation":"Le passage indique : « Une enquête sur les repas au travail mesure la durée disponible autant que les choix alimentaires. Certains salariés disent manger vite, non par préférence, mais à cause de pauses courtes. » Cela justifie la réponse : Les conditions de travail influencent les pratiques alimentaires."},{"number":29,"points":21,"passage":"Un marché prévoit un stand pour les petits producteurs débutants. Les emplacements tournent chaque mois pour leur permettre de tester la vente avant un engagement plus long. Les participants bénéficient d'un accompagnement pour présenter leurs prix et leurs produits. Ils peuvent ensuite comparer les retours des clients avec leurs capacités de production. Les candidats discuteront de ce qu'ils ont appris avant de décider d'une présence plus régulière.","question":"Quelle fonction remplit ce stand ?","options":["Garantir des ventes identiques","Offrir une période d'essai commercial","Remplacer le travail agricole par une formation","Éliminer les producteurs établis"],"correct":"B","explanation":"Le passage indique : « Un marché prévoit un stand pour les petits producteurs débutants. Les emplacements tournent chaque mois pour leur permettre de tester la vente avant un engagement plus long. » Cela justifie la réponse : Offrir une période d'essai commercial."},{"number":30,"points":26,"passage":"L'étiquette « fait maison » rassure certains clients, mais ne décrit pas à elle seule l'origine des produits ni l'équilibre d'un repas. Une diététicienne invite à poser plusieurs questions plutôt qu'à déduire toutes les qualités d'une seule mention. Elle propose notamment de regarder les quantités et les ingrédients effectivement servis. Le sens d'une mention doit rester précis, pour éviter qu'un seul mot remplace l'ensemble des informations nécessaires à un choix.","question":"Quelle limite d'interprétation est signalée ?","options":["Une mention ne renseigne pas sur toutes les dimensions du repas","Une étiquette remplace l'observation du menu","L'origine des aliments est toujours secrète","Toute préparation maison est identique"],"correct":"A","explanation":"Le passage indique : « L'étiquette « fait maison » rassure certains clients, mais ne décrit pas à elle seule l'origine des produits ni l'équilibre d'un repas. Une diététicienne invite à poser plusieurs questions plutôt qu'à déduire toutes les qualités d'une seule mention. » Cela justifie la réponse : Une mention ne renseigne pas sur toutes les dimensions du repas."},{"number":31,"points":26,"passage":"Un prix bas peut être obtenu par de grands volumes, une organisation efficace ou des conditions défavorables aux fournisseurs. Sans information sur ces facteurs, il serait imprudent d'attribuer la même cause à tous les produits bon marché. Des comparaisons entre produits proches et des informations sur les fournisseurs peuvent aider à comprendre ces différences. Le prix reste un repère important pour le budget, sans être une explication complète du fonctionnement de la production.","question":"Quelle attitude le texte recommande-t-il ?","options":["Considérer le prix comme une preuve unique de qualité","Examiner les mécanismes derrière le prix","Condamner tous les prix bas de la même manière","Ignorer les conditions de production"],"correct":"B","explanation":"Le passage indique : « Un prix bas peut être obtenu par de grands volumes, une organisation efficace ou des conditions défavorables aux fournisseurs. Sans information sur ces facteurs, il serait imprudent d'attribuer la même cause à tous les produits bon marché. » Cela justifie la réponse : Examiner les mécanismes derrière le prix."},{"number":32,"points":26,"passage":"Les recettes d'un patrimoine culinaire sont souvent adaptées aux produits accessibles dans le lieu où vivent les familles. Cette transformation n'efface pas nécessairement leur histoire. Elle peut être précisément la manière dont la transmission continue dans un contexte différent. Les familles racontent les substitutions qu'elles ont essayées et les goûts qu'elles souhaitaient retrouver. Ces récits montrent une continuité vivante, dont les changements peuvent être décrits plutôt que dissimulés sous l'idée d'une recette restée toujours identique.","question":"Quelle idée est défendue ?","options":["La transmission cesse dès qu'une famille déménage","Toute modification détruit obligatoirement l'héritage","Une recette doit ignorer les produits disponibles","L'adaptation peut faire vivre une tradition"],"correct":"D","explanation":"Le passage indique : « Les recettes d'un patrimoine culinaire sont souvent adaptées aux produits accessibles dans le lieu où vivent les familles. Cette transformation n'efface pas nécessairement leur histoire. Elle peut être précisément la manière dont la transmission continue dans un contexte différent. » Cela justifie la réponse : L'adaptation peut faire vivre une tradition."},{"number":33,"points":26,"passage":"Une cantine veut améliorer ses menus à partir d'un vote. Les plats peu connus risquent d'obtenir peu de voix avant même d'avoir été goûtés. L'équipe ajoute des dégustations aux questionnaires pour éviter que la consultation ne reproduise seulement les habitudes existantes. L'équipe comparera leurs avis avant et après l'essai pour voir si le menu futur doit être ajusté ou simplement mieux présenté.","question":"Pourquoi organiser des dégustations ?","options":["Supprimer toutes les habitudes alimentaires","Éviter de présenter les plats nouveaux","Imposer un résultat sans échange","Éclairer les préférences avant de les mesurer"],"correct":"D","explanation":"Le passage indique : « Une cantine veut améliorer ses menus à partir d'un vote. Les plats peu connus risquent d'obtenir peu de voix avant même d'avoir été goûtés. L'équipe ajoute des dégustations aux questionnaires pour éviter que la consultation ne reproduise seulement les habitudes existantes. » Cela justifie la réponse : Éclairer les préférences avant de les mesurer."},{"number":34,"points":26,"passage":"Un producteur remplace des livraisons quotidiennes par deux tournées hebdomadaires. Les trajets diminuent, mais certains restaurants doivent adapter leurs capacités de stockage. L'économie logistique suppose donc une coordination entre ceux qui livrent et ceux qui reçoivent. Le calendrier sera discuté à l'avance avec les cuisines. Certains produits nécessiteront un autre rythme, tandis que d'autres pourront être livrés ensemble sans difficulté. L'essai devra donc être évalué pour chaque type d'approvisionnement.","question":"Quelle condition rend le changement viable ?","options":["L'indifférence aux besoins des restaurants","La multiplication des trajets individuels","L'adaptation coordonnée des partenaires","La suppression des réserves alimentaires"],"correct":"C","explanation":"Le passage indique : « Un producteur remplace des livraisons quotidiennes par deux tournées hebdomadaires. Les trajets diminuent, mais certains restaurants doivent adapter leurs capacités de stockage. L'économie logistique suppose donc une coordination entre ceux qui livrent et ceux qui reçoivent. » Cela justifie la réponse : L'adaptation coordonnée des partenaires."},{"number":35,"points":26,"passage":"La lutte contre le gaspillage en cuisine est parfois réduite au recyclage des restes. Un collectif insiste d'abord sur les prévisions, les achats et les portions. Le traitement final reste utile, mais intervient après que des décisions évitables ont déjà produit un surplus. Ces informations peuvent conduire à modifier l'organisation du service avant même de chercher de nouvelles recettes pour transformer les aliments non consommés.","question":"Quelle priorité est proposée ?","options":["Prévenir la formation des surplus","Produire plus de restes pour mieux les recycler","Abandonner les prévisions de repas","Considérer tout surplus comme inévitable"],"correct":"A","explanation":"Le passage indique : « La lutte contre le gaspillage en cuisine est parfois réduite au recyclage des restes. Un collectif insiste d'abord sur les prévisions, les achats et les portions. Le traitement final reste utile, mais intervient après que des décisions évitables ont déjà produit un surplus. » Cela justifie la réponse : Prévenir la formation des surplus."},{"number":36,"points":33,"passage":"Un service de paniers « personnalisés » promet de répondre à chaque préférence. Pour y parvenir, il multiplie les petites commandes et les emballages séparés. Les clients gagnent en choix, mais le système perd une partie de l'efficacité du panier commun. La personnalisation peut déplacer les coûts matériels vers l'organisation qui la rend possible. Pour préserver une partie de cette souplesse, le service propose désormais quelques choix communs plutôt qu'une composition entièrement différente pour chaque foyer. Les clients peuvent indiquer des contraintes essentielles, mais toutes les préférences ne donneront plus lieu à un emballage séparé. Le responsable souhaite mesurer les volumes réellement transportés et jetés, pas seulement la satisfaction au moment de la commande. Il espère ainsi conserver un service utile, tout en rendant visibles les ressources mobilisées derrière une offre qui semblait simplement apporter davantage de liberté à chacun.","question":"Quel arbitrage est mis en évidence ?","options":["Une commande personnalisée réduit toujours les emballages","Les préférences n'ont aucun effet sur l'approvisionnement","Les paniers communs interdisent toute alimentation variée","Choix individuel et efficacité collective peuvent entrer en tension"],"correct":"D","explanation":"Le passage indique : « La personnalisation peut déplacer les coûts matériels vers l'organisation qui la rend possible. » Cela justifie la réponse : Choix individuel et efficacité collective peuvent entrer en tension."},{"number":37,"points":33,"passage":"Un restaurant annonce une cuisine locale. Son menu comporte surtout des produits de proximité, mais certains ingrédients complémentaires viennent d'ailleurs. Le chef publie ces exceptions et leurs raisons. La cohérence de son engagement repose sur des choix expliqués, plutôt que sur une formule absolue que la pratique démentirait. Il indique les fournisseurs principaux et la période à laquelle certains produits deviennent disponibles. Les clients peuvent ainsi comprendre pourquoi une recette change ou pourquoi une épice n'est pas produite dans la région. Le restaurateur souhaite éviter qu'une promesse trop générale transforme chaque exception en soupçon de tromperie. Cette précision n'empêche pas la discussion sur ses choix. Elle permet au contraire de les comparer avec d'autres possibilités, en distinguant une priorité réelle d'une affirmation commerciale qui paraîtrait valable pour chaque ingrédient et pendant toute l'année.","question":"Quelle démarche le chef privilégie-t-il ?","options":["Supprimer toute information sur les fournisseurs","Rendre son engagement précis et vérifiable","Prétendre que tous les produits sont locaux","Cacher les ingrédients qui viennent de loin"],"correct":"B","explanation":"Le passage indique : « La cohérence de son engagement repose sur des choix expliqués, plutôt que sur une formule absolue que la pratique démentirait. » Cela justifie la réponse : Rendre son engagement précis et vérifiable."},{"number":38,"points":33,"passage":"Une ville distribue des brochures pour encourager une alimentation variée. Une enquête montre cependant que plusieurs ménages disposent d'un équipement de cuisson limité et de peu de commerces accessibles. La connaissance des recommandations n'est pas leur principale difficulté. Des conseils utiles doivent s'accompagner d'une attention aux conditions concrètes qui permettent de les suivre. Les associations proposent de compléter la campagne par des ateliers utilisant le matériel réellement disponible dans les logements. Elles demandent aussi que l'accès aux commerces et aux lieux de conservation soit examiné. Certaines personnes connaissent déjà les conseils et souhaitent les suivre, mais doivent composer avec un budget ou un horaire peu compatible avec l'offre locale. Les responsables veulent donc éviter un message qui ferait de ces contraintes une faute personnelle. La réussite du programme dépendra de ce qu'il rend effectivement possible dans le quotidien des familles auxquelles il s'adresse.","question":"Quelle limite de la campagne est soulignée ?","options":["L'accès aux commerces n'influence pas l'alimentation","L'information ne résout pas les obstacles matériels","Les ménages refusent nécessairement toute diversité","Une brochure crée automatiquement une cuisine équipée"],"correct":"B","explanation":"Le passage indique : « Des conseils utiles doivent s'accompagner d'une attention aux conditions concrètes qui permettent de les suivre. » Cela justifie la réponse : L'information ne résout pas les obstacles matériels."},{"number":39,"points":33,"passage":"Une ferme propose aux clients de partager les risques d'une saison en payant un panier à l'avance. Certains craignent de recevoir moins lors d'une mauvaise récolte. Le producteur explique que le contrat n'est pas une garantie de volume identique, mais une relation différente avec l'activité agricole. Le prix finance aussi une continuité de production confrontée à l'incertitude. Le groupe prévoit une visite des cultures et une information régulière sur l'évolution de la saison. Les membres pourront discuter des substitutions possibles, tout en comprenant qu'un engagement ne fait pas disparaître les aléas du climat. Le producteur garde la responsabilité d'expliquer ses choix et de travailler avec soin. Les acheteurs, eux, acceptent que leur contribution ne corresponde pas toujours au même poids de produits.","question":"Qu'est-ce qui distingue ce contrat d'un achat ordinaire ?","options":["Un engagement qui prend en compte le risque de production","Une absence de relation avec la ferme","Une obligation d'acheter chaque produit séparément","Une promesse de quantité constante sans aléa"],"correct":"A","explanation":"Le passage indique : « Le prix finance aussi une continuité de production confrontée à l'incertitude. » Cela justifie la réponse : Un engagement qui prend en compte le risque de production."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-08','tcf-reading-2026-11-reference-v3',$paper${"id":"tcf-reading-08","version":"tcf-reading-2026-11-reference-v3","title":"TCF Reading · Test 08","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"La piscine ferme ses bassins à dix-neuf heures. Les vestiaires restent accessibles quinze minutes supplémentaires.\n\nMerci de prévoir le temps nécessaire avant la fermeture des vestiaires. Le personnel rappellera cette règle à l'entrée de chaque séance.","question":"Jusqu'à quand peut-on se changer ?","options":["Dix-neuf heures trente","Dix-neuf heures quinze","Dix-huit heures quarante-cinq","Vingt heures"],"correct":"B","explanation":"Le passage indique : « La piscine ferme ses bassins à dix-neuf heures. Les vestiaires restent accessibles quinze minutes supplémentaires. » Cela justifie la réponse : Dix-neuf heures quinze."},{"number":2,"points":3,"passage":"Le cours de yoga est déplacé au gymnase. Apportez votre tapis ; les chaises seront fournies aux personnes qui en ont besoin.\n\nL'animateur accueillera les participants devant la salle.","question":"Quel matériel est demandé ?","options":["Un ballon","Un tapis","Une chaise","Un casque"],"correct":"B","explanation":"Le passage indique : « Le cours de yoga est déplacé au gymnase. Apportez votre tapis ; les chaises seront fournies aux personnes qui en ont besoin. » Cela justifie la réponse : Un tapis."},{"number":3,"points":3,"passage":"L'accueil du cabinet sera fermé mardi matin. Les consultations déjà prévues sont maintenues ; sonnez à la porte latérale.\n\nLes demandes non urgentes seront traitées dès le retour de l'équipe d'accueil.","question":"Qui peut venir mardi matin ?","options":["Uniquement les livreurs","Les visiteurs sans motif","Les patients ayant rendez-vous","Toute personne souhaitant s'inscrire"],"correct":"C","explanation":"Le passage indique : « L'accueil du cabinet sera fermé mardi matin. Les consultations déjà prévues sont maintenues ; sonnez à la porte latérale. » Cela justifie la réponse : Les patients ayant rendez-vous."},{"number":4,"points":3,"passage":"Le parcours de marche est glissant après la pluie. Utilisez provisoirement la boucle courte sur sol stabilisé.\n\nDes panneaux indiquent la déviation à l'entrée du parc. Les équipes vérifieront l'état du terrain avant de rouvrir le passage habituel.","question":"Que conseille l'annonce ?","options":["Une sortie sans chaussures","Une course plus rapide","L'accès au parcours glissant","Un itinéraire alternatif"],"correct":"D","explanation":"Le passage indique : « Le parcours de marche est glissant après la pluie. Utilisez provisoirement la boucle courte sur sol stabilisé. » Cela justifie la réponse : Un itinéraire alternatif."},{"number":5,"points":9,"passage":"Je reprends doucement le vélo après ma pause. Pour dimanche, choisissons le trajet plat ; nous réserverons les côtes à une autre sortie.\n\nLe groupe peut conserver une allure tranquille et s'arrêter lorsque ce sera nécessaire. Je veux reprendre régulièrement sans transformer cette première sortie en épreuve trop difficile.","question":"Quel parcours est souhaité ?","options":["Une route inconnue de nuit","Une compétition chronométrée","Une ascension difficile","Un trajet sans montée importante"],"correct":"D","explanation":"Le passage indique : « Je reprends doucement le vélo après ma pause. Pour dimanche, choisissons le trajet plat ; nous réserverons les côtes à une autre sortie. » Cela justifie la réponse : Un trajet sans montée importante."},{"number":6,"points":9,"passage":"Votre rendez-vous de contrôle est avancé à jeudi. Prévenez le secrétariat si ce nouvel horaire ne vous convient pas.\n\nLe cabinet proposera un autre créneau selon les disponibilités. Merci de signaler votre réponse rapidement pour éviter de laisser une place inutilisée.","question":"Que faire en cas d'indisponibilité ?","options":["Contacter le secrétariat","Venir sans prévenir un autre jour","Annuler tous les soins","Demander à un voisin de consulter"],"correct":"A","explanation":"Le passage indique : « Votre rendez-vous de contrôle est avancé à jeudi. Prévenez le secrétariat si ce nouvel horaire ne vous convient pas. » Cela justifie la réponse : Contacter le secrétariat."},{"number":7,"points":9,"passage":"L'association prête des bâtons de marche pendant les trois premières séances. Ensuite, chacun choisira s'il souhaite continuer l'activité.\n\nUn animateur vérifiera leur taille et expliquera les gestes de base. Vous pourrez ensuite poser vos questions avant de vous engager dans une pratique régulière.","question":"Quel est l'intérêt du prêt ?","options":["Recevoir un équipement définitif","Essayer avant de s'équiper","Participer sans jamais s'inscrire","Éviter toute séance encadrée"],"correct":"B","explanation":"Le passage indique : « L'association prête des bâtons de marche pendant les trois premières séances. Ensuite, chacun choisira s'il souhaite continuer l'activité. » Cela justifie la réponse : Essayer avant de s'équiper."},{"number":8,"points":9,"passage":"Nous maintenons la randonnée, mais avec davantage de pauses à cause de la chaleur. Emportez de l'eau et prévenez si vous préférez renoncer.\n\nLe guide vérifiera les points d'eau et adaptera l'allure au groupe.","question":"Quelle adaptation est prévue ?","options":["Un départ sans accompagnateur","Des arrêts plus fréquents","Une distance doublée","La suppression des boissons"],"correct":"B","explanation":"Le passage indique : « Nous maintenons la randonnée, mais avec davantage de pauses à cause de la chaleur. Emportez de l'eau et prévenez si vous préférez renoncer. » Cela justifie la réponse : Des arrêts plus fréquents."},{"number":9,"points":9,"passage":"La séance découverte de natation est réservée aux adultes débutants. Il n'est pas nécessaire de savoir nager pour s'inscrire.\n\nLes exercices commenceront dans une zone où chacun peut garder ses repères. Un échange permettra de préciser les attentes avant le premier passage dans l'eau.","question":"À qui s'adresse la séance ?","options":["Aux enfants accompagnés","Aux adultes qui apprennent","Aux nageurs en compétition seulement","Aux entraîneurs professionnels"],"correct":"B","explanation":"Le passage indique : « La séance découverte de natation est réservée aux adultes débutants. Il n'est pas nécessaire de savoir nager pour s'inscrire. » Cela justifie la réponse : Aux adultes qui apprennent."},{"number":10,"points":9,"passage":"Je vais marcher le midi plutôt que courir tard le soir. Cela s'accorde mieux avec mes horaires et me laisse du temps en famille.\n\nJe compte aussi préparer mes affaires à l'avance pour ne pas renoncer au dernier moment.","question":"Qu'est-ce qui motive ce changement ?","options":["Un projet de compétition","Un déménagement en montagne","Une interdiction de courir","Une meilleure organisation du quotidien"],"correct":"D","explanation":"Le passage indique : « Je vais marcher le midi plutôt que courir tard le soir. Cela s'accorde mieux avec mes horaires et me laisse du temps en famille. » Cela justifie la réponse : Une meilleure organisation du quotidien."},{"number":11,"points":15,"passage":"Un club organise une séance sans classement. Les participants choisissent leur rythme et peuvent interrompre l'exercice avant la fin.\n\nLes animateurs proposent plusieurs exercices au même endroit et expliquent les adaptations possibles. Une personne qui débute n'a pas à suivre exactement le programme d'un habitué. Le club souhaite que chacun trouve une manière de participer sans craindre de ralentir les autres. Les responsables observeront les inscriptions, mais aussi les retours après plusieurs semaines. Une séance accueillante n'atteint pas son objectif si les nouveaux venus se sentent encore incapables de revenir seuls ou de demander une pause.","question":"Quelle place est donnée à la performance ?","options":["Elle n'est pas l'objectif principal","Elle exclut les nouveaux membres","Elle détermine le droit d'entrer","Elle impose un temps identique"],"correct":"A","explanation":"Le passage indique : « Un club organise une séance sans classement. Les participants choisissent leur rythme et peuvent interrompre l'exercice avant la fin. » Cela justifie la réponse : Elle n'est pas l'objectif principal."},{"number":12,"points":15,"passage":"Une résidence propose des rencontres autour du sommeil. Les animateurs donnent des informations générales et orientent les situations particulières vers un professionnel.\n\nLes participants peuvent parler de leurs habitudes, mais ne sont pas invités à dévoiler un dossier médical devant le groupe. Les séances abordent notamment l'organisation de la soirée et les conditions du logement. Les intervenants rappellent que des difficultés persistantes peuvent demander une consultation.","question":"Quelle limite est précisée ?","options":["L'atelier ne remplace pas un suivi individuel","Les animateurs prescrivent systématiquement un traitement","Aucune question ne peut être posée","Les participants reçoivent tous un diagnostic"],"correct":"A","explanation":"Le passage indique : « Une résidence propose des rencontres autour du sommeil. Les animateurs donnent des informations générales et orientent les situations particulières vers un professionnel. » Cela justifie la réponse : L'atelier ne remplace pas un suivi individuel."},{"number":13,"points":15,"passage":"Le parcours sportif du parc comporte des variantes assises et debout. Les panneaux montrent plusieurs niveaux pour un même mouvement.\n\nLes indications ne supposent pas que l'on connaisse déjà les appareils. Des dessins montrent les positions et rappellent qu'une pause est possible. Le service souhaite accueillir les personnes qui ne fréquentent pas les salles, autant que les sportifs habituels. Les usagers pourront signaler un mouvement difficile à comprendre. Une première évaluation regardera la variété des participants et la facilité d'utilisation du parcours, plutôt que le seul nombre d'équipements installés ou la vitesse à laquelle ils sont utilisés.","question":"Quel objectif poursuit l'aménagement ?","options":["Permettre différentes capacités de participation","Supprimer les explications","Réserver le parc aux spécialistes","Imposer une difficulté unique"],"correct":"A","explanation":"Le passage indique : « Le parcours sportif du parc comporte des variantes assises et debout. Les panneaux montrent plusieurs niveaux pour un même mouvement. » Cela justifie la réponse : Permettre différentes capacités de participation."},{"number":14,"points":15,"passage":"Un club de course accueille un groupe de marche rapide. Certains membres souhaitent bouger régulièrement sans rechercher la vitesse.\n\nLes rendez-vous gardent une progression et un encadrement, mais les distances sont adaptées aux objectifs annoncés par les participants. Certains cherchent une activité après le travail ; d'autres veulent retrouver une habitude interrompue. Le responsable souhaite éviter qu'une même image de la performance fasse croire que le club n'accueille que des coureurs rapides. Les deux groupes pourront partager des rencontres et quelques exercices, sans que l'un soit considéré comme une version moins valable de l'autre.","question":"Pourquoi ce groupe est-il créé ?","options":["Pour imposer un classement plus strict","Pour limiter l'accès aux nouveaux venus","Pour remplacer toutes les sorties","Pour diversifier les façons de pratiquer"],"correct":"D","explanation":"Le passage indique : « Un club de course accueille un groupe de marche rapide. Certains membres souhaitent bouger régulièrement sans rechercher la vitesse. » Cela justifie la réponse : Pour diversifier les façons de pratiquer."},{"number":15,"points":15,"passage":"Les consultations d'un centre se réservent aussi par téléphone. Le site internet n'est pas l'unique moyen d'obtenir un créneau.\n\nLes personnes qui appellent reçoivent les mêmes informations sur les créneaux et les documents utiles. Les secrétaires peuvent expliquer une étape incomprise sans demander l'aide d'un proche équipé. Le centre ne veut pas supprimer les démarches en ligne, pratiques pour une partie du public. Il souhaite simplement conserver une possibilité réelle pour ceux qui ne peuvent pas les utiliser seuls. Les responsables suivront les attentes sur chaque canal pour éviter qu'un accès annoncé reste beaucoup plus difficile que l'autre.","question":"Quel obstacle cherche-t-on à réduire ?","options":["L'existence d'un accueil","La diversité des horaires","La dépendance aux outils numériques","Le besoin d'un rendez-vous"],"correct":"C","explanation":"Le passage indique : « Les consultations d'un centre se réservent aussi par téléphone. Le site internet n'est pas l'unique moyen d'obtenir un créneau. » Cela justifie la réponse : La dépendance aux outils numériques."},{"number":16,"points":15,"passage":"Une entreprise réorganise ses postes pour éviter de rester longtemps dans la même position. Les pauses courtes complètent cet aménagement.\n\nLes salariés ont participé aux essais en indiquant les gestes qui provoquaient une gêne. Certaines tâches seront alternées et quelques équipements déplacés pour faciliter les changements de position. L'entreprise veut observer le travail réel avant de distribuer uniquement des recommandations individuelles. Une affiche pourra rappeler des repères, mais ne remplacera pas une organisation permettant effectivement de bouger.","question":"Quelle approche est adoptée ?","options":["Remplacer tous les meubles par des écrans","Agir sur l'organisation et les pauses","Exiger l'immobilité toute la journée","Supprimer les changements de tâche"],"correct":"B","explanation":"Le passage indique : « Une entreprise réorganise ses postes pour éviter de rester longtemps dans la même position. Les pauses courtes complètent cet aménagement. » Cela justifie la réponse : Agir sur l'organisation et les pauses."},{"number":17,"points":15,"passage":"Un entraîneur fait noter les sensations après l'exercice, pas seulement la distance parcourue. Une même distance peut représenter un effort différent selon les jours.\n\nLe carnet reste personnel et sert de base à une discussion avec l'entraîneur. Les participants peuvent y signaler un sommeil court, une reprise après une absence ou un effort inhabituel dans la journée. Le club souhaite ainsi éviter une comparaison trop mécanique entre deux sorties. Les chiffres restent utiles pour suivre une progression, mais prennent un autre sens lorsqu'ils sont rapprochés des conditions dans lesquelles ils ont été obtenus.","question":"Pourquoi recueillir ces sensations ?","options":["Comparer uniquement les chaussures","Mieux comprendre l'effort réellement ressenti","Remplacer tout mouvement par un questionnaire","Garantir des progrès identiques"],"correct":"B","explanation":"Le passage indique : « Un entraîneur fait noter les sensations après l'exercice, pas seulement la distance parcourue. Une même distance peut représenter un effort différent selon les jours. » Cela justifie la réponse : Mieux comprendre l'effort réellement ressenti."},{"number":18,"points":15,"passage":"Le centre social propose un atelier cuisine et santé à prix libre. Le montant versé n'influence pas la taille de la portion servie.\n\nLes participants cuisinent ensemble avant de partager le repas. Le centre souhaite préserver une activité commune plutôt que distinguer plusieurs catégories de convives. Les recettes sont pensées pour être reproduites avec un équipement courant. Le bilan prendra en compte l'équilibre financier de l'atelier, mais aussi la possibilité pour des personnes aux budgets différents de s'y retrouver régulièrement dans les mêmes conditions d'accueil.","question":"Quel principe est appliqué ?","options":["Une participation obligatoirement gratuite","Une réservation réservée aux donateurs","Une portion proportionnelle au paiement","Un accueil indépendant de la contribution financière"],"correct":"D","explanation":"Le passage indique : « Le centre social propose un atelier cuisine et santé à prix libre. Le montant versé n'influence pas la taille de la portion servie. » Cela justifie la réponse : Un accueil indépendant de la contribution financière."},{"number":19,"points":15,"passage":"Pour une course locale, les organisateurs installent un espace calme après l'arrivée. Les participants peuvent récupérer sans rester dans la foule.\n\nL'organisation rappelle que cet espace ne remplace pas les secours prévus pour un problème particulier. Il répond surtout au besoin de se poser après l'effort et de retrouver ses proches tranquillement. Les responsables interrogeront les participants sur sa localisation, car un équipement utile en principe peut être délaissé s'il reste difficile à trouver au milieu des autres installations.","question":"À quoi sert cet espace ?","options":["Distribuer les dossards avant le départ","Remplacer les vestiaires","Faciliter la récupération dans un environnement apaisé","Organiser une seconde course"],"correct":"C","explanation":"Le passage indique : « Pour une course locale, les organisateurs installent un espace calme après l'arrivée. Les participants peuvent récupérer sans rester dans la foule. » Cela justifie la réponse : Faciliter la récupération dans un environnement apaisé."},{"number":20,"points":21,"passage":"Un quartier propose des promenades accompagnées pour les personnes qui hésitent à sortir seules. Le programme varie selon le groupe : le lien social et la régularité importent davantage que le nombre de kilomètres. Les animateurs préparent plusieurs possibilités de trajet et demandent aux nouveaux venus ce qui leur paraît réalisable. Les pauses offrent un moment pour échanger avec les autres habitants. Le centre souhaite que les personnes puissent ensuite proposer elles-mêmes une sortie. Il suivra la régularité des rencontres et les relations qui se maintiennent, sans transformer le programme en concours de distance ou de vitesse.","question":"Quelle priorité est donnée ?","options":["Remplacer tous les déplacements quotidiens","Sélectionner les marcheurs les plus rapides","Soutenir une pratique régulière et partagée","Atteindre une distance maximale"],"correct":"C","explanation":"Le passage indique : « Un quartier propose des promenades accompagnées pour les personnes qui hésitent à sortir seules. Le programme varie selon le groupe : le lien social et la régularité importent davantage que le nombre de kilomètres. » Cela justifie la réponse : Soutenir une pratique régulière et partagée."},{"number":21,"points":21,"passage":"Une étude locale sur l'activité physique repose sur des volontaires déjà membres de clubs. Ses auteurs signalent que leurs réponses ne représentent pas forcément les personnes éloignées du sport. Les chercheurs chercheront ensuite à rencontrer d'autres habitants, y compris ceux qui ne disposent pas d'un équipement adapté ou n'aiment pas les activités proposées. Ces réponses permettront de distinguer les préférences et les obstacles. Le premier questionnaire reste utile pour comprendre la vie des clubs, mais sa portée doit être clairement annoncée.","question":"Quelle limite est reconnue ?","options":["Aucune donnée n'a été recueillie","Les réponses concernent uniquement les enfants","Le profil des participants peut influencer les résultats","Les clubs refusent toute enquête"],"correct":"C","explanation":"Le passage indique : « Une étude locale sur l'activité physique repose sur des volontaires déjà membres de clubs. Ses auteurs signalent que leurs réponses ne représentent pas forcément les personnes éloignées du sport. » Cela justifie la réponse : Le profil des participants peut influencer les résultats."},{"number":22,"points":21,"passage":"Une commune rénove un terrain, puis observe surtout une fréquentation masculine. Elle consulte les autres habitants sur les horaires, l'éclairage et les activités proposées. Les réponses évoquent parfois la difficulté de venir sans connaître quelqu'un, ou l'absence d'une activité souhaitée. Il ne souhaite pas simplement compter les entrées et déclarer le projet terminé. La consultation doit aider à comprendre qui utilise le lieu, qui reste à l'écart et quelles modifications pourraient changer cette situation.","question":"Pourquoi poursuivre la consultation ?","options":["Confirmer que chacun l'utilise déjà","Comprendre les obstacles à une participation plus large","Supprimer toutes les activités gratuites","Fermer le terrain aux usagers actuels"],"correct":"B","explanation":"Le passage indique : « Une commune rénove un terrain, puis observe surtout une fréquentation masculine. Elle consulte les autres habitants sur les horaires, l'éclairage et les activités proposées. » Cela justifie la réponse : Comprendre les obstacles à une participation plus large."},{"number":23,"points":21,"passage":"Un employeur propose un cours sportif facultatif pendant la pause. Les salariés demandent que la participation ne soit pas utilisée comme signe d'engagement professionnel. Des personnes apprécient l'offre tout en préférant se reposer ou régler une démarche pendant la pause. Elles souhaitent pouvoir choisir sans craindre un jugement sur leur attitude. La direction précisera donc le caractère facultatif du cours et demandera aux responsables de ne pas le commenter dans les entretiens.","question":"Quelle séparation souhaitent-ils préserver ?","options":["Celle entre débutants et entraîneurs uniquement","Celle entre les jours ouvrés et les congés scolaires","Celle entre deux vestiaires","Celle entre activité personnelle et évaluation au travail"],"correct":"D","explanation":"Le passage indique : « Un employeur propose un cours sportif facultatif pendant la pause. Les salariés demandent que la participation ne soit pas utilisée comme signe d'engagement professionnel. » Cela justifie la réponse : Celle entre activité personnelle et évaluation au travail."},{"number":24,"points":21,"passage":"Un club prête du matériel adapté, mais manque de personnel pour accompagner les nouveaux membres. L'équipement élargit les possibilités sans suffire à assurer l'accueil. Les nouveaux pratiquants peuvent avoir besoin d'explications, de repères ou d'une présence rassurante lors des premières séances. L'association cherche donc des personnes formées à cet accueil et réorganise quelques horaires. Le bilan distinguera les prêts effectués et les séances que les personnes ont pu suivre dans de bonnes conditions.","question":"Quel besoin reste présent ?","options":["Une augmentation des obstacles matériels","Un classement plus précis","Un accompagnement humain","Une fermeture des inscriptions"],"correct":"C","explanation":"Le passage indique : « Un club prête du matériel adapté, mais manque de personnel pour accompagner les nouveaux membres. L'équipement élargit les possibilités sans suffire à assurer l'accueil. » Cela justifie la réponse : Un accompagnement humain."},{"number":25,"points":21,"passage":"Un centre propose des horaires de consultation plus tardifs. Il mesure ensuite les annulations et le temps d'attente, afin de vérifier que l'ouverture répond réellement à un besoin. Les responsables regarderont notamment si de nouveaux publics peuvent venir sans demander un arrangement exceptionnel. Les équipes expliqueront aussi les contraintes rencontrées après l'ouverture. L'augmentation du nombre d'heures ne sera pas présentée comme un résultat suffisant si les créneaux restent vides ou si la qualité de l'accueil diminue.","question":"Comment la mesure sera-t-elle évaluée ?","options":["Par l'observation de son usage et de ses effets","Sans aucune information des patients","Par le nombre d'affiches imprimées","Uniquement par l'annonce de nouveaux horaires"],"correct":"A","explanation":"Le passage indique : « Un centre propose des horaires de consultation plus tardifs. Il mesure ensuite les annulations et le temps d'attente, afin de vérifier que l'ouverture répond réellement à un besoin. » Cela justifie la réponse : Par l'observation de son usage et de ses effets."},{"number":26,"points":21,"passage":"Une application de sport envoie des rappels quotidiens. Certains utilisateurs les trouvent utiles ; d'autres désactivent les messages pour éviter une pression supplémentaire. Elle recueillera les retours sur l'usage dans la durée, pas seulement lors de l'inscription. Les responsables veulent éviter qu'un outil présenté comme encourageant devienne une source de culpabilité. Ils rappellent qu'une notification ne remplace pas les conditions pratiques, le plaisir ou le soutien qui permettent de conserver une activité.","question":"Que montrent ces réactions ?","options":["Un même outil peut avoir des effets différents","La pratique exige des messages permanents","Les rappels plaisent nécessairement à tous","Tous les utilisateurs abandonnent le sport"],"correct":"A","explanation":"Le passage indique : « Une application de sport envoie des rappels quotidiens. Certains utilisateurs les trouvent utiles ; d'autres désactivent les messages pour éviter une pression supplémentaire. » Cela justifie la réponse : Un même outil peut avoir des effets différents."},{"number":27,"points":21,"passage":"Un médecin participe à une réunion publique sur la prévention. Il refuse de commenter les dossiers personnels dans la salle et propose des échanges confidentiels dans un autre cadre. Les personnes peuvent poser des questions sur l'organisation générale du service et sur les ressources disponibles. Les cas individuels seront abordés par les canaux habituels, dans des conditions permettant un échange adapté.","question":"Quel principe applique-t-il ?","options":["Éviter toute information générale","Réserver la réunion aux professionnels","Protéger les informations individuelles","Transformer les dossiers en exemples publics"],"correct":"C","explanation":"Le passage indique : « Un médecin participe à une réunion publique sur la prévention. Il refuse de commenter les dossiers personnels dans la salle et propose des échanges confidentiels dans un autre cadre. » Cela justifie la réponse : Protéger les informations individuelles."},{"number":28,"points":21,"passage":"Un gymnase reste ouvert plus longtemps, mais l'arrêt de bus ferme tôt. Les habitants sans voiture ne profitent pas des nouveaux créneaux. Les associations proposent de comparer les horaires du réseau et les sorties réelles du gymnase. Une meilleure coordination pourrait être plus utile qu'une nouvelle campagne d'inscription. Elle souhaite éviter que l'ouverture soit annoncée comme une amélioration identique pour tous, alors que certains habitants ne disposent pas du moyen de rentrer chez eux.","question":"Quelle limite de l'ouverture apparaît ?","options":["Tous les habitants possèdent une voiture","Les horaires du gymnase n'ont pas changé","L'accès dépend aussi des transports","Le bus circule plus longtemps que le gymnase"],"correct":"C","explanation":"Le passage indique : « Un gymnase reste ouvert plus longtemps, mais l'arrêt de bus ferme tôt. Les habitants sans voiture ne profitent pas des nouveaux créneaux. » Cela justifie la réponse : L'accès dépend aussi des transports."},{"number":29,"points":21,"passage":"Une association remplace son défi de perte de poids par un suivi de pratiques choisies avec les participants. Elle veut éviter de réduire le bien-être à un seul chiffre. Les participants discutent de ce qu'ils souhaitent rendre plus facile dans leur quotidien. Certains choisissent une promenade régulière, d'autres un moment de préparation des repas ou une reprise progressive d'activité. Le suivi sera ajusté à ces objectifs.","question":"Quel changement de perspective adopte-t-elle ?","options":["Considérer plusieurs dimensions du bien-être","Imposer un résultat identique à tous","Mesurer uniquement la taille des vêtements","Abandonner toute discussion sur les pratiques"],"correct":"A","explanation":"Le passage indique : « Une association remplace son défi de perte de poids par un suivi de pratiques choisies avec les participants. Elle veut éviter de réduire le bien-être à un seul chiffre. » Cela justifie la réponse : Considérer plusieurs dimensions du bien-être."},{"number":30,"points":26,"passage":"Les campagnes qui invitent chacun à bouger supposent parfois que le temps disponible est librement choisi. Les emplois du temps irréguliers et les charges familiales peuvent rendre difficile une activité régulière. Adapter les propositions suppose de comprendre ces contraintes plutôt que d'attribuer toute absence à un manque de volonté. Ils évaluent ensuite si ces possibilités touchent effectivement les personnes jusqu'alors absentes, au lieu de supposer que l'affichage d'une offre suffit à la rendre accessible.","question":"Quelle explication simpliste est contestée ?","options":["L'utilité d'activités accessibles","Le manque de motivation comme cause unique","L'influence possible des horaires","La diversité des situations familiales"],"correct":"B","explanation":"Le passage indique : « Les campagnes qui invitent chacun à bouger supposent parfois que le temps disponible est librement choisi. Les emplois du temps irréguliers et les charges familiales peuvent rendre difficile une activité régulière. Adapter les propositions suppose de comprendre ces contraintes plutôt que d'attribuer toute absence à un manque de volonté. » Cela justifie la réponse : Le manque de motivation comme cause unique."},{"number":31,"points":26,"passage":"Une salle sportive mesure le succès d'un programme par le nombre d'inscriptions. Des animateurs proposent aussi de regarder qui continue après trois mois et pour quelles raisons. Attirer un public et lui permettre de rester actif sont deux résultats liés, mais distincts. Ces échanges permettent de comprendre les obstacles et d'ajuster les séances plutôt que présenter le nombre d'inscrits comme une preuve complète de réussite.","question":"Quel indicateur complémentaire est proposé ?","options":["La couleur des cartes d'accès","Le nombre de casiers installés","La surface du parking uniquement","La continuité de la participation"],"correct":"D","explanation":"Le passage indique : « Une salle sportive mesure le succès d'un programme par le nombre d'inscriptions. Des animateurs proposent aussi de regarder qui continue après trois mois et pour quelles raisons. Attirer un public et lui permettre de rester actif sont deux résultats liés, mais distincts. » Cela justifie la réponse : La continuité de la participation."},{"number":32,"points":26,"passage":"Une publicité promet une amélioration rapide grâce à un équipement. Un professionnel rappelle que les effets dépendent de l'usage, de la régularité et des situations individuelles. L'achat n'est donc pas en lui-même une preuve de bénéfice. L'utilisateur doit notamment savoir dans quelles conditions la comparaison a été réalisée. Une amélioration observée dans un essai précis ne se transforme pas automatiquement en promesse identique pour chaque personne achetant le produit.","question":"Quelle distinction est faite ?","options":["La régularité empêche les progrès","La publicité remplace un usage réel","Tout équipement est inutile","Posséder un objet ne garantit pas l'effet annoncé"],"correct":"D","explanation":"Le passage indique : « Une publicité promet une amélioration rapide grâce à un équipement. Un professionnel rappelle que les effets dépendent de l'usage, de la régularité et des situations individuelles. L'achat n'est donc pas en lui-même une preuve de bénéfice. » Cela justifie la réponse : Posséder un objet ne garantit pas l'effet annoncé."},{"number":33,"points":26,"passage":"Des aménagements urbains favorisent les déplacements à pied. Leur effet dépasse les personnes qui s'inscrivent volontairement à une activité : un chemin sûr et agréable modifie aussi les trajets ordinaires. La promotion du mouvement peut ainsi passer par le cadre quotidien plutôt que par des programmes spécialisés. Les services observent donc les trajets ordinaires et les points où les habitants renoncent à marcher.","question":"Quelle approche est mise en valeur ?","options":["Remplacer tous les chemins par des salles","Agir sur l'environnement des déplacements courants","Réserver la marche aux clubs","Exiger une inscription pour se déplacer"],"correct":"B","explanation":"Le passage indique : « Des aménagements urbains favorisent les déplacements à pied. Leur effet dépasse les personnes qui s'inscrivent volontairement à une activité : un chemin sûr et agréable modifie aussi les trajets ordinaires. La promotion du mouvement peut ainsi passer par le cadre quotidien plutôt que par des programmes spécialisés. » Cela justifie la réponse : Agir sur l'environnement des déplacements courants."},{"number":34,"points":26,"passage":"Un programme de reprise d'activité accepte les interruptions. Les participants peuvent revenir sans recommencer toutes les démarches. Les animateurs considèrent les parcours irréguliers comme une réalité à accompagner, et non comme une faute qui justifierait l'exclusion. Les animateurs demandent simplement de reprendre contact pour adapter le retour. Ils veulent maintenir une porte ouverte, tout en organisant un groupe qui puisse accueillir les personnes sans ignorer les contraintes réelles de chacune.","question":"Quelle règle favorise la continuité à long terme ?","options":["Exclure dès la première absence","Imposer un résultat uniforme","Permettre le retour après une interruption","Supprimer tout accompagnement"],"correct":"C","explanation":"Le passage indique : « Un programme de reprise d'activité accepte les interruptions. Les participants peuvent revenir sans recommencer toutes les démarches. Les animateurs considèrent les parcours irréguliers comme une réalité à accompagner, et non comme une faute qui justifierait l'exclusion. » Cela justifie la réponse : Permettre le retour après une interruption."},{"number":35,"points":26,"passage":"Une enquête mesure le stress au travail avec un questionnaire très court. Elle permet de repérer des tendances, mais ne décrit pas les causes précises dans chaque service. Les responsables complètent donc les chiffres par des échanges avec les équipes. Les équipes peuvent alors expliquer les interruptions, les priorités concurrentes et les moments difficiles. Le service souhaite construire des pistes d'amélioration à partir de ce dialogue, sans considérer chaque score comme une explication déjà complète.","question":"Pourquoi ajouter des échanges ?","options":["Comprendre ce que l'indicateur général ne détaille pas","Transformer chaque réponse en diagnostic individuel","Effacer toutes les réponses recueillies","Éviter d'écouter les salariés"],"correct":"A","explanation":"Le passage indique : « Une enquête mesure le stress au travail avec un questionnaire très court. Elle permet de repérer des tendances, mais ne décrit pas les causes précises dans chaque service. Les responsables complètent donc les chiffres par des échanges avec les équipes. » Cela justifie la réponse : Comprendre ce que l'indicateur général ne détaille pas."},{"number":36,"points":33,"passage":"Un club veut rendre ses activités accessibles à tous en réduisant les cotisations. Les demandes augmentent, mais des personnes restent absentes : certaines n'osent pas venir seules, d'autres ne se reconnaissent pas dans les images utilisées. L'obstacle financier est réel, sans être la seule barrière à une pratique accueillante. L'association cherche désormais des relais dans les lieux fréquentés par ces habitants et propose des premières séances accompagnées. Elle conserve aussi les tarifs réduits, car les contraintes se cumulent souvent au lieu de se remplacer. Les responsables souhaitent éviter de conclure que les absents ne s'intéressent pas à l'activité. Ils vérifieront plutôt si les nouveaux moyens d'accueil changent les expériences des personnes qui viennent pour la première fois. L'objectif reste d'ouvrir des possibilités concrètes, sans transformer une mesure utile en réponse présentée comme suffisante à toutes les difficultés.","question":"Quelle conclusion se dégage ?","options":["L'accessibilité comporte aussi des dimensions sociales","La baisse des prix ne peut jamais être utile","L'absence de nouveaux membres prouve une hausse des tarifs","Tout problème disparaît avec une inscription gratuite"],"correct":"A","explanation":"Le passage indique : « L'obstacle financier est réel, sans être la seule barrière à une pratique accueillante. » Cela justifie la réponse : L'accessibilité comporte aussi des dimensions sociales."},{"number":37,"points":33,"passage":"Les outils de suivi comptent facilement les pas ou les minutes d'exercice. Ils décrivent moins bien le plaisir, la fatigue ou la confiance retrouvée. Un animateur utilise les chiffres comme point de discussion, sans en faire la définition complète du progrès. Ce qui se mesure simplement n'épuise pas ce qui compte pour la personne. Une personne peut marcher moins longtemps qu'une autre tout en retrouvant la possibilité de sortir de chez elle. Une autre cherche surtout à partager une activité avec des amis. L'animateur souhaite pouvoir entendre ces objectifs sans les remplacer par un classement unique. Il ne rejette pas les mesures, mais demande qu'elles restent des outils de compréhension. Les participants pourront choisir ce qu'ils veulent suivre et expliquer ce qu'ils ressentent.","question":"Quelle place donne-t-il aux données ?","options":["Un repère à interpréter dans une expérience plus large","Une obligation identique pour chaque participant","Une description exhaustive du bien-être","Un résultat qu'il faut ignorer systématiquement"],"correct":"A","explanation":"Le passage indique : « Ce qui se mesure simplement n'épuise pas ce qui compte pour la personne. » Cela justifie la réponse : Un repère à interpréter dans une expérience plus large."},{"number":38,"points":33,"passage":"Une ville installe des équipements sportifs dans un parc. Les services observent des usages imprévus : certains habitants s'y retrouvent pour discuter et font quelques mouvements ensemble. Plutôt que restreindre cet usage, ils ajoutent des bancs. Un aménagement peut produire des bénéfices différents de ceux que ses concepteurs avaient précisément anticipés. Les agents constatent que les rencontres régulières encouragent parfois des personnes jusque-là hésitantes à essayer les appareils. Ils vont donc continuer à observer le lieu à différentes heures avant de fixer de nouvelles règles. Les usagers pourront proposer de petits changements et signaler les difficultés. La commune ne veut pas transformer chaque usage imprévu en erreur à corriger. Elle cherche à comprendre ce que l'installation rend possible dans la vie du quartier, au-delà du programme exact qui avait été imaginé sur le plan initial.","question":"Comment la ville réagit-elle ?","options":["Elle exige une pratique chronométrée","Elle retire immédiatement les appareils","Elle interdit toutes les conversations","Elle adapte le lieu aux usages réellement observés"],"correct":"D","explanation":"Le passage indique : « Un aménagement peut produire des bénéfices différents de ceux que ses concepteurs avaient précisément anticipés. » Cela justifie la réponse : Elle adapte le lieu aux usages réellement observés."},{"number":39,"points":33,"passage":"Une organisation souhaite prévenir l'épuisement professionnel en proposant des séances de relaxation. Les salariés apprécient l'offre, mais demandent aussi de revoir une répartition de tâches devenue irréaliste. Un soutien individuel peut être utile sans remplacer la transformation des conditions collectives qui produisent la difficulté. Certains décrivent des journées où les demandes s'ajoutent sans que les priorités soient revues. D'autres évoquent des interruptions qui rendent difficile l'achèvement d'une tâche. Les représentants souhaitent que ces éléments soient discutés avec les responsables du service. Ils ne demandent pas de supprimer les séances proposées, mais de ne pas les utiliser comme preuve que le problème serait désormais traité. Le programme sera donc accompagné d'un examen des effectifs, des délais et des possibilités de récupération. Son intérêt dépendra aussi de cette cohérence entre aide personnelle et fonctionnement quotidien du travail.","question":"Quelle complémentarité défendent-ils ?","options":["Supprimer les aides déjà proposées","Attribuer les difficultés aux salariés seulement","Associer soutien personnel et changements organisationnels","Remplacer toute discussion du travail par la relaxation"],"correct":"C","explanation":"Le passage indique : « Un soutien individuel peut être utile sans remplacer la transformation des conditions collectives qui produisent la difficulté. » Cela justifie la réponse : Associer soutien personnel et changements organisationnels."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-09','tcf-reading-2026-11-reference-v3',$paper${"id":"tcf-reading-09","version":"tcf-reading-2026-11-reference-v3","title":"TCF Reading · Test 09","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"Le planétarium annule la séance de midi pour réparation. Les billets restent valables pour celle de quinze heures.\n\nLes personnes indisponibles pourront contacter l'accueil pour un échange. La boutique restera ouverte pendant les horaires habituels du musée.","question":"Quelle solution est proposée ?","options":["Acheter un billet obligatoire","Assister à la séance de quinze heures","Revenir uniquement le mois prochain","Visiter gratuitement une autre ville"],"correct":"B","explanation":"Le passage indique : « Le planétarium annule la séance de midi pour réparation. Les billets restent valables pour celle de quinze heures. » Cela justifie la réponse : Assister à la séance de quinze heures."},{"number":2,"points":3,"passage":"L'atelier robotique prête des tournevis. Apportez seulement un carnet pour noter vos essais.\n\nLes animateurs montreront comment utiliser chaque outil. Aucun montage ne devra être commencé avant la présentation des consignes communes.","question":"Quel objet faut-il apporter ?","options":["Un carnet","Un tournevis","Une perceuse","Un robot terminé"],"correct":"A","explanation":"Le passage indique : « L'atelier robotique prête des tournevis. Apportez seulement un carnet pour noter vos essais. » Cela justifie la réponse : Un carnet."},{"number":3,"points":3,"passage":"Le laboratoire ouvre ses portes samedi sur inscription. Les enfants doivent être accompagnés ; les groupes scolaires ont un autre créneau.\n\nUne confirmation précisera l'entrée et la durée du parcours.","question":"Qui peut venir samedi ?","options":["Uniquement les chercheurs","Des enfants accompagnés et inscrits","Des classes sans réservation","Des mineurs obligatoirement seuls"],"correct":"B","explanation":"Le passage indique : « Le laboratoire ouvre ses portes samedi sur inscription. Les enfants doivent être accompagnés ; les groupes scolaires ont un autre créneau. » Cela justifie la réponse : Des enfants accompagnés et inscrits."},{"number":4,"points":3,"passage":"L'observation des étoiles dépend de la météo. Si le ciel est couvert, une présentation aura lieu dans la salle attenante.\n\nCette solution permet de conserver la rencontre même si les conditions extérieures sont défavorables.","question":"Que se passe-t-il en cas de nuages ?","options":["Tout le matériel est vendu","L'horaire est reporté d'un an","Les participants montent seuls sur le toit","L'activité se poursuit à l'intérieur"],"correct":"D","explanation":"Le passage indique : « L'observation des étoiles dépend de la météo. Si le ciel est couvert, une présentation aura lieu dans la salle attenante. » Cela justifie la réponse : L'activité se poursuit à l'intérieur."},{"number":5,"points":9,"passage":"Je t'envoie mes mesures demain après avoir vérifié le thermomètre. Les valeurs de ce matin semblaient inhabituelles.\n\nJ'ai demandé à une collègue de refaire un relevé avec un autre appareil. Nous comparerons les deux séries avant de rédiger le compte rendu et de tirer une conclusion.","question":"Pourquoi l'envoi est-il différé ?","options":["Pour supprimer tous les résultats","Pour attendre un financement","Pour contrôler la fiabilité de l'instrument","Pour changer le sujet du projet"],"correct":"C","explanation":"Le passage indique : « Je t'envoie mes mesures demain après avoir vérifié le thermomètre. Les valeurs de ce matin semblaient inhabituelles. » Cela justifie la réponse : Pour contrôler la fiabilité de l'instrument."},{"number":6,"points":9,"passage":"Le club d'astronomie accueille les curieux sans télescope personnel. Des instruments seront installés par les bénévoles.\n\nLes bénévoles aideront chacun à regarder et répondront aux questions. Une carte du ciel sera distribuée pour retrouver ensuite quelques repères sans matériel complexe.","question":"Quel équipement personnel est obligatoire ?","options":["Une caméra professionnelle","Une antenne radio","Aucun télescope n'est exigé","Un grand télescope"],"correct":"C","explanation":"Le passage indique : « Le club d'astronomie accueille les curieux sans télescope personnel. Des instruments seront installés par les bénévoles. » Cela justifie la réponse : Aucun télescope n'est exigé."},{"number":7,"points":9,"passage":"Notre groupe cherche un local sombre pour tester les lampes. Une grande fenêtre rendrait les comparaisons plus difficiles.\n\nIl nous faut surtout garder les mêmes conditions pendant les essais. Nous noterons chaque changement pour comprendre ce qui pourrait expliquer une différence entre deux résultats.","question":"Quelle caractéristique du local est recherchée ?","options":["Une faible lumière extérieure","Un accès réservé aux vendeurs","Une exposition maximale au soleil","Une température tropicale"],"correct":"A","explanation":"Le passage indique : « Notre groupe cherche un local sombre pour tester les lampes. Une grande fenêtre rendrait les comparaisons plus difficiles. » Cela justifie la réponse : Une faible lumière extérieure."},{"number":8,"points":9,"passage":"Bonjour, la conférence reste ouverte aux non-spécialistes. Le vocabulaire sera expliqué et un temps sera prévu pour les questions.\n\nLes personnes souhaitant approfondir recevront des références après la rencontre, sans devoir tout comprendre dès les premières minutes.","question":"À quel public s'adresse l'événement ?","options":["Aussi aux personnes sans formation scientifique","Uniquement aux chercheurs diplômés","Seulement aux vendeurs d'instruments","Aux participants refusant les explications"],"correct":"A","explanation":"Le passage indique : « Bonjour, la conférence reste ouverte aux non-spécialistes. Le vocabulaire sera expliqué et un temps sera prévu pour les questions. » Cela justifie la réponse : Aussi aux personnes sans formation scientifique."},{"number":9,"points":9,"passage":"Apportez votre appareil cassé à l'atelier démontage. Nous étudierons ses composants, sans garantir sa remise en marche.\n\nLes objets dangereux ou trop volumineux seront refusés, et les propriétaires repartiront avec les pièces à la fin de la séance.","question":"Quel résultat n'est pas garanti ?","options":["La présence d'un animateur","L'observation des pièces","L'ouverture de l'atelier","La réparation de l'appareil"],"correct":"D","explanation":"Le passage indique : « Apportez votre appareil cassé à l'atelier démontage. Nous étudierons ses composants, sans garantir sa remise en marche. » Cela justifie la réponse : La réparation de l'appareil."},{"number":10,"points":9,"passage":"Nous répéterons l'expérience avec des récipients identiques. Les formes différentes utilisées hier empêchaient de comparer correctement.\n\nNous conserverons les autres paramètres pour mieux identifier l'effet observé. Le groupe préparera un tableau commun avant de recommencer les mesures dans les conditions prévues.","question":"Pourquoi changer les récipients ?","options":["Éviter toute répétition","Obtenir un résultat décidé d'avance","Rendre les conditions comparables","Augmenter la couleur des liquides"],"correct":"C","explanation":"Le passage indique : « Nous répéterons l'expérience avec des récipients identiques. Les formes différentes utilisées hier empêchaient de comparer correctement. » Cela justifie la réponse : Rendre les conditions comparables."},{"number":11,"points":15,"passage":"Des collégiens mesurent l'ombre d'un bâton à plusieurs heures. Ils gardent le bâton au même endroit pour observer l'évolution au cours de la journée.\n\nIls notent chaque observation sur un dessin du sol, avec la date et l'état du ciel. Les journées couvertes donnent aussi lieu à une discussion sur ce qui reste visible. Leur professeur ne leur demande pas de retrouver un chiffre annoncé d'avance, mais de décrire une série cohérente. Les résultats seront comparés entre deux groupes pour repérer les difficultés de lecture. Les élèves expliqueront ensuite les limites de leur expérience, notamment ce qu'ils ne peuvent pas déduire d'une seule journée d'observation.","question":"Qu'est-ce qui varie dans leur protocole ?","options":["L'heure de la mesure","Le lieu choisi","La longueur du bâton","Le nombre de saisons"],"correct":"A","explanation":"Le passage indique : « Des collégiens mesurent l'ombre d'un bâton à plusieurs heures. Ils gardent le bâton au même endroit pour observer l'évolution au cours de la journée. » Cela justifie la réponse : L'heure de la mesure."},{"number":12,"points":15,"passage":"Une équipe publie aussi les essais qui n'ont pas confirmé son hypothèse. Ces résultats peuvent éviter à d'autres de répéter inutilement les mêmes démarches.\n\nLe compte rendu décrit les conditions et les vérifications réalisées avant l'arrêt de la tentative. Les auteurs souhaitent rendre ces informations compréhensibles, même lorsque le résultat ne se transforme pas en application immédiate. Une autre équipe pourra ainsi comparer ses propres méthodes et identifier une différence utile.","question":"Quel intérêt présente cette publication ?","options":["Dissimuler les méthodes employées","Rendre les tentatives infructueuses utiles à d'autres","Remplacer les expériences futures par des opinions","Prouver que toute recherche échoue"],"correct":"B","explanation":"Le passage indique : « Une équipe publie aussi les essais qui n'ont pas confirmé son hypothèse. Ces résultats peuvent éviter à d'autres de répéter inutilement les mêmes démarches. » Cela justifie la réponse : Rendre les tentatives infructueuses utiles à d'autres."},{"number":13,"points":15,"passage":"Un musée prête une maquette démontable de volcan. Les visiteurs découvrent une représentation simplifiée, pas une reproduction de tous les phénomènes réels.\n\nLes médiateurs montrent ce qui a été conservé et ce qui a été laissé de côté pour rendre l'ensemble lisible. Les visiteurs peuvent poser des questions sur la différence entre une représentation et une observation sur le terrain. Des photographies et des mesures complètent donc l'activité. Elles permettent de comprendre pourquoi plusieurs outils sont nécessaires pour étudier un phénomène dont les dimensions et les rythmes ne tiennent pas dans une salle.","question":"Quelle limite de la maquette est indiquée ?","options":["Elle fonctionne comme un volcan réel","Elle remplace toutes les observations","Elle permet de prévoir toute éruption","Elle simplifie la réalité"],"correct":"D","explanation":"Le passage indique : « Un musée prête une maquette démontable de volcan. Les visiteurs découvrent une représentation simplifiée, pas une reproduction de tous les phénomènes réels. » Cela justifie la réponse : Elle simplifie la réalité."},{"number":14,"points":15,"passage":"Des bénévoles relèvent la température de leur quartier. Les capteurs sont placés à l'ombre, loin des murs chauffés par le soleil.\n\nLes participants reçoivent une fiche d'installation et photographient l'emplacement choisi. Une équipe vérifiera quelques points avant d'utiliser les séries dans une carte commune. Les habitants peuvent aussi noter les changements survenus autour du capteur, comme un déplacement ou des travaux. Le projet souhaite multiplier les observations sans présenter tous les nombres recueillis comme directement comparables. Les consignes communes servent à distinguer une différence entre quartiers d'un effet produit par la manière de placer l'appareil.","question":"Pourquoi préciser leur emplacement ?","options":["Rendre les capteurs invisibles aux oiseaux","Augmenter automatiquement les températures","Éviter une influence locale qui fausserait la comparaison","Accélérer la croissance des arbres"],"correct":"C","explanation":"Le passage indique : « Des bénévoles relèvent la température de leur quartier. Les capteurs sont placés à l'ombre, loin des murs chauffés par le soleil. » Cela justifie la réponse : Éviter une influence locale qui fausserait la comparaison."},{"number":15,"points":15,"passage":"Une invention facilite l'ouverture des bocaux. Ses concepteurs invitent des utilisateurs aux forces différentes pour tester la poignée.\n\nLes volontaires essaient plusieurs positions et expliquent les moments où la prise leur semble inconfortable. Les concepteurs notent aussi les remarques des personnes qui comprennent moins vite la forme du dispositif. L'essai ne consiste pas à choisir l'utilisateur le plus habile, mais à voir si la poignée facilite réellement le geste pour des personnes différentes. Les prototypes seront modifiés avant une seconde séance. Le groupe veut éviter qu'un bon résultat obtenu par une seule personne serve de promesse générale au moment de présenter le produit.","question":"Quel critère veulent-ils examiner ?","options":["Le prix du verre","La vitesse de livraison du produit","La couleur des couvercles","La facilité d'utilisation pour divers profils"],"correct":"D","explanation":"Le passage indique : « Une invention facilite l'ouverture des bocaux. Ses concepteurs invitent des utilisateurs aux forces différentes pour tester la poignée. » Cela justifie la réponse : La facilité d'utilisation pour divers profils."},{"number":16,"points":15,"passage":"Un observatoire diffuse des images en direct, mais archive aussi les séries anciennes. Les comparaisons dans le temps aident à repérer des évolutions lentes.\n\nLes responsables gardent les dates, les réglages et les informations sur les instruments utilisés. Les chercheurs qui consultent les archives peuvent ainsi apprécier les différences entre deux séries. L'observatoire souhaite que les anciennes données restent compréhensibles lorsque les appareils changent. Il ne conserve pas seulement de belles images, mais des éléments permettant de poser de nouvelles questions.","question":"À quoi servent les archives ?","options":["Éviter toute comparaison","Remplacer les images actuelles par des publicités","Observer des changements sur la durée","Garantir que rien ne change"],"correct":"C","explanation":"Le passage indique : « Un observatoire diffuse des images en direct, mais archive aussi les séries anciennes. Les comparaisons dans le temps aident à repérer des évolutions lentes. » Cela justifie la réponse : Observer des changements sur la durée."},{"number":17,"points":15,"passage":"Un fabricant annonce une batterie plus légère. L'équipe de test mesure aussi sa durée de fonctionnement avant de juger le progrès.\n\nLes essais portent sur des usages comparables, avec les mêmes réglages. L'équipe indique les conditions retenues pour que les lecteurs puissent apprécier la portée du résultat. Elle examine aussi les situations où le gain de poids serait particulièrement utile. Un appareil destiné à rester posé ne présente pas les mêmes besoins qu'un équipement porté pendant plusieurs heures. Les résultats seront donc présentés avec plusieurs critères plutôt qu'une seule formule annonçant un progrès identique pour tous les acheteurs.","question":"Quelle information complémentaire est nécessaire ?","options":["Le nombre d'affiches commerciales","Le nom du livreur","La forme de la facture","L'autonomie de la batterie"],"correct":"D","explanation":"Le passage indique : « Un fabricant annonce une batterie plus légère. L'équipe de test mesure aussi sa durée de fonctionnement avant de juger le progrès. » Cela justifie la réponse : L'autonomie de la batterie."},{"number":18,"points":15,"passage":"La médiathèque organise un débat avec une chercheuse. Les questions seront regroupées par thème pour éviter de répéter les mêmes échanges.\n\nLes participants peuvent envoyer une question auparavant ou la poser pendant le temps d'échange. L'animatrice expliquera pourquoi certaines demandes sont rapprochées et laissera la possibilité de signaler un point oublié. La bibliothèque souhaite conserver une discussion accessible malgré la diversité du public. La chercheuse pourra préciser ce qu'elle sait et ce qui dépasse son domaine de travail.","question":"Pourquoi regrouper les questions ?","options":["Écarter tous les non-spécialistes","Interdire les désaccords","Mieux organiser la discussion","Fixer les réponses avant le débat"],"correct":"C","explanation":"Le passage indique : « La médiathèque organise un débat avec une chercheuse. Les questions seront regroupées par thème pour éviter de répéter les mêmes échanges. » Cela justifie la réponse : Mieux organiser la discussion."},{"number":19,"points":15,"passage":"Un club construit un four solaire. Le repas prévu reste simple : l'objectif est de comprendre les effets de l'orientation et de l'ensoleillement.\n\nLes participants compareront plusieurs positions et noteront le temps nécessaire dans les conditions du jour. Le responsable a prévu une solution pour le repas si le ciel se couvre durablement. Il veut éviter que cette contrainte empêche de poursuivre les observations. Le groupe discutera ensuite de ce que l'essai montre réellement et des situations où un tel appareil peut être utile.","question":"Quel est l'objectif principal ?","options":["Explorer le fonctionnement du dispositif","Éviter de modifier l'orientation","Ouvrir immédiatement un restaurant","Garantir une cuisson par tous les temps"],"correct":"A","explanation":"Le passage indique : « Un club construit un four solaire. Le repas prévu reste simple : l'objectif est de comprendre les effets de l'orientation et de l'ensoleillement. » Cela justifie la réponse : Explorer le fonctionnement du dispositif."},{"number":20,"points":21,"passage":"Une étude compare deux matériaux sur de petites pièces. Ses auteurs demandent des essais supplémentaires avant de généraliser les résultats à de grandes constructions. Les spécialistes devront notamment examiner la résistance dans la durée et les contraintes de fabrication. Une petite pièce permet de contrôler facilement certaines conditions qui deviennent plus difficiles à maintenir ailleurs. Le laboratoire souhaite publier un résultat utile sans lui attribuer une portée que l'expérience n'a pas encore vérifiée. Les partenaires pourront ensuite choisir les essais nécessaires à leur propre projet.","question":"Quelle prudence expriment-ils ?","options":["Les essais sur petites pièces sont toujours inutiles","Le changement d'échelle doit être vérifié","Les matériaux sont déjà interdits","Toute comparaison est impossible"],"correct":"B","explanation":"Le passage indique : « Une étude compare deux matériaux sur de petites pièces. Ses auteurs demandent des essais supplémentaires avant de généraliser les résultats à de grandes constructions. » Cela justifie la réponse : Le changement d'échelle doit être vérifié."},{"number":21,"points":21,"passage":"Un laboratoire échange avec des artisans sur les usages d'un nouvel outil. Les chercheurs disposent de mesures précises ; les professionnels signalent des contraintes rencontrées pendant une journée réelle. Un outil rapide sur une table d'essai peut être difficile à nettoyer, à ranger ou à utiliser avec des gants. Les artisans décrivent ces situations avec des exemples. L'équipe veut intégrer ces remarques pendant qu'il est encore possible de modifier le prototype. La consultation ne remplace pas les mesures ; elle aide à choisir celles qui correspondent aux difficultés réellement rencontrées.","question":"Quel est l'intérêt de l'échange ?","options":["Éliminer les artisans du projet","Choisir uniquement la meilleure photographie","Croiser mesures techniques et expérience d'usage","Remplacer toute mesure par une anecdote"],"correct":"C","explanation":"Le passage indique : « Un laboratoire échange avec des artisans sur les usages d'un nouvel outil. Les chercheurs disposent de mesures précises ; les professionnels signalent des contraintes rencontrées pendant une journée réelle. » Cela justifie la réponse : Croiser mesures techniques et expérience d'usage."},{"number":22,"points":21,"passage":"Une annonce parle d'une découverte « prometteuse ». Le compte rendu précise qu'elle a été observée dans des conditions limitées. Les deux formulations ne sont pas contradictoires, mais elles n'autorisent pas la même attente. Les journalistes sont invités à expliquer la taille de l'essai et les étapes encore nécessaires. Les chercheurs ne souhaitent ni minimiser une piste intéressante, ni laisser croire qu'elle donne déjà une solution disponible pour tous.","question":"Que faut-il distinguer ?","options":["Un laboratoire et un musée","Un potentiel et un résultat déjà généralisable","Une expérience et une absence totale de résultat","Deux découvertes nécessairement opposées"],"correct":"B","explanation":"Le passage indique : « Une annonce parle d'une découverte « prometteuse ». Le compte rendu précise qu'elle a été observée dans des conditions limitées. Les deux formulations ne sont pas contradictoires, mais elles n'autorisent pas la même attente. » Cela justifie la réponse : Un potentiel et un résultat déjà généralisable."},{"number":23,"points":21,"passage":"Une ville utilise des capteurs pour repérer les îlots de chaleur. Elle confronte les données aux témoignages des habitants, notamment pour identifier les lieux utilisés aux heures chaudes. Certains points sont très chauds mais peu fréquentés, tandis que d'autres accueillent de longues attentes sans ombre. Les responsables souhaitent distinguer ces situations avant de décider où intervenir. Les témoignages ne changent pas la température mesurée ; ils apportent une information sur son importance dans la vie quotidienne.","question":"Pourquoi ajouter ces témoignages ?","options":["Relier les mesures aux situations vécues","Remplacer la carte par des votes","Annuler toutes les températures enregistrées","Garantir une météo uniforme"],"correct":"A","explanation":"Le passage indique : « Une ville utilise des capteurs pour repérer les îlots de chaleur. Elle confronte les données aux témoignages des habitants, notamment pour identifier les lieux utilisés aux heures chaudes. » Cela justifie la réponse : Relier les mesures aux situations vécues."},{"number":24,"points":21,"passage":"Un appareil de mesure devient moins cher. Les utilisateurs doivent toujours l'étalonner : une grande diffusion ne garantit pas que chaque instrument donne spontanément une valeur fiable. La notice fournit une procédure courte et un repère pour contrôler l'appareil. Les utilisateurs peuvent signaler une difficulté au distributeur ou à l'association qui organise les relevés. Un instrument accessible financièrement reste utile si les personnes savent aussi dans quelles conditions elles peuvent se fier aux valeurs qu'il affiche.","question":"Quelle exigence demeure ?","options":["L'absence de tout réglage","La vérification des mesures","La suppression des relevés","L'achat d'un appareil plus lourd"],"correct":"B","explanation":"Le passage indique : « Un appareil de mesure devient moins cher. Les utilisateurs doivent toujours l'étalonner : une grande diffusion ne garantit pas que chaque instrument donne spontanément une valeur fiable. » Cela justifie la réponse : La vérification des mesures."},{"number":25,"points":21,"passage":"Un concours récompense une solution réparable avec des outils courants. Le jury regarde aussi les pièces détachées disponibles ; une conception démontable serait peu utile sans possibilité de remplacer les éléments. Les candidats présentent un exemple de démontage et expliquent les outils nécessaires. Le jury demande aussi comment un utilisateur pourra identifier la pièce défectueuse. Il souhaite distinguer une possibilité théorique d'ouverture et une réparation réellement réalisable.","question":"Quel complément à la conception est nécessaire ?","options":["Un prix toujours croissant","Un brevet sur chaque vis","L'accès aux pièces de rechange","Un emballage impossible à ouvrir"],"correct":"C","explanation":"Le passage indique : « Un concours récompense une solution réparable avec des outils courants. Le jury regarde aussi les pièces détachées disponibles ; une conception démontable serait peu utile sans possibilité de remplacer les éléments. » Cela justifie la réponse : L'accès aux pièces de rechange."},{"number":26,"points":21,"passage":"Des scientifiques expliquent leur travail dans des ateliers publics. Ils présentent leurs désaccords sur certaines interprétations sans remettre en cause les observations communes. Les visiteurs découvrent des méthodes communes de vérification, mais aussi des questions qui restent ouvertes. Les intervenants expliquent comment ils comparent leurs interprétations et quelles observations pourraient les conduire à changer d'avis. Le programme veut donner une image plus précise du travail scientifique, sans le réduire à une collection de certitudes ni à une simple opposition d'opinions sans critères partagés.","question":"Que montre cette démarche ?","options":["Tout désaccord annule toutes les observations","Les données ne jouent aucun rôle","La science exige une opinion identique sur tout","Un accord sur des faits peut coexister avec des débats"],"correct":"D","explanation":"Le passage indique : « Des scientifiques expliquent leur travail dans des ateliers publics. Ils présentent leurs désaccords sur certaines interprétations sans remettre en cause les observations communes. » Cela justifie la réponse : Un accord sur des faits peut coexister avec des débats."},{"number":27,"points":21,"passage":"Un logiciel repère des anomalies dans des photographies. Les cas signalés sont ensuite examinés par une personne. L'outil accélère le tri, mais ne remplace pas la décision finale. Les personnes chargées de la lecture finale doivent comprendre les erreurs possibles et les limites des images utilisées. Le laboratoire conserve aussi des exemples où le logiciel n'a rien signalé, afin de vérifier ce qu'il pourrait manquer.","question":"Quel rôle lui est attribué ?","options":["Décider seul de tous les résultats","Assister une vérification humaine","Interdire les contrôles","Supprimer les photographies utiles"],"correct":"B","explanation":"Le passage indique : « Un logiciel repère des anomalies dans des photographies. Les cas signalés sont ensuite examinés par une personne. L'outil accélère le tri, mais ne remplace pas la décision finale. » Cela justifie la réponse : Assister une vérification humaine."},{"number":28,"points":21,"passage":"Une équipe répète une expérience dans un second laboratoire. Les conditions sont décrites précisément afin de comprendre d'éventuelles différences. Les équipes gardent une trace des réglages et discutent des écarts avant de modifier leur protocole. Elles veulent distinguer un effet du matériel d'une différence liée à la préparation. Il reste essentiel pour savoir dans quelles conditions un résultat peut être utilisé par d'autres personnes et avec quel degré de confiance.","question":"Quel objectif poursuit cette répétition ?","options":["Obtenir automatiquement la même opinion","Remplacer les instruments par un questionnaire","Tester la robustesse du résultat","Éviter d'expliquer les méthodes"],"correct":"C","explanation":"Le passage indique : « Une équipe répète une expérience dans un second laboratoire. Les conditions sont décrites précisément afin de comprendre d'éventuelles différences. » Cela justifie la réponse : Tester la robustesse du résultat."},{"number":29,"points":21,"passage":"Une exposition présente des inventions abandonnées. Certaines avaient de bonnes performances techniques, mais ne répondaient pas aux pratiques ou aux moyens des utilisateurs. Les visiteurs peuvent ainsi suivre une histoire moins simple qu'une opposition entre réussite et mauvaise invention. Le musée souhaite montrer que l'adoption d'un objet dépend de plusieurs acteurs et de contraintes concrètes, qui ne sont pas toujours visibles dans une démonstration technique réalisée devant un public enthousiaste.","question":"Que révèle cette sélection ?","options":["Une bonne performance garantit le succès","Le coût n'a aucun effet sur l'usage","L'utilité dépend aussi du contexte d'adoption","Toutes les inventions anciennes étaient défectueuses"],"correct":"C","explanation":"Le passage indique : « Une exposition présente des inventions abandonnées. Certaines avaient de bonnes performances techniques, mais ne répondaient pas aux pratiques ou aux moyens des utilisateurs. » Cela justifie la réponse : L'utilité dépend aussi du contexte d'adoption."},{"number":30,"points":26,"passage":"Un chiffre moyen résume une série de mesures, mais peut masquer des écarts importants. Une médiatrice montre deux ensembles ayant la même moyenne et des répartitions très différentes. L'indicateur reste correct ; sa lecture doit être complétée. Elle invite donc le public à regarder plusieurs valeurs et les écarts entre elles. Les participants apprennent à poser une question sur ce qu'un résumé laisse visible ou rend plus difficile à voir.","question":"Quelle leçon veut-elle transmettre ?","options":["Les moyennes sont toujours fausses","Les mesures individuelles ne servent jamais","Deux moyennes égales prouvent des situations identiques","Une moyenne ne décrit pas toute la distribution"],"correct":"D","explanation":"Le passage indique : « Un chiffre moyen résume une série de mesures, mais peut masquer des écarts importants. Une médiatrice montre deux ensembles ayant la même moyenne et des répartitions très différentes. L'indicateur reste correct ; sa lecture doit être complétée. » Cela justifie la réponse : Une moyenne ne décrit pas toute la distribution."},{"number":31,"points":26,"passage":"Un prototype fonctionne en démonstration sous la surveillance de ses concepteurs. Pour apprécier son usage futur, il faut aussi observer l'entretien, les erreurs ordinaires et les contraintes des lieux d'installation. La réussite ponctuelle ne constitue pas encore un bilan d'utilisation. Le fabricant souhaite que les futurs utilisateurs puissent apprécier l'écart entre une possibilité technique montrée une fois et un service fiable dans leurs propres conditions de travail.","question":"Quelle distinction est faite ?","options":["Démonstration réussie et fonctionnement quotidien","Matériel neuf et appareil obligatoirement inutile","Invention et absence de tout essai","Mesure scientifique et interdiction d'usage"],"correct":"A","explanation":"Le passage indique : « Un prototype fonctionne en démonstration sous la surveillance de ses concepteurs. Pour apprécier son usage futur, il faut aussi observer l'entretien, les erreurs ordinaires et les contraintes des lieux d'installation. La réussite ponctuelle ne constitue pas encore un bilan d'utilisation. » Cela justifie la réponse : Démonstration réussie et fonctionnement quotidien."},{"number":32,"points":26,"passage":"Les collections anciennes d'un musée peuvent servir à de nouvelles recherches. Des méthodes récentes révèlent des informations que les premiers collecteurs ne pouvaient pas observer. La conservation maintient ainsi des possibilités de questions futures, pas seulement le souvenir d'un savoir déjà établi. Les chercheurs peuvent revenir sur des spécimens avec des questions nouvelles. La valeur d'une collection dépend alors aussi des descriptions et des conditions de conservation qui permettent de comprendre ce qui a été recueilli à l'époque.","question":"Quelle valeur supplémentaire est attribuée aux collections ?","options":["Prouver que toutes les questions ont leur réponse","Remplacer tous les laboratoires","Empêcher les méthodes nouvelles","Permettre de nouvelles investigations"],"correct":"D","explanation":"Le passage indique : « Les collections anciennes d'un musée peuvent servir à de nouvelles recherches. Des méthodes récentes révèlent des informations que les premiers collecteurs ne pouvaient pas observer. La conservation maintient ainsi des possibilités de questions futures, pas seulement le souvenir d'un savoir déjà établi. » Cela justifie la réponse : Permettre de nouvelles investigations."},{"number":33,"points":26,"passage":"Une représentation graphique peut simplifier un ensemble complexe sans le trahir. Le risque apparaît lorsqu'elle efface une limite essentielle, par exemple une incertitude sur une estimation. La clarté ne consiste donc pas toujours à retirer des informations, mais à rendre visibles celles qui changent l'interprétation. Le médiateur présente les choix de représentation et invite les lecteurs à comparer deux versions.","question":"Que faut-il préserver dans la simplification ?","options":["Un résultat présenté comme certain à tout prix","Les éléments nécessaires à une interprétation juste","Tous les détails sans hiérarchie","Uniquement les couleurs du graphique"],"correct":"B","explanation":"Le passage indique : « Une représentation graphique peut simplifier un ensemble complexe sans le trahir. Le risque apparaît lorsqu'elle efface une limite essentielle, par exemple une incertitude sur une estimation. La clarté ne consiste donc pas toujours à retirer des informations, mais à rendre visibles celles qui changent l'interprétation. » Cela justifie la réponse : Les éléments nécessaires à une interprétation juste."},{"number":34,"points":26,"passage":"Un programme encourage les jeunes à inventer rapidement une solution. Les animateurs ajoutent ensuite une étape d'observation du problème avec les utilisateurs. Une réponse ingénieuse peut être mal orientée si la difficulté initiale a été définie sans ceux qui la rencontrent. Le centre souhaite préserver l'imagination des participants tout en l'orientant vers une difficulté qu'ils ont suffisamment comprise pour proposer une réponse réellement pertinente.","question":"Pourquoi modifier le programme ?","options":["Mieux comprendre le besoin avant de stabiliser la solution","Interdire toute idée technique","Garantir une invention sans essai","Réduire la place des utilisateurs"],"correct":"A","explanation":"Le passage indique : « Un programme encourage les jeunes à inventer rapidement une solution. Les animateurs ajoutent ensuite une étape d'observation du problème avec les utilisateurs. Une réponse ingénieuse peut être mal orientée si la difficulté initiale a été définie sans ceux qui la rencontrent. » Cela justifie la réponse : Mieux comprendre le besoin avant de stabiliser la solution."},{"number":35,"points":26,"passage":"Une publication scientifique accepte qu'une hypothèse soit corrigée à la lumière de nouveaux résultats. Ce changement n'est pas automatiquement une preuve d'incompétence initiale. Il peut manifester une démarche qui accepte de distinguer ce qui était plausible de ce que les observations permettent désormais d'affirmer. Ils souhaitent que le lecteur puisse suivre le raisonnement, plutôt que prendre la modification comme une simple contradiction sans explication.","question":"Quelle conception du savoir est défendue ?","options":["Un refus de publier les observations","Une opinion qu'aucune donnée ne peut modifier","Une certitude identique dès la première question","Un savoir révisable selon les preuves disponibles"],"correct":"D","explanation":"Le passage indique : « Une publication scientifique accepte qu'une hypothèse soit corrigée à la lumière de nouveaux résultats. Ce changement n'est pas automatiquement une preuve d'incompétence initiale. Il peut manifester une démarche qui accepte de distinguer ce qui était plausible de ce que les observations permettent désormais d'affirmer. » Cela justifie la réponse : Un savoir révisable selon les preuves disponibles."},{"number":36,"points":33,"passage":"Une fondation souhaite ne financer que des recherches dont l'application serait immédiatement prévisible. Des chercheurs rappellent que certaines méthodes utiles aujourd'hui proviennent de travaux d'abord motivés par des questions fondamentales. Exiger d'avance un bénéfice précis peut écarter des explorations dont l'intérêt se révèle autrement ou plus tard. Les responsables de la fondation craignent de financer des travaux dont ils ne pourraient pas annoncer rapidement l'utilité au public. Les chercheurs proposent donc des comptes rendus qui rendent visible la progression des questions et des méthodes. Ils ne demandent pas de renoncer à tout bilan. Ils veulent seulement éviter qu'un calendrier trop court et une définition unique du bénéfice empêchent d'explorer des pistes importantes. La discussion porte ainsi sur les formes de responsabilité d'un projet, et sur la manière d'expliquer un travail dont les effets ne peuvent pas toujours être prévus avec précision au moment de son lancement.","question":"Quel risque est souligné ?","options":["Réduire la diversité des voies de découverte","Financer automatiquement toutes les recherches","Garantir des résultats inutiles dans chaque projet","Supprimer le besoin de méthodes fiables"],"correct":"A","explanation":"Le passage indique : « Exiger d'avance un bénéfice précis peut écarter des explorations dont l'intérêt se révèle autrement ou plus tard. » Cela justifie la réponse : Réduire la diversité des voies de découverte."},{"number":37,"points":33,"passage":"Une simulation aide une commune à anticiper les crues. Ses cartes dépendent d'hypothèses sur la pluie et l'état des sols. Les responsables les utilisent pour comparer des scénarios, sans les présenter comme une photographie certaine de l'avenir. La force de l'outil tient à l'explicitation des possibles, non à la disparition de l'incertitude. La commune publiera les hypothèses principales et présentera plusieurs situations aux habitants. Certaines cartes permettront d'examiner un épisode fréquent, d'autres un événement plus rare mais plus grave. Les responsables devront choisir des aménagements qui restent utiles malgré cette diversité. Ils souhaitent que l'outil aide à comprendre leurs décisions, sans lui attribuer la responsabilité de les prendre seul. Les personnes concernées pourront ainsi discuter des priorités et des limites du dispositif.","question":"Comment la simulation est-elle utilisée ?","options":["Comme une garantie exacte de chaque événement futur","Comme un appui à la comparaison de scénarios","Comme un substitut à toute décision publique","Comme une représentation indépendante de ses hypothèses"],"correct":"B","explanation":"Le passage indique : « La force de l'outil tient à l'explicitation des possibles, non à la disparition de l'incertitude. » Cela justifie la réponse : Comme un appui à la comparaison de scénarios."},{"number":38,"points":33,"passage":"Une équipe cherche à reproduire un résultat publié et obtient un écart. Avant d'accuser les premiers auteurs, elle examine les instruments, les matériaux et les conditions de l'essai. Un désaccord expérimental devient une source d'information lorsqu'on recherche ce qui le produit, plutôt que de le réduire immédiatement à une faute. Les deux laboratoires échangent leurs observations et préparent de nouveaux essais. Ils découvrent parfois qu'un détail jugé secondaire dans le premier compte rendu modifie le résultat. Cette découverte peut enrichir la compréhension du phénomène, même si elle complique l'annonce initiale. Les chercheurs souhaitent rendre ces étapes visibles pour éviter que toute différence soit interprétée comme un conflit personnel. La publication des méthodes devient alors aussi importante que celle de la conclusion. D'autres équipes pourront examiner les mêmes éléments, essayer des conditions différentes et préciser progressivement la portée de ce qui a été observé.","question":"Quelle attitude est mise en valeur ?","options":["Écarter les nouveaux résultats sans examen","Considérer toute reproduction comme inutile","Conclure immédiatement à une fraude","Enquêter sur les causes de l'écart"],"correct":"D","explanation":"Le passage indique : « Un désaccord expérimental devient une source d'information lorsqu'on recherche ce qui le produit, plutôt que de le réduire immédiatement à une faute. » Cela justifie la réponse : Enquêter sur les causes de l'écart."},{"number":39,"points":33,"passage":"Des citoyens participent à une enquête sur la qualité de l'air. Les scientifiques les associent au choix des lieux, mais conservent un protocole commun de mesure. La participation n'exige pas l'abandon de la rigueur ; elle peut enrichir les questions posées tout en maintenant des conditions qui rendent les résultats comparables. Les habitants connaissent des endroits où les personnes attendent longtemps et des horaires où la circulation change. Ils apportent ces repères lors de la préparation des relevés. Les spécialistes expliquent ensuite les règles de placement et les vérifications nécessaires pour éviter des comparaisons trompeuses. Le groupe discutera les résultats ensemble, avec les circonstances de chaque mesure. Les participants ne deviennent pas interchangeables, mais leurs connaissances se complètent. Le projet souhaite ainsi produire des informations plus utiles au territoire, tout en permettant au public de comprendre comment un résultat est construit et quelles questions il laisse encore ouvertes.","question":"Quelle articulation est défendue ?","options":["Remplacer les données par un vote sur les résultats","Associer expérience citoyenne et méthode partagée","Réserver toutes les questions aux seuls experts","Laisser chaque mesure sans règle commune"],"correct":"B","explanation":"Le passage indique : « La participation n'exige pas l'abandon de la rigueur ; elle peut enrichir les questions posées tout en maintenant des conditions qui rendent les résultats comparables. » Cela justifie la réponse : Associer expérience citoyenne et méthode partagée."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-10','tcf-reading-2026-11-reference-v3',$paper${"id":"tcf-reading-10","version":"tcf-reading-2026-11-reference-v3","title":"TCF Reading · Test 10","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"La salle d'étude ouvre désormais le dimanche matin. Le prêt de documents reste fermé ce jour-là.\n\nLe personnel pourra orienter les lecteurs vers les rayons accessibles. Merci de respecter les espaces réservés au travail silencieux.","question":"Quel service est disponible dimanche ?","options":["Rencontrer tous les enseignants","Travailler dans la salle","Emprunter des livres","Inscrire une classe"],"correct":"B","explanation":"Le passage indique : « La salle d'étude ouvre désormais le dimanche matin. Le prêt de documents reste fermé ce jour-là. » Cela justifie la réponse : Travailler dans la salle."},{"number":2,"points":3,"passage":"Le cours d'initiation commence mercredi. Aucun niveau préalable n'est demandé ; le matériel sera prêté.\n\nUne première rencontre permettra de présenter les objectifs et l'organisation. Les candidats peuvent poser leurs questions avant de confirmer.","question":"Qui peut s'inscrire ?","options":["Une personne déjà experte","Une personne débutante","Uniquement un diplômé","Un professeur seulement"],"correct":"B","explanation":"Le passage indique : « Le cours d'initiation commence mercredi. Aucun niveau préalable n'est demandé ; le matériel sera prêté. » Cela justifie la réponse : Une personne débutante."},{"number":3,"points":3,"passage":"Les copies seront remises lundi en classe. Les élèves absents pourront les récupérer au secrétariat mardi.\n\nLe secrétariat demandera simplement le nom de l'élève et sa classe. Les documents ne seront pas laissés dans un lieu ouvert à tous.","question":"Où un élève absent pourra-t-il récupérer sa copie ?","options":["Dans une autre école","Uniquement par courrier","Au secrétariat mardi","À la bibliothèque dimanche"],"correct":"C","explanation":"Le passage indique : « Les copies seront remises lundi en classe. Les élèves absents pourront les récupérer au secrétariat mardi. » Cela justifie la réponse : Au secrétariat mardi."},{"number":4,"points":3,"passage":"La réunion des parents se déroulera sans les élèves. Un accueil gratuit des enfants est organisé dans la salle voisine.\n\nLe service est proposé pendant toute la durée des échanges. Merci de signaler le nombre d'enfants au moment de confirmer votre venue.","question":"Quel accompagnement est proposé ?","options":["Un cours obligatoire pour les parents","Un examen pour les enfants","Une sortie scolaire payante","Une garde pendant la réunion"],"correct":"D","explanation":"Le passage indique : « La réunion des parents se déroulera sans les élèves. Un accueil gratuit des enfants est organisé dans la salle voisine. » Cela justifie la réponse : Une garde pendant la réunion."},{"number":5,"points":9,"passage":"Je suis inscrit au cours du soir, mais je travaillerai deux mercredis ce mois-ci. Pourrais-tu me transmettre les exercices de ces séances ?\n\nJe veux éviter de prendre du retard avant le prochain chapitre. Si certains points demandent une explication, je contacterai ensuite le formateur pour savoir comment les reprendre.","question":"Que demande cette personne ?","options":["Un changement définitif de professeur","Une dispense de tous les cours","Les exercices qu'elle manquera","Un diplôme sans examen"],"correct":"C","explanation":"Le passage indique : « Je suis inscrit au cours du soir, mais je travaillerai deux mercredis ce mois-ci. Pourrais-tu me transmettre les exercices de ces séances ? » Cela justifie la réponse : Les exercices qu'elle manquera."},{"number":6,"points":9,"passage":"Votre inscription est reçue. Le groupe n'ouvrira que si six personnes confirment ; nous vous informerons avant tout paiement.\n\nLe centre vous indiquera aussi les autres créneaux possibles. Si le groupe n'ouvre pas, vous pourrez choisir une autre formule ou renoncer sans frais.","question":"Quelle condition détermine l'ouverture ?","options":["Un nombre minimal de confirmations","La réussite à un concours","Une expérience professionnelle précise","L'achat immédiat d'un manuel"],"correct":"A","explanation":"Le passage indique : « Votre inscription est reçue. Le groupe n'ouvrira que si six personnes confirment ; nous vous informerons avant tout paiement. » Cela justifie la réponse : Un nombre minimal de confirmations."},{"number":7,"points":9,"passage":"Apporte un objet de ton choix pour la séance de langue. Il servira de point de départ à une courte présentation orale.\n\nVous pourrez expliquer pourquoi vous l'avez choisi et raconter un souvenir qui lui est associé. Aucun objet coûteux ou particulièrement original n'est nécessaire pour participer à cet exercice.","question":"À quoi servira l'objet ?","options":["Être vendu en classe","Décorer définitivement l'école","Remplacer l'inscription","Soutenir une prise de parole"],"correct":"D","explanation":"Le passage indique : « Apporte un objet de ton choix pour la séance de langue. Il servira de point de départ à une courte présentation orale. » Cela justifie la réponse : Soutenir une prise de parole."},{"number":8,"points":9,"passage":"Je souhaite apprendre à lire les plans de mon atelier, pas préparer un examen général. Peux-tu m'indiquer le module correspondant ?\n\nJ'utilise déjà ces documents au quotidien, mais certains symboles restent difficiles à interpréter.","question":"Quel besoin est exprimé ?","options":["Un cours de dessin artistique uniquement","Un changement de lieu de travail","Une préparation à tous les examens","Un apprentissage lié à une tâche précise"],"correct":"D","explanation":"Le passage indique : « Je souhaite apprendre à lire les plans de mon atelier, pas préparer un examen général. Peux-tu m'indiquer le module correspondant ? » Cela justifie la réponse : Un apprentissage lié à une tâche précise."},{"number":9,"points":9,"passage":"La bibliothèque organise un échange de méthodes de révision. Chaque participant peut présenter une pratique qui l'aide, sans prétendre qu'elle convient à tous.\n\nL'animateur aidera à comparer les pratiques et les situations dans lesquelles elles fonctionnent.","question":"Quelle attitude est attendue ?","options":["Écarter les débutants","Partager une méthode sans l'imposer","Défendre une solution obligatoire","Comparer les notes publiquement"],"correct":"B","explanation":"Le passage indique : « La bibliothèque organise un échange de méthodes de révision. Chaque participant peut présenter une pratique qui l'aide, sans prétendre qu'elle convient à tous. » Cela justifie la réponse : Partager une méthode sans l'imposer."},{"number":10,"points":9,"passage":"Le stage d'été comprend des matinées encadrées et des après-midi de travail autonome. Un tuteur reste joignable pendant ces périodes.\n\nLes participants auront quelques exercices à terminer et pourront organiser leur temps. Une rencontre courte permettra de vérifier les difficultés avant de poursuivre la suite du programme.","question":"Comment sont organisés les après-midi ?","options":["En autonomie avec une aide possible","Sans aucun travail prévu","Avec un examen permanent","Uniquement en présence du directeur"],"correct":"A","explanation":"Le passage indique : « Le stage d'été comprend des matinées encadrées et des après-midi de travail autonome. Un tuteur reste joignable pendant ces périodes. » Cela justifie la réponse : En autonomie avec une aide possible."},{"number":11,"points":15,"passage":"Une école propose une version audio des consignes. Le texte écrit demeure disponible ; les élèves peuvent choisir le support qui les aide.\n\nLes supports sont préparés avec le même contenu pour que personne ne reçoive une consigne différente par erreur. Les élèves peuvent réécouter un passage ou revenir au texte lorsqu'un mot leur échappe. L'équipe souhaite distinguer la compréhension de la tâche et les difficultés d'accès à son énoncé. Les enseignants observeront les usages avant de décider quels documents adapter ensuite. Ils ne présentent pas le choix du support comme une dispense d'apprendre à lire, mais comme une aide pour participer aux activités prévues.","question":"Quel principe est retenu ?","options":["Multiplier les moyens d'accès à la consigne","Imposer une seule méthode","Réserver l'audio aux enseignants","Supprimer la lecture pour tous"],"correct":"A","explanation":"Le passage indique : « Une école propose une version audio des consignes. Le texte écrit demeure disponible ; les élèves peuvent choisir le support qui les aide. » Cela justifie la réponse : Multiplier les moyens d'accès à la consigne."},{"number":12,"points":15,"passage":"Un atelier de conversation accueille des adultes de niveaux différents. Les activités alternent échanges libres et petits groupes pour que chacun puisse prendre la parole.\n\nLes personnes peuvent commencer par des échanges courts puis rejoindre une discussion plus longue. Les animateurs proposent des thèmes proches du quotidien et demandent aux habitués de laisser un temps de réponse. Le centre veut éviter qu'un niveau élevé chez quelques participants rende les autres invisibles.","question":"Pourquoi varier les groupes ?","options":["Éviter toute interaction","Supprimer les activités libres","Favoriser la participation de chacun","Classer définitivement les participants"],"correct":"C","explanation":"Le passage indique : « Un atelier de conversation accueille des adultes de niveaux différents. Les activités alternent échanges libres et petits groupes pour que chacun puisse prendre la parole. » Cela justifie la réponse : Favoriser la participation de chacun."},{"number":13,"points":15,"passage":"Des élèves rédigent un journal scientifique. Avant publication, ils doivent distinguer les faits vérifiés des hypothèses qu'ils souhaitent tester.\n\nLes groupes doivent indiquer d'où viennent leurs informations et conserver les documents consultés. Un enseignant les aide à voir quand une formulation affirme davantage que ce que la source permet. Les textes seront relus avant d'être montrés aux autres classes. Le projet souhaite donner une expérience concrète de publication, avec ses responsabilités. Les élèves pourront poser de nouvelles questions sans les présenter immédiatement comme des découvertes établies. Ils apprendront aussi à expliquer une incertitude plutôt qu'à la cacher pour rendre leur article plus impressionnant.","question":"Quel apprentissage est travaillé ?","options":["Identifier le statut des informations","Écrire sans vérifier","Éliminer toutes les questions","Publier uniquement des certitudes personnelles"],"correct":"A","explanation":"Le passage indique : « Des élèves rédigent un journal scientifique. Avant publication, ils doivent distinguer les faits vérifiés des hypothèses qu'ils souhaitent tester. » Cela justifie la réponse : Identifier le statut des informations."},{"number":14,"points":15,"passage":"Une formation professionnelle reconnaît certains acquis après entretien et exercice. Le parcours peut donc être plus court pour une personne déjà expérimentée.\n\nLes candidats apportent des exemples de tâches réalisées et décrivent les responsabilités qu'ils avaient réellement. L'exercice permet de vérifier certains points sans se fier uniquement au titre d'un ancien poste. Cette reconnaissance ne garantit pas une validation automatique : elle sert à rendre le parcours plus pertinent. Les participants savent ainsi pourquoi certaines séances leur sont proposées et pourquoi d'autres ne doivent pas nécessairement être suivies une seconde fois.","question":"Pourquoi la durée peut-elle varier ?","options":["Les participants choisissent leur diplôme","Les examens sont tirés au sort","Les acquis initiaux sont pris en compte","Le tarif dépend de la taille des classes"],"correct":"C","explanation":"Le passage indique : « Une formation professionnelle reconnaît certains acquis après entretien et exercice. Le parcours peut donc être plus court pour une personne déjà expérimentée. » Cela justifie la réponse : Les acquis initiaux sont pris en compte."},{"number":15,"points":15,"passage":"Un enseignant autorise un premier essai non noté. Les élèves reçoivent un retour puis reprennent leur travail avant l'évaluation.\n\nLe retour porte sur des éléments précis du raisonnement et sur les moyens de progresser. Les élèves peuvent poser une question avant de reprendre le document. L'enseignant souhaite que la note finale ne soit pas la première information reçue sur la qualité de leur démarche. Il prévoit aussi un temps pour comparer les deux versions et identifier les changements utiles. Ce travail n'efface pas les exigences de l'évaluation ; il rend plus visible ce qui peut être appris entre une tentative initiale et une production plus aboutie.","question":"À quoi sert le premier essai ?","options":["Distribuer des notes secrètes","Éviter toute correction","Apprendre à partir des erreurs","Remplacer définitivement l'évaluation"],"correct":"C","explanation":"Le passage indique : « Un enseignant autorise un premier essai non noté. Les élèves reçoivent un retour puis reprennent leur travail avant l'évaluation. » Cela justifie la réponse : Apprendre à partir des erreurs."},{"number":16,"points":15,"passage":"La classe visite une entreprise après avoir préparé des questions. Le compte rendu devra comparer les attentes initiales et les observations réelles.\n\nCertains découvrent des tâches peu visibles pendant une simple présentation du métier. Les responsables de l'entreprise répondent aux questions, mais ne corrigent pas toutes les impressions à leur place. L'école souhaite que les jeunes apprennent à formuler un constat et à l'appuyer sur une situation concrète, plutôt qu'à reproduire uniquement les éléments les plus valorisants d'une brochure de recrutement ou d'une visite préparée pour eux.","question":"Quelle démarche est demandée ?","options":["Recopier une publicité sans commentaire","Évaluer le salaire des visiteurs","Donner uniquement une impression avant la visite","Confronter une représentation à l'expérience"],"correct":"D","explanation":"Le passage indique : « La classe visite une entreprise après avoir préparé des questions. Le compte rendu devra comparer les attentes initiales et les observations réelles. » Cela justifie la réponse : Confronter une représentation à l'expérience."},{"number":17,"points":15,"passage":"Un centre prête des calculatrices pour éviter que l'achat soit un obstacle à l'inscription. Les appareils doivent être rendus après le cours.\n\nLes étudiants peuvent poser des questions sans supposer qu'ils connaissent déjà le modèle. La formation ne veut pas évaluer une différence d'équipement familial à la place de la compétence travaillée. Les responsables suivront les demandes de prêt afin de prévoir un stock suffisant. Ils souhaitent que les personnes découvrent ce droit assez tôt pour ne pas abandonner une inscription simplement parce qu'elles pensent devoir acheter immédiatement du matériel supplémentaire.","question":"Quel problème cherche-t-on à réduire ?","options":["Une barrière matérielle à la formation","Le manque de places de parking","Le nombre de devoirs","La durée du trimestre"],"correct":"A","explanation":"Le passage indique : « Un centre prête des calculatrices pour éviter que l'achat soit un obstacle à l'inscription. Les appareils doivent être rendus après le cours. » Cela justifie la réponse : Une barrière matérielle à la formation."},{"number":18,"points":15,"passage":"Une école aménage un espace calme accessible pendant les pauses. Il complète la cour active sans imposer le silence à tous les élèves.\n\nLes élèves ont participé au choix des sièges et des règles d'usage. Certaines personnes y lisent, d'autres préfèrent simplement s'asseoir quelques minutes. L'établissement souhaite reconnaître des besoins différents pendant le même temps de pause. Le bilan portera sur la manière dont les espaces se complètent, plutôt que sur une compétition entre ceux qui choisissent de jouer dehors et ceux qui recherchent un environnement plus calme.","question":"Quel choix est offert ?","options":["La suppression de la cour","Différentes façons de vivre la pause","Une obligation de rester en classe","Un examen pendant la récréation"],"correct":"B","explanation":"Le passage indique : « Une école aménage un espace calme accessible pendant les pauses. Il complète la cour active sans imposer le silence à tous les élèves. » Cela justifie la réponse : Différentes façons de vivre la pause."},{"number":19,"points":15,"passage":"Un groupe apprend à identifier les sources d'une photographie. Les participants recherchent sa date et son contexte avant d'interpréter ce qu'elle semble montrer.\n\nLes animateurs montrent comment une même image peut circuler avec des commentaires différents. Les participants essaient ensuite la démarche sur des exemples préparés pour l'atelier. Ils ne cherchent pas à démontrer que toute photographie serait fausse, mais à comprendre ce qui permet de lui attribuer un sens précis.","question":"Quelle précaution est enseignée ?","options":["Vérifier le contexte de l'image","Se fier uniquement à sa première impression","Ignorer la date de publication","Compter les couleurs"],"correct":"A","explanation":"Le passage indique : « Un groupe apprend à identifier les sources d'une photographie. Les participants recherchent sa date et son contexte avant d'interpréter ce qu'elle semble montrer. » Cela justifie la réponse : Vérifier le contexte de l'image."},{"number":20,"points":21,"passage":"Des adultes souhaitent reprendre des études, mais hésitent à suivre un long programme. Le centre propose un premier module court, dont les acquis pourront être conservés s'ils continuent. Le centre précise les étapes suivantes et les conditions de reprise dès le début. Les personnes peuvent ainsi décider si elles souhaitent poursuivre après avoir découvert le rythme et le travail demandé. L'objectif est de proposer une première expérience suffisamment complète pour être utile, sans transformer une hésitation initiale en échec. Les acquis seront décrits dans un document conservé par l'apprenant.","question":"Que permet ce dispositif ?","options":["Éviter tout travail personnel","Obtenir immédiatement tous les diplômes","Interdire une poursuite d'études","Commencer progressivement sans perdre ses acquis"],"correct":"D","explanation":"Le passage indique : « Des adultes souhaitent reprendre des études, mais hésitent à suivre un long programme. Le centre propose un premier module court, dont les acquis pourront être conservés s'ils continuent. » Cela justifie la réponse : Commencer progressivement sans perdre ses acquis."},{"number":21,"points":21,"passage":"Une équipe enseignante analyse les questions posées après le cours. Des demandes répétées sur une consigne peuvent indiquer un problème d'explication, pas seulement un manque d'attention des élèves. Les formateurs regroupent les difficultés récurrentes et comparent la façon dont les consignes ont été présentées. Ils peuvent alors modifier un exemple ou prévoir une explication supplémentaire. Elle permet simplement de ne pas attribuer automatiquement une difficulté collective à des défauts individuels, alors qu'une même formulation a peut-être laissé plusieurs personnes dans l'incertitude.","question":"Quelle interprétation est ajoutée ?","options":["Toutes les questions sont inutiles","Les élèves comprennent toujours les consignes","La répétition prouve nécessairement un refus d'apprendre","La clarté de l'enseignement doit aussi être examinée"],"correct":"D","explanation":"Le passage indique : « Une équipe enseignante analyse les questions posées après le cours. Des demandes répétées sur une consigne peuvent indiquer un problème d'explication, pas seulement un manque d'attention des élèves. » Cela justifie la réponse : La clarté de l'enseignement doit aussi être examinée."},{"number":22,"points":21,"passage":"Un cours en ligne reste consultable longtemps, mais prévoit des rendez-vous réguliers avec un tuteur. Les concepteurs veulent associer souplesse d'accès et soutien dans la durée. Les échanges avec le tuteur servent à préparer les étapes suivantes et à discuter des obstacles rencontrés. Les participants n'ont pas tous le même emploi du temps ni le même équipement. Le programme prévoit donc plusieurs possibilités de rendez-vous, sans laisser chacun seul face à une liste de vidéos.","question":"Quels éléments sont combinés ?","options":["Isolement et contrôle permanent","Absence d'horaires et absence de contact","Cours uniquement en présence","Autonomie et accompagnement"],"correct":"D","explanation":"Le passage indique : « Un cours en ligne reste consultable longtemps, mais prévoit des rendez-vous réguliers avec un tuteur. Les concepteurs veulent associer souplesse d'accès et soutien dans la durée. » Cela justifie la réponse : Autonomie et accompagnement."},{"number":23,"points":21,"passage":"Une école invite les familles à expliquer les langues utilisées à la maison. Le projet ne mesure pas une maîtrise parfaite ; il rend visibles des ressources souvent absentes des échanges scolaires. Les enfants peuvent apporter une chanson, expliquer une expression ou raconter un usage quotidien. Les enseignants ne demandent pas aux parents de représenter toute une langue ou tout un pays. Ils souhaitent donner une place à des expériences présentes dans la classe, sans transformer l'activité en concours.","question":"Quel objectif est poursuivi ?","options":["Imposer une langue unique au domicile","Classer les familles selon leurs revenus","Reconnaître des pratiques linguistiques diverses","Organiser un examen pour les parents"],"correct":"C","explanation":"Le passage indique : « Une école invite les familles à expliquer les langues utilisées à la maison. Le projet ne mesure pas une maîtrise parfaite ; il rend visibles des ressources souvent absentes des échanges scolaires. » Cela justifie la réponse : Reconnaître des pratiques linguistiques diverses."},{"number":24,"points":21,"passage":"Un atelier de programmation commence par un problème concret, puis introduit les commandes nécessaires. Les participants comprennent ainsi à quoi sert l'outil avant d'en mémoriser la syntaxe. Les premiers essais peuvent être faits sans écrire toutes les lignes à partir de zéro. Les participants pourront modifier l'exemple et observer le résultat. Le centre souhaite que les nouvelles commandes deviennent des moyens d'agir et de comprendre, plutôt que des mots mémorisés sans lien avec un objectif identifiable.","question":"Quelle progression pédagogique est choisie ?","options":["Éviter toute mise en pratique","Commencer par un classement des participants","Apprendre toutes les commandes sans usage","Partir d'un besoin pour introduire les notions"],"correct":"D","explanation":"Le passage indique : « Un atelier de programmation commence par un problème concret, puis introduit les commandes nécessaires. Les participants comprennent ainsi à quoi sert l'outil avant d'en mémoriser la syntaxe. » Cela justifie la réponse : Partir d'un besoin pour introduire les notions."},{"number":25,"points":21,"passage":"Une association propose un tutorat entre élèves. Les tuteurs apprennent à poser des questions plutôt qu'à fournir directement la réponse. Les élèves préparant une aide reçoivent quelques repères pour écouter et vérifier ce que leur camarade a déjà essayé. Ils doivent savoir quand demander l'intervention du professeur. Il donne à chacun un rôle précis et permet aussi de découvrir que comprendre un exercice et aider quelqu'un à le comprendre sont deux activités différentes.","question":"Quel rôle doivent-ils jouer ?","options":["Aider l'autre à construire sa démarche","Remplacer les enseignants dans toutes leurs tâches","Faire tous les exercices à sa place","Attribuer les notes finales"],"correct":"A","explanation":"Le passage indique : « Une association propose un tutorat entre élèves. Les tuteurs apprennent à poser des questions plutôt qu'à fournir directement la réponse. » Cela justifie la réponse : Aider l'autre à construire sa démarche."},{"number":26,"points":21,"passage":"Le centre compare la satisfaction immédiate et l'utilisation réelle des compétences quelques mois plus tard. Un cours apprécié peut avoir peu d'effet si les participants n'ont pas l'occasion de pratiquer. Les anciens participants seront invités à décrire une situation où ils ont utilisé la formation et une autre où ils n'ont pas réussi à la mobiliser. Ils souhaitent distinguer un apprentissage réel, une appréciation favorable et les conditions nécessaires pour que ces acquis servent ensuite dans le travail ou dans les démarches prévues.","question":"Quelle distinction motive cette évaluation ?","options":["Âge des participants et taille du centre","Plaisir de la formation et transfert dans la pratique","Prix du cours et couleur des supports","Présence en classe et nombre de fenêtres"],"correct":"B","explanation":"Le passage indique : « Le centre compare la satisfaction immédiate et l'utilisation réelle des compétences quelques mois plus tard. Un cours apprécié peut avoir peu d'effet si les participants n'ont pas l'occasion de pratiquer. » Cela justifie la réponse : Plaisir de la formation et transfert dans la pratique."},{"number":27,"points":21,"passage":"Un professeur montre deux solutions correctes à un problème. Les élèves doivent expliquer leurs différences plutôt que deviner laquelle l'enseignant préfère. Le professeur garde un rôle de vérification et ne présente pas toutes les propositions comme correctes par principe. Il veut que les élèves justifient leurs choix à partir du problème, au lieu de chercher seulement un indice sur la réponse qu'ils pensent attendue dans la classe.","question":"Quel apprentissage est privilégié ?","options":["Refuser toute méthode différente","Comparer des démarches justifiées","Copier une préférence supposée","Choisir la réponse la plus longue"],"correct":"B","explanation":"Le passage indique : « Un professeur montre deux solutions correctes à un problème. Les élèves doivent expliquer leurs différences plutôt que deviner laquelle l'enseignant préfère. » Cela justifie la réponse : Comparer des démarches justifiées."},{"number":28,"points":21,"passage":"Une université transforme une partie de sa bibliothèque en salles de groupe. Elle conserve des zones silencieuses après consultation des étudiants. Les étudiants ont expliqué à quels moments ils travaillent seuls, en groupe ou avec un document fragile. Elle souhaite éviter qu'un changement présenté comme moderne efface une fonction encore importante. Le bilan examinera la disponibilité réelle des espaces, notamment pendant les périodes où les demandes de travail individuel augmentent fortement.","question":"Quel équilibre cherche-t-elle ?","options":["Interdire les échanges entre étudiants","Répondre à des usages de travail différents","Supprimer toute étude individuelle","Réserver les livres aux groupes"],"correct":"B","explanation":"Le passage indique : « Une université transforme une partie de sa bibliothèque en salles de groupe. Elle conserve des zones silencieuses après consultation des étudiants. » Cela justifie la réponse : Répondre à des usages de travail différents."},{"number":29,"points":21,"passage":"Des participants abandonnent une formation malgré de bons résultats. Les entretiens révèlent des difficultés de garde et de transport. Le centre modifie ses aides plutôt que simplifier automatiquement les contenus. Les responsables ont contacté les personnes parties avant la fin pour comprendre leur expérience. Plusieurs souhaitaient continuer et savaient réaliser les exercices demandés. Le centre propose donc des solutions d'organisation et des relais locaux avant de revoir le niveau pédagogique.","question":"Quelle cause est identifiée ?","options":["Des contraintes extérieures à l'apprentissage","Le refus de toute aide","Une absence de progrès","Un niveau systématiquement trop élevé"],"correct":"A","explanation":"Le passage indique : « Des participants abandonnent une formation malgré de bons résultats. Les entretiens révèlent des difficultés de garde et de transport. Le centre modifie ses aides plutôt que simplifier automatiquement les contenus. » Cela justifie la réponse : Des contraintes extérieures à l'apprentissage."},{"number":30,"points":26,"passage":"Le droit à l'erreur est souvent invoqué en formation. Il suppose pourtant un retour permettant de comprendre et de reprendre. Sans cet accompagnement, répéter qu'on peut se tromper laisse l'apprenant face à une difficulté inchangée. Le formateur peut montrer comment analyser une tentative et préparer le prochain essai. La personne dispose alors d'éléments pour agir, au lieu d'être simplement rassurée sans savoir ce qu'elle pourrait modifier concrètement. Le retour doit rester précis et utilisable pour la prochaine tentative.","question":"Quelle condition rend ce droit utile ?","options":["Une possibilité accompagnée d'analyser et de corriger","Une absence totale de retour","L'interdiction de recommencer","La suppression de tous les objectifs"],"correct":"A","explanation":"Le passage indique : « Le droit à l'erreur est souvent invoqué en formation. Il suppose pourtant un retour permettant de comprendre et de reprendre. Sans cet accompagnement, répéter qu'on peut se tromper laisse l'apprenant face à une difficulté inchangée. » Cela justifie la réponse : Une possibilité accompagnée d'analyser et de corriger."},{"number":31,"points":26,"passage":"Un programme personnalise les exercices à partir des réponses précédentes. Les enseignants souhaitent garder une vue sur les choix du logiciel. Une adaptation automatique peut être utile tout en enfermant un élève dans des tâches trop semblables à celles qu'il a déjà réalisées. Les enseignants conservent donc des possibilités de changer la proposition ou d'introduire une tâche moins familière.","question":"Quel risque veulent-ils surveiller ?","options":["Une impossibilité de conserver les réponses","Une absence de tout exercice","Une limitation des occasions d'explorer d'autres tâches","Une multiplication certaine des enseignants"],"correct":"C","explanation":"Le passage indique : « Un programme personnalise les exercices à partir des réponses précédentes. Les enseignants souhaitent garder une vue sur les choix du logiciel. Une adaptation automatique peut être utile tout en enfermant un élève dans des tâches trop semblables à celles qu'il a déjà réalisées. » Cela justifie la réponse : Une limitation des occasions d'explorer d'autres tâches."},{"number":32,"points":26,"passage":"Une école développe des projets collectifs. Pour éviter que seuls les élèves déjà à l'aise prennent les décisions, les rôles tournent et les méthodes sont discutées. Travailler ensemble ne suffit pas spontanément à répartir les occasions d'apprendre. Chaque élève pourra expliquer sa contribution et les difficultés rencontrées dans le rôle occupé. Cette attention évite de considérer qu'un résultat collectif réussi prouve automatiquement que tous les membres ont eu les mêmes occasions de travailler.","question":"Pourquoi faire tourner les rôles ?","options":["Éviter les discussions sur le travail","Fixer les mêmes meneurs pour tous les projets","Supprimer les responsabilités","Distribuer plus équitablement les apprentissages"],"correct":"D","explanation":"Le passage indique : « Une école développe des projets collectifs. Pour éviter que seuls les élèves déjà à l'aise prennent les décisions, les rôles tournent et les méthodes sont discutées. Travailler ensemble ne suffit pas spontanément à répartir les occasions d'apprendre. » Cela justifie la réponse : Distribuer plus équitablement les apprentissages."},{"number":33,"points":26,"passage":"Un adulte utilise efficacement un outil au travail mais peine à l'expliquer dans un dossier de formation. Son accompagnateur distingue la compétence pratique et la capacité à la décrire. L'une ne prouve pas automatiquement l'autre. Des exemples concrets et une observation peuvent compléter le dossier. Le centre souhaite éviter qu'une difficulté de rédaction masque un savoir réel, tout en aidant la personne à présenter ses acquis de manière compréhensible pour un évaluateur extérieur.","question":"Que doit permettre l'accompagnement ?","options":["Remplacer l'expérience par une opinion","Mettre en mots une expérience déjà acquise","Conclure immédiatement à une absence de savoir-faire","Éviter tout exemple concret"],"correct":"B","explanation":"Le passage indique : « Un adulte utilise efficacement un outil au travail mais peine à l'expliquer dans un dossier de formation. Son accompagnateur distingue la compétence pratique et la capacité à la décrire. L'une ne prouve pas automatiquement l'autre. » Cela justifie la réponse : Mettre en mots une expérience déjà acquise."},{"number":34,"points":26,"passage":"Un établissement publie son taux de réussite. Il précise aussi les caractéristiques des étudiants accueillis et les parcours interrompus. Sans ces informations, comparer deux taux pourrait confondre l'effet de l'enseignement avec les conditions de recrutement ou de vie des étudiants. Les responsables souhaitent une comparaison utile, sans transformer un indicateur simple en verdict sur toutes les dimensions d'un établissement.","question":"Quelle prudence est recommandée ?","options":["Classer les établissements avec un seul pourcentage","Contextualiser les chiffres avant de comparer","Ignorer tous les abandons","Considérer les publics comme identiques partout"],"correct":"B","explanation":"Le passage indique : « Un établissement publie son taux de réussite. Il précise aussi les caractéristiques des étudiants accueillis et les parcours interrompus. Sans ces informations, comparer deux taux pourrait confondre l'effet de l'enseignement avec les conditions de recrutement ou de vie des étudiants. » Cela justifie la réponse : Contextualiser les chiffres avant de comparer."},{"number":35,"points":26,"passage":"Un atelier vise l'autonomie. Les formateurs donnent progressivement moins d'indices, sans supprimer brutalement leur soutien. L'autonomie n'est pas supposée présente dès l'entrée : elle se construit dans une relation dont l'intensité évolue. Les apprenants sont invités à demander un appui lorsqu'une difficulté nouvelle apparaît. Le centre ne considère pas cette demande comme un échec de l'autonomie, mais comme une ressource possible pour continuer à progresser.","question":"Comment l'autonomie est-elle envisagée ?","options":["Comme un objectif préparé par un accompagnement ajusté","Comme une aptitude impossible à développer","Comme l'absence immédiate de toute aide","Comme une obligation de travailler toujours seul"],"correct":"A","explanation":"Le passage indique : « Un atelier vise l'autonomie. Les formateurs donnent progressivement moins d'indices, sans supprimer brutalement leur soutien. L'autonomie n'est pas supposée présente dès l'entrée : elle se construit dans une relation dont l'intensité évolue. » Cela justifie la réponse : Comme un objectif préparé par un accompagnement ajusté."},{"number":36,"points":33,"passage":"Une école distribue des tablettes à tous les élèves et constate des usages très différents. Certains disposent chez eux d'un espace calme et d'un adulte disponible ; d'autres partagent une connexion fragile. L'égalité d'équipement ne garantit pas l'égalité des conditions d'apprentissage. Certaines familles doivent attendre qu'un appareil soit libre pour terminer un devoir, tandis que d'autres peuvent reprendre les consignes à tout moment. L'école va donc proposer un accès encadré après les cours et des supports utilisables sans connexion permanente. Les enseignants examineront aussi la charge demandée à la maison. Le matériel distribué reste un progrès, mais ses effets dépendent des situations dans lesquelles il est utilisé. Le projet doit être évalué à partir de ces usages réels, pas seulement du nombre de tablettes remises lors d'une première journée de lancement.","question":"Quelle limite du dispositif apparaît ?","options":["Tous les élèves bénéficient du même soutien","La connexion ne joue aucun rôle","Les conditions d'utilisation restent inégales","Une tablette empêche nécessairement d'apprendre"],"correct":"C","explanation":"Le passage indique : « L'égalité d'équipement ne garantit pas l'égalité des conditions d'apprentissage. » Cela justifie la réponse : Les conditions d'utilisation restent inégales."},{"number":37,"points":33,"passage":"Une formation promet de respecter le rythme de chacun. Mais son calendrier final reste rigide, et les aides disparaissent après une courte période. Les participants qui ont besoin de plus de temps sont alors les premiers exclus. Une personnalisation annoncée doit être cohérente avec l'organisation qui encadre réellement les parcours. Les responsables avaient surtout décrit les possibilités offertes par les supports, sans regarder les délais ni la disponibilité des accompagnateurs. Les personnes intéressées pourront ainsi choisir en connaissant les limites du programme. Le centre souhaite conserver des objectifs communs sans prétendre qu'un outil flexible rend toutes les contraintes sans importance. Les résultats seront étudiés avec les abandons et les reprises, afin de vérifier si la nouvelle organisation aide effectivement ceux qui avaient du mal à suivre le rythme prévu.","question":"Quel décalage est dénoncé ?","options":["Une formation qui refuse d'utiliser des supports","Un accompagnement illimité pour tous","L'absence de toute date dans le programme","Une promesse de souplesse contredite par les règles du parcours"],"correct":"D","explanation":"Le passage indique : « Une personnalisation annoncée doit être cohérente avec l'organisation qui encadre réellement les parcours. » Cela justifie la réponse : Une promesse de souplesse contredite par les règles du parcours."},{"number":38,"points":33,"passage":"Apprendre une méthode ne signifie pas toujours savoir quand l'utiliser. Des élèves réussissent un exercice familier, puis échouent lorsque le même problème apparaît dans une présentation différente. Le professeur multiplie les contextes et fait discuter les choix. La maîtrise implique aussi de reconnaître les situations auxquelles un savoir peut répondre. Les exercices proposés ensuite changent de présentation et mélangent plusieurs notions. Les élèves doivent expliquer pourquoi ils en choisissent une plutôt qu'une autre. Le professeur observe les hésitations, car elles peuvent révéler un repère mal compris malgré une procédure bien mémorisée. Il ne cherche pas à multiplier les pièges. Il veut rendre possible un passage des tâches familières à celles où il faut d'abord identifier le problème. Les retours aideront chacun à reconnaître des indices pertinents et à vérifier une démarche, plutôt qu'à reproduire automatiquement un geste appris dans un ordre toujours identique.","question":"Quel objectif dépasse l'exécution d'une méthode ?","options":["Choisir la méthode la plus rapide sans analyser","Éviter toute situation nouvelle","Identifier ses conditions d'utilisation","Mémoriser seulement l'ordre des pages"],"correct":"C","explanation":"Le passage indique : « La maîtrise implique aussi de reconnaître les situations auxquelles un savoir peut répondre. » Cela justifie la réponse : Identifier ses conditions d'utilisation."},{"number":39,"points":33,"passage":"Un centre valorise l'expérience de ses apprenants adultes. Il ne considère pourtant pas que cette expérience suffit à répondre à toute question. Les échanges mettent parfois en évidence des habitudes efficaces dans un contexte et inadaptées dans un autre. Reconnaître un parcours permet d'en faire une ressource d'analyse, sans le transformer en vérité intangible. Les apprenants apportent des exemples et discutent des conditions dans lesquelles leurs solutions ont fonctionné. Le formateur introduit d'autres situations pour faire apparaître les points communs et les différences. Certains participants découvrent qu'ils possèdent des ressources utiles sans avoir encore les mots pour les décrire. D'autres doivent modifier un automatisme longtemps efficace dans leur ancien contexte. Le cours ne demande donc ni d'oublier son parcours ni de s'y enfermer. Il propose de le travailler avec d'autres repères, afin de préparer des décisions plus adaptées aux situations nouvelles rencontrées pendant la formation ou ensuite.","question":"Quelle place est donnée à l'expérience ?","options":["Un obstacle qu'il faut toujours oublier","Un savoir nécessairement identique pour tous","Une ressource à examiner et à enrichir","Une preuve qui ne peut jamais être discutée"],"correct":"C","explanation":"Le passage indique : « Reconnaître un parcours permet d'en faire une ressource d'analyse, sans le transformer en vérité intangible. » Cela justifie la réponse : Une ressource à examiner et à enrichir."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-11','tcf-reading-2026-11-reference-v3',$paper${"id":"tcf-reading-11","version":"tcf-reading-2026-11-reference-v3","title":"TCF Reading · Test 11","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"La collecte de couvertures se termine samedi. Déposez uniquement des articles propres et secs ; les vêtements seront collectés le mois prochain.\n\nLes articles non adaptés ne doivent pas être laissés devant le local.","question":"Que peut-on donner cette semaine ?","options":["Des meubles démontés","Des aliments ouverts","Des couvertures propres","Des vêtements mouillés"],"correct":"C","explanation":"Le passage indique : « La collecte de couvertures se termine samedi. Déposez uniquement des articles propres et secs ; les vêtements seront collectés le mois prochain. » Cela justifie la réponse : Des couvertures propres."},{"number":2,"points":3,"passage":"La permanence d'entraide reçoit sans rendez-vous le jeudi. Les autres jours, un appel préalable est nécessaire.\n\nMerci de prévoir un temps d'attente pendant les périodes de forte fréquentation.","question":"Quand peut-on venir directement ?","options":["Tous les matins","Le dimanche soir","Le lundi seulement","Le jeudi"],"correct":"D","explanation":"Le passage indique : « La permanence d'entraide reçoit sans rendez-vous le jeudi. Les autres jours, un appel préalable est nécessaire. » Cela justifie la réponse : Le jeudi."},{"number":3,"points":3,"passage":"Les bénévoles du repas partagé se retrouveront à neuf heures pour installer les tables. Le public arrivera à midi.\n\nLes personnes inscrites pour une autre mission garderont leur horaire habituel de présence.","question":"Qui est attendu à neuf heures ?","options":["Les musiciens du soir uniquement","Tous les convives","Les clients du marché","Les bénévoles chargés de l'installation"],"correct":"D","explanation":"Le passage indique : « Les bénévoles du repas partagé se retrouveront à neuf heures pour installer les tables. Le public arrivera à midi. » Cela justifie la réponse : Les bénévoles chargés de l'installation."},{"number":4,"points":3,"passage":"La distribution de cahiers est ouverte aux familles inscrites. Apportez votre confirmation, imprimée ou sur téléphone.\n\nLe personnel retrouvera ensuite votre dossier sans demander une nouvelle inscription. Une famille rencontrant une difficulté peut contacter l'accueil avant le jour prévu.","question":"Quel document faut-il présenter ?","options":["La confirmation d'inscription","Un billet de spectacle","Un relevé bancaire","Un diplôme scolaire"],"correct":"A","explanation":"Le passage indique : « La distribution de cahiers est ouverte aux familles inscrites. Apportez votre confirmation, imprimée ou sur téléphone. » Cela justifie la réponse : La confirmation d'inscription."},{"number":5,"points":9,"passage":"Je peux aider à trier les dons samedi, mais pas porter les cartons lourds. Peux-tu me prévoir une tâche à table ?\n\nJe suis disponible toute la matinée et peux aussi aider à vérifier les étiquettes. Ainsi, l'équipe pourra répartir les autres tâches entre les bénévoles disponibles.","question":"Quelle adaptation est demandée ?","options":["Un service de transport privé","Une absence d'activité","Une tâche sans port de charges lourdes","Un changement de tous les horaires"],"correct":"C","explanation":"Le passage indique : « Je peux aider à trier les dons samedi, mais pas porter les cartons lourds. Peux-tu me prévoir une tâche à table ? » Cela justifie la réponse : Une tâche sans port de charges lourdes."},{"number":6,"points":9,"passage":"Notre association cherche des personnes pour lire des histoires. Il suffit d'aimer partager des textes ; aucune expérience de spectacle n'est exigée.\n\nUne séance d'accueil permettra de découvrir les livres et de préparer une première lecture.","question":"Quel profil convient ?","options":["Uniquement un comédien professionnel","Une personne intéressée par la lecture partagée","Une personne refusant de lire à voix haute","Un vendeur de livres seulement"],"correct":"B","explanation":"Le passage indique : « Notre association cherche des personnes pour lire des histoires. Il suffit d'aimer partager des textes ; aucune expérience de spectacle n'est exigée. » Cela justifie la réponse : Une personne intéressée par la lecture partagée."},{"number":7,"points":9,"passage":"Merci de confirmer votre disponibilité avant mardi. Nous devons constituer les binômes d'accompagnement, pas simplement compter les inscrits.\n\nUne absence peut être signalée sans devoir fournir de détail personnel au groupe. Il faut surtout que le responsable puisse rechercher un remplaçant assez tôt.","question":"Pourquoi la confirmation est-elle importante ?","options":["Annuler toutes les inscriptions","Calculer le prix des repas","Organiser les équipes de deux","Modifier le lieu du festival"],"correct":"C","explanation":"Le passage indique : « Merci de confirmer votre disponibilité avant mardi. Nous devons constituer les binômes d'accompagnement, pas simplement compter les inscrits. » Cela justifie la réponse : Organiser les équipes de deux."},{"number":8,"points":9,"passage":"La boutique solidaire vend aussi au grand public. Ces achats contribuent à financer les tarifs adaptés proposés à certaines familles.\n\nLe prix annoncé au public correspond aussi au travail de tri, d'entretien et d'accueil nécessaire au fonctionnement du lieu.","question":"Quel rôle jouent les achats ordinaires ?","options":["Remplacer les dons par un impôt","Réserver tous les articles aux touristes","Soutenir le fonctionnement solidaire","Supprimer les tarifs adaptés"],"correct":"C","explanation":"Le passage indique : « La boutique solidaire vend aussi au grand public. Ces achats contribuent à financer les tarifs adaptés proposés à certaines familles. » Cela justifie la réponse : Soutenir le fonctionnement solidaire."},{"number":9,"points":9,"passage":"Je préfère m'engager une fois par mois régulièrement plutôt que promettre chaque semaine et annuler souvent.\n\nNous pourrons revoir le calendrier si mes disponibilités changent, plutôt que laisser l'équipe découvrir une absence le jour même.","question":"Quelle forme d'engagement est choisie ?","options":["Une disponibilité moins fréquente mais fiable","Une participation sans calendrier","Un arrêt de toute aide","Une présence quotidienne"],"correct":"A","explanation":"Le passage indique : « Je préfère m'engager une fois par mois régulièrement plutôt que promettre chaque semaine et annuler souvent. » Cela justifie la réponse : Une disponibilité moins fréquente mais fiable."},{"number":10,"points":9,"passage":"L'équipe propose une séance d'accueil avant la première mission. Les nouveaux bénévoles y découvriront les règles de confidentialité.\n\nLes volontaires pourront poser leurs questions avant de s'engager. Les responsables présenteront aussi les limites des tâches et les situations qui demandent de contacter une personne compétente.","question":"À quoi sert cette séance ?","options":["Attribuer un diplôme professionnel","Présenter les dossiers personnels au public","Préparer l'entrée dans l'activité","Sélectionner les donateurs les plus riches"],"correct":"C","explanation":"Le passage indique : « L'équipe propose une séance d'accueil avant la première mission. Les nouveaux bénévoles y découvriront les règles de confidentialité. » Cela justifie la réponse : Préparer l'entrée dans l'activité."},{"number":11,"points":15,"passage":"Une association échange des services entre habitants. Une heure de jardinage donne droit à une heure d'aide, quelle que soit la valeur marchande habituelle du métier.\n\nLes participants indiquent les services qu'ils peuvent proposer et les moments où ils sont disponibles. Un coordinateur facilite les premières rencontres sans promettre une réponse immédiate à chaque demande. Les échanges sont enregistrés dans un carnet commun pour que chacun sache ce qu'il a donné et reçu. Le groupe souhaite reconnaître des compétences diverses, y compris des gestes ordinaires parfois peu valorisés.","question":"Quel principe régit l'échange ?","options":["Seuls les professionnels peuvent participer","Le revenu détermine le nombre d'heures","Une même durée a la même valeur","Les outils sont vendus aux voisins"],"correct":"C","explanation":"Le passage indique : « Une association échange des services entre habitants. Une heure de jardinage donne droit à une heure d'aide, quelle que soit la valeur marchande habituelle du métier. » Cela justifie la réponse : Une même durée a la même valeur."},{"number":12,"points":15,"passage":"Le centre social aide à remplir des formulaires, mais demande aux personnes de rester présentes. Les animateurs expliquent les démarches plutôt que décider à leur place.\n\nLes animateurs montrent où trouver une information et demandent aux personnes de vérifier ce qui les concerne. L'aide peut prendre plus de temps qu'une saisie rapide effectuée sans explication. Le centre considère cependant que cette présence permet aussi de préparer une prochaine démarche.","question":"Quel objectif accompagne l'aide immédiate ?","options":["Remplacer les décisions des bénéficiaires","Éviter toute explication","Confisquer les documents personnels","Renforcer la compréhension des démarches"],"correct":"D","explanation":"Le passage indique : « Le centre social aide à remplir des formulaires, mais demande aux personnes de rester présentes. Les animateurs expliquent les démarches plutôt que décider à leur place. » Cela justifie la réponse : Renforcer la compréhension des démarches."},{"number":13,"points":15,"passage":"Une maraude adapte son parcours aux besoins signalés. Les bénévoles ne publient pas les lieux de rencontre pour protéger les personnes accompagnées.\n\nLes personnes choisissent ce qu'elles souhaitent dire et peuvent refuser une rencontre. L'équipe note seulement les informations nécessaires au suivi, dans un document non accessible au public. Les nouveaux volontaires reçoivent une présentation de ces règles avant leur première sortie. L'association souhaite favoriser un contact régulier sans transformer la situation d'une personne en contenu destiné à attirer de nouveaux donateurs. Les récits utilisés pour présenter le projet seront préparés séparément, avec un accord explicite des personnes concernées par la publication.","question":"Pourquoi limiter ces informations publiques ?","options":["Supprimer les rencontres","Attirer des visiteurs payants","Empêcher toute coordination interne","Préserver la confidentialité"],"correct":"D","explanation":"Le passage indique : « Une maraude adapte son parcours aux besoins signalés. Les bénévoles ne publient pas les lieux de rencontre pour protéger les personnes accompagnées. » Cela justifie la réponse : Préserver la confidentialité."},{"number":14,"points":15,"passage":"Un atelier de réparation réserve des places sans inscription en ligne. Les organisateurs veulent accueillir aussi ceux qui n'utilisent pas internet.\n\nUne partie des places reste réservée à un accueil sur place ou par téléphone. Les bénévoles expliquent ensuite comment préparer l'objet et quels renseignements apporter. Le service souhaite que la méthode d'inscription ne sélectionne pas à elle seule les participants. Les demandes seront suivies pour vérifier si ce choix touche réellement de nouvelles personnes. Il ne s'agit pas d'abandonner un outil pratique pour les habitués, mais de garder plusieurs voies possibles vers la même activité, dans des conditions clairement annoncées au public.","question":"Quelle barrière cherchent-ils à réduire ?","options":["Une difficulté d'accès numérique","La durée des réparations","Le nombre de chaises","Le coût des outils professionnels"],"correct":"A","explanation":"Le passage indique : « Un atelier de réparation réserve des places sans inscription en ligne. Les organisateurs veulent accueillir aussi ceux qui n'utilisent pas internet. » Cela justifie la réponse : Une difficulté d'accès numérique."},{"number":15,"points":15,"passage":"Une association fournit des repas sans demander aux personnes de raconter publiquement leur situation. L'accueil ne doit pas devenir une épreuve de justification devant les autres.\n\nLes bénéficiaires peuvent s'adresser discrètement à un responsable s'ils ont une demande particulière. Les bénévoles suivent une procédure commune pour éviter des pratiques très différentes selon la personne présente. L'association souhaite que la simplicité de l'accueil ne dépende pas d'une relation personnelle ou de la capacité à raconter une histoire convaincante. Elle vérifiera aussi les temps d'attente et l'organisation de la file.","question":"Quel principe est défendu ?","options":["La publicité des dossiers","Le respect de la dignité","La sélection par la prise de parole","Le classement des difficultés"],"correct":"B","explanation":"Le passage indique : « Une association fournit des repas sans demander aux personnes de raconter publiquement leur situation. L'accueil ne doit pas devenir une épreuve de justification devant les autres. » Cela justifie la réponse : Le respect de la dignité."},{"number":16,"points":15,"passage":"Des voisins prêtent des objets grâce à un catalogue commun. Une fiche indique leur état au départ et au retour pour éviter les malentendus.\n\nL'emprunteur peut poser des questions avant de confirmer le prêt. Les organisateurs souhaitent préserver la confiance entre voisins sans attendre qu'un problème se transforme en accusation. Les règles précisent aussi ce qui se passe lorsqu'un objet s'abîme malgré une utilisation normale, afin de ne pas confondre tout incident avec une faute ou de promettre qu'un objet partagé restera toujours intact.","question":"À quoi sert cette fiche ?","options":["Clarifier les responsabilités lors du prêt","Garantir que rien ne s'abîmera jamais","Remplacer tous les échanges humains","Fixer un prix de vente obligatoire"],"correct":"A","explanation":"Le passage indique : « Des voisins prêtent des objets grâce à un catalogue commun. Une fiche indique leur état au départ et au retour pour éviter les malentendus. » Cela justifie la réponse : Clarifier les responsabilités lors du prêt."},{"number":17,"points":15,"passage":"Une équipe organise des visites amicales. Les visiteurs ne réalisent pas de soins ; ils signalent les besoins particuliers au responsable compétent.\n\nLe programme prévoit surtout du temps pour discuter, lire ou faire une petite promenade lorsque cela convient. Les personnes accompagnées choisissent les activités et peuvent demander de reporter un rendez-vous. Le responsable distingue cette présence amicale des interventions nécessitant une formation ou une autorisation particulière. L'association préfère un cadre clair à une promesse d'aide illimitée, qui pourrait mettre en difficulté les visiteurs comme les personnes qu'ils viennent rencontrer.","question":"Quelle limite est posée ?","options":["Les conversations sont interdites","Les visiteurs prescrivent des traitements","Les bénéficiaires doivent rester seuls","Les visites ne remplacent pas des soins"],"correct":"D","explanation":"Le passage indique : « Une équipe organise des visites amicales. Les visiteurs ne réalisent pas de soins ; ils signalent les besoins particuliers au responsable compétent. » Cela justifie la réponse : Les visites ne remplacent pas des soins."},{"number":18,"points":15,"passage":"Un collectif propose des réunions avec traduction dans plusieurs langues. Les comptes rendus restent courts pour que les informations circulent facilement.\n\nLes participants reçoivent les principaux documents avant la réunion et peuvent demander une précision pendant les échanges. Le comité souhaite que les personnes moins à l'aise dans une langue ne soient pas réduites à écouter sans intervenir. Les traducteurs ne prennent pas les décisions à leur place. Ils facilitent la compréhension de ce qui est proposé et des choix à effectuer.","question":"Quel objectif guide ces choix ?","options":["Élargir la participation aux échanges","Rendre les documents plus techniques","Réserver les décisions aux traducteurs","Supprimer les débats"],"correct":"A","explanation":"Le passage indique : « Un collectif propose des réunions avec traduction dans plusieurs langues. Les comptes rendus restent courts pour que les informations circulent facilement. » Cela justifie la réponse : Élargir la participation aux échanges."},{"number":19,"points":15,"passage":"Une collecte de jouets demande des jeux complets. Les pièces manquantes seront recherchées avant la distribution, afin d'offrir des objets réellement utilisables.\n\nLes bénévoles essaient les mécanismes et indiquent les limites lorsqu'un jeu ne peut pas être complété. Certains objets seront réparés avant d'être proposés, d'autres orientés vers une autre filière. Elle expliquera les critères de tri aux personnes qui apportent des jouets, afin de réduire les déplacements inutiles et de préparer les prochaines collectes dans de meilleures conditions.","question":"Pourquoi vérifier les jeux ?","options":["Éviter tout tri","Assurer la qualité des dons distribués","Réserver les jeux aux organisateurs","Augmenter leur prix de revente"],"correct":"B","explanation":"Le passage indique : « Une collecte de jouets demande des jeux complets. Les pièces manquantes seront recherchées avant la distribution, afin d'offrir des objets réellement utilisables. » Cela justifie la réponse : Assurer la qualité des dons distribués."},{"number":20,"points":21,"passage":"Une association consulte les bénéficiaires avant de choisir les horaires d'ouverture. Les créneaux pratiques pour les bénévoles ne sont pas toujours ceux qui conviennent aux personnes accueillies. Les personnes interrogées indiquent notamment les moments où elles peuvent se déplacer et les contraintes liées aux transports. L'association compare ces réponses avec les disponibilités de l'équipe avant de proposer un calendrier. Elle veut éviter qu'une permanence apparemment ouverte reste inaccessible à ceux qu'elle vise. Les horaires seront réexaminés après quelques semaines, en regardant les demandes non satisfaites autant que les présences effectivement enregistrées à l'accueil.","question":"Pourquoi cette consultation est-elle nécessaire ?","options":["Supprimer toute disponibilité bénévole","Prendre en compte des contraintes différentes","Fixer les horaires au hasard","Éviter de rencontrer les bénéficiaires"],"correct":"B","explanation":"Le passage indique : « Une association consulte les bénéficiaires avant de choisir les horaires d'ouverture. Les créneaux pratiques pour les bénévoles ne sont pas toujours ceux qui conviennent aux personnes accueillies. » Cela justifie la réponse : Prendre en compte des contraintes différentes."},{"number":21,"points":21,"passage":"Un réseau de covoiturage solidaire rembourse les frais réels des conducteurs. Il ne cherche pas à leur procurer un revenu complémentaire. Les trajets et les dépenses doivent être notés selon les règles annoncées à l'inscription. L'association souhaite que les conducteurs n'avancent pas durablement des frais qu'ils ne peuvent pas supporter. Elle précise cependant que le dispositif reste différent d'une activité commerciale de transport. Les responsables vérifieront les documents sans demander aux bénéficiaires de négocier directement un prix à chaque sortie, afin de préserver un cadre compréhensible pour les deux parties.","question":"Quelle distinction est faite ?","options":["Les frais réels sont toujours nuls","Tous les déplacements sont des emplois","Les conducteurs paient les passagers","Rembourser une dépense n'est pas rémunérer un service"],"correct":"D","explanation":"Le passage indique : « Un réseau de covoiturage solidaire rembourse les frais réels des conducteurs. Il ne cherche pas à leur procurer un revenu complémentaire. » Cela justifie la réponse : Rembourser une dépense n'est pas rémunérer un service."},{"number":22,"points":21,"passage":"Une collecte financière réussit au-delà des prévisions. L'association publie l'utilisation du surplus au lieu de modifier discrètement l'objectif annoncé. Les responsables présentent les dépenses supplémentaires envisagées et expliquent leur lien avec le projet initial. Le comité souhaite que la réussite de la collecte ne rende pas son fonctionnement moins lisible. Une somme reçue au-delà de l'objectif reste une ressource à utiliser avec soin, selon des décisions identifiables, et non un montant dont l'emploi pourrait être laissé sans explication publique.","question":"Quel souci manifeste cette démarche ?","options":["L'abandon du projet initial sans explication","La transparence envers les donateurs","Le refus de tout suivi","La recherche de nouveaux frais cachés"],"correct":"B","explanation":"Le passage indique : « Une collecte financière réussit au-delà des prévisions. L'association publie l'utilisation du surplus au lieu de modifier discrètement l'objectif annoncé. » Cela justifie la réponse : La transparence envers les donateurs."},{"number":23,"points":21,"passage":"Un café accueille des rencontres entre personnes arrivées récemment et habitants installés. Les échanges portent sur des centres d'intérêt partagés, pas uniquement sur les difficultés administratives. Des ateliers de musique, des promenades et des échanges de recettes servent de premiers points de rencontre. Les personnes peuvent venir sans devoir exposer immédiatement leur parcours. L'équipe veut que chacun puisse être reconnu pour ses intérêts et ses contributions, pas uniquement pour une difficulté. Les informations pratiques restent disponibles dans un autre cadre.","question":"Quel effet est recherché ?","options":["Éviter les intérêts personnels","Réserver le lieu aux nouveaux arrivants","Créer des relations qui dépassent le seul besoin d'aide","Transformer toutes les rencontres en démarches"],"correct":"C","explanation":"Le passage indique : « Un café accueille des rencontres entre personnes arrivées récemment et habitants installés. Les échanges portent sur des centres d'intérêt partagés, pas uniquement sur les difficultés administratives. » Cela justifie la réponse : Créer des relations qui dépassent le seul besoin d'aide."},{"number":24,"points":21,"passage":"Une plateforme met en relation des bénévoles et des associations. Les petites structures souhaitent aussi un accompagnement, car publier une mission ne suffit pas à organiser l'accueil des volontaires. Les coordinateurs doivent présenter la mission, expliquer les limites et prévoir un interlocuteur pour le premier jour. Les structures peu nombreuses n'ont pas toujours le temps de préparer seules ces éléments. Elles demandent donc un soutien qui dépasse la simple visibilité de leur annonce.","question":"Quel besoin complémentaire expriment-elles ?","options":["De l'aide pour intégrer les bénévoles","Une rémunération automatique de tous les volontaires","Un remplacement de leur activité par des annonces","Une suppression des missions"],"correct":"A","explanation":"Le passage indique : « Une plateforme met en relation des bénévoles et des associations. Les petites structures souhaitent aussi un accompagnement, car publier une mission ne suffit pas à organiser l'accueil des volontaires. » Cela justifie la réponse : De l'aide pour intégrer les bénévoles."},{"number":25,"points":21,"passage":"Un jardin collectif attribue des tâches adaptées aux capacités de chacun. L'association reconnaît aussi l'organisation et l'accueil comme des contributions, pas seulement le travail physique. Les membres discutent des tâches avant chaque période importante, puis peuvent changer de rôle. Certaines personnes connaissent les plantes, d'autres savent accueillir un nouveau voisin ou tenir le planning. L'association souhaite éviter qu'une même forme de contribution devienne la mesure unique de l'engagement.","question":"Quelle idée de la participation apparaît ?","options":["Seule la force physique compte","Des apports différents peuvent être également utiles","Tous doivent accomplir la même tâche","L'accueil ne demande jamais de travail"],"correct":"B","explanation":"Le passage indique : « Un jardin collectif attribue des tâches adaptées aux capacités de chacun. L'association reconnaît aussi l'organisation et l'accueil comme des contributions, pas seulement le travail physique. » Cela justifie la réponse : Des apports différents peuvent être également utiles."},{"number":26,"points":21,"passage":"Une banque alimentaire forme ses équipes à expliquer les choix disponibles. Les personnes accompagnées peuvent exprimer leurs préférences dans les limites du stock. Les bénévoles présentent les aliments et les conditions de conservation sans supposer que toutes les familles les utilisent de la même manière. L'équipe ne promet pas un choix sans limite, mais veut que les possibilités réelles soient expliquées et que les personnes ne soient pas simplement destinataires d'une décision prise sans elles.","question":"Quel changement dans l'accueil est recherché ?","options":["Supprimer la gestion des stocks","Garantir tous les produits à toute heure","Laisser une place au choix des personnes","Distribuer sans aucun échange"],"correct":"C","explanation":"Le passage indique : « Une banque alimentaire forme ses équipes à expliquer les choix disponibles. Les personnes accompagnées peuvent exprimer leurs préférences dans les limites du stock. » Cela justifie la réponse : Laisser une place au choix des personnes."},{"number":27,"points":21,"passage":"Un groupe souhaite pérenniser ses actions après une urgence locale. Il organise un calendrier et répartit les responsabilités pour éviter que tout repose sur deux fondateurs. Les fondateurs préparent des fiches simples et accompagnent les nouveaux responsables lors des premières permanences. Ils souhaitent que l'information circule au lieu de rester dans quelques téléphones personnels. Les membres pourront signaler les tâches trop lourdes avant de se décourager.","question":"Quel risque cherche-t-il à réduire ?","options":["La régularité des actions","Le partage des informations utiles","L'arrivée de nouveaux bénévoles","La dépendance à quelques personnes"],"correct":"D","explanation":"Le passage indique : « Un groupe souhaite pérenniser ses actions après une urgence locale. Il organise un calendrier et répartit les responsabilités pour éviter que tout repose sur deux fondateurs. » Cela justifie la réponse : La dépendance à quelques personnes."},{"number":28,"points":21,"passage":"L'association ajoute des témoignages à son bilan chiffré. Une aide ponctuelle peut avoir un effet important que le seul nombre d'interventions ne décrit pas. Les récits sont recueillis avec l'accord des personnes et relus avant une éventuelle publication. Ils ne remplacent pas les données de suivi, mais aident à comprendre des effets que les tableaux résument mal. Le centre veut éviter de présenter chaque histoire comme représentative de toutes les situations.","question":"Pourquoi compléter les chiffres ?","options":["Comparer uniquement les budgets","Mieux comprendre les effets des actions","Remplacer les personnes par des statistiques","Renoncer à toute vérification"],"correct":"B","explanation":"Le passage indique : « L'association ajoute des témoignages à son bilan chiffré. Une aide ponctuelle peut avoir un effet important que le seul nombre d'interventions ne décrit pas. » Cela justifie la réponse : Mieux comprendre les effets des actions."},{"number":29,"points":21,"passage":"Un centre propose de participer à l'organisation aux personnes qui viennent y chercher une aide. Cette possibilité est facultative et n'est pas une condition pour être accueilli. Les bénéficiaires peuvent proposer une activité, aider à un rangement ou participer à une réunion lorsqu'ils le souhaitent. Ils veulent préserver un droit à l'accueil tout en reconnaissant que les personnes reçues peuvent aussi contribuer à la vie du lieu.","question":"Quelle règle distingue cette participation ?","options":["Elle concerne seulement les salariés","Elle ne conditionne pas l'accès à l'aide","Elle remplace toute aide matérielle","Elle est obligatoire chaque semaine"],"correct":"B","explanation":"Le passage indique : « Un centre propose de participer à l'organisation aux personnes qui viennent y chercher une aide. Cette possibilité est facultative et n'est pas une condition pour être accueilli. » Cela justifie la réponse : Elle ne conditionne pas l'accès à l'aide."},{"number":30,"points":26,"passage":"L'engagement bénévole est parfois présenté comme un temps libre sans contraintes. Or une association doit aussi définir les limites des missions et reconnaître les indisponibilités. Une disponibilité généreuse mais sans cadre peut conduire à l'épuisement et compromettre la continuité de l'action. Les responsables prévoient des pauses, des relais et un interlocuteur en cas de difficulté. Ces règles ne diminuent pas la générosité du projet ; elles lui permettent de rester possible quand les premières semaines d'enthousiasme sont passées.","question":"Quelle organisation est recommandée ?","options":["Une absence de répartition des tâches","Une disponibilité permanente exigée de tous","Une interdiction de se retirer d'une mission","Un engagement soutenable avec des limites explicites"],"correct":"D","explanation":"Le passage indique : « L'engagement bénévole est parfois présenté comme un temps libre sans contraintes. Or une association doit aussi définir les limites des missions et reconnaître les indisponibilités. Une disponibilité généreuse mais sans cadre peut conduire à l'épuisement et compromettre la continuité de l'action. » Cela justifie la réponse : Un engagement soutenable avec des limites explicites."},{"number":31,"points":26,"passage":"Une aide rapide répond à une urgence. Elle ne modifie pas nécessairement les causes qui rendent cette aide indispensable. Un collectif maintient ses distributions tout en participant à un travail sur l'accès au logement. Les deux démarches répondent à des temporalités différentes. Ils souhaitent continuer à répondre aux besoins présents, tout en utilisant ce qu'ils observent pour participer à des changements qui pourraient réduire la nécessité de ces interventions à l'avenir.","question":"Quelle complémentarité est défendue ?","options":["Agir sur l'urgence et sur les causes","Remplacer toute aide immédiate par une étude","Confondre chaque distribution avec une réforme complète","Renoncer aux questions de logement"],"correct":"A","explanation":"Le passage indique : « Une aide rapide répond à une urgence. Elle ne modifie pas nécessairement les causes qui rendent cette aide indispensable. Un collectif maintient ses distributions tout en participant à un travail sur l'accès au logement. Les deux démarches répondent à des temporalités différentes. » Cela justifie la réponse : Agir sur l'urgence et sur les causes."},{"number":32,"points":26,"passage":"Le nombre de volontaires inscrits sur une plateforme augmente. Les associations observent pourtant des présences irrégulières. Pour apprécier les ressources réelles, elles distinguent une intention d'engagement et une participation effectivement organisée. Les responsables proposent un accueil et une confirmation concrète des créneaux. Le passage d'une candidature à une présence régulière demande une organisation, même lorsque les personnes déclarent sincèrement vouloir aider et disposent de compétences utiles à l'association.","question":"Quelle distinction faut-il faire ?","options":["Bénévolat et obligation de salaire","Nombre d'ordinateurs et nombre de missions","Inscription et disponibilité réelle","Aide sociale et vente de billets"],"correct":"C","explanation":"Le passage indique : « Le nombre de volontaires inscrits sur une plateforme augmente. Les associations observent pourtant des présences irrégulières. Pour apprécier les ressources réelles, elles distinguent une intention d'engagement et une participation effectivement organisée. » Cela justifie la réponse : Inscription et disponibilité réelle."},{"number":33,"points":26,"passage":"Une organisation souhaite « donner la parole » à ses bénéficiaires. Elle doit aussi leur laisser un effet sur les décisions. Recueillir des avis sans expliquer ce qui en sera fait peut transformer la consultation en simple illustration d'un projet déjà arrêté. Cette réponse permet aux participants d'apprécier la portée de leur contribution et de comprendre les contraintes, au lieu de disparaître après la réunion.","question":"Quelle condition rend la consultation significative ?","options":["L'absence de tout retour aux participants","La publication de citations uniquement décoratives","Un questionnaire sans suite","Un lien explicite avec les décisions"],"correct":"D","explanation":"Le passage indique : « Une organisation souhaite « donner la parole » à ses bénéficiaires. Elle doit aussi leur laisser un effet sur les décisions. Recueillir des avis sans expliquer ce qui en sera fait peut transformer la consultation en simple illustration d'un projet déjà arrêté. » Cela justifie la réponse : Un lien explicite avec les décisions."},{"number":34,"points":26,"passage":"Une boutique solidaire améliore sa présentation pour que les clients puissent choisir dans un lieu accueillant. Certains s'inquiètent qu'une belle vitrine fasse oublier la mission sociale. L'équipe répond que le respect des personnes peut aussi passer par la qualité ordinaire du service. Les clients peuvent consulter les prix et demander des informations sur les objets comme dans un autre commerce.","question":"Quelle position est défendue ?","options":["Qualité commerciale et mission sociale peuvent se soutenir","Une belle vitrine supprime toute solidarité","Les clients doivent renoncer à choisir","Un service solidaire doit être négligé"],"correct":"A","explanation":"Le passage indique : « Une boutique solidaire améliore sa présentation pour que les clients puissent choisir dans un lieu accueillant. Certains s'inquiètent qu'une belle vitrine fasse oublier la mission sociale. L'équipe répond que le respect des personnes peut aussi passer par la qualité ordinaire du service. » Cela justifie la réponse : Qualité commerciale et mission sociale peuvent se soutenir."},{"number":35,"points":26,"passage":"Le développement d'un réseau d'entraide augmente les demandes adressées aux coordinateurs. Pour durer, le groupe formalise certaines règles sans supprimer les échanges informels. Il cherche à préserver la confiance tout en rendant l'organisation moins dépendante de relations personnelles fragiles. Les nouveaux membres sauront où chercher une information et à qui poser une question, même lorsque les personnes qui les ont accueillis sont absentes.","question":"Quel équilibre recherche-t-il ?","options":["Associer confiance et organisation explicite","Refuser la croissance des besoins sans discussion","Maintenir toutes les règles secrètes","Remplacer toute relation par des formulaires"],"correct":"A","explanation":"Le passage indique : « Le développement d'un réseau d'entraide augmente les demandes adressées aux coordinateurs. Pour durer, le groupe formalise certaines règles sans supprimer les échanges informels. Il cherche à préserver la confiance tout en rendant l'organisation moins dépendante de relations personnelles fragiles. » Cela justifie la réponse : Associer confiance et organisation explicite."},{"number":36,"points":33,"passage":"Un projet associe des personnes précaires à des ateliers culturels. Les organisateurs refusent de mesurer le résultat uniquement par un retour à l'emploi. Les relations, la confiance et la possibilité de participer à une vie commune ont une valeur propre. L'utilité sociale ne se réduit pas toujours à un indicateur économique immédiat. Les participants peuvent parler d'un changement dans leurs relations ou de la possibilité de sortir plus facilement de chez eux. Certains envisagent ensuite une formation ou un emploi, d'autres recherchent surtout un espace où ils se sentent reconnus. Le centre souhaite décrire ces trajectoires sans les classer selon une seule issue. Il discutera donc des critères avec les personnes concernées avant de rédiger son bilan. Le projet peut avoir plusieurs effets utiles, dont certains apparaissent lentement et restent difficiles à résumer dans un chiffre unique présenté à la fin de l'année.","question":"Quelle conception du résultat est défendue ?","options":["Transformer chaque atelier en entretien d'embauche","Reconnaître plusieurs effets utiles de la participation","Ignorer toute expérience des participants","Évaluer uniquement le nombre de contrats signés"],"correct":"B","explanation":"Le passage indique : « L'utilité sociale ne se réduit pas toujours à un indicateur économique immédiat. » Cela justifie la réponse : Reconnaître plusieurs effets utiles de la participation."},{"number":37,"points":33,"passage":"Une association dépend d'un financement annuel renouvelable. Elle peut annoncer beaucoup d'activités, mais hésite à former durablement son équipe sans visibilité. Les financeurs demandent de la stabilité aux actions qu'ils soutiennent. Cette stabilité devient difficile lorsque les ressources permettant de la construire restent elles-mêmes incertaines. Les responsables cherchent un calendrier de financement qui permette d'anticiper les embauches et la formation. Ils expliquent que le temps passé à reconstruire sans cesse des dossiers réduit aussi celui disponible pour l'accueil. Les financeurs souhaitent garder la possibilité d'évaluer les actions et de réorienter les soutiens. Le débat porte donc sur des engagements assez stables pour rendre l'activité possible, sans supprimer l'examen de ses résultats. Les associations veulent que cette incertitude soit visible dans le bilan, plutôt que les interruptions soient interprétées uniquement comme un défaut d'organisation interne.","question":"Quelle contradiction apparaît ?","options":["Financer des actions sans aucune attente de durée","Exiger la continuité sans garantir les moyens de la préparer","Garantir des moyens tout en interdisant les activités","Former une équipe qui dispose de ressources illimitées"],"correct":"B","explanation":"Le passage indique : « Cette stabilité devient difficile lorsque les ressources permettant de la construire restent elles-mêmes incertaines. » Cela justifie la réponse : Exiger la continuité sans garantir les moyens de la préparer."},{"number":38,"points":33,"passage":"Un collectif publie les récits de personnes accompagnées pour sensibiliser le public. Il leur propose de relire les textes et de retirer leur accord avant diffusion. Le fait qu'un témoignage serve une cause utile ne supprime pas les droits de la personne dont il raconte l'expérience. L'objectif collectif ne dispense pas de respecter une décision individuelle de ne pas s'exposer. L'association présente plusieurs moyens de contribuer à la sensibilisation, dont certains ne montrent aucun visage ni détail personnel. Elle accepte qu'une personne préfère ne pas participer, sans changer l'aide qu'elle reçoit. Les responsables souhaitent éviter qu'un accord donné dans une situation fragile devienne une obligation ressentie. Avant chaque nouvelle utilisation, le cadre sera expliqué dans une langue compréhensible. La communication pourra ainsi servir le projet tout en conservant une place à la décision de chacun, y compris lorsqu'une histoire particulièrement émouvante semblerait très efficace pour mobiliser de futurs soutiens.","question":"Quel principe guide la publication ?","options":["Le public choisit à la place des personnes","La cause autorise automatiquement tous les récits","Toute aide reçue impose de témoigner","Le consentement reste nécessaire malgré l'utilité de la cause"],"correct":"D","explanation":"Le passage indique : « L'objectif collectif ne dispense pas de respecter une décision individuelle de ne pas s'exposer. » Cela justifie la réponse : Le consentement reste nécessaire malgré l'utilité de la cause."},{"number":39,"points":33,"passage":"Une initiative locale attire l'attention nationale. Ses responsables sont invités à reproduire partout le même modèle. Ils présentent les principes, mais soulignent les relations de confiance et les ressources particulières qui ont permis leur réussite. Transmettre une expérience ne signifie pas promettre qu'elle produira les mêmes effets sans adaptation. Ils proposent aux nouveaux groupes d'examiner les besoins, les partenaires et les disponibilités avant de reprendre les mêmes activités. Certaines règles pourront être conservées, tandis que d'autres devront changer selon les personnes accueillies. L'équipe souhaite rester utile sans transformer un succès local en formule universelle. Les échanges porteront aussi sur les difficultés rencontrées, pas seulement sur les résultats faciles à montrer. Cette démarche demande plus de temps qu'une copie rapide, mais permet de distinguer les principes transférables et les conditions particulières qui doivent être reconstruites dans le nouveau territoire.","question":"Quelle limite à la reproduction du projet est soulignée ?","options":["La nécessité de tenir compte du contexte local","L'impossibilité de partager des connaissances","L'inutilité de toute relation de confiance","La certitude d'un résultat identique partout"],"correct":"A","explanation":"Le passage indique : « Transmettre une expérience ne signifie pas promettre qu'elle produira les mêmes effets sans adaptation. » Cela justifie la réponse : La nécessité de tenir compte du contexte local."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-12','tcf-reading-2026-11-reference-v3',$paper${"id":"tcf-reading-12","version":"tcf-reading-2026-11-reference-v3","title":"TCF Reading · Test 12","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"Le sentier des vergers est fermé pendant la récolte. La promenade reste possible par le chemin communal.\n\nLes promeneurs sont invités à suivre les panneaux temporaires. La fermeture doit permettre le passage des équipes et du matériel sans gêne.","question":"Quel chemin reste accessible ?","options":["Tous les champs privés","Le sentier des vergers","La cour de la ferme","Le chemin communal"],"correct":"D","explanation":"Le passage indique : « Le sentier des vergers est fermé pendant la récolte. La promenade reste possible par le chemin communal. » Cela justifie la réponse : Le chemin communal."},{"number":2,"points":3,"passage":"La ferme ouvre sa boutique vendredi, mais les visites d'élevage reprendront seulement au printemps.\n\nL'équipe peut toutefois répondre aux questions sur les produits pendant les horaires de vente.","question":"Que peut-on faire vendredi ?","options":["Dormir dans l'étable","Visiter l'élevage","Acheter à la boutique","Participer aux naissances"],"correct":"C","explanation":"Le passage indique : « La ferme ouvre sa boutique vendredi, mais les visites d'élevage reprendront seulement au printemps. » Cela justifie la réponse : Acheter à la boutique."},{"number":3,"points":3,"passage":"Les chiens sont acceptés sur le chemin s'ils restent en laisse. Ils ne doivent pas entrer dans les parcelles.\n\nCette consigne permet de maintenir l'accès public sans perturber le travail dans les champs voisins.","question":"Quelle règle concerne les chiens ?","options":["Accompagner obligatoirement chaque visiteur","Courir librement dans les cultures","Rester attachés sur le chemin","Entrer dans tous les bâtiments"],"correct":"C","explanation":"Le passage indique : « Les chiens sont acceptés sur le chemin s'ils restent en laisse. Ils ne doivent pas entrer dans les parcelles. » Cela justifie la réponse : Rester attachés sur le chemin."},{"number":4,"points":3,"passage":"Le moulin reçoit les groupes sur réservation. Les visiteurs individuels peuvent venir dimanche entre dix et seize heures.\n\nLes groupes recevront une confirmation avec les conditions d'accueil. Les visites individuelles suivront le parcours ouvert et respecteront les espaces non accessibles au public.","question":"Quand une personne seule peut-elle venir sans réservation ?","options":["Dimanche pendant les horaires indiqués","Après seize heures dimanche","Tous les soirs","Uniquement en hiver"],"correct":"A","explanation":"Le passage indique : « Le moulin reçoit les groupes sur réservation. Les visiteurs individuels peuvent venir dimanche entre dix et seize heures. » Cela justifie la réponse : Dimanche pendant les horaires indiqués."},{"number":5,"points":9,"passage":"Je te garderai les plants jusqu'à samedi. Mets-les à l'abri si le gel revient ; ils ne sont pas encore prêts pour la pleine terre.\n\nJe te préciserai quelles variétés supportent mieux le froid. Prévois quelques pots pour les garder temporairement près d'une fenêtre plutôt que les installer trop vite au jardin.","question":"Quelle précaution est conseillée ?","options":["Protéger les jeunes plants du gel","Les laisser sans lumière pendant un mois","Les arroser avec de l'eau glacée","Les planter immédiatement dehors"],"correct":"A","explanation":"Le passage indique : « Je te garderai les plants jusqu'à samedi. Mets-les à l'abri si le gel revient ; ils ne sont pas encore prêts pour la pleine terre. » Cela justifie la réponse : Protéger les jeunes plants du gel."},{"number":6,"points":9,"passage":"L'association recherche des photos anciennes du village. Les originaux seront numérisés puis rendus ; aucun don définitif n'est demandé.\n\nUne fiche permettra d'identifier les lieux et les personnes représentés lorsque ces informations sont connues. Les propriétaires pourront vérifier les légendes avant l'exposition.","question":"Que deviendront les documents prêtés ?","options":["Ils resteront obligatoirement au musée","Ils seront vendus aux visiteurs","Ils seront restitués après copie","Ils seront détruits après exposition"],"correct":"C","explanation":"Le passage indique : « L'association recherche des photos anciennes du village. Les originaux seront numérisés puis rendus ; aucun don définitif n'est demandé. » Cela justifie la réponse : Ils seront restitués après copie."},{"number":7,"points":9,"passage":"Nous visiterons les ruches avec un apiculteur. Les personnes sensibles aux piqûres doivent le signaler avant la sortie.\n\nUn équipement de protection sera présenté au groupe avant l'approche. Le responsable pourra proposer une autre manière de suivre l'activité si une situation demande davantage de précautions.","question":"Quelle démarche est demandée à certaines personnes ?","options":["Approcher seules les ruches","Renoncer à toute activité rurale","Apporter leur propre miel","Prévenir l'organisateur à l'avance"],"correct":"D","explanation":"Le passage indique : « Nous visiterons les ruches avec un apiculteur. Les personnes sensibles aux piqûres doivent le signaler avant la sortie. » Cela justifie la réponse : Prévenir l'organisateur à l'avance."},{"number":8,"points":9,"passage":"Le panier de cette semaine contient moins de fruits, mais davantage de légumes. La grêle a touché une partie du verger.\n\nLes quantités seront expliquées au point de retrait. Les producteurs vous remercient pour votre compréhension.","question":"Pourquoi le contenu change-t-il ?","options":["Une récolte a subi un aléa météo","Tous les fruits ont été vendus à l'étranger","Les clients ont demandé uniquement des légumes","Le point de retrait est fermé"],"correct":"A","explanation":"Le passage indique : « Le panier de cette semaine contient moins de fruits, mais davantage de légumes. La grêle a touché une partie du verger. » Cela justifie la réponse : Une récolte a subi un aléa météo."},{"number":9,"points":9,"passage":"Apportez des bottes pour la visite : le chemin près des pâtures est boueux, même lorsque la cour semble sèche.\n\nNous marcherons aussi sur une partie du terrain pour découvrir les activités du jour.","question":"Quel équipement est recommandé ?","options":["Des sandales de ville","Des chaussures adaptées à la boue","Des patins","Un masque de plongée"],"correct":"B","explanation":"Le passage indique : « Apportez des bottes pour la visite : le chemin près des pâtures est boueux, même lorsque la cour semble sèche. » Cela justifie la réponse : Des chaussures adaptées à la boue."},{"number":10,"points":9,"passage":"Je préfère venir aider au désherbage tôt le matin. Ensuite, la chaleur rend le travail plus fatigant.\n\nJe pourrai ensuite aider à ranger le matériel avant de repartir. Cette organisation me permettra de travailler tranquillement sans devoir interrompre longtemps l'activité aux heures les plus difficiles.","question":"Pourquoi choisir cet horaire ?","options":["Éviter toute rencontre","Limiter la fatigue liée à la chaleur","Terminer une livraison nocturne","Profiter d'une température plus élevée"],"correct":"B","explanation":"Le passage indique : « Je préfère venir aider au désherbage tôt le matin. Ensuite, la chaleur rend le travail plus fatigant. » Cela justifie la réponse : Limiter la fatigue liée à la chaleur."},{"number":11,"points":15,"passage":"Une commune conserve de petites mares malgré leur aspect parfois désordonné. Elles accueillent des espèces qui ne vivent pas dans les bassins décoratifs.\n\nLes agents ont prévu un entretien différent des abords, afin de ne pas retirer toute la végétation pendant une période sensible. Des panneaux expliqueront ce choix aux passants. La commune souhaite éviter que la présence de plantes irrégulières ou d'eau trouble soit automatiquement interprétée comme un abandon. Les habitants pourront alors découvrir les fonctions de ces lieux modestes, dont l'intérêt ne se voit pas toujours dans un paysage aménagé uniquement pour paraître propre sur une photographie.","question":"Quel intérêt est souligné ?","options":["La suppression des plantes aquatiques","La préservation d'habitats particuliers","L'uniformité esthétique","La création d'un parking"],"correct":"B","explanation":"Le passage indique : « Une commune conserve de petites mares malgré leur aspect parfois désordonné. Elles accueillent des espèces qui ne vivent pas dans les bassins décoratifs. » Cela justifie la réponse : La préservation d'habitats particuliers."},{"number":12,"points":15,"passage":"Un éleveur déplace ses animaux entre plusieurs parcelles. Les périodes de repos permettent à l'herbe de repousser.\n\nIl observe la végétation et les traces de passage avant de décider du prochain déplacement. L'exploitant ne présente pas la rotation comme un calendrier indépendant de la météo : elle demande un suivi, afin que l'organisation protège les ressources dont les animaux auront besoin pendant le reste de la saison.","question":"À quoi sert la rotation ?","options":["Transformer les prairies en routes","Récolter le lait sans déplacement","Laisser les prairies se renouveler","Éviter toute alimentation des animaux"],"correct":"C","explanation":"Le passage indique : « Un éleveur déplace ses animaux entre plusieurs parcelles. Les périodes de repos permettent à l'herbe de repousser. » Cela justifie la réponse : Laisser les prairies se renouveler."},{"number":13,"points":15,"passage":"Des habitants relèvent la présence d'insectes sur une haie. Ils observent aussi les fleurs disponibles pour relier les visites aux ressources du lieu.\n\nLes bénévoles utilisent une fiche commune et choisissent plusieurs moments d'observation pour ne pas retenir seulement une visite exceptionnelle. Les espèces difficiles à identifier seront examinées avec une association. Le groupe souhaite apprendre à relier les présences aux conditions du lieu, sans conclure à partir d'une photographie isolée. Les habitants pourront ainsi comprendre pourquoi deux observations différentes ne signifient pas automatiquement qu'une plante attire toujours davantage d'insectes qu'une autre dans toutes les situations.","question":"Quelle information complète le comptage ?","options":["Le prix des clôtures","La présence de fleurs","La couleur des maisons","Le nombre de voitures"],"correct":"B","explanation":"Le passage indique : « Des habitants relèvent la présence d'insectes sur une haie. Ils observent aussi les fleurs disponibles pour relier les visites aux ressources du lieu. » Cela justifie la réponse : La présence de fleurs."},{"number":14,"points":15,"passage":"Une ferme vend des produits transformés sur place pour mieux répartir ses revenus dans l'année. Les ateliers occupent notamment les périodes où les ventes fraîches diminuent.\n\nLes préparations sont choisies selon les produits disponibles et les équipements que la ferme peut utiliser correctement. Les clients peuvent acheter sur place ou lors de quelques marchés. L'exploitant suit le temps consacré à cette activité, car transformer demande aussi de nouvelles compétences et une organisation précise. Il ne suffit pas de conserver un produit pour garantir sa vente.","question":"Quel objectif économique est poursuivi ?","options":["Supprimer toutes les ventes fraîches","Travailler uniquement un mois par an","Acheter exclusivement des produits importés","Réduire les variations saisonnières de revenus"],"correct":"D","explanation":"Le passage indique : « Une ferme vend des produits transformés sur place pour mieux répartir ses revenus dans l'année. Les ateliers occupent notamment les périodes où les ventes fraîches diminuent. » Cela justifie la réponse : Réduire les variations saisonnières de revenus."},{"number":15,"points":15,"passage":"Une classe découvre les semences avant le potager. Les élèves comparent leur taille et leurs besoins plutôt que planter tout au même moment.\n\nLes groupes peuvent comparer leurs observations avant d'intervenir. Les animateurs souhaitent éviter que l'activité soit réduite à enfouir des graines puis attendre un résultat identique. Certaines demandes d'eau, de lumière ou de température doivent être anticipées. À la fin de la saison, les élèves raconteront aussi les essais qui n'ont pas fonctionné, afin de comprendre ce qu'ils ont appris sans mesurer la réussite uniquement au nombre de légumes récoltés dans leur petite parcelle.","question":"Quel apprentissage est visé ?","options":["Éviter toute observation","Appliquer une règle identique à toutes les graines","Distinguer les conditions de culture","Mesurer seulement le prix des sachets"],"correct":"C","explanation":"Le passage indique : « Une classe découvre les semences avant le potager. Les élèves comparent leur taille et leurs besoins plutôt que planter tout au même moment. » Cela justifie la réponse : Distinguer les conditions de culture."},{"number":16,"points":15,"passage":"Des bénévoles restaurent un muret sans ciment. Ils apprennent une technique locale qui permet l'écoulement de l'eau et offre des refuges à de petits animaux.\n\nLes participants observent les pierres disponibles avant de commencer et choisissent leur position avec l'aide d'un artisan. Ils ne cherchent pas à reproduire un décor sans comprendre sa construction. Le chantier permettra aussi de discuter des réparations anciennes et des gestes d'entretien. Le village souhaite conserver un savoir utile en donnant aux bénévoles l'occasion de pratiquer, plutôt qu'en montrant seulement un mur terminé.","question":"Quel avantage est indiqué ?","options":["Remplacer les pierres par du plastique","Empêcher tous les passages d'eau","Conserver plusieurs fonctions du muret","Rendre le sol totalement étanche"],"correct":"C","explanation":"Le passage indique : « Des bénévoles restaurent un muret sans ciment. Ils apprennent une technique locale qui permet l'écoulement de l'eau et offre des refuges à de petits animaux. » Cela justifie la réponse : Conserver plusieurs fonctions du muret."},{"number":17,"points":15,"passage":"Un producteur ouvre une journée d'autocueillette. Les visiteurs paient les fruits récoltés et doivent respecter les rangs indiqués pour ne pas abîmer les plants.\n\nLes rangs ouverts sont marqués et les quantités pesées à la sortie. L'équipe explique quels fruits peuvent être cueillis et comment éviter de casser les branches. Les visiteurs sont invités à demander conseil plutôt qu'à déplacer les repères eux-mêmes. La ferme souhaite proposer une rencontre agréable avec la production, sans oublier que les plantes doivent continuer à donner après leur passage.","question":"Quelle responsabilité accompagne l'activité ?","options":["Récolter dans toutes les parcelles","Préserver les cultures pendant la récolte","Choisir gratuitement tout le stock","Entrer sans consigne"],"correct":"B","explanation":"Le passage indique : « Un producteur ouvre une journée d'autocueillette. Les visiteurs paient les fruits récoltés et doivent respecter les rangs indiqués pour ne pas abîmer les plants. » Cela justifie la réponse : Préserver les cultures pendant la récolte."},{"number":18,"points":15,"passage":"Un marché rural ajoute un arrêt de navette. Les personnes sans voiture peuvent désormais y venir, sans dépendre d'un voisin disponible.\n\nLes horaires ont été construits autour des jours de marché, avec un temps suffisant pour faire les achats sans courir. Une information sera distribuée aux habitants qui ne consultent pas les annonces en ligne. Les responsables regarderont si les correspondances et l'emplacement de l'arrêt conviennent réellement. Ils ne souhaitent pas présenter la création de la ligne comme une réponse achevée avant de connaître l'expérience des premiers usagers.","question":"Quel effet est attendu ?","options":["Une fermeture des commerces","Une hausse obligatoire des achats","Une suppression des relations de voisinage","Un accès plus autonome au marché"],"correct":"D","explanation":"Le passage indique : « Un marché rural ajoute un arrêt de navette. Les personnes sans voiture peuvent désormais y venir, sans dépendre d'un voisin disponible. » Cela justifie la réponse : Un accès plus autonome au marché."},{"number":19,"points":15,"passage":"Une association surveille les floraisons chaque année. Une floraison plus précoce sera interprétée avec d'autres observations, pas comme la preuve isolée d'une tendance générale.\n\nLe groupe utilise plusieurs points fixes et conserve les relevés même lorsqu'aucun changement remarquable n'est visible. Les participants peuvent noter les conditions du moment et demander une vérification de leur identification. L'association souhaite construire une série utile, pas seulement recueillir des annonces de phénomènes inhabituels. Les visiteurs découvriront les résultats avec ces limites.","question":"Quelle prudence est exprimée ?","options":["Refuser toute comparaison annuelle","Ignorer les dates de floraison","Croiser les observations avant de conclure","Considérer un seul événement comme suffisant"],"correct":"C","explanation":"Le passage indique : « Une association surveille les floraisons chaque année. Une floraison plus précoce sera interprétée avec d'autres observations, pas comme la preuve isolée d'une tendance générale. » Cela justifie la réponse : Croiser les observations avant de conclure."},{"number":20,"points":21,"passage":"Une commune loue des terres à de nouveaux agriculteurs. Le bail laisse du temps pour développer une activité, mais prévoit un suivi des pratiques et des engagements pris. Les candidats présentent leur projet et les moyens dont ils disposent pour le mettre en place. Le service souhaite leur donner le temps d'apprendre le terrain et de préparer leurs débouchés. Les rencontres de suivi permettront d'identifier les difficultés, sans modifier les règles à chaque imprévu. La commune veut une activité viable et cohérente avec les objectifs annoncés, plutôt qu'une installation rapide qui disparaîtrait après une première saison difficile.","question":"Quel équilibre est recherché ?","options":["Donner de la stabilité avec un suivi","Exiger des résultats immédiats identiques","Réserver les terres aux exploitants déjà installés","Offrir un accès sans aucune règle"],"correct":"A","explanation":"Le passage indique : « Une commune loue des terres à de nouveaux agriculteurs. Le bail laisse du temps pour développer une activité, mais prévoit un suivi des pratiques et des engagements pris. » Cela justifie la réponse : Donner de la stabilité avec un suivi."},{"number":21,"points":21,"passage":"Le retour de certains oiseaux près d'une ferme encourage ses habitants. Ils ne l'attribuent pas à une seule mesure : haies, mares et changements de pratiques ont été mis en place ensemble. Les habitants ont participé à plusieurs actions et les changements ne peuvent pas être isolés facilement dans leurs souvenirs. Une association propose de garder des repères communs pour les prochaines années. Les observations resteront utiles, même sans permettre d'affirmer qu'un geste unique explique tout.","question":"Pourquoi rester prudent sur la cause ?","options":["Plusieurs changements ont eu lieu simultanément","Les habitants ignorent le lieu de la ferme","Les mesures n'ont jamais été réalisées","Aucun oiseau n'a été observé"],"correct":"A","explanation":"Le passage indique : « Le retour de certains oiseaux près d'une ferme encourage ses habitants. Ils ne l'attribuent pas à une seule mesure : haies, mares et changements de pratiques ont été mis en place ensemble. » Cela justifie la réponse : Plusieurs changements ont eu lieu simultanément."},{"number":22,"points":21,"passage":"Un village transforme un ancien bâtiment agricole en atelier partagé. Il conserve la charpente, mais adapte l'accès aux normes actuelles. La conservation ne signifie pas l'absence de modification. Les futurs utilisateurs ont expliqué les espaces nécessaires au rangement, aux machines et à la circulation. Certains éléments seront protégés ou déplacés pour permettre ces activités. Le comité souhaite que les visiteurs puissent encore comprendre l'histoire du bâtiment. Il refuse cependant de confondre respect du lieu et impossibilité d'y travailler autrement.","question":"Quelle démarche est décrite ?","options":["Préserver tout en adaptant à un nouvel usage","Conserver uniquement le nom de la ferme","Reconstruire une copie sans utiliser le bâtiment","Interdire toute activité nouvelle"],"correct":"A","explanation":"Le passage indique : « Un village transforme un ancien bâtiment agricole en atelier partagé. Il conserve la charpente, mais adapte l'accès aux normes actuelles. La conservation ne signifie pas l'absence de modification. » Cela justifie la réponse : Préserver tout en adaptant à un nouvel usage."},{"number":23,"points":21,"passage":"Des agriculteurs proposent une vente collective. Chacun gagne du temps de commercialisation, mais doit accepter des règles communes de présence et de présentation des produits. Les produits de chacun sont identifiés et les ventes suivies dans un document partagé. Les décisions importantes seront discutées avant d'être appliquées. Les agriculteurs veulent que la boutique reste compatible avec leurs périodes de travail sur les terres. Ils devront parfois échanger une permanence ou réduire une présence annoncée.","question":"Quelle contrepartie accompagne le gain de temps ?","options":["Une disparition des responsabilités","Une coordination entre producteurs","L'arrêt de toute production","L'obligation de vendre les mêmes produits"],"correct":"B","explanation":"Le passage indique : « Des agriculteurs proposent une vente collective. Chacun gagne du temps de commercialisation, mais doit accepter des règles communes de présence et de présentation des produits. » Cela justifie la réponse : Une coordination entre producteurs."},{"number":24,"points":21,"passage":"Un parcours explique les paysages avec les témoignages de travailleurs agricoles. Les champs sont présentés comme des espaces de production et de décisions, pas seulement comme un décor. Les témoins racontent les rythmes de l'année et les raisons de certaines transformations visibles depuis le chemin. Les visiteurs pourront comparer ces récits avec des cartes. Les organisateurs ne demandent pas aux habitants de présenter une campagne idéale ni de justifier chaque choix devant le public.","question":"Quelle lecture du paysage est proposée ?","options":["Remplacer les fermes par des cartes postales","Ignorer toute intervention humaine","Évaluer uniquement les couleurs","Comprendre les activités qui le façonnent"],"correct":"D","explanation":"Le passage indique : « Un parcours explique les paysages avec les témoignages de travailleurs agricoles. Les champs sont présentés comme des espaces de production et de décisions, pas seulement comme un décor. » Cela justifie la réponse : Comprendre les activités qui le façonnent."},{"number":25,"points":21,"passage":"Une coopérative hésite entre agrandir son entrepôt et mieux partager les capacités existantes. Elle réalise d'abord un état des lieux des périodes d'utilisation avant d'investir. Le groupe relève les volumes, les moments de pointe et les marges disponibles dans les bâtiments voisins. Certains espaces semblent vides une partie de l'année, mais leur usage reste important pendant une courte période. La coopérative veut donc regarder l'ensemble du calendrier avant de conclure à une capacité inutile ou insuffisante.","question":"Pourquoi commencer par cet état des lieux ?","options":["Supprimer toutes les récoltes","Garantir immédiatement un nouvel entrepôt","Choisir l'emplacement des bureaux seulement","Vérifier les besoins réels de capacité"],"correct":"D","explanation":"Le passage indique : « Une coopérative hésite entre agrandir son entrepôt et mieux partager les capacités existantes. Elle réalise d'abord un état des lieux des périodes d'utilisation avant d'investir. » Cela justifie la réponse : Vérifier les besoins réels de capacité."},{"number":26,"points":21,"passage":"Des habitants veulent planter des arbres fruitiers communs. L'association prévoit aussi qui taillera, arrosera et récoltera. La plantation n'est que le début de l'engagement. Les habitants préparent un calendrier et identifient les personnes pouvant transmettre les gestes nécessaires aux nouveaux participants. Des périodes d'absence doivent aussi être prévues. Le projet ne veut pas dépendre d'un seul jardinier enthousiaste qui s'occuperait de tout sans relais. Les décisions porteront donc sur les plantations et sur les conditions qui permettront de les garder en bon état.","question":"Quel aspect complète le projet ?","options":["L'absence de responsabilité après plantation","La vente immédiate de toute la place","La garantie de fruits dès le lendemain","L'organisation de l'entretien dans la durée"],"correct":"D","explanation":"Le passage indique : « Des habitants veulent planter des arbres fruitiers communs. L'association prévoit aussi qui taillera, arrosera et récoltera. La plantation n'est que le début de l'engagement. » Cela justifie la réponse : L'organisation de l'entretien dans la durée."},{"number":27,"points":21,"passage":"Une zone humide est parfois vide d'eau en été. Des visiteurs la jugent inutile, mais les gestionnaires expliquent que ses cycles saisonniers font partie de son fonctionnement. Les gestionnaires montreront des photographies prises à différents moments et expliqueront les espèces qui utilisent le lieu. Certaines fonctions sont moins faciles à observer pendant une visite courte. Le programme souhaite donner ces repères sans prétendre qu'un état unique serait le bon toute l'année.","question":"Quelle erreur d'interprétation est corrigée ?","options":["Penser que les saisons existent","Reconnaître que l'eau peut varier","Confondre un état saisonnier avec une absence de fonction","Observer le site en été"],"correct":"C","explanation":"Le passage indique : « Une zone humide est parfois vide d'eau en été. Des visiteurs la jugent inutile, mais les gestionnaires expliquent que ses cycles saisonniers font partie de son fonctionnement. » Cela justifie la réponse : Confondre un état saisonnier avec une absence de fonction."},{"number":28,"points":21,"passage":"Un agriculteur réduit une culture très rentable pour diversifier ses productions. Il accepte un gain immédiat moins élevé afin de moins dépendre d'un seul débouché. Il étudie d'autres ventes possibles et réserve du temps pour apprendre les nouvelles cultures. Cette évolution comporte elle aussi des difficultés, qu'il ne veut pas cacher dans son bilan. L'exploitant cherche une organisation moins fragile lorsqu'un prix baisse ou qu'un acheteur se retire.","question":"Quel objectif motive son choix ?","options":["Maximiser uniquement le revenu de l'année","Limiter un risque économique","Abandonner toute vente","Produire pour un client unique"],"correct":"B","explanation":"Le passage indique : « Un agriculteur réduit une culture très rentable pour diversifier ses productions. Il accepte un gain immédiat moins élevé afin de moins dépendre d'un seul débouché. » Cela justifie la réponse : Limiter un risque économique."},{"number":29,"points":21,"passage":"Une fête de village donne une place aux nouveaux habitants dans son organisation. Les traditions restent présentes, mais des activités supplémentaires sont proposées après discussion. Les nouveaux bénévoles peuvent participer aux réunions et proposer un rôle correspondant à leurs disponibilités. Les organisateurs souhaitent transmettre les habitudes sans demander de les connaître toutes avant de venir. Le programme final garde des repères familiers et introduit quelques essais.","question":"Comment le programme évolue-t-il ?","options":["Il associe héritage et nouvelles contributions","Il est fixé sans échange","Il refuse toute proposition extérieure","Il supprime toutes les habitudes"],"correct":"A","explanation":"Le passage indique : « Une fête de village donne une place aux nouveaux habitants dans son organisation. Les traditions restent présentes, mais des activités supplémentaires sont proposées après discussion. » Cela justifie la réponse : Il associe héritage et nouvelles contributions."},{"number":30,"points":26,"passage":"L'image d'une campagne immobile masque les transformations des métiers, des techniques et des relations entre habitants. Un chercheur observe ces changements sans en déduire que tous les villages suivent la même trajectoire. La ruralité ne décrit pas une situation unique. Il compare notamment l'accès aux services, les activités et les relations avec les villes proches. Ces éléments aident à comprendre pourquoi une mesure utile dans un village ne produit pas automatiquement le même effet dans tous les autres.","question":"Quelle simplification est contestée ?","options":["L'idée d'un monde rural uniforme et sans changement","La diversité des territoires","La possibilité de nouveaux habitants","L'existence de métiers agricoles"],"correct":"A","explanation":"Le passage indique : « L'image d'une campagne immobile masque les transformations des métiers, des techniques et des relations entre habitants. Un chercheur observe ces changements sans en déduire que tous les villages suivent la même trajectoire. La ruralité ne décrit pas une situation unique. » Cela justifie la réponse : L'idée d'un monde rural uniforme et sans changement."},{"number":31,"points":26,"passage":"Une aide agricole dépend du nombre d'arbres plantés. Certains bénéficiaires demandent qu'un suivi de leur survie soit également financé. Compter les plantations sans regarder leur avenir risque de récompenser un geste ponctuel plutôt qu'un effet durable sur le paysage. Elles demandent des moyens pour agir après la photographie du jour de plantation, lorsque la réussite dépend encore de gestes moins visibles mais réguliers.","question":"Quel indicateur complémentaire est proposé ?","options":["La longueur des discours","La couleur des formulaires","Le nombre de photos prises","Le maintien des arbres dans le temps"],"correct":"D","explanation":"Le passage indique : « Une aide agricole dépend du nombre d'arbres plantés. Certains bénéficiaires demandent qu'un suivi de leur survie soit également financé. Compter les plantations sans regarder leur avenir risque de récompenser un geste ponctuel plutôt qu'un effet durable sur le paysage. » Cela justifie la réponse : Le maintien des arbres dans le temps."},{"number":32,"points":26,"passage":"Un circuit court réduit le nombre d'intermédiaires, mais ne dit pas à lui seul quelle distance parcourt le produit. Un achat direct très éloigné peut demander davantage de transport qu'un produit distribué localement par plusieurs acteurs. Les consommateurs peuvent donc demander où le produit a été fabriqué et comment il est acheminé. Une information claire permettra de comparer les offres sans attribuer à un seul terme des garanties qu'il ne donne pas forcément.","question":"Quelle distinction faut-il retenir ?","options":["Tout achat direct vient nécessairement du village","Tout intermédiaire impose un trajet international","La distance ne peut jamais être estimée","Nombre d'intermédiaires et distance ne sont pas identiques"],"correct":"D","explanation":"Le passage indique : « Un circuit court réduit le nombre d'intermédiaires, mais ne dit pas à lui seul quelle distance parcourt le produit. Un achat direct très éloigné peut demander davantage de transport qu'un produit distribué localement par plusieurs acteurs. » Cela justifie la réponse : Nombre d'intermédiaires et distance ne sont pas identiques."},{"number":33,"points":26,"passage":"Des pratiques agricoles se transmettent par l'observation de signes locaux : état du sol, végétation, humidité. Un nouvel outil apporte d'autres données. Les utilisateurs les plus expérimentés ne choisissent pas forcément entre les deux ; ils cherchent comment les confronter utilement. Les producteurs discutent les cas où les deux sources se complètent et ceux où elles semblent se contredire.","question":"Quelle démarche est mise en avant ?","options":["Croiser savoirs d'expérience et informations nouvelles","Considérer l'outil comme infaillible","Écarter toute observation locale","Refuser toute donnée mesurée"],"correct":"A","explanation":"Le passage indique : « Des pratiques agricoles se transmettent par l'observation de signes locaux : état du sol, végétation, humidité. Un nouvel outil apporte d'autres données. Les utilisateurs les plus expérimentés ne choisissent pas forcément entre les deux ; ils cherchent comment les confronter utilement. » Cela justifie la réponse : Croiser savoirs d'expérience et informations nouvelles."},{"number":34,"points":26,"passage":"Une commune aménage des chemins pour les visiteurs, mais les engins agricoles doivent continuer à circuler. Les règles élaborées avec les usagers tiennent compte des périodes de travail. Ouvrir un espace ne signifie pas effacer les activités qui y existaient déjà. Le projet veut rendre les rencontres possibles tout en expliquant pourquoi certaines contraintes ne peuvent pas être décidées uniquement selon le confort des visiteurs.","question":"Quel enjeu d'aménagement apparaît ?","options":["Organiser la coexistence des usages","Supprimer toute information sur les récoltes","Interdire l'agriculture près des promenades","Réserver tous les chemins à un seul public"],"correct":"A","explanation":"Le passage indique : « Une commune aménage des chemins pour les visiteurs, mais les engins agricoles doivent continuer à circuler. Les règles élaborées avec les usagers tiennent compte des périodes de travail. Ouvrir un espace ne signifie pas effacer les activités qui y existaient déjà. » Cela justifie la réponse : Organiser la coexistence des usages."},{"number":35,"points":26,"passage":"Des fermes accueillent des classes pour montrer la production alimentaire. Les visites les plus riches ne se limitent pas à une démonstration agréable : elles expliquent aussi les choix difficiles et les incertitudes du métier. Comprendre une activité demande parfois de dépasser son image rassurante. Les responsables souhaitent qu'ils comprennent les liens entre une décision et ses conséquences, au lieu de repartir avec une image agréable mais incomplète d'une journée de travail.","question":"Quel type de découverte est valorisé ?","options":["Une imitation des seules publicités","Une approche comprenant les contraintes du métier","Une visite réduite aux souvenirs vendus","Une présentation sans aucune difficulté"],"correct":"B","explanation":"Le passage indique : « Des fermes accueillent des classes pour montrer la production alimentaire. Les visites les plus riches ne se limitent pas à une démonstration agréable : elles expliquent aussi les choix difficiles et les incertitudes du métier. Comprendre une activité demande parfois de dépasser son image rassurante. » Cela justifie la réponse : Une approche comprenant les contraintes du métier."},{"number":36,"points":33,"passage":"Un projet propose de protéger un paysage en interdisant toute transformation. Les habitants rappellent que ce paysage résulte lui-même de pratiques successives. Ils souhaitent préserver des qualités sans figer les conditions de vie. La conservation d'un territoire habité doit composer avec les besoins de ceux qui continuent à le faire vivre. Certains bâtiments nécessitent de nouvelles fonctions pour rester entretenus, et les exploitants doivent parfois changer leur organisation. Les habitants souhaitent distinguer ces besoins de transformations qui effaceraient sans raison les qualités du lieu. La discussion devra donc examiner des cas concrets et leurs effets. Une règle générale apparemment protectrice peut devenir difficile à vivre si elle traite toute modification comme une dégradation. Les responsables du projet proposent des visites communes pour comprendre les usages présents, les héritages à maintenir et les possibilités d'adaptation compatibles avec la vie du village.","question":"Quelle tension le projet soulève-t-il ?","options":["Supprimer toute notion de patrimoine","Remplacer tous les habitants par des visiteurs","Préserver un paysage tout en permettant son évolution","Choisir entre deux couleurs de clôture uniquement"],"correct":"C","explanation":"Le passage indique : « La conservation d'un territoire habité doit composer avec les besoins de ceux qui continuent à le faire vivre. » Cela justifie la réponse : Préserver un paysage tout en permettant son évolution."},{"number":37,"points":33,"passage":"Une exploitation est souvent évaluée par son rendement sur une seule culture. Pourtant, elle entretient aussi des haies, partage du matériel et contribue à l'emploi local. Ces fonctions ne justifient pas d'ignorer le rendement, mais elles élargissent les questions à poser. Une performance devient différente selon les dimensions que l'on accepte de compter. Les responsables souhaitent notamment rendre visibles des tâches qui n'apparaissent pas directement dans les volumes vendus. Les comparaisons devront donc préciser ce qu'elles retiennent et les limites du résultat. Une ferme peut présenter des forces et des difficultés différentes selon le domaine observé. Le bilan devient plus utile lorsqu'il aide à discuter ces écarts, plutôt que lorsqu'il transforme un seul chiffre en classement complet de toutes les activités et de leurs effets sur le territoire.","question":"Quelle approche est proposée ?","options":["Une suppression de tout indicateur productif","Une évaluation comportant plusieurs dimensions","Une assimilation de toutes les fermes","Une comparaison limitée à la superficie"],"correct":"B","explanation":"Le passage indique : « Une performance devient différente selon les dimensions que l'on accepte de compter. » Cela justifie la réponse : Une évaluation comportant plusieurs dimensions."},{"number":38,"points":33,"passage":"La vente directe est parfois présentée comme une relation spontanée entre producteur et consommateur. Elle demande pourtant du temps pour accueillir, expliquer et organiser les commandes. Un producteur peut bien cultiver sans souhaiter assurer seul cette activité supplémentaire. Réduire les intermédiaires ne fait pas disparaître les fonctions qu'ils prenaient en charge. Les clients doivent pouvoir connaître les horaires, réserver, obtenir une réponse et récupérer leur commande dans de bonnes conditions. Ces tâches peuvent être partagées ou confiées à un partenaire sans effacer le lien recherché avec les producteurs. Le débat ne porte donc pas seulement sur le nombre d'acteurs entre le champ et le panier. Il concerne aussi la manière dont le travail est réparti et reconnu. Les exploitants souhaitent comparer les solutions avec leur charge réelle, afin qu'une formule présentée comme plus simple pour l'acheteur ne rende pas leur propre activité plus difficile à maintenir.","question":"Quelle idée est soulignée ?","options":["La vente directe ne demande aucun travail","Les tâches de commercialisation doivent toujours être réalisées","Le producteur doit nécessairement tout faire seul","Les consommateurs peuvent supprimer toutes les commandes"],"correct":"B","explanation":"Le passage indique : « Réduire les intermédiaires ne fait pas disparaître les fonctions qu'ils prenaient en charge. » Cela justifie la réponse : Les tâches de commercialisation doivent toujours être réalisées."},{"number":39,"points":33,"passage":"Un village développe son attractivité pour retenir des habitants. Des services nouveaux apparaissent, mais le prix des logements augmente. Les familles que le projet voulait initialement maintenir peuvent alors rencontrer davantage de difficultés. L'attractivité n'est pas automatiquement synonyme d'accessibilité pour les habitants déjà présents. Les élus doivent donc suivre les coûts du logement en même temps que les arrivées et les recettes nouvelles. Les habitants demandent des possibilités de rester près de leur travail et de leurs proches. Plusieurs solutions seront étudiées, dont des logements accessibles et un maintien de certains services ordinaires. Le programme ne sera pas jugé uniquement à partir d'une image plus attractive ou d'une hausse des visites. Il faudra aussi regarder qui peut encore vivre sur place et dans quelles conditions, afin de comprendre à qui profite réellement le changement annoncé pour l'ensemble du village.","question":"Quel effet contradictoire est décrit ?","options":["Une disparition immédiate des nouveaux services","Une baisse certaine de tous les loyers","Un succès territorial qui peut compliquer le maintien des résidents","Un arrêt de toute arrivée de population"],"correct":"C","explanation":"Le passage indique : « L'attractivité n'est pas automatiquement synonyme d'accessibilité pour les habitants déjà présents. » Cela justifie la réponse : Un succès territorial qui peut compliquer le maintien des résidents."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-13','tcf-reading-2026-11-reference-v3',$paper${"id":"tcf-reading-13","version":"tcf-reading-2026-11-reference-v3","title":"TCF Reading · Test 13","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"La salle informatique sera fermée pour mise à jour mardi matin. L'accueil pourra toujours imprimer vos documents.\n\nLes agents retrouveront le service habituel après les vérifications. Merci de ne pas essayer d'entrer dans la salle pendant l'intervention.","question":"Quel service sera maintenu ?","options":["L'impression à l'accueil","L'accès à tous les ordinateurs","Le cours dans la salle fermée","Le prêt d'une imprimante personnelle"],"correct":"A","explanation":"Le passage indique : « La salle informatique sera fermée pour mise à jour mardi matin. L'accueil pourra toujours imprimer vos documents. » Cela justifie la réponse : L'impression à l'accueil."},{"number":2,"points":3,"passage":"Votre mot de passe ne vous sera jamais demandé par téléphone. En cas d'appel suspect, contactez directement l'assistance habituelle.\n\nLe numéro figure sur vos documents de service.","question":"Que faut-il faire après un appel suspect ?","options":["Publier ses identifiants","Joindre l'assistance par son canal connu","Donner son mot de passe","Rappeler le numéro fourni sans vérification"],"correct":"B","explanation":"Le passage indique : « Votre mot de passe ne vous sera jamais demandé par téléphone. En cas d'appel suspect, contactez directement l'assistance habituelle. » Cela justifie la réponse : Joindre l'assistance par son canal connu."},{"number":3,"points":3,"passage":"L'atelier photo accepte les téléphones anciens. Chargez votre batterie avant de venir ; les prises disponibles sont limitées.\n\nLes participants pourront venir avec un modèle qu'ils utilisent déjà au quotidien, sans devoir en acheter un autre.","question":"Quelle préparation est demandée ?","options":["Supprimer la batterie","Acheter un nouveau téléphone","Recharger l'appareil","Imprimer toutes les photos"],"correct":"C","explanation":"Le passage indique : « L'atelier photo accepte les téléphones anciens. Chargez votre batterie avant de venir ; les prises disponibles sont limitées. » Cela justifie la réponse : Recharger l'appareil."},{"number":4,"points":3,"passage":"Le formulaire peut être enregistré puis repris plus tard. Le bouton « Envoyer » termine la démarche.\n\nUn message confirme ensuite la réception. Avant cette dernière étape, vous pouvez encore relire et corriger les informations saisies dans votre dossier personnel.","question":"Quel bouton finalise le dossier ?","options":["Envoyer","Enregistrer provisoirement","Agrandir le texte","Fermer la fenêtre"],"correct":"A","explanation":"Le passage indique : « Le formulaire peut être enregistré puis repris plus tard. Le bouton « Envoyer » termine la démarche. » Cela justifie la réponse : Envoyer."},{"number":5,"points":9,"passage":"Je t'enverrai les fichiers par le dossier partagé. Évite les pièces jointes : nous risquerions de travailler sur des versions différentes.\n\nJ'ai préparé des noms de documents simples pour retrouver rapidement le travail de chacun. Nous pourrons discuter des modifications dans la note commune sans multiplier les copies.","question":"Pourquoi utiliser un dossier commun ?","options":["Empêcher toute modification","Réduire le nombre de participants","Remplacer les fichiers par des appels","Limiter la confusion entre les versions"],"correct":"D","explanation":"Le passage indique : « Je t'enverrai les fichiers par le dossier partagé. Évite les pièces jointes : nous risquerions de travailler sur des versions différentes. » Cela justifie la réponse : Limiter la confusion entre les versions."},{"number":6,"points":9,"passage":"La permanence numérique accompagne les démarches, mais ne conserve pas vos codes. Vous devrez les saisir vous-même.\n\nLe bénévole peut expliquer où trouver une information, mais les données restent sous votre responsabilité. Merci de fermer votre session après la démarche.","question":"Quelle règle protège l'utilisateur ?","options":["Le partage de tous les mots de passe","La non-conservation des codes par l'accompagnateur","L'envoi des codes aux autres participants","La publication des comptes créés"],"correct":"B","explanation":"Le passage indique : « La permanence numérique accompagne les démarches, mais ne conserve pas vos codes. Vous devrez les saisir vous-même. » Cela justifie la réponse : La non-conservation des codes par l'accompagnateur."},{"number":7,"points":9,"passage":"Mon téléphone fonctionne encore. Je préfère changer sa batterie plutôt que remplacer tout l'appareil.\n\nLe réparateur a vérifié que cette intervention est possible sur mon modèle. Je conserverai aussi mes photos avant de lui laisser l'appareil, par précaution. Je demanderai aussi combien de temps cela prendra.","question":"Quelle décision est prise ?","options":["Abandonner tout appel","Prolonger l'usage du téléphone","Vendre la batterie neuve","Acheter immédiatement un modèle récent"],"correct":"B","explanation":"Le passage indique : « Mon téléphone fonctionne encore. Je préfère changer sa batterie plutôt que remplacer tout l'appareil. » Cela justifie la réponse : Prolonger l'usage du téléphone."},{"number":8,"points":9,"passage":"Pour suivre le cours à distance, un casque est conseillé, pas obligatoire. Une transcription écrite sera disponible après la séance.\n\nLes personnes souhaitant revoir un passage pourront le retrouver après la rencontre.","question":"Quel autre support est prévu ?","options":["Un nouvel ordinateur gratuit","Un examen en salle obligatoire","Une vidéo sans son uniquement","Un texte de la séance"],"correct":"D","explanation":"Le passage indique : « Pour suivre le cours à distance, un casque est conseillé, pas obligatoire. Une transcription écrite sera disponible après la séance. » Cela justifie la réponse : Un texte de la séance."},{"number":9,"points":9,"passage":"J'ai désactivé les notifications pendant mes révisions. Je regarderai les messages à des moments choisis.\n\nJe répondrai aux demandes importantes après ma séance de travail. Si une urgence se présente, mes proches savent comment me joindre autrement que par une succession de notifications.","question":"Quel objectif poursuit cette personne ?","options":["Travailler uniquement la nuit","Mieux maîtriser les interruptions","Supprimer définitivement sa messagerie","Empêcher tous ses proches d'écrire"],"correct":"B","explanation":"Le passage indique : « J'ai désactivé les notifications pendant mes révisions. Je regarderai les messages à des moments choisis. » Cela justifie la réponse : Mieux maîtriser les interruptions."},{"number":10,"points":9,"passage":"Le club prête des tablettes pour le week-end. Elles doivent être rapportées lundi avec leur chargeur.\n\nUne fiche indiquera les précautions et les accessoires remis au départ. Les emprunteurs devront signaler un problème avant de repartir avec le matériel pour un nouveau prêt.","question":"Que faut-il restituer ?","options":["Un appareil acheté neuf","La tablette et son chargeur","Uniquement la housse","Un abonnement téléphonique"],"correct":"B","explanation":"Le passage indique : « Le club prête des tablettes pour le week-end. Elles doivent être rapportées lundi avec leur chargeur. » Cela justifie la réponse : La tablette et son chargeur."},{"number":11,"points":15,"passage":"Une association propose une initiation au rangement des fichiers. Les participants apprennent d'abord à retrouver un document avant d'utiliser des fonctions plus avancées.\n\nLe formateur utilise des exemples courants et laisse les personnes choisir un classement qu'elles comprennent. Il montre aussi comment éviter des noms trop semblables et comment reconnaître plusieurs versions d'un même fichier. Les participants essaient ensuite de retrouver un document après avoir fermé le dossier. L'objectif est de vérifier qu'ils possèdent un repère utilisable seuls, pas seulement qu'ils réussissent à suivre une démonstration. Les questions permettront de préparer les séances suivantes selon les usages réellement rencontrés dans leur quotidien personnel ou professionnel.","question":"Quelle priorité est donnée ?","options":["Acheter du stockage supplémentaire","Effacer tous les dossiers","Créer des programmes complexes","Acquérir un repère de base"],"correct":"D","explanation":"Le passage indique : « Une association propose une initiation au rangement des fichiers. Les participants apprennent d'abord à retrouver un document avant d'utiliser des fonctions plus avancées. » Cela justifie la réponse : Acquérir un repère de base."},{"number":12,"points":15,"passage":"Une application demande l'accès aux contacts pour afficher la météo. Une animatrice explique que cette autorisation n'est pas nécessaire à la fonction annoncée.\n\nLes participants comparent plusieurs exemples pour éviter de penser qu'une application doit toujours recevoir tous les accès proposés. Le but n'est pas de refuser automatiquement chaque service, mais de comprendre la relation entre une fonction et les informations demandées.","question":"Quelle question faut-il se poser ?","options":["Si l'accès demandé correspond au service","Si tous les contacts utilisent l'application","Si le logo est suffisamment coloré","Si le téléphone est assez grand"],"correct":"A","explanation":"Le passage indique : « Une application demande l'accès aux contacts pour afficher la météo. Une animatrice explique que cette autorisation n'est pas nécessaire à la fonction annoncée. » Cela justifie la réponse : Si l'accès demandé correspond au service."},{"number":13,"points":15,"passage":"Un service municipal conserve un accueil téléphonique en parallèle du portail en ligne. Il ne souhaite pas que l'absence d'équipement empêche une démarche.\n\nLes usagers peuvent consulter les mêmes informations essentielles quel que soit le canal choisi. Le personnel est formé pour expliquer les différences de procédure sans renvoyer systématiquement les personnes vers un ordinateur. Le service souhaite conserver la simplicité du portail pour ceux qui l'utilisent, tout en regardant ce qui reste possible pour les autres. Les responsables suivront les temps d'attente, car une alternative annoncée mais difficile à joindre ne constitue pas nécessairement un accès réel.","question":"Quel objectif est poursuivi ?","options":["Maintenir plusieurs voies d'accès au service","Supprimer les formulaires","Réserver les appels aux informaticiens","Obliger chacun à acheter un ordinateur"],"correct":"A","explanation":"Le passage indique : « Un service municipal conserve un accueil téléphonique en parallèle du portail en ligne. Il ne souhaite pas que l'absence d'équipement empêche une démarche. » Cela justifie la réponse : Maintenir plusieurs voies d'accès au service."},{"number":14,"points":15,"passage":"Un atelier montre comment sauvegarder ses photos sur un second support. Une copie située seulement sur le téléphone disparaîtrait avec lui en cas de perte.\n\nLes animateurs distinguent une sauvegarde et une simple copie restée dans le même appareil. Les participants apprennent aussi à vérifier qu'ils peuvent ouvrir les documents sur le second support. Le cours ne promet pas qu'une opération unique protégera définitivement tous les fichiers. Il propose une organisation régulière, adaptée au volume et à l'importance des données. Chacun prépare un premier essai avec des images fictives avant de choisir ses propres documents.","question":"À quoi sert la seconde copie ?","options":["Rendre les photos publiques","Augmenter automatiquement la qualité des images","Supprimer le besoin de classement","Limiter les conséquences de la perte de l'appareil"],"correct":"D","explanation":"Le passage indique : « Un atelier montre comment sauvegarder ses photos sur un second support. Une copie située seulement sur le téléphone disparaîtrait avec lui en cas de perte. » Cela justifie la réponse : Limiter les conséquences de la perte de l'appareil."},{"number":15,"points":15,"passage":"Des habitants testent une nouvelle borne. Ils signalent que les boutons sont lisibles mais que le temps laissé pour répondre est trop court.\n\nCertains habitants ont besoin de relire une consigne ou d'obtenir une explication avant d'appuyer. Les concepteurs avaient surtout testé la borne avec des personnes connaissant déjà les démarches. Ils vont donc revoir le délai et permettre de demander plus de temps. Les essais suivants comprendront des profils différents. L'équipe souhaite distinguer une difficulté liée au contenu et une difficulté produite par le rythme imposé à l'écran.","question":"Quel aspect doit être amélioré ?","options":["Le nombre de fenêtres de la salle","Le prix du papier","Le rythme de l'interaction","La couleur du bâtiment"],"correct":"C","explanation":"Le passage indique : « Des habitants testent une nouvelle borne. Ils signalent que les boutons sont lisibles mais que le temps laissé pour répondre est trop court. » Cela justifie la réponse : Le rythme de l'interaction."},{"number":16,"points":15,"passage":"Une bibliothèque prête des livres numériques. Le prêt s'arrête automatiquement à la date prévue ; le document ne devient pas un achat définitif.\n\nLa bibliothèque explique les possibilités de renouvellement et les conditions de téléchargement. Les lecteurs peuvent demander une démonstration s'ils découvrent le service. Les fichiers empruntés ne doivent pas être confondus avec ceux qu'ils ont achetés ailleurs. Les responsables souhaitent que chacun comprenne les droits annoncés avant de commencer un livre, notamment pendant un voyage.","question":"Quelle distinction est précisée ?","options":["Le livre reste acquis pour toujours","L'emprunteur doit imprimer chaque page","Le droit de lecture est temporaire","Le prêt n'a aucune durée"],"correct":"C","explanation":"Le passage indique : « Une bibliothèque prête des livres numériques. Le prêt s'arrête automatiquement à la date prévue ; le document ne devient pas un achat définitif. » Cela justifie la réponse : Le droit de lecture est temporaire."},{"number":17,"points":15,"passage":"Une équipe choisit un outil de messagerie après un essai commun. Elle évalue aussi la facilité de quitter le service et d'exporter les données.\n\nLes salariés comparent les formats obtenus et regardent si les conversations utiles restent compréhensibles hors de l'outil. Ils souhaitent éviter une dépendance découverte uniquement au moment du départ. Cette vérification ne signifie pas que le groupe prévoit déjà d'abandonner le service. Elle sert à conserver une marge de décision si les besoins, les tarifs ou les règles changent.","question":"Quel critère dépasse l'usage immédiat ?","options":["La couleur du câble","Le nombre de publicités","La possibilité de changer d'outil plus tard","La taille du logo"],"correct":"C","explanation":"Le passage indique : « Une équipe choisit un outil de messagerie après un essai commun. Elle évalue aussi la facilité de quitter le service et d'exporter les données. » Cela justifie la réponse : La possibilité de changer d'outil plus tard."},{"number":18,"points":15,"passage":"Un atelier apprend à repérer l'adresse exacte d'un site. Une page qui ressemble à un service connu peut être hébergée ailleurs.\n\nLes participants observent des exemples fictifs où un détail du nom change alors que le logo paraît familier. Ils apprennent à retrouver le service par un moyen connu plutôt qu'à suivre immédiatement un lien reçu. Le formateur souhaite ralentir le geste lorsque la demande semble inhabituelle. Il ne promet pas une méthode qui remplacerait toute vérification future.","question":"Quelle précaution est enseignée ?","options":["Faire confiance à toute copie visuelle","Télécharger tous les fichiers proposés","Vérifier l'adresse plutôt que le seul aspect","Ignorer les informations du navigateur"],"correct":"C","explanation":"Le passage indique : « Un atelier apprend à repérer l'adresse exacte d'un site. Une page qui ressemble à un service connu peut être hébergée ailleurs. » Cela justifie la réponse : Vérifier l'adresse plutôt que le seul aspect."},{"number":19,"points":15,"passage":"Une école demande aux familles de ne pas diffuser les images de groupe sans vérifier les autorisations. Une photo reçue ne donne pas automatiquement le droit de la publier.\n\nLes organisateurs recueilleront les choix avant le prochain événement et indiqueront quelles images peuvent être utilisées sur les supports du groupe. Les familles pourront poser une question sans devoir se justifier devant tout le monde. L'école veut éviter qu'une habitude de partage transforme un souvenir reçu en autorisation supposée générale.","question":"Quelle limite est rappelée ?","options":["La publication est obligatoire après réception","Les familles ne peuvent jamais regarder les photos","Toute image de groupe doit être vendue","Recevoir une image ne suffit pas à autoriser sa diffusion"],"correct":"D","explanation":"Le passage indique : « Une école demande aux familles de ne pas diffuser les images de groupe sans vérifier les autorisations. Une photo reçue ne donne pas automatiquement le droit de la publier. » Cela justifie la réponse : Recevoir une image ne suffit pas à autoriser sa diffusion."},{"number":20,"points":21,"passage":"Une administration simplifie ses formulaires numériques avec les usagers. Les erreurs fréquentes servent à identifier des consignes peu claires, et pas seulement à constater l'inattention des personnes. Les agents relisent les demandes avec des personnes connaissant peu la procédure. Ils observent où les utilisateurs hésitent et quels mots produisent des interprétations différentes. Le service souhaite garder les informations nécessaires, mais les présenter au moment où elles sont utiles. Les modifications seront testées sur de nouveaux exemples avant d'être généralisées. Un formulaire plus court ne sera pas automatiquement meilleur si les étapes supprimées empêchent encore de comprendre ce qui est demandé.","question":"Comment les erreurs sont-elles utilisées ?","options":["Pour améliorer la conception du service","Pour supprimer automatiquement les dossiers","Pour éviter toute correction","Pour classer publiquement les usagers"],"correct":"A","explanation":"Le passage indique : « Une administration simplifie ses formulaires numériques avec les usagers. Les erreurs fréquentes servent à identifier des consignes peu claires, et pas seulement à constater l'inattention des personnes. » Cela justifie la réponse : Pour améliorer la conception du service."},{"number":21,"points":21,"passage":"Un logiciel permet de travailler sans connexion puis de synchroniser les documents. L'équipe vérifie les conflits de versions lorsque deux personnes ont modifié le même fichier hors ligne. Les documents gardent une trace des changements et les auteurs peuvent expliquer ce qu'ils souhaitaient modifier. Elle veut savoir comment réagir lorsque la réunion automatique des modifications produit un résultat ambigu. Les personnes ne seront pas invitées à considérer tout fichier final comme correct simplement parce qu'une synchronisation s'est terminée sans afficher de message d'erreur.","question":"Quel problème doit être géré ?","options":["L'impossibilité d'écrire sans internet","Le manque de papier","La disparition obligatoire du fichier","La réunion de modifications concurrentes"],"correct":"D","explanation":"Le passage indique : « Un logiciel permet de travailler sans connexion puis de synchroniser les documents. L'équipe vérifie les conflits de versions lorsque deux personnes ont modifié le même fichier hors ligne. » Cela justifie la réponse : La réunion de modifications concurrentes."},{"number":22,"points":21,"passage":"Une plateforme affiche les avis dans l'ordre de publication plutôt que selon leur popularité. Elle souhaite éviter que les premiers avis très appréciés occupent durablement toute la visibilité. Les lecteurs pourront toujours rechercher un ancien avis ou examiner les réponses reçues. Le changement ne garantit pas que toutes les contributions seront lues autant, mais modifie ce qui apparaît en premier. La plateforme souhaite expliquer cette règle pour que le classement ne soit pas interprété comme une mesure neutre de qualité.","question":"Quel effet cherche-t-elle à limiter ?","options":["Le classement chronologique des dates","La concentration de l'attention sur quelques avis","L'apparition de nouveaux commentaires","La possibilité de lire les avis récents"],"correct":"B","explanation":"Le passage indique : « Une plateforme affiche les avis dans l'ordre de publication plutôt que selon leur popularité. Elle souhaite éviter que les premiers avis très appréciés occupent durablement toute la visibilité. » Cela justifie la réponse : La concentration de l'attention sur quelques avis."},{"number":23,"points":21,"passage":"Un service propose de supprimer un compte tout en permettant de récupérer ses documents auparavant. Cette étape évite de confondre départ du service et perte souhaitée de tous les fichiers. La procédure indique les formats disponibles et demande de vérifier les copies avant la fermeture définitive. Les utilisateurs disposent d'un délai pour poser une question. Le service souhaite que le départ reste compréhensible, sans confondre fidélisation et difficulté à récupérer son travail.","question":"Quelle possibilité est offerte ?","options":["Conserver ses documents avant de partir","Transférer les fichiers sans accord à la publicité","Interdire la suppression du compte","Rester abonné sans le savoir"],"correct":"A","explanation":"Le passage indique : « Un service propose de supprimer un compte tout en permettant de récupérer ses documents auparavant. Cette étape évite de confondre départ du service et perte souhaitée de tous les fichiers. » Cela justifie la réponse : Conserver ses documents avant de partir."},{"number":24,"points":21,"passage":"Une entreprise réduit le nombre de réunions vidéo, mais conserve des échanges audio et des notes partagées. Le but est d'adapter le support au besoin, pas d'interdire la communication à distance. Les équipes précisent ce qui demande un échange immédiat et ce qui peut être lu plus tard. Elles souhaitent éviter qu'un changement d'outil augmente simplement le nombre de messages ou d'interruptions. Le bilan regardera donc l'organisation complète du travail.","question":"Quel principe guide le changement ?","options":["Remplacer tous les échanges par le silence","Choisir le moyen de communication selon l'usage","Éviter toute trace écrite","Imposer une caméra permanente"],"correct":"B","explanation":"Le passage indique : « Une entreprise réduit le nombre de réunions vidéo, mais conserve des échanges audio et des notes partagées. Le but est d'adapter le support au besoin, pas d'interdire la communication à distance. » Cela justifie la réponse : Choisir le moyen de communication selon l'usage."},{"number":25,"points":21,"passage":"Des formateurs utilisent des exercices sans compte personnel pour les premières séances. Les apprenants peuvent découvrir les fonctions avant de transmettre des informations les concernant. Les personnes peuvent décider à partir d'une expérience concrète, plutôt que remplir immédiatement une longue série de champs. Le centre veut que la découverte d'un outil ne soit pas conditionnée à une transmission de données dont l'utilité reste encore difficile à comprendre pour un débutant.","question":"Quel avantage présente ce choix ?","options":["Découvrir avant de s'engager dans une inscription","Éviter d'expliquer les fonctions","Supprimer toute possibilité d'apprentissage","Garantir une absence totale de données sur internet"],"correct":"A","explanation":"Le passage indique : « Des formateurs utilisent des exercices sans compte personnel pour les premières séances. Les apprenants peuvent découvrir les fonctions avant de transmettre des informations les concernant. » Cela justifie la réponse : Découvrir avant de s'engager dans une inscription."},{"number":26,"points":21,"passage":"Une application propose une recommandation automatique de trajet. Elle affiche aussi les critères retenus pour que l'utilisateur comprenne pourquoi un parcours est privilégié. L'utilisateur peut alors décider si le gain de temps annoncé correspond à sa situation. Il peut choisir un trajet différent lorsqu'un critère non retenu lui paraît plus important. Des retours permettront d'améliorer les informations et d'identifier les contraintes fréquentes que le service n'avait pas encore correctement prises en compte dans ses premières propositions.","question":"Quel apport fournit cette explication ?","options":["Une suppression des choix possibles","Un changement automatique de destination","Une meilleure compréhension de la recommandation","Une garantie que le trajet convient à tous"],"correct":"C","explanation":"Le passage indique : « Une application propose une recommandation automatique de trajet. Elle affiche aussi les critères retenus pour que l'utilisateur comprenne pourquoi un parcours est privilégié. » Cela justifie la réponse : Une meilleure compréhension de la recommandation."},{"number":27,"points":21,"passage":"Une médiathèque accueille des adolescents pour discuter de leurs pratiques en ligne. Les animateurs partent de situations concrètes plutôt que d'un discours présentant tous les usages comme dangereux. Les participants parlent de leurs habitudes, mais aussi des moments où ils ont besoin d'aide ou de recul. Les questions seront reprises lors d'une séance suivante avec les familles intéressées, dans un cadre respectant les choix de chacun.","question":"Quelle approche est privilégiée ?","options":["Remplacer les discussions par des sanctions","Condamner tous les usages sans échange","Ignorer les expériences des jeunes","Examiner les pratiques avec les utilisateurs"],"correct":"D","explanation":"Le passage indique : « Une médiathèque accueille des adolescents pour discuter de leurs pratiques en ligne. Les animateurs partent de situations concrètes plutôt que d'un discours présentant tous les usages comme dangereux. » Cela justifie la réponse : Examiner les pratiques avec les utilisateurs."},{"number":28,"points":21,"passage":"Un site simplifie ses menus après des tests avec des lecteurs d'écran. Les améliorations facilitent aussi la navigation de nombreux autres visiteurs. Les menus deviennent plus prévisibles et les formulaires plus explicites. Certains visiteurs sans outil particulier disent aussi trouver plus rapidement la bonne page. Elle observe leurs effets sur des parcours variés, tout en continuant à vérifier les besoins spécifiques qui ne seraient pas résolus par une modification générale de la présentation.","question":"Que montre cet effet ?","options":["L'accessibilité impose de supprimer les contenus","Les lecteurs d'écran gênent nécessairement les autres","Un travail d'accessibilité peut bénéficier largement","Tous les visiteurs utilisent le même outil"],"correct":"C","explanation":"Le passage indique : « Un site simplifie ses menus après des tests avec des lecteurs d'écran. Les améliorations facilitent aussi la navigation de nombreux autres visiteurs. » Cela justifie la réponse : Un travail d'accessibilité peut bénéficier largement."},{"number":29,"points":21,"passage":"Une association organise des ateliers en petits groupes. Les questions techniques y sont liées à une tâche réelle, comme retrouver un justificatif, afin d'éviter des manipulations sans objectif compréhensible. Les participants peuvent expliquer les étapes qu'ils comprennent et celles où ils ont besoin d'un soutien. Les formateurs évitent de multiplier les fonctions avant que la première démarche soit maîtrisée.","question":"Pourquoi partir d'une tâche réelle ?","options":["Éviter toute autonomie","Remplacer les démarches par des jeux uniquement","Rendre les outils plus coûteux","Donner du sens aux apprentissages"],"correct":"D","explanation":"Le passage indique : « Une association organise des ateliers en petits groupes. Les questions techniques y sont liées à une tâche réelle, comme retrouver un justificatif, afin d'éviter des manipulations sans objectif compréhensible. » Cela justifie la réponse : Donner du sens aux apprentissages."},{"number":30,"points":26,"passage":"Les réglages par défaut influencent les pratiques, car de nombreux utilisateurs ne les modifient pas. Un service choisit donc un partage limité au départ. La possibilité d'élargir ensuite l'accès demeure, mais elle résulte d'une décision explicite. Les explications montrent comment élargir l'accès si une personne le souhaite. Le service veut que cette décision soit compréhensible et réversible, plutôt qu'un changement que l'utilisateur découvrirait après la diffusion de ses informations à un public inattendu.","question":"Quelle responsabilité le service reconnaît-il ?","options":["L'absence de toute influence des paramètres","L'effet des choix initiaux sur la confidentialité","L'obligation de tout rendre public","L'impossibilité de modifier un réglage"],"correct":"B","explanation":"Le passage indique : « Les réglages par défaut influencent les pratiques, car de nombreux utilisateurs ne les modifient pas. Un service choisit donc un partage limité au départ. La possibilité d'élargir ensuite l'accès demeure, mais elle résulte d'une décision explicite. » Cela justifie la réponse : L'effet des choix initiaux sur la confidentialité."},{"number":31,"points":26,"passage":"Une interface peut afficher beaucoup de fonctions et paraître complète. Si les actions courantes sont difficiles à trouver, cette richesse devient un obstacle. Les concepteurs retirent des éléments de l'écran principal sans supprimer les fonctions avancées accessibles ailleurs. Ils souhaitent réduire le temps de recherche, sans décider que les fonctions moins fréquentes ne servent plus à personne ou doivent disparaître du service.","question":"Quelle amélioration est recherchée ?","options":["Multiplier les étapes ordinaires","Réduire toute possibilité d'action","Rendre les usages fréquents plus lisibles","Masquer définitivement les fonctions utiles"],"correct":"C","explanation":"Le passage indique : « Une interface peut afficher beaucoup de fonctions et paraître complète. Si les actions courantes sont difficiles à trouver, cette richesse devient un obstacle. Les concepteurs retirent des éléments de l'écran principal sans supprimer les fonctions avancées accessibles ailleurs. » Cela justifie la réponse : Rendre les usages fréquents plus lisibles."},{"number":32,"points":26,"passage":"Une organisation numérise ses archives. Elle doit aussi conserver des descriptions, des formats lisibles et des copies fiables. Transformer un document en fichier ne suffit pas à garantir qu'il pourra être retrouvé et compris dix ans plus tard. Les archivistes contrôlent donc régulièrement les supports et les informations associées. Ils prévoient aussi les changements de format, afin qu'un fichier conservé matériellement ne devienne pas un document impossible à lire ou à interpréter plus tard.","question":"Quelle condition de durée est soulignée ?","options":["Organiser la conservation et l'interprétation des fichiers","Stocker sans classement une seule copie","Choisir uniquement le format le plus récent","Supprimer toute description des documents"],"correct":"A","explanation":"Le passage indique : « Une organisation numérise ses archives. Elle doit aussi conserver des descriptions, des formats lisibles et des copies fiables. Transformer un document en fichier ne suffit pas à garantir qu'il pourra être retrouvé et compris dix ans plus tard. » Cela justifie la réponse : Organiser la conservation et l'interprétation des fichiers."},{"number":33,"points":26,"passage":"Un outil automatisé classe les demandes selon les exemples utilisés pour le préparer. Si ces exemples représentent mal certaines situations, l'efficacité moyenne peut masquer des erreurs répétées pour un groupe. Une évaluation doit donc regarder la répartition des erreurs, pas seulement leur total. Ils pourront alors préparer des tests complémentaires, plutôt que publier seulement un taux global encourageant qui laisserait certains problèmes durablement invisibles.","question":"Quel examen complémentaire est nécessaire ?","options":["Compter uniquement les réponses rapides","Identifier quels cas subissent les erreurs","Supprimer tous les exemples","Considérer la moyenne comme exhaustive"],"correct":"B","explanation":"Le passage indique : « Un outil automatisé classe les demandes selon les exemples utilisés pour le préparer. Si ces exemples représentent mal certaines situations, l'efficacité moyenne peut masquer des erreurs répétées pour un groupe. Une évaluation doit donc regarder la répartition des erreurs, pas seulement leur total. » Cela justifie la réponse : Identifier quels cas subissent les erreurs."},{"number":34,"points":26,"passage":"Le travail à distance permet une présence géographique plus souple, mais peut rendre les limites horaires moins visibles. Une équipe définit des temps sans attente de réponse. La souplesse ne signifie pas une disponibilité permanente ; elle demande aussi des règles partagées de déconnexion. Les salariés peuvent ainsi organiser leur journée sans devoir interpréter chaque silence comme un refus de travailler ou chaque message tardif comme une demande immédiate.","question":"Quel équilibre est recherché ?","options":["Absence de tout accord collectif","Connexion continue de tous les salariés","Suppression des échanges écrits","Souplesse de travail et limites de disponibilité"],"correct":"D","explanation":"Le passage indique : « Le travail à distance permet une présence géographique plus souple, mais peut rendre les limites horaires moins visibles. Une équipe définit des temps sans attente de réponse. La souplesse ne signifie pas une disponibilité permanente ; elle demande aussi des règles partagées de déconnexion. » Cela justifie la réponse : Souplesse de travail et limites de disponibilité."},{"number":35,"points":26,"passage":"Une formation numérique promet l'autonomie après quelques séances. Les outils changent pourtant rapidement. Les formateurs privilégient donc des repères pour chercher de l'aide, comprendre une consigne et vérifier une information, plutôt qu'une liste de gestes liée à un seul écran. Les personnes pourront réutiliser ces repères lorsqu'une fonction change de place. Le centre veut transmettre une manière de chercher et de vérifier, sans promettre qu'un seul cours rendrait toutes les interfaces futures immédiatement familières et faciles.","question":"Quelle compétence durable cherchent-ils à développer ?","options":["Une dépendance permanente au formateur","La capacité de s'orienter face à un changement","La mémorisation immuable d'une interface","Le refus de tout nouvel outil"],"correct":"B","explanation":"Le passage indique : « Une formation numérique promet l'autonomie après quelques séances. Les outils changent pourtant rapidement. Les formateurs privilégient donc des repères pour chercher de l'aide, comprendre une consigne et vérifier une information, plutôt qu'une liste de gestes liée à un seul écran. » Cela justifie la réponse : La capacité de s'orienter face à un changement."},{"number":36,"points":33,"passage":"Une plateforme présente ses recommandations comme neutres parce qu'elles sont calculées. Pourtant, elle doit choisir ce qu'elle optimise : durée de consultation, diversité ou satisfaction déclarée. Ces objectifs peuvent conduire à des sélections différentes. Un calcul n'efface pas les choix inscrits dans les critères qui le guident. Une recommandation peut être très efficace pour garder un utilisateur longtemps sur un site, sans lui faire découvrir des sources différentes. Une autre peut lui proposer plus de variété, mais demander davantage d'effort au début. Le service doit donc expliquer ses priorités et observer leurs conséquences. Les responsables souhaitent que le public puisse discuter ces choix, plutôt que considérer la formule comme une simple description du monde. La technique apporte des moyens de calcul, mais elle ne décide pas seule de la valeur que l'on attribue à chacun des résultats recherchés.","question":"Quelle idée est contestée ?","options":["La sélection dépend de ce qu'on souhaite favoriser","Un système doit utiliser des critères","L'automaticité garantirait une neutralité sans choix","Des objectifs différents peuvent produire des résultats différents"],"correct":"C","explanation":"Le passage indique : « Un calcul n'efface pas les choix inscrits dans les critères qui le guident. » Cela justifie la réponse : L'automaticité garantirait une neutralité sans choix."},{"number":37,"points":33,"passage":"Une administration remplace un guichet par une démarche en ligne. Le nombre de dossiers déposés augmente, mais les personnes en difficulté se déplacent désormais vers les associations pour obtenir de l'aide. Une simplification pour le service peut déplacer le travail d'accompagnement vers d'autres acteurs plutôt que le faire disparaître. Les bénévoles expliquent qu'ils doivent apprendre les nouvelles interfaces et accompagner des cas parfois complexes. Cette activité ne figure pas toujours dans les économies annoncées par le service public. Les responsables vont rencontrer les associations pour préciser les difficultés et garder une possibilité d'accueil direct. Ils souhaitent mesurer les démarches menées jusqu'au bout, pas seulement les formulaires commencés. Le bilan devra donc inclure les personnes qui n'ont pas réussi seules et les ressources nécessaires pour les aider, afin de comprendre si le nouveau fonctionnement simplifie réellement l'accès pour l'ensemble du public.","question":"Quel effet doit être pris en compte ?","options":["L'autonomie immédiate de tous les usagers","La disparition totale des besoins d'accompagnement","La réduction automatique des déplacements pour chacun","Le transfert de certaines tâches d'aide"],"correct":"D","explanation":"Le passage indique : « Une simplification pour le service peut déplacer le travail d'accompagnement vers d'autres acteurs plutôt que le faire disparaître. » Cela justifie la réponse : Le transfert de certaines tâches d'aide."},{"number":38,"points":33,"passage":"Un service demande le consentement avant d'utiliser des données, puis présente un formulaire très long dont le refus est difficile à trouver. Le choix existe juridiquement à l'écran, mais l'organisation de la page peut orienter fortement la décision. La présence d'une option ne suffit pas à garantir qu'elle soit aussi facile à comprendre et à exercer que les autres. Les utilisateurs peuvent accepter rapidement pour terminer une tâche urgente, même s'ils auraient préféré limiter l'utilisation de leurs informations. Une association propose donc des choix présentés avec la même lisibilité et un résumé des effets principaux. Les responsables souhaitent conserver les explications détaillées pour ceux qui en ont besoin, sans rendre le refus plus compliqué que l'accord. Les essais seront menés avec des personnes découvrant le service.","question":"Quelle limite du consentement est soulignée ?","options":["Toute option affichée est également accessible","Un formulaire long garantit une meilleure compréhension","Les conditions de présentation influencent le choix réel","Refuser est toujours impossible techniquement"],"correct":"C","explanation":"Le passage indique : « La présence d'une option ne suffit pas à garantir qu'elle soit aussi facile à comprendre et à exercer que les autres. » Cela justifie la réponse : Les conditions de présentation influencent le choix réel."},{"number":39,"points":33,"passage":"Un logiciel rend une tâche plus rapide. Les professionnels conservent néanmoins un moyen de travailler en cas de panne et des connaissances pour contrôler les résultats. Ils ne rejettent pas l'automatisation ; ils évitent qu'une commodité se transforme en dépendance sans recours. La maîtrise d'un outil comprend aussi la possibilité de vérifier et de s'en passer temporairement. Des exercices permettent de repérer un résultat inhabituel et de reprendre une tâche avec un autre moyen. Les nouveaux collègues reçoivent ces repères lors de leur arrivée, pour éviter qu'ils disparaissent avec les personnes les plus expérimentées. L'organisation souhaite profiter du gain de temps sans perdre la compréhension de ce qui est réalisé. Le bilan portera donc sur la vitesse, mais aussi sur la capacité à expliquer les décisions et à continuer lors d'un incident.","question":"Quelle forme d'autonomie est défendue ?","options":["Garder des capacités de contrôle et de solution de repli","Supprimer les connaissances humaines après installation","Refuser toute amélioration technique","Déléguer toute vérification au logiciel"],"correct":"A","explanation":"Le passage indique : « La maîtrise d'un outil comprend aussi la possibilité de vérifier et de s'en passer temporairement. » Cela justifie la réponse : Garder des capacités de contrôle et de solution de repli."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-14','tcf-reading-2026-11-reference-v3',$paper${"id":"tcf-reading-14","version":"tcf-reading-2026-11-reference-v3","title":"TCF Reading · Test 14","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"Le journal du quartier recevra vos annonces jusqu'au vendredi midi. Les textes arrivés ensuite paraîtront le mois suivant.\n\nUn message confirmera la réception des annonces retenues. Merci d'indiquer une date et un contact pour permettre aux lecteurs de demander des renseignements.","question":"Quand une annonce tardive sera-t-elle publiée ?","options":["Vendredi soir obligatoirement","Le mois suivant","Jamais","Avant son envoi"],"correct":"B","explanation":"Le passage indique : « Le journal du quartier recevra vos annonces jusqu'au vendredi midi. Les textes arrivés ensuite paraîtront le mois suivant. » Cela justifie la réponse : Le mois suivant."},{"number":2,"points":3,"passage":"La conférence de rédaction est ouverte aux lecteurs mercredi. Merci de réserver une place ; la salle est petite.\n\nLes personnes inscrites recevront les horaires et le lieu d'accueil.","question":"Pourquoi faut-il réserver ?","options":["L'accès est réservé aux journalistes","Les lecteurs doivent apporter un article","La réunion est payante","La capacité est limitée"],"correct":"D","explanation":"Le passage indique : « La conférence de rédaction est ouverte aux lecteurs mercredi. Merci de réserver une place ; la salle est petite. » Cela justifie la réponse : La capacité est limitée."},{"number":3,"points":3,"passage":"Les photos de l'exposition peuvent être utilisées pour un travail scolaire en citant leur auteur. L'usage commercial nécessite un accord séparé.\n\nLes conditions sont indiquées sur le site avec les noms des photographes.","question":"Quel usage est autorisé sous condition de citation ?","options":["Une attribution à un autre photographe","Toute publicité commerciale","Une vente sans accord","Un travail scolaire"],"correct":"D","explanation":"Le passage indique : « Les photos de l'exposition peuvent être utilisées pour un travail scolaire en citant leur auteur. L'usage commercial nécessite un accord séparé. » Cela justifie la réponse : Un travail scolaire."},{"number":4,"points":3,"passage":"Le bulletin ne sera pas distribué dans les boîtes aux lettres cette semaine. Il reste disponible à la mairie.\n\nLa rédaction publiera aussi une version numérique pour les lecteurs qui ne peuvent pas se déplacer.","question":"Où peut-on le consulter ?","options":["À la mairie","Au guichet de la piscine seulement","Dans chaque train","Uniquement dans les boîtes aux lettres"],"correct":"A","explanation":"Le passage indique : « Le bulletin ne sera pas distribué dans les boîtes aux lettres cette semaine. Il reste disponible à la mairie. » Cela justifie la réponse : À la mairie."},{"number":5,"points":9,"passage":"Je t'ai transmis un article ancien par erreur. Vérifie la date avant de partager l'annonce de fermeture du pont.\n\nLe nouveau texte de la mairie indique que la circulation a déjà repris. Je préfère te prévenir avant que tu organises un autre trajet à partir de mon premier envoi.","question":"Quelle vérification est demandée ?","options":["La taille du fichier uniquement","Le nombre de photos du pont","La date de l'information","Le nom de tous les lecteurs"],"correct":"C","explanation":"Le passage indique : « Je t'ai transmis un article ancien par erreur. Vérifie la date avant de partager l'annonce de fermeture du pont. » Cela justifie la réponse : La date de l'information."},{"number":6,"points":9,"passage":"Notre podcast accueille des témoignages courts. Nous vous rappellerons avant diffusion pour confirmer les passages retenus.\n\nLes enregistrements seront montés pour rendre les échanges plus faciles à suivre. Vous pourrez poser vos questions sur ce fonctionnement avant de confirmer votre participation au programme.","question":"Quelle étape est prévue ?","options":["Une publication automatique intégrale","Un vote sur son identité","Une diffusion sans contact préalable","Une confirmation avec le témoin"],"correct":"D","explanation":"Le passage indique : « Notre podcast accueille des témoignages courts. Nous vous rappellerons avant diffusion pour confirmer les passages retenus. » Cela justifie la réponse : Une confirmation avec le témoin."},{"number":7,"points":9,"passage":"J'aimerais interviewer un artisan, pas réaliser une publicité. Je lui demanderai aussi quelles difficultés il rencontre.\n\nJe préparerai des questions sur ses choix, ses outils et l'organisation de ses journées. Le lecteur doit pouvoir comprendre son activité, pas seulement connaître les produits qu'il souhaite vendre.","question":"Quel type de contenu est recherché ?","options":["Une annonce uniquement promotionnelle","Un portrait comportant des questions critiques","Un catalogue de prix sans entretien","Un texte rédigé par tous les clients"],"correct":"B","explanation":"Le passage indique : « J'aimerais interviewer un artisan, pas réaliser une publicité. Je lui demanderai aussi quelles difficultés il rencontre. » Cela justifie la réponse : Un portrait comportant des questions critiques."},{"number":8,"points":9,"passage":"Le groupe de discussion réserve les messages urgents aux informations de service. Les débats généraux se tiennent dans un autre espace.\n\nLes membres pourront continuer à discuter sans rendre difficile la recherche d'une annonce importante au milieu des réactions.","question":"Pourquoi séparer les espaces ?","options":["Supprimer les annonces de service","Rendre les informations urgentes plus visibles","Augmenter le nombre d'alertes sans distinction","Interdire toute discussion"],"correct":"B","explanation":"Le passage indique : « Le groupe de discussion réserve les messages urgents aux informations de service. Les débats généraux se tiennent dans un autre espace. » Cela justifie la réponse : Rendre les informations urgentes plus visibles."},{"number":9,"points":9,"passage":"Merci de corriger le nom de mon association dans l'article. Les propos cités sont exacts ; seule cette mention pose problème.\n\nUne note courte permettra aux lecteurs de retrouver le bon organisme sans modifier le sens de l'entretien.","question":"Quelle correction est demandée ?","options":["Le nom de l'association","Le sujet complet de l'article","Toutes les citations","La date de l'entretien"],"correct":"A","explanation":"Le passage indique : « Merci de corriger le nom de mon association dans l'article. Les propos cités sont exacts ; seule cette mention pose problème. » Cela justifie la réponse : Le nom de l'association."},{"number":10,"points":9,"passage":"Nous préparons une émission sur les souvenirs du quartier. Les participants peuvent raconter une expérience personnelle sans prétendre parler pour tous les habitants.\n\nLes personnes pourront aussi préférer un texte ou une photographie à un enregistrement de leur voix pendant la rencontre.","question":"Quelle limite est reconnue ?","options":["Seuls les élus peuvent témoigner","Un témoignage représente d'abord une expérience individuelle","Chaque récit décrit nécessairement toute la population","Les souvenirs doivent tous être identiques"],"correct":"B","explanation":"Le passage indique : « Nous préparons une émission sur les souvenirs du quartier. Les participants peuvent raconter une expérience personnelle sans prétendre parler pour tous les habitants. » Cela justifie la réponse : Un témoignage représente d'abord une expérience individuelle."},{"number":11,"points":15,"passage":"Un journaliste publie le document à l'origine de son enquête. Les lecteurs peuvent ainsi distinguer la source et l'analyse qu'il en propose.\n\nLe document est accompagné de sa date et d'une indication sur la manière dont il a été obtenu. Les journalistes expliquent les passages qui leur paraissent importants et les limites de ce qu'ils peuvent en déduire. Les lecteurs peuvent ainsi examiner le raisonnement sans devoir accepter une conclusion sur la seule réputation du média. La rédaction souhaite rendre le travail plus lisible, pas prétendre qu'une source brute supprimerait tout besoin d'analyse ou donnerait automatiquement une interprétation identique à toutes les personnes qui la consultent.","question":"Quel intérêt présente cette publication ?","options":["Éviter toute lecture critique","Prouver que toute analyse est impossible","Permettre de vérifier le point de départ","Remplacer l'enquête par un titre"],"correct":"C","explanation":"Le passage indique : « Un journaliste publie le document à l'origine de son enquête. Les lecteurs peuvent ainsi distinguer la source et l'analyse qu'il en propose. » Cela justifie la réponse : Permettre de vérifier le point de départ."},{"number":12,"points":15,"passage":"Une photographie montre une rue vide à l'aube. Utilisée pour illustrer l'activité de toute la journée, elle peut donner une impression trompeuse.\n\nLa légende devrait préciser les conditions et éviter de présenter ce moment comme représentatif de toutes les heures. Des observations complémentaires pourraient montrer les variations de fréquentation. Les élèves de l'atelier comparent plusieurs usages de la même image et discutent des impressions produites.","question":"Quelle information manque pour l'interpréter ?","options":["Le nom du fabricant du papier","Le moment de la prise de vue","Le prix de l'appareil","La largeur du cadre"],"correct":"B","explanation":"Le passage indique : « Une photographie montre une rue vide à l'aube. Utilisée pour illustrer l'activité de toute la journée, elle peut donner une impression trompeuse. » Cela justifie la réponse : Le moment de la prise de vue."},{"number":13,"points":15,"passage":"Une radio locale rediffuse une émission en signalant clairement sa date initiale. Les informations pratiques anciennes ne doivent pas être prises pour des annonces actuelles.\n\nLe présentateur rappelle également le contexte avant les passages consacrés aux services du quotidien. Certaines questions restent intéressantes longtemps, mais des horaires ou des procédures peuvent avoir changé depuis l'entretien. Elle souhaite conserver la valeur des archives sans encourager des démarches à partir d'une information devenue ancienne. Les auditeurs pourront retrouver la version d'origine, avec les précisions permettant de la distinguer d'une annonce nouvelle destinée au public de cette semaine.","question":"Pourquoi afficher cette date ?","options":["Éviter une confusion temporelle","Augmenter le volume sonore","Interdire la rediffusion","Cacher l'origine du programme"],"correct":"A","explanation":"Le passage indique : « Une radio locale rediffuse une émission en signalant clairement sa date initiale. Les informations pratiques anciennes ne doivent pas être prises pour des annonces actuelles. » Cela justifie la réponse : Éviter une confusion temporelle."},{"number":14,"points":15,"passage":"Un atelier compare deux titres portant sur le même rapport. Les participants repèrent les aspects sélectionnés et ceux qui ne sont pas mentionnés.\n\nLes groupes lisent ensuite les extraits correspondants pour voir ce que chaque titre permet réellement d'affirmer. Un titre peut être exact tout en donnant la priorité à un aspect particulier. Les animateurs souhaitent que les lecteurs apprennent à reconnaître ce travail de sélection, sans conclure que toutes les formulations sont nécessairement trompeuses. Les participants proposeront une autre version et expliqueront leur choix.","question":"Quelle compétence est travaillée ?","options":["Désigner un titre sans lire","Éviter toute comparaison","Mémoriser tous les titres","Identifier un choix de présentation"],"correct":"D","explanation":"Le passage indique : « Un atelier compare deux titres portant sur le même rapport. Les participants repèrent les aspects sélectionnés et ceux qui ne sont pas mentionnés. » Cela justifie la réponse : Identifier un choix de présentation."},{"number":15,"points":15,"passage":"Une rédaction distingue les tribunes d'opinion des enquêtes d'information. Les rubriques ne demandent pas au lecteur la même manière d'évaluer les arguments.\n\nLes tribunes peuvent défendre une position et doivent être lues comme des arguments signés. La rédaction précise cependant que la séparation des rubriques ne dispense pas de vérifier une affirmation lorsqu'elle apparaît dans un texte d'opinion. Le journal souhaite rendre sa présentation plus claire, sans créer une catégorie dans laquelle les auteurs pourraient affirmer n'importe quoi en se contentant de rappeler que le texte exprime leur point de vue personnel.","question":"Quelle distinction est rendue visible ?","options":["La taille des bureaux","Le poids du papier","La nature des textes publiés","La profession de tous les abonnés"],"correct":"C","explanation":"Le passage indique : « Une rédaction distingue les tribunes d'opinion des enquêtes d'information. Les rubriques ne demandent pas au lecteur la même manière d'évaluer les arguments. » Cela justifie la réponse : La nature des textes publiés."},{"number":16,"points":15,"passage":"Le journal rectifie un chiffre et explique l'erreur dans une note. Il conserve une trace de la correction au lieu de modifier silencieusement l'article.\n\nLa note indique ce qui a changé et pourquoi l'équipe a retenu la nouvelle valeur. Les lecteurs peuvent ainsi comprendre si la correction modifie ou non la conclusion générale. La rédaction ne souhaite pas garder une donnée fausse simplement pour ne pas attirer l'attention sur l'incident. Elle veut aussi éviter qu'une modification invisible empêche de suivre le parcours d'une information déjà citée ailleurs.","question":"Quel principe applique-t-il ?","options":["La transparence sur les rectifications","L'effacement de toute responsabilité","La suppression de toutes les archives","L'interdiction de signaler une erreur"],"correct":"A","explanation":"Le passage indique : « Le journal rectifie un chiffre et explique l'erreur dans une note. Il conserve une trace de la correction au lieu de modifier silencieusement l'article. » Cela justifie la réponse : La transparence sur les rectifications."},{"number":17,"points":15,"passage":"Un communiqué annonce un projet municipal. Avant de le reprendre, une journaliste interroge aussi les personnes concernées par ses effets.\n\nLa journaliste recueille les réactions des riverains et consulte des documents sur des réalisations comparables. Elle veut distinguer les intentions et les effets encore à vérifier. Les responsables du projet pourront répondre aux questions, mais leur présentation ne sera pas traitée comme un bilan déjà établi. Le journal souhaite que les lecteurs comprennent ce qui est annoncé et ce qui reste incertain.","question":"Quelle démarche complète le communiqué ?","options":["Le refus de consulter les habitants","Le remplacement du projet par une rumeur","Le recueil de points de vue indépendants de l'annonce","La copie exacte de la publicité"],"correct":"C","explanation":"Le passage indique : « Un communiqué annonce un projet municipal. Avant de le reprendre, une journaliste interroge aussi les personnes concernées par ses effets. » Cela justifie la réponse : Le recueil de points de vue indépendants de l'annonce."},{"number":18,"points":15,"passage":"Un média publie des statistiques accompagnées du nombre de répondants. Un résultat fondé sur un petit groupe demande davantage de prudence dans sa généralisation.\n\nLe média précise aussi comment les personnes ont été choisies et dans quelles conditions elles ont répondu. Les journalistes souhaitent éviter qu'un pourcentage donne une impression de précision supérieure à celle des données. Le chiffre peut rester utile pour décrire les répondants, sans représenter automatiquement une population plus vaste. Les lecteurs pourront consulter les limites annoncées et comparer avec d'autres travaux.","question":"Quelle information aide à juger la portée du résultat ?","options":["La longueur du titre","Le prix de l'abonnement","La couleur du graphique","La taille du groupe interrogé"],"correct":"D","explanation":"Le passage indique : « Un média publie des statistiques accompagnées du nombre de répondants. Un résultat fondé sur un petit groupe demande davantage de prudence dans sa généralisation. » Cela justifie la réponse : La taille du groupe interrogé."},{"number":19,"points":15,"passage":"Une émission invite une experte sur son domaine de recherche. Le présentateur distingue ses connaissances professionnelles de ses préférences personnelles.\n\nL'invitée peut indiquer les résultats qu'elle connaît et préciser les questions qui dépassent son travail. Le présentateur souhaite éviter de transformer une qualité professionnelle réelle en autorité générale sur tous les sujets. Les auditeurs recevront des références pour approfondir les éléments scientifiques abordés. Les préférences exprimées seront présentées comme telles, afin que chacun puisse apprécier leur statut.","question":"Pourquoi cette distinction importe-t-elle ?","options":["Une experte ne peut avoir aucune préférence","Le métier suffit à valider toute opinion","Toutes ses opinions n'ont pas le même fondement d'expertise","Les connaissances interdisent les questions"],"correct":"C","explanation":"Le passage indique : « Une émission invite une experte sur son domaine de recherche. Le présentateur distingue ses connaissances professionnelles de ses préférences personnelles. » Cela justifie la réponse : Toutes ses opinions n'ont pas le même fondement d'expertise."},{"number":20,"points":21,"passage":"Un journal souhaite élargir son lectorat. Il réduit les termes techniques, mais conserve les sources et les explications nécessaires. Simplifier la langue ne signifie pas supprimer ce qui permet de comprendre le raisonnement. Des lecteurs ont participé à la relecture des premiers essais. Ils ont signalé les mots qui gênaient la compréhension et les endroits où une explication manquait. Les journalistes ont ensuite réorganisé certains passages sans retirer les éléments qui permettent de contrôler les affirmations. Le journal souhaite une lecture plus fluide, pas une conclusion qu'il faudrait accepter sans comprendre comment elle a été construite.","question":"Quel équilibre cherche-t-il ?","options":["Réserver l'article aux spécialistes","Remplacer toutes les preuves par des slogans","Supprimer les informations importantes","Rendre le texte accessible sans effacer ses fondements"],"correct":"D","explanation":"Le passage indique : « Un journal souhaite élargir son lectorat. Il réduit les termes techniques, mais conserve les sources et les explications nécessaires. Simplifier la langue ne signifie pas supprimer ce qui permet de comprendre le raisonnement. » Cela justifie la réponse : Rendre le texte accessible sans effacer ses fondements."},{"number":21,"points":21,"passage":"Des habitants lancent une lettre locale parce que certaines initiatives ne sont jamais couvertes. Ils prévoient toutefois de mentionner leurs liens avec les associations présentées. La lettre indiquera qui a proposé le sujet et si un membre de la rédaction participe à l'activité présentée. Les lecteurs pourront demander d'autres points de vue. Le groupe souhaite conserver sa connaissance du quartier, tout en rendant visibles les relations qui peuvent influencer ses choix. Il ne prétend pas remplacer cette proximité par une absence de position impossible à garantir.","question":"Pourquoi annoncer ces liens ?","options":["Éviter d'identifier les sujets","Remplacer les informations par des adhésions","Permettre au lecteur d'apprécier leur position","Garantir que toute critique sera supprimée"],"correct":"C","explanation":"Le passage indique : « Des habitants lancent une lettre locale parce que certaines initiatives ne sont jamais couvertes. Ils prévoient toutefois de mentionner leurs liens avec les associations présentées. » Cela justifie la réponse : Permettre au lecteur d'apprécier leur position."},{"number":22,"points":21,"passage":"Une rédaction organise ses reportages selon les questions du public, mais garde la décision sur les vérifications et les sources. La participation des lecteurs nourrit l'enquête sans en fixer d'avance la conclusion. Les journalistes regroupent les propositions, vérifient ce qui peut être étudié et expliquent les sujets qu'ils ne pourront pas traiter immédiatement. Certains lecteurs apportent des documents ou des observations utiles. La rédaction conserve toutefois la responsabilité de confronter ces éléments à d'autres sources.","question":"Quelle place est donnée aux lecteurs ?","options":["Supprimer les vérifications","Remplacer tous les journalistes","Décider du résultat avant l'enquête","Contribuer aux questions à examiner"],"correct":"D","explanation":"Le passage indique : « Une rédaction organise ses reportages selon les questions du public, mais garde la décision sur les vérifications et les sources. La participation des lecteurs nourrit l'enquête sans en fixer d'avance la conclusion. » Cela justifie la réponse : Contribuer aux questions à examiner."},{"number":23,"points":21,"passage":"Une vidéo très partagée montre une scène réelle, mais le commentaire affirme qu'elle se déroule dans une autre ville. La fausseté ne se trouve pas dans l'image elle-même, mais dans son attribution. Les participants apprennent donc à rechercher l'origine de la vidéo et les publications antérieures. Ils comparent les détails visibles avec les lieux annoncés. Un document réel peut être utilisé pour soutenir une affirmation fausse si le contexte ajouté ne correspond pas à ce qui a été filmé.","question":"Quel problème est identifié ?","options":["Un contexte ajouté de manière erronée","Une image entièrement inventée nécessairement","Une absence de toute scène visible","Une qualité technique trop faible uniquement"],"correct":"A","explanation":"Le passage indique : « Une vidéo très partagée montre une scène réelle, mais le commentaire affirme qu'elle se déroule dans une autre ville. La fausseté ne se trouve pas dans l'image elle-même, mais dans son attribution. » Cela justifie la réponse : Un contexte ajouté de manière erronée."},{"number":24,"points":21,"passage":"Un média refuse de citer une personne de manière anonyme sans en connaître l'identité. Il peut protéger son nom publiquement tout en vérifiant qui fournit l'information. La rédaction évalue les raisons de la protection et cherche des confirmations indépendantes. Elle explique aux lecteurs la portée de ce choix sans révéler les informations permettant d'identifier la personne. L'objectif est de rendre possible un témoignage utile, tout en gardant une exigence de fiabilité.","question":"Quelle différence est faite ?","options":["Une identité connue doit toujours être publiée","La protection d'une source interdit tout entretien","L'anonymat impose de ne rien vérifier","Anonymat public et absence de vérification ne se confondent pas"],"correct":"D","explanation":"Le passage indique : « Un média refuse de citer une personne de manière anonyme sans en connaître l'identité. Il peut protéger son nom publiquement tout en vérifiant qui fournit l'information. » Cela justifie la réponse : Anonymat public et absence de vérification ne se confondent pas."},{"number":25,"points":21,"passage":"Un atelier explique qu'un nombre de partages mesure une circulation, pas une exactitude. Une information fausse peut être très visible, et une enquête fiable peu connue. Les participants comparent la circulation de plusieurs messages et cherchent les documents sur lesquels ils s'appuient. Certains contenus attirent surtout parce qu'ils surprennent ou confirment une opinion. Le groupe souhaite distinguer ces raisons de partage du travail nécessaire pour établir un fait.","question":"Quelle déduction faut-il éviter ?","options":["Confondre popularité et fiabilité","Observer la diffusion d'un message","Comparer plusieurs documents","Rechercher une source"],"correct":"A","explanation":"Le passage indique : « Un atelier explique qu'un nombre de partages mesure une circulation, pas une exactitude. Une information fausse peut être très visible, et une enquête fiable peu connue. » Cela justifie la réponse : Confondre popularité et fiabilité."},{"number":26,"points":21,"passage":"Un reportage suit une seule famille pendant une année. Il rend son expérience précise, mais les auteurs ne prétendent pas que toutes les familles vivent la même situation. Les journalistes montrent les choix quotidiens, les hésitations et les changements observés pendant le suivi. Ils présentent aussi les circonstances de cette rencontre, afin de ne pas donner l'illusion d'une famille choisie comme résumé de toute la société. Le reportage peut ainsi rendre sensible une expérience précise.","question":"Quelle est la portée du reportage ?","options":["Garantir une moyenne statistique nationale","Supprimer toute singularité","Approfondir un cas sans le rendre universel","Mesurer toutes les familles du pays"],"correct":"C","explanation":"Le passage indique : « Un reportage suit une seule famille pendant une année. Il rend son expérience précise, mais les auteurs ne prétendent pas que toutes les familles vivent la même situation. » Cela justifie la réponse : Approfondir un cas sans le rendre universel."},{"number":27,"points":21,"passage":"Une émission débat d'un désaccord scientifique. Le producteur distingue une controverse entre spécialistes et une affirmation isolée sans preuve. Donner un temps égal à toute affirmation ne produirait pas forcément une représentation équilibrée des connaissances. Les organisateurs consultent donc des travaux de référence et demandent aux invités de préciser leurs arguments. Ils ne souhaitent pas éliminer le désaccord, mais rendre visible ce qui le soutient.","question":"Quel critère dépasse l'égalité du temps de parole ?","options":["La solidité et la place des arguments dans le savoir disponible","La longueur des biographies","Le nombre de spectateurs seulement","La couleur du studio"],"correct":"A","explanation":"Le passage indique : « Une émission débat d'un désaccord scientifique. Le producteur distingue une controverse entre spécialistes et une affirmation isolée sans preuve. Donner un temps égal à toute affirmation ne produirait pas forcément une représentation équilibrée des connaissances. » Cela justifie la réponse : La solidité et la place des arguments dans le savoir disponible."},{"number":28,"points":21,"passage":"Un journal ajoute un résumé au début de ses enquêtes longues. Les lecteurs pressés disposent d'un repère, tandis que les détails restent consultables. La rédaction veut permettre une entrée plus facile dans un sujet complexe. Elle observera aussi si les lecteurs retrouvent les explications dont ils ont besoin. Une lecture rapide reste possible, mais elle ne doit pas être présentée comme nécessairement équivalente à l'examen complet du dossier et de ses limites.","question":"Quel objectif est poursuivi ?","options":["Remplacer toutes les enquêtes par des titres","Interdire la lecture complète","Supprimer les documents annexes","Offrir plusieurs niveaux de lecture"],"correct":"D","explanation":"Le passage indique : « Un journal ajoute un résumé au début de ses enquêtes longues. Les lecteurs pressés disposent d'un repère, tandis que les détails restent consultables. » Cela justifie la réponse : Offrir plusieurs niveaux de lecture."},{"number":29,"points":21,"passage":"Une association explique ses décisions dans un bulletin. Elle mentionne aussi les propositions non retenues et leurs raisons, afin que le compte rendu ne paraisse pas présenter un accord unanime fictif. Les membres absents peuvent ainsi comprendre pourquoi une décision a été prise et quelles difficultés ont été discutées. Le bulletin distingue les points d'accord et ceux qui restent ouverts.","question":"Quelle information rend le processus plus lisible ?","options":["Le nombre de feuilles utilisées","Les choix écartés et leur justification","La météo de la réunion","Uniquement la liste des absents"],"correct":"B","explanation":"Le passage indique : « Une association explique ses décisions dans un bulletin. Elle mentionne aussi les propositions non retenues et leurs raisons, afin que le compte rendu ne paraisse pas présenter un accord unanime fictif. » Cela justifie la réponse : Les choix écartés et leur justification."},{"number":30,"points":26,"passage":"Une phrase exacte peut devenir trompeuse lorsqu'elle est séparée de la condition qui la limitait. Un atelier demande donc de retrouver le passage complet avant de discuter une citation très courte. Vérifier les mots ne suffit pas toujours à vérifier le sens attribué. Les animateurs proposent des citations dont les mots sont authentiques mais le sens incomplet. Les participants peuvent alors examiner ce qui change lorsque l'on retrouve la question posée et la suite de la réponse.","question":"Quelle précaution est recommandée ?","options":["Faire confiance au format court","Compter seulement les caractères","Lire le contexte de la citation","Remplacer les mots par une image"],"correct":"C","explanation":"Le passage indique : « Une phrase exacte peut devenir trompeuse lorsqu'elle est séparée de la condition qui la limitait. Un atelier demande donc de retrouver le passage complet avant de discuter une citation très courte. Vérifier les mots ne suffit pas toujours à vérifier le sens attribué. » Cela justifie la réponse : Lire le contexte de la citation."},{"number":31,"points":26,"passage":"La rapidité est devenue un argument des médias. Une rédaction choisit pourtant de retarder une annonce lorsqu'une vérification essentielle manque. Elle ne renonce pas à informer, mais considère que publier avant de savoir peut créer une erreur difficile à corriger ensuite. Elle souhaite conserver une information utile au public, sans transformer le délai de vérification en silence total ni l'urgence de publier en excuse pour affirmer sans preuve.","question":"Quel arbitrage est assumé ?","options":["Publier d'abord toutes les rumeurs","Privilégier une vérification nécessaire sur l'immédiateté","Supprimer toute information récente","Confondre attente et censure automatique"],"correct":"B","explanation":"Le passage indique : « La rapidité est devenue un argument des médias. Une rédaction choisit pourtant de retarder une annonce lorsqu'une vérification essentielle manque. Elle ne renonce pas à informer, mais considère que publier avant de savoir peut créer une erreur difficile à corriger ensuite. » Cela justifie la réponse : Privilégier une vérification nécessaire sur l'immédiateté."},{"number":32,"points":26,"passage":"Un graphique commence son axe vertical au-dessus de zéro. Ce choix peut rendre une variation plus visible. Il n'est pas forcément illégitime, mais doit être compris : une impression de rupture spectaculaire peut venir en partie de l'échelle choisie. Les lecteurs peuvent comparer plusieurs échelles à partir des mêmes valeurs. Le cours veut rendre ces choix compréhensibles plutôt que demander de se fier uniquement à l'impression immédiate produite par la hauteur de deux colonnes.","question":"Quelle vigilance est demandée ?","options":["Examiner la construction visuelle du graphique","Déduire une cause de la seule couleur","Ignorer les valeurs indiquées","Rejeter tous les graphiques"],"correct":"A","explanation":"Le passage indique : « Un graphique commence son axe vertical au-dessus de zéro. Ce choix peut rendre une variation plus visible. Il n'est pas forcément illégitime, mais doit être compris : une impression de rupture spectaculaire peut venir en partie de l'échelle choisie. » Cela justifie la réponse : Examiner la construction visuelle du graphique."},{"number":33,"points":26,"passage":"Un journal local entretient des relations régulières avec les acteurs qu'il couvre. Cette proximité facilite l'accès aux informations, mais peut rendre une critique délicate. L'équipe formalise ses règles pour préserver une indépendance qui ne dépend pas de l'absence totale de contacts. Le journal souhaite que la confiance se construise sur des pratiques visibles, pas seulement sur l'affirmation générale de son indépendance dans une présentation officielle.","question":"Quelle tension est décrite ?","options":["Proximité utile et indépendance éditoriale","Publicité et coût du papier uniquement","Lecture et absence de documents","Distance géographique et vitesse du courrier"],"correct":"A","explanation":"Le passage indique : « Un journal local entretient des relations régulières avec les acteurs qu'il couvre. Cette proximité facilite l'accès aux informations, mais peut rendre une critique délicate. L'équipe formalise ses règles pour préserver une indépendance qui ne dépend pas de l'absence totale de contacts. » Cela justifie la réponse : Proximité utile et indépendance éditoriale."},{"number":34,"points":26,"passage":"Une correction atteint souvent moins de lecteurs que le message initial. Des journalistes réfléchissent donc à la manière de la diffuser auprès du même public. Reconnaître l'erreur constitue une étape ; réparer son effet demande aussi de regarder sa circulation. Elle vérifiera la visibilité du correctif, plutôt que considérer le travail terminé dès qu'une note exacte a été placée dans une rubrique peu consultée.","question":"Quel enjeu dépasse la simple publication d'un correctif ?","options":["Effacer toutes les archives exactes","Modifier uniquement la date du journal","Faire parvenir la correction aux personnes exposées","Interdire les réactions des lecteurs"],"correct":"C","explanation":"Le passage indique : « Une correction atteint souvent moins de lecteurs que le message initial. Des journalistes réfléchissent donc à la manière de la diffuser auprès du même public. Reconnaître l'erreur constitue une étape ; réparer son effet demande aussi de regarder sa circulation. » Cela justifie la réponse : Faire parvenir la correction aux personnes exposées."},{"number":35,"points":26,"passage":"Une enquête associe cartes, témoignages et documents. Aucun support n'épuise le sujet : les chiffres situent une tendance, tandis qu'un récit montre ses conséquences dans une vie. Leur combinaison devient utile si le lecteur comprend ce que chaque élément permet réellement d'affirmer. Le lecteur peut ainsi comprendre comment les éléments se complètent, sans attribuer à une histoire singulière la représentativité d'une enquête ni aux nombres la précision d'un récit individuel.","question":"Quelle démarche est défendue ?","options":["Croiser des formes de preuve aux portées différentes","Considérer toutes les informations comme identiques","Remplacer les sources par une seule émotion","Transformer chaque témoignage en statistique nationale"],"correct":"A","explanation":"Le passage indique : « Une enquête associe cartes, témoignages et documents. Aucun support n'épuise le sujet : les chiffres situent une tendance, tandis qu'un récit montre ses conséquences dans une vie. Leur combinaison devient utile si le lecteur comprend ce que chaque élément permet réellement d'affirmer. » Cela justifie la réponse : Croiser des formes de preuve aux portées différentes."},{"number":36,"points":33,"passage":"Une rédaction veut représenter équitablement un débat. Elle invite les acteurs les plus visibles, puis découvre que certains habitants directement concernés ne disposent d'aucun porte-parole organisé. La visibilité publique n'est pas une mesure suffisante de l'importance d'un point de vue dans une situation. Les journalistes vont rechercher ces personnes avec des relais locaux et proposer plusieurs façons de répondre. Certaines ne souhaitent pas intervenir sur un plateau mais peuvent expliquer leur expérience dans un autre cadre. La rédaction veut éviter que son calendrier et ses habitudes de contact ne déterminent seuls les voix entendues. Les acteurs déjà présents ne seront pas écartés pour autant. Le dossier sera construit à partir des intérêts en jeu et des personnes concernées, plutôt qu'à partir d'une liste de porte-parole faciles à joindre et habitués à parler dans les médias.","question":"Que doit-elle corriger ?","options":["La vérification des déclarations","La sélection de voix fondée uniquement sur leur visibilité","La présence des habitants concernés","L'existence de tout débat"],"correct":"B","explanation":"Le passage indique : « La visibilité publique n'est pas une mesure suffisante de l'importance d'un point de vue dans une situation. » Cela justifie la réponse : La sélection de voix fondée uniquement sur leur visibilité."},{"number":37,"points":33,"passage":"Un média explique ses choix de sujets. Certains lecteurs y voient un aveu de subjectivité qui invaliderait toute information. La rédaction répond que sélectionner est inévitable, mais que les critères peuvent être discutés et les faits vérifiés. Reconnaître un point de vue de travail ne revient pas à déclarer que toutes les affirmations se valent. Elle présente les critères qui l'ont conduite à suivre un événement et les moyens utilisés pour vérifier les informations. Les lecteurs peuvent contester ces choix ou proposer des sujets absents. La rédaction souhaite conserver cette discussion sans confondre critique des priorités et rejet de toute possibilité d'établir des faits. Certaines questions restent ouvertes, d'autres peuvent recevoir des réponses mieux appuyées que de simples impressions. Les sources restent consultables.","question":"Quelle idée défend la rédaction ?","options":["Toute sélection rend la vérification inutile","Les faits changent selon le prix du journal","L'absence d'explication garantit la neutralité","Des choix éditoriaux explicites peuvent coexister avec la rigueur"],"correct":"D","explanation":"Le passage indique : « Reconnaître un point de vue de travail ne revient pas à déclarer que toutes les affirmations se valent. » Cela justifie la réponse : Des choix éditoriaux explicites peuvent coexister avec la rigueur."},{"number":38,"points":33,"passage":"Une campagne de communication cherche un message très simple. Les responsables retirent successivement les réserves jusqu'à produire une promesse plus forte que le projet réel. La clarté devient trompeuse lorsqu'elle efface précisément les conditions qui déterminent la validité de ce qu'elle annonce. L'équipe compare la formule finale aux engagements réellement possibles et réintroduit les limites importantes. Elle veut garder un message lisible, mais aussi permettre au destinataire de savoir si l'offre correspond à sa situation. Des exemples courts peuvent parfois être plus utiles qu'une promesse très large suivie d'une longue liste de réserves difficiles à trouver. Le projet sera donc présenté avec ses conditions principales au même endroit. La communication ne remplace pas la réalisation, mais elle influence les attentes à partir desquelles les personnes jugeront ensuite ce qui a effectivement été fait.","question":"Quelle limite de la simplification est soulignée ?","options":["Elle exige toujours de supprimer les réserves","Elle doit préserver les conditions essentielles de la promesse","Elle remplace la réalisation du projet","Elle interdit tout message court"],"correct":"B","explanation":"Le passage indique : « La clarté devient trompeuse lorsqu'elle efface précisément les conditions qui déterminent la validité de ce qu'elle annonce. » Cela justifie la réponse : Elle doit préserver les conditions essentielles de la promesse."},{"number":39,"points":33,"passage":"Les plateformes recommandent souvent des contenus suscitant une réaction rapide. Une enquête complexe demande au contraire du temps avant de produire une conclusion. Évaluer tous les contenus par la réaction immédiate risque de défavoriser des formes d'information dont l'intérêt apparaît au cours d'une lecture attentive. Le média expérimente des présentations qui aident à entrer dans ces sujets sans les réduire à une formule provocante. Il observe aussi les lectures achevées et les retours plus tardifs. Les responsables souhaitent éviter qu'un travail utile mais lent à produire une réaction soit systématiquement moins visible. Ils ne demandent pas d'ignorer l'intérêt du public. Ils cherchent d'autres manières de le comprendre, en tenant compte du temps nécessaire pour découvrir une question complexe. Les choix de recommandation doivent ainsi être discutés avec les effets qu'ils produisent sur les informations accessibles, pas seulement avec le nombre de clics obtenus dans les premières secondes.","question":"Quel effet du critère d'évaluation est envisagé ?","options":["Une meilleure vérification automatique des faits","Une durée de lecture identique pour tous les contenus","Une moindre visibilité de certains travaux approfondis","Une disparition de toutes les réactions rapides"],"correct":"C","explanation":"Le passage indique : « Évaluer tous les contenus par la réaction immédiate risque de défavoriser des formes d'information dont l'intérêt apparaît au cours d'une lecture attentive. » Cela justifie la réponse : Une moindre visibilité de certains travaux approfondis."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-15','tcf-reading-2026-11-reference-v3',$paper${"id":"tcf-reading-15","version":"tcf-reading-2026-11-reference-v3","title":"TCF Reading · Test 15","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"Les articles soldés peuvent être échangés pendant quinze jours avec le ticket. Cette offre ne prévoit pas de remboursement.\n\nL'article doit être rapporté dans son état d'origine. Le personnel vérifiera les conditions indiquées sur le document remis au moment de l'achat.","question":"Quelle possibilité est annoncée ?","options":["Un remboursement sans ticket","Un échange sans limite de temps","Une reprise par n'importe quel magasin","Un échange sous conditions"],"correct":"D","explanation":"Le passage indique : « Les articles soldés peuvent être échangés pendant quinze jours avec le ticket. Cette offre ne prévoit pas de remboursement. » Cela justifie la réponse : Un échange sous conditions."},{"number":2,"points":3,"passage":"Le devis reste valable trente jours. Toute modification de la demande donnera lieu à un nouveau calcul.\n\nLe client recevra les nouvelles conditions avant toute intervention.","question":"Que se passe-t-il si la demande change ?","options":["Le prix doit être recalculé","Le devis initial s'applique toujours","Le service devient gratuit","Le délai disparaît"],"correct":"A","explanation":"Le passage indique : « Le devis reste valable trente jours. Toute modification de la demande donnera lieu à un nouveau calcul. » Cela justifie la réponse : Le prix doit être recalculé."},{"number":3,"points":3,"passage":"Le retrait des commandes se fait derrière le magasin. L'accueil principal reste réservé aux achats sur place.\n\nUn panneau indiquera l'accès depuis le parking. Présentez la confirmation reçue pour que l'équipe retrouve les articles déjà préparés à votre nom.","question":"Où retirer une commande ?","options":["Chez un commerçant voisin","À la caisse principale obligatoirement","Dans l'atelier fermé","À l'arrière du magasin"],"correct":"D","explanation":"Le passage indique : « Le retrait des commandes se fait derrière le magasin. L'accueil principal reste réservé aux achats sur place. » Cela justifie la réponse : À l'arrière du magasin."},{"number":4,"points":3,"passage":"La réparation est suspendue en attendant votre accord sur le devis. Aucune pièce supplémentaire ne sera commandée avant votre réponse.\n\nLe réparateur vous indiquera ensuite le délai, selon votre choix et la disponibilité des pièces.","question":"Quelle action est attendue du client ?","options":["Remplacer lui-même toutes les pièces","Envoyer une publicité","Accepter ou refuser le devis","Venir chercher une commande déjà achevée"],"correct":"C","explanation":"Le passage indique : « La réparation est suspendue en attendant votre accord sur le devis. Aucune pièce supplémentaire ne sera commandée avant votre réponse. » Cela justifie la réponse : Accepter ou refuser le devis."},{"number":5,"points":9,"passage":"J'ai choisi l'abonnement mensuel, même s'il coûte plus cher sur un an. Je ne sais pas encore combien de temps j'utiliserai le service.\n\nJe pourrai passer à une formule plus longue lorsque mon emploi du temps sera stabilisé. Pour le moment, je préfère garder la possibilité d'arrêter sans payer toute une année.","question":"Pourquoi ce choix est-il fait ?","options":["Payer nécessairement le moins cher sur douze mois","Limiter la durée d'engagement","Obtenir un contrat définitif","Éviter toute facture"],"correct":"B","explanation":"Le passage indique : « J'ai choisi l'abonnement mensuel, même s'il coûte plus cher sur un an. Je ne sais pas encore combien de temps j'utiliserai le service. » Cela justifie la réponse : Limiter la durée d'engagement."},{"number":6,"points":9,"passage":"Votre colis est arrivé dans un autre point de retrait. Vous disposez de deux jours supplémentaires pour le récupérer.\n\nLe message précise l'adresse et les nouveaux horaires. Merci de vérifier ces informations avant de vous déplacer au lieu que vous utilisez habituellement.","question":"Quelle adaptation est proposée ?","options":["Une livraison gratuite à l'étranger","Un délai de retrait prolongé","Une annulation automatique","Un achat supplémentaire obligatoire"],"correct":"B","explanation":"Le passage indique : « Votre colis est arrivé dans un autre point de retrait. Vous disposez de deux jours supplémentaires pour le récupérer. » Cela justifie la réponse : Un délai de retrait prolongé."},{"number":7,"points":9,"passage":"Je veux comparer le coût total, pas seulement la première mensualité. Peux-tu vérifier les frais d'installation et de résiliation ?\n\nUne petite différence annoncée peut devenir importante sur plusieurs mois. J'aimerais donc noter les conditions dans le même tableau avant de comparer les deux offres proposées.","question":"Quelle information est recherchée ?","options":["L'ensemble des frais liés au contrat","Le nombre de publicités","La couleur du matériel","Le prix du premier mois uniquement"],"correct":"A","explanation":"Le passage indique : « Je veux comparer le coût total, pas seulement la première mensualité. Peux-tu vérifier les frais d'installation et de résiliation ? » Cela justifie la réponse : L'ensemble des frais liés au contrat."},{"number":8,"points":9,"passage":"La boutique prête un appareil pendant certaines réparations. Signalez ce besoin lors du dépôt ; le stock est limité.\n\nLe prêt ne sera pas automatiquement possible pour chaque modèle ou à toutes les périodes de l'année.","question":"Que doit faire le client intéressé ?","options":["Venir sans signaler son besoin","Attendre la fin de la réparation","Demander le prêt dès le dépôt","Acheter un appareil neuf obligatoirement"],"correct":"C","explanation":"Le passage indique : « La boutique prête un appareil pendant certaines réparations. Signalez ce besoin lors du dépôt ; le stock est limité. » Cela justifie la réponse : Demander le prêt dès le dépôt."},{"number":9,"points":9,"passage":"Merci de ne pas commander deux tailles pour notre atelier de fabrication sur mesure. Nous pouvons organiser une prise de mesures avant de lancer la production.\n\nUn conseiller vous expliquera les étapes et les délais.","question":"Quelle solution évite les commandes multiples ?","options":["Commander trois tailles","Produire sans connaître les dimensions","Attendre le retour de tous les clients","Mesurer avant fabrication"],"correct":"D","explanation":"Le passage indique : « Merci de ne pas commander deux tailles pour notre atelier de fabrication sur mesure. Nous pouvons organiser une prise de mesures avant de lancer la production. » Cela justifie la réponse : Mesurer avant fabrication."},{"number":10,"points":9,"passage":"La facture distingue maintenant les fournitures et la main-d'œuvre. Le montant total ne change pas.\n\nLes clients pourront poser une question sur chaque rubrique. Le service souhaite rendre le document plus facile à comprendre sans modifier les conditions du travail déjà convenu.","question":"Quel changement est annoncé ?","options":["Une suppression de la main-d'œuvre","Une hausse automatique","Une présentation plus détaillée","Une réduction des fournitures"],"correct":"C","explanation":"Le passage indique : « La facture distingue maintenant les fournitures et la main-d'œuvre. Le montant total ne change pas. » Cela justifie la réponse : Une présentation plus détaillée."},{"number":11,"points":15,"passage":"Une coopérative répare les objets avant de les revendre. Les clients reçoivent une description des interventions réalisées.\n\nLes intervenants indiquent les pièces remplacées et les limites éventuelles du matériel. L'acheteur peut ainsi demander une précision avant de décider. La coopérative veut distinguer une remise en état vérifiée d'un objet simplement présenté comme une bonne affaire. Les bénévoles gardent une trace des contrôles et expliquent les conditions du service après la vente. Ils ne promettent pas qu'un produit d'occasion sera identique à un appareil neuf, mais souhaitent que la comparaison repose sur des informations suffisamment claires pour les personnes intéressées.","question":"Quelle information accompagne la vente ?","options":["L'historique des réparations effectuées","La liste des anciens utilisateurs","Une promesse de fonctionnement éternel","Le prix de tous les objets neufs"],"correct":"A","explanation":"Le passage indique : « Une coopérative répare les objets avant de les revendre. Les clients reçoivent une description des interventions réalisées. » Cela justifie la réponse : L'historique des réparations effectuées."},{"number":12,"points":15,"passage":"Un magasin affiche le prix à l'unité et au litre. Cela permet de comparer des bouteilles de contenances différentes.\n\nLe personnel peut montrer où lire cette indication sur les étiquettes. Le magasin utilise la même base pour éviter que les clients comparent seulement le prix placé en grands caractères. Le format le plus économique dépend aussi de la quantité réellement utilisée. Une grande bouteille n'est donc pas présentée comme toujours préférable.","question":"Quel objectif poursuit cet affichage ?","options":["Comparer uniquement les couleurs","Faciliter une comparaison homogène","Éviter de montrer les prix","Garantir que la plus grosse bouteille coûte moins cher"],"correct":"B","explanation":"Le passage indique : « Un magasin affiche le prix à l'unité et au litre. Cela permet de comparer des bouteilles de contenances différentes. » Cela justifie la réponse : Faciliter une comparaison homogène."},{"number":13,"points":15,"passage":"Une association aide à lire les contrats, sans choisir un fournisseur à la place du consommateur.\n\nLes conseillers expliquent les termes et aident à repérer les frais annoncés. Ils peuvent aussi proposer une liste de questions à adresser au fournisseur. Le service ne connaît pas forcément tous les besoins personnels et ne transforme pas son accompagnement en vente d'une offre particulière. Les personnes restent libres de poursuivre leur comparaison après la rencontre. L'association souhaite surtout que la signature corresponde à une décision comprise, plutôt qu'à un accord donné rapidement parce que le document semblait trop complexe pour être examiné ou discuté avant l'engagement.","question":"Quelle est la limite de l'accompagnement ?","options":["L'association signe tous les contrats","Tous les fournisseurs sont exclus","Le consommateur doit changer d'offre","La décision reste au consommateur"],"correct":"D","explanation":"Le passage indique : « Une association aide à lire les contrats, sans choisir un fournisseur à la place du consommateur. » Cela justifie la réponse : La décision reste au consommateur."},{"number":14,"points":15,"passage":"Une entreprise vend un service d'entretien annuel. Les interventions supplémentaires sont facturées séparément et doivent être autorisées.\n\nLes clients recevront une fiche avec les opérations habituelles comprises dans l'abonnement. Une intervention inhabituelle fera l'objet d'une proposition précisant le travail et son montant. L'entreprise veut éviter une confusion entre un service régulier et une prise en charge illimitée de tout incident. Le bilan de l'année indiquera aussi les demandes les plus fréquentes, afin de voir si la formule correspond bien aux usages réels ou si elle doit être revue pour rester compréhensible et utile.","question":"Quelle information est importante ?","options":["L'autorisation du client n'a aucun rôle","Tout n'est pas inclus dans le forfait","Le forfait interdit les interventions","Chaque réparation est nécessairement gratuite"],"correct":"B","explanation":"Le passage indique : « Une entreprise vend un service d'entretien annuel. Les interventions supplémentaires sont facturées séparément et doivent être autorisées. » Cela justifie la réponse : Tout n'est pas inclus dans le forfait."},{"number":15,"points":15,"passage":"Un atelier partage une machine coûteuse entre plusieurs professionnels. Les horaires sont coordonnés pour réduire les temps inutilisés.\n\nLes utilisateurs réservent des plages et signalent leurs besoins avant les périodes les plus chargées. Le collectif souhaite éviter qu'une machine accessible en principe soit presque toujours indisponible au moment où chacun en a besoin. Les horaires seront donc réexaminés après les premiers mois. Le projet ne consiste pas seulement à répartir un prix d'achat, mais à organiser un équipement capable de servir correctement plusieurs activités dans la durée, avec des responsabilités connues de toutes les personnes concernées.","question":"Quel avantage économique est recherché ?","options":["Supprimer toutes les réservations","Acheter une machine pour chaque heure","Mieux utiliser un équipement commun","Réduire les compétences nécessaires"],"correct":"C","explanation":"Le passage indique : « Un atelier partage une machine coûteuse entre plusieurs professionnels. Les horaires sont coordonnés pour réduire les temps inutilisés. » Cela justifie la réponse : Mieux utiliser un équipement commun."},{"number":16,"points":15,"passage":"Une boutique propose la location d'une tenue de cérémonie. Le nettoyage est compris, mais les retouches personnelles sont interdites.\n\nLe personnel vérifie l'état du vêtement au départ et au retour avec le client. Il explique les précautions et les accessoires fournis. Une demande particulière doit être discutée avant la réservation, car le même article sera ensuite porté par d'autres personnes. La boutique souhaite offrir une solution ponctuelle sans laisser croire qu'une location donne tous les droits d'un achat.","question":"Que peut attendre le client ?","options":["Un nettoyage inclus","Un achat définitif","La possibilité de découper le vêtement","Une fabrication sur mesure automatique"],"correct":"A","explanation":"Le passage indique : « Une boutique propose la location d'une tenue de cérémonie. Le nettoyage est compris, mais les retouches personnelles sont interdites. » Cela justifie la réponse : Un nettoyage inclus."},{"number":17,"points":15,"passage":"Un réparateur refuse un remplacement coûteux avant d'avoir vérifié une panne simple. Il explique les étapes du diagnostic.\n\nIl décrit les observations nécessaires et indique le coût du premier examen. Les clients peuvent ensuite décider s'ils souhaitent poursuivre. Le professionnel veut éviter qu'une solution techniquement possible soit choisie avant que son utilité soit appréciée. Certains défauts demandent une intervention importante, d'autres une vérification plus simple. Le service conserve une trace des échanges pour que les opérations réalisées correspondent à ce qui a été expliqué.","question":"Quelle démarche adopte-t-il ?","options":["Identifier la cause avant d'engager une dépense","Changer immédiatement tout l'appareil","Vendre uniquement du matériel neuf","Garantir une panne précise sans examen"],"correct":"A","explanation":"Le passage indique : « Un réparateur refuse un remplacement coûteux avant d'avoir vérifié une panne simple. Il explique les étapes du diagnostic. » Cela justifie la réponse : Identifier la cause avant d'engager une dépense."},{"number":18,"points":15,"passage":"Une entreprise demande un acompte pour acheter les matériaux. Le solde sera payé après la livraison convenue.\n\nLe document précise le calendrier, les matériaux concernés et les étapes qui restent à réaliser. L'entreprise souhaite expliquer pourquoi une somme est demandée alors que l'objet n'a pas encore été livré. Les conditions d'une modification ou d'un abandon seront indiquées avant le versement, afin que les personnes sachent quels engagements elles prennent et quelles questions poser si la préparation ne peut pas avancer comme prévu.","question":"À quoi sert l'acompte ?","options":["Garantir l'absence de toute facture","Payer un service déjà terminé uniquement","Supprimer le montant final","Financer une partie de la préparation"],"correct":"D","explanation":"Le passage indique : « Une entreprise demande un acompte pour acheter les matériaux. Le solde sera payé après la livraison convenue. » Cela justifie la réponse : Financer une partie de la préparation."},{"number":19,"points":15,"passage":"Le marché d'occasion organise un contrôle visuel des objets électriques. Les organisateurs précisent qu'il ne remplace pas une vérification technique complète.\n\nLes bénévoles regardent les signes de dommage visibles et les informations présentes sur l'appareil. Ils orientent les cas douteux vers un professionnel et refusent de promettre une sécurité complète sur cette seule base. Le marché souhaite réduire les risques sans transformer une inspection rapide en certification. Les acheteurs sont invités à demander les limites du contrôle et à vérifier l'adaptation de l'objet à leur usage.","question":"Quelle limite est reconnue ?","options":["Le contrôle ne garantit pas tous les aspects techniques","Aucune observation n'est réalisée","Les objets sont tous neufs","Le prix assure automatiquement la sécurité"],"correct":"A","explanation":"Le passage indique : « Le marché d'occasion organise un contrôle visuel des objets électriques. Les organisateurs précisent qu'il ne remplace pas une vérification technique complète. » Cela justifie la réponse : Le contrôle ne garantit pas tous les aspects techniques."},{"number":20,"points":21,"passage":"Une promotion propose un prix bas pour trois articles. Un conseiller rappelle que l'économie n'existe que si l'acheteur utilise réellement ces quantités. Une personne vivant seule pourra préférer un article à l'unité, même si le prix annoncé pour un lot semble plus avantageux. Le conseiller propose de comparer le montant total et la consommation prévue. Il souhaite éviter que le mot promotion suffise à faire acheter une quantité sans rapport avec les habitudes. Les dates et les possibilités de conservation restent des informations utiles pour apprécier la proposition dans chaque foyer.","question":"Quelle condition faut-il examiner ?","options":["L'adéquation entre quantité achetée et besoin","La musique diffusée","Le nombre de caisses du magasin","La taille de l'affiche"],"correct":"A","explanation":"Le passage indique : « Une promotion propose un prix bas pour trois articles. Un conseiller rappelle que l'économie n'existe que si l'acheteur utilise réellement ces quantités. » Cela justifie la réponse : L'adéquation entre quantité achetée et besoin."},{"number":21,"points":21,"passage":"Une entreprise baisse ses coûts de livraison en regroupant les commandes. Elle annonce des délais moins rapides mais plus prévisibles. L'entreprise explique pourquoi elle ne promet plus un départ immédiat après chaque commande. Les économies réalisées seront suivies avec les retards et les difficultés de regroupement. Le service veut éviter qu'un gain pour sa propre organisation se traduise par une attente mal expliquée ou par une obligation pour les clients de rester disponibles sans connaître un créneau de réception.","question":"Quel compromis est proposé ?","options":["Un retrait obligatoire à l'usine","Moins de rapidité contre une meilleure organisation","Une suppression de tous les délais","Une livraison immédiate garantie partout"],"correct":"B","explanation":"Le passage indique : « Une entreprise baisse ses coûts de livraison en regroupant les commandes. Elle annonce des délais moins rapides mais plus prévisibles. » Cela justifie la réponse : Moins de rapidité contre une meilleure organisation."},{"number":22,"points":21,"passage":"Des artisans créent une boutique collective. Les ventes soutiennent chacun, mais la permanence est partagée selon un calendrier commun. Les membres s'engagent sur des créneaux compatibles avec leur travail de production. Une personne de remplacement pourra être prévue lorsque plusieurs marchés ont lieu le même jour. Les résultats seront discutés à partir des ventes et du temps réellement consacré au lieu, afin de savoir si la coopération apporte un avantage soutenable à chacun plutôt qu'un surcroît de tâches mal réparti.","question":"Quelle obligation accompagne cette organisation ?","options":["Vendre tous les objets au même prix","Abandonner son propre atelier","Participer à la tenue de la boutique","Refuser les nouveaux clients"],"correct":"C","explanation":"Le passage indique : « Des artisans créent une boutique collective. Les ventes soutiennent chacun, mais la permanence est partagée selon un calendrier commun. » Cela justifie la réponse : Participer à la tenue de la boutique."},{"number":23,"points":21,"passage":"Un client compare deux produits de prix proches. Celui dont les pièces sont disponibles longtemps pourrait coûter moins cher à l'usage, même si l'achat initial est légèrement supérieur. Le client se renseigne sur les références et les délais de commande. Il cherche aussi à savoir si l'appareil peut être ouvert avec un outillage courant. Les documents disponibles lui permettront de comparer des situations possibles, sans garantir à l'avance qu'aucune panne ne surviendra. Son choix repose sur plusieurs dépenses probables au cours du temps.","question":"Quel critère complète le prix d'achat ?","options":["Le nombre de slogans","La date des publicités","La possibilité d'entretenir le produit","Le volume de l'emballage seulement"],"correct":"C","explanation":"Le passage indique : « Un client compare deux produits de prix proches. Celui dont les pièces sont disponibles longtemps pourrait coûter moins cher à l'usage, même si l'achat initial est légèrement supérieur. » Cela justifie la réponse : La possibilité d'entretenir le produit."},{"number":24,"points":21,"passage":"Une commune teste une monnaie locale auprès de commerces volontaires. L'objectif est de favoriser les échanges dans le réseau, pas de remplacer tous les moyens de paiement. Les participants reçoivent une information sur les lieux acceptant le dispositif et les modalités de fonctionnement. Les organisateurs veulent observer les achats effectivement réalisés dans le réseau, sans confondre inscriptions et échanges. Les commerçants restent libres de participer selon les règles annoncées.","question":"Quelle ambition est précisée ?","options":["Interdire la monnaie habituelle","Supprimer les prix","Obliger tous les magasins à participer","Soutenir certains échanges de proximité"],"correct":"D","explanation":"Le passage indique : « Une commune teste une monnaie locale auprès de commerces volontaires. L'objectif est de favoriser les échanges dans le réseau, pas de remplacer tous les moyens de paiement. » Cela justifie la réponse : Soutenir certains échanges de proximité."},{"number":25,"points":21,"passage":"Un service de réservation facture une annulation tardive. Il explique cette règle avant paiement, car le créneau ne peut pas toujours être attribué à un autre client. Les clients peuvent annuler sans frais jusqu'à une limite clairement annoncée. Au-delà, le prestataire examine les conditions prévues au contrat. Il souhaite éviter que plusieurs rendez-vous restent inutilisés alors que d'autres personnes attendent une place. Les responsables vérifieront cependant que la règle est visible et comprise avant la confirmation.","question":"Quel motif justifie la règle annoncée ?","options":["L'absence de toute réservation","La volonté de réduire les informations","La gratuité du service","La perte possible d'un créneau réservé"],"correct":"D","explanation":"Le passage indique : « Un service de réservation facture une annulation tardive. Il explique cette règle avant paiement, car le créneau ne peut pas toujours être attribué à un autre client. » Cela justifie la réponse : La perte possible d'un créneau réservé."},{"number":26,"points":21,"passage":"Une entreprise annonce une hausse de prix et décrit les coûts concernés. Certains clients restent mécontents, mais peuvent comparer les raisons données plutôt que découvrir un montant sans explication. Les explications distinguent les éléments durables des variations temporaires. Le commerce ne demande pas aux clients d'accepter toute décision parce qu'un motif est présenté. Il souhaite leur donner des repères pour juger si l'offre reste adaptée à leur budget et à leurs besoins.","question":"Quel apport fournit cette démarche ?","options":["Une interdiction de comparer les offres","Une satisfaction garantie de tous","Une disparition de la hausse","Une base de compréhension et de discussion"],"correct":"D","explanation":"Le passage indique : « Une entreprise annonce une hausse de prix et décrit les coûts concernés. Certains clients restent mécontents, mais peuvent comparer les raisons données plutôt que découvrir un montant sans explication. » Cela justifie la réponse : Une base de compréhension et de discussion."},{"number":27,"points":21,"passage":"Une étude de satisfaction reçoit surtout les réponses des clients très contents ou très déçus. Le commerce ajoute des entretiens courts avec des acheteurs ordinaires. Les enquêteurs demandent aux personnes comment s'est déroulé un achat récent, sans les choisir uniquement à partir d'une note déjà publiée. Le commerce souhaite conserver les critiques et les compliments, mais savoir aussi comment ils se répartissent parmi les clients.","question":"Pourquoi compléter l'enquête ?","options":["Supprimer les critiques reçues","Garantir une note parfaite","Mieux représenter des expériences moins exprimées","Interdire les avis favorables"],"correct":"C","explanation":"Le passage indique : « Une étude de satisfaction reçoit surtout les réponses des clients très contents ou très déçus. Le commerce ajoute des entretiens courts avec des acheteurs ordinaires. » Cela justifie la réponse : Mieux représenter des expériences moins exprimées."},{"number":28,"points":21,"passage":"Une offre gratuite est financée par la publicité. Les utilisateurs ne paient pas directement, mais leur attention intéresse les annonceurs. Il ne souhaite pas que l'absence de paiement direct soit comprise comme l'absence de tout échange économique. Les utilisateurs pourront ainsi apprécier ce qui finance les fonctions proposées, au lieu de devoir déduire le fonctionnement de la seule mention gratuite placée en tête de la présentation commerciale du produit.","question":"Quelle source économique est identifiée ?","options":["Les revenus publicitaires","L'absence totale de financement","Le remboursement des utilisateurs","Une vente obligatoire d'objets"],"correct":"A","explanation":"Le passage indique : « Une offre gratuite est financée par la publicité. Les utilisateurs ne paient pas directement, mais leur attention intéresse les annonceurs. » Cela justifie la réponse : Les revenus publicitaires."},{"number":29,"points":21,"passage":"Un commerçant préfère une petite gamme suivie à un choix très vaste souvent indisponible. Il veut rendre plus fiables les promesses de stock. Les fournisseurs connaissent mieux les quantités et les dates auxquelles le magasin s'engage. Les clients peuvent demander un article particulier, mais la boutique préfère annoncer un délai réaliste plutôt qu'une disponibilité supposée immédiate. Le responsable suivra les commandes non satisfaites pour ajuster la gamme.","question":"Quel avantage recherche-t-il ?","options":["Une absence de relations avec les fournisseurs","Une meilleure disponibilité des références proposées","Un nombre maximal d'articles affichés sans stock","Une réduction des informations de prix"],"correct":"B","explanation":"Le passage indique : « Un commerçant préfère une petite gamme suivie à un choix très vaste souvent indisponible. Il veut rendre plus fiables les promesses de stock. » Cela justifie la réponse : Une meilleure disponibilité des références proposées."},{"number":30,"points":26,"passage":"Le coût d'un produit comprend parfois des dépenses reportées : consommables, entretien et remplacement d'accessoires. Un prix de départ attractif ne suffit donc pas à juger une offre. Comparer suppose de définir une durée et des usages vraisemblables. Les utilisateurs peuvent ainsi comparer les offres sur une base plus cohérente. Une estimation restera cependant liée aux hypothèses retenues, qu'il faut rendre lisibles plutôt que présenter comme des dépenses futures certaines pour chaque personne.","question":"Quelle méthode est recommandée ?","options":["Additionner toutes les publicités","Évaluer le coût dans les conditions d'utilisation prévues","Regarder seulement le prix du premier jour","Choisir l'emballage le plus grand"],"correct":"B","explanation":"Le passage indique : « Le coût d'un produit comprend parfois des dépenses reportées : consommables, entretien et remplacement d'accessoires. Un prix de départ attractif ne suffit donc pas à juger une offre. Comparer suppose de définir une durée et des usages vraisemblables. » Cela justifie la réponse : Évaluer le coût dans les conditions d'utilisation prévues."},{"number":31,"points":26,"passage":"Une entreprise mesure le service client par la durée moyenne des appels. Les employés raccourcissent les échanges, mais les mêmes personnes rappellent davantage. L'amélioration apparente d'un indicateur peut donc masquer une résolution moins efficace des problèmes. L'entreprise ajoute donc le nombre de demandes résolues sans rappel à son suivi. Elle souhaite que les salariés puissent prendre le temps utile, sans confondre rapidité de l'échange et qualité du résultat obtenu pour le client.","question":"Quelle limite de l'indicateur apparaît ?","options":["Un appel court n'est pas forcément un problème résolu","La durée ne peut jamais être mesurée","Les rappels prouvent une satisfaction parfaite","Tous les appels longs sont inutiles"],"correct":"A","explanation":"Le passage indique : « Une entreprise mesure le service client par la durée moyenne des appels. Les employés raccourcissent les échanges, mais les mêmes personnes rappellent davantage. L'amélioration apparente d'un indicateur peut donc masquer une résolution moins efficace des problèmes. » Cela justifie la réponse : Un appel court n'est pas forcément un problème résolu."},{"number":32,"points":26,"passage":"Un magasin affirme pratiquer des prix équitables. Pour rendre l'engagement compréhensible, il explique la répartition du prix entre production, transport et distribution. Une formule valorisante devient plus informative lorsqu'elle renvoie à des éléments que l'on peut examiner. Le magasin mettra ces informations à jour lorsque ses conditions d'achat changent. Il souhaite que les clients puissent poser des questions précises, au lieu de devoir accepter une formule générale qui paraît positive sans expliquer ce qu'elle garantit réellement.","question":"Qu'est-ce qui renforce la crédibilité de l'annonce ?","options":["L'absence de toute comparaison","La répétition du mot équitable uniquement","Un logo sans information","Des explications sur les mécanismes du prix"],"correct":"D","explanation":"Le passage indique : « Un magasin affirme pratiquer des prix équitables. Pour rendre l'engagement compréhensible, il explique la répartition du prix entre production, transport et distribution. Une formule valorisante devient plus informative lorsqu'elle renvoie à des éléments que l'on peut examiner. » Cela justifie la réponse : Des explications sur les mécanismes du prix."},{"number":33,"points":26,"passage":"Un service de location réduit l'achat individuel d'équipements rarement utilisés. Son intérêt dépend toutefois de la durée de vie du matériel et des déplacements nécessaires. Le partage constitue une possibilité d'économie, pas une garantie indépendante de son organisation. Les responsables regardent les prêts achevés, les réparations et les trajets nécessaires. Cette observation permet de distinguer une intention de partage et une organisation qui remplace effectivement des achats individuels dans les conditions ordinaires d'utilisation.","question":"Quelle approche du partage est proposée ?","options":["Compter uniquement les inscriptions","Évaluer ses conditions concrètes de fonctionnement","Le rejeter dès qu'un trajet existe","Le considérer toujours bénéfique sans examen"],"correct":"B","explanation":"Le passage indique : « Un service de location réduit l'achat individuel d'équipements rarement utilisés. Son intérêt dépend toutefois de la durée de vie du matériel et des déplacements nécessaires. Le partage constitue une possibilité d'économie, pas une garantie indépendante de son organisation. » Cela justifie la réponse : Évaluer ses conditions concrètes de fonctionnement."},{"number":34,"points":26,"passage":"Une boutique veut fidéliser ses clients par des réductions fréquentes. Certains attendent alors systématiquement la prochaine promotion. Le mécanisme qui devait stimuler l'achat immédiat transforme la perception du prix habituel et peut ralentir les ventes entre deux offres. Elle veut savoir si les offres augmentent réellement les achats ou les déplacent, et comprendre les attentes qu'elles installent chez les clients lorsqu'ils reviennent hors promotion.","question":"Quel effet imprévu est décrit ?","options":["Les prix deviennent identiques partout","Les clients ne voient plus les promotions","La fidélité supprime toutes les attentes","Les promotions incitent à différer certains achats"],"correct":"D","explanation":"Le passage indique : « Une boutique veut fidéliser ses clients par des réductions fréquentes. Certains attendent alors systématiquement la prochaine promotion. Le mécanisme qui devait stimuler l'achat immédiat transforme la perception du prix habituel et peut ralentir les ventes entre deux offres. » Cela justifie la réponse : Les promotions incitent à différer certains achats."},{"number":35,"points":26,"passage":"Un contrat standard facilite la vente rapide. Mais lorsqu'une situation particulière apparaît, le client doit pouvoir comprendre ses options. Une entreprise forme donc ses équipes à expliquer les clauses plutôt qu'à renvoyer systématiquement vers un document difficile à lire. Les conseillers disposent d'exemples et peuvent reconnaître les cas qui demandent un avis spécialisé. L'entreprise souhaite conserver une procédure commune sans traiter toutes les questions comme si la lecture du même paragraphe apportait nécessairement une réponse suffisante.","question":"Quel besoin complète la standardisation ?","options":["Une disparition des contrats","Une interdiction de poser des questions","Une capacité d'explication adaptée","Une signature sans information"],"correct":"C","explanation":"Le passage indique : « Un contrat standard facilite la vente rapide. Mais lorsqu'une situation particulière apparaît, le client doit pouvoir comprendre ses options. Une entreprise forme donc ses équipes à expliquer les clauses plutôt qu'à renvoyer systématiquement vers un document difficile à lire. » Cela justifie la réponse : Une capacité d'explication adaptée."},{"number":36,"points":33,"passage":"Une plateforme classe les offres selon leur popularité. Les nouveaux fournisseurs, encore peu visibles, ont alors moins de chances d'obtenir les achats qui amélioreraient leur classement. Un indicateur censé refléter le succès peut aussi contribuer à reproduire l'avantage de ceux qui sont déjà installés. Les clients voient surtout les offres déjà achetées par d'autres et hésitent à essayer celles qui n'ont pas encore reçu d'avis. La plateforme étudie des moyens de présenter de nouveaux fournisseurs sans prétendre qu'ils auraient déjà la même expérience. Elle devra aussi expliquer les critères utilisés, afin que le classement ne paraisse pas une simple photographie indépendante des règles du site. Les responsables veulent distinguer la popularité observée et les effets produits par leur propre présentation. Cette distinction devient importante lorsqu'un outil d'information influence directement les possibilités de vendre et de se faire connaître.","question":"Quel mécanisme est mis en évidence ?","options":["Un prix identique pour toutes les offres","Une disparition de tout classement","Un renforcement circulaire de la visibilité","Une égalité automatique entre anciens et nouveaux"],"correct":"C","explanation":"Le passage indique : « Un indicateur censé refléter le succès peut aussi contribuer à reproduire l'avantage de ceux qui sont déjà installés. » Cela justifie la réponse : Un renforcement circulaire de la visibilité."},{"number":37,"points":33,"passage":"Une entreprise revendique un service rapide en supprimant certaines étapes de contrôle. Les délais diminuent, mais les retours augmentent. Elle doit comparer le gain initial au travail supplémentaire causé par les erreurs. L'efficacité ne se mesure pas toujours au temps économisé à une seule étape du parcours. Les équipes doivent alors rouvrir les dossiers, répondre aux clients et organiser des échanges. Ces tâches mobilisent parfois davantage de moyens que les vérifications supprimées au départ. Les responsables vont comparer plusieurs organisations sur une durée suffisante. Ils ne souhaitent pas revenir automatiquement à chaque ancienne étape, mais identifier celles qui évitent un travail plus lourd ensuite. Le résultat sera décrit avec les retards et les erreurs, pas uniquement avec le délai initial.","question":"Quel bilan faut-il réaliser ?","options":["Un comptage limité à la première livraison","Un bilan du processus entier","Une mesure du seul emballage","Une suppression des données sur les retours"],"correct":"B","explanation":"Le passage indique : « L'efficacité ne se mesure pas toujours au temps économisé à une seule étape du parcours. » Cela justifie la réponse : Un bilan du processus entier."},{"number":38,"points":33,"passage":"Un consommateur choisit un article durable pour limiter ses achats. Les campagnes du fabricant l'encouragent néanmoins à le remplacer souvent pour suivre de nouvelles versions. La durée de vie technique d'un produit ne garantit pas sa durée réelle d'usage si les pratiques commerciales poussent à son renouvellement. Les associations demandent des informations sur les réparations et les mises à jour permettant de continuer à utiliser l'appareil. Certains clients choisiraient de le garder plus longtemps s'ils savaient comment traiter une panne ou conserver les fonctions nécessaires. Le fabricant devra donc regarder ses services et ses messages commerciaux, pas seulement les caractéristiques du modèle neuf. Une promesse de durabilité peut perdre une partie de son sens lorsque toute l'organisation pousse à renouveler rapidement les achats. Les utilisateurs pourront comparer ces dimensions avant de juger si l'engagement annoncé correspond réellement à leurs possibilités d'usage dans le temps.","question":"Quelle distinction le texte souligne-t-il ?","options":["Durabilité de l'objet et durée de conservation par l'utilisateur","Prix initial et poids du carton uniquement","Nouveauté et qualité nécessairement supérieure","Garantie et absence de toute réparation"],"correct":"A","explanation":"Le passage indique : « La durée de vie technique d'un produit ne garantit pas sa durée réelle d'usage si les pratiques commerciales poussent à son renouvellement. » Cela justifie la réponse : Durabilité de l'objet et durée de conservation par l'utilisateur."},{"number":39,"points":33,"passage":"Une entreprise associe des clients à la conception d'un service. Les participants les plus disponibles ne représentent pas tous les futurs usagers. L'équipe cherche donc d'autres retours avant de stabiliser le projet. La participation fournit des informations précieuses sans supprimer la question de ceux qui n'ont pas pu participer. Elle organise des essais courts à plusieurs horaires et propose des échanges à distance pour ceux qui ne peuvent pas venir. Les personnes rencontrées ne deviennent pas pour autant un portrait exact de tous les clients. Elles apportent d'autres difficultés et d'autres façons d'utiliser le service. Les concepteurs souhaitent comparer ces retours avant de choisir des règles durables. Le travail participatif reste utile, mais doit être décrit avec ses conditions et ses limites. Un groupe enthousiaste peut aider à améliorer un projet sans suffire à garantir qu'il conviendra ensuite aux publics qui n'étaient pas présents lors de sa préparation.","question":"Quelle précaution méthodologique est prise ?","options":["Fixer le service avant toute observation","Élargir les retours au-delà du groupe volontaire","Considérer les volontaires comme parfaitement représentatifs","Écarter toutes les contributions des clients"],"correct":"B","explanation":"Le passage indique : « La participation fournit des informations précieuses sans supprimer la question de ceux qui n'ont pas pu participer. » Cela justifie la réponse : Élargir les retours au-delà du groupe volontaire."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-16','tcf-reading-2026-11-reference-v3',$paper${"id":"tcf-reading-16","version":"tcf-reading-2026-11-reference-v3","title":"TCF Reading · Test 16","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"La tour se visite uniquement l'après-midi cette semaine. La cour reste accessible dès neuf heures.\n\nUn panneau rappellera les créneaux de visite à l'entrée. Les billets peuvent être retirés à l'accueil pendant les horaires habituels.","question":"Quel espace ouvre le matin ?","options":["La tour","La salle haute","Le toit","La cour"],"correct":"D","explanation":"Le passage indique : « La tour se visite uniquement l'après-midi cette semaine. La cour reste accessible dès neuf heures. » Cela justifie la réponse : La cour."},{"number":2,"points":3,"passage":"La visite des archives exige une pièce d'identité. Les sacs seront déposés dans les casiers avant l'entrée.\n\nLe personnel indiquera les règles de manipulation des documents.","question":"Que faut-il laisser au vestiaire ?","options":["La pièce d'identité","Le billet de visite","Les sacs","Les lunettes"],"correct":"C","explanation":"Le passage indique : « La visite des archives exige une pièce d'identité. Les sacs seront déposés dans les casiers avant l'entrée. » Cela justifie la réponse : Les sacs."},{"number":3,"points":3,"passage":"Le passage sous les remparts est fermé pour travaux. Suivez les panneaux bleus vers la porte sud.\n\nLa déviation ajoute quelques minutes de marche. Les agents demandent de ne pas déplacer les barrières, même lorsque le chantier semble inoccupé.","question":"Quelle direction faut-il prendre ?","options":["Le passage fermé","Le sommet des remparts","La sortie sans panneau","La porte sud"],"correct":"D","explanation":"Le passage indique : « Le passage sous les remparts est fermé pour travaux. Suivez les panneaux bleus vers la porte sud. » Cela justifie la réponse : La porte sud."},{"number":4,"points":3,"passage":"L'exposition de maquettes est gratuite samedi. Les visites guidées restent sur réservation.\n\nLe personnel pourra expliquer les horaires et les places encore disponibles. Une entrée gratuite ne garantit pas automatiquement une place dans un groupe déjà complet.","question":"Quel service exige toujours une réservation ?","options":["L'accès à toutes les rues","La visite accompagnée","La lecture des panneaux","L'entrée libre à l'exposition"],"correct":"B","explanation":"Le passage indique : « L'exposition de maquettes est gratuite samedi. Les visites guidées restent sur réservation. » Cela justifie la réponse : La visite accompagnée."},{"number":5,"points":9,"passage":"J'ai choisi la visite du quartier industriel. Nous connaissons déjà le château et je voudrais découvrir un autre aspect de la ville.\n\nLe guide parlera aussi des habitants qui travaillaient dans les anciens ateliers. Nous pourrons comparer ce parcours avec les visites habituelles, sans chercher uniquement les monuments les plus connus.","question":"Pourquoi choisir cette visite ?","options":["Acheter une usine","Revoir uniquement le château","Éviter toute activité culturelle","Découvrir une histoire moins familière"],"correct":"D","explanation":"Le passage indique : « J'ai choisi la visite du quartier industriel. Nous connaissons déjà le château et je voudrais découvrir un autre aspect de la ville. » Cela justifie la réponse : Découvrir une histoire moins familière."},{"number":6,"points":9,"passage":"Apportez une photo ancienne de votre rue, si vous en avez une. Nous la comparerons aux lieux actuels pendant la promenade.\n\nLes images seront observées avec leur date, lorsque celle-ci est connue. Vous pourrez repartir avec les originaux après leur numérisation pour le groupe.","question":"À quoi servira la photo ?","options":["Prouver la propriété d'un bâtiment","Observer les transformations du quartier","Remplacer la carte de transport","Décorer uniquement la salle d'accueil"],"correct":"B","explanation":"Le passage indique : « Apportez une photo ancienne de votre rue, si vous en avez une. Nous la comparerons aux lieux actuels pendant la promenade. » Cela justifie la réponse : Observer les transformations du quartier."},{"number":7,"points":9,"passage":"La réunion sur la place rénovée est avancée d'une heure. Le plan présenté ne change pas ; seule l'heure a été modifiée.\n\nLes participants recevront une confirmation et pourront préparer leurs questions. Les responsables souhaitent garder le même temps d'échange malgré ce changement d'organisation.","question":"Quel élément est conservé ?","options":["Le projet présenté","Le numéro de téléphone uniquement","L'horaire initial","La date de publication du bulletin"],"correct":"A","explanation":"Le passage indique : « La réunion sur la place rénovée est avancée d'une heure. Le plan présenté ne change pas ; seule l'heure a été modifiée. » Cela justifie la réponse : Le projet présenté."},{"number":8,"points":9,"passage":"Le musée prête des sièges pliants pour suivre la visite. Demandez-les à l'accueil avant le départ du groupe.\n\nLes sièges doivent être rapportés avant de quitter le musée. Le personnel expliquera les endroits où ils peuvent être utilisés sans gêner les passages.","question":"Comment obtenir ce matériel ?","options":["Le retirer dans la boutique voisine","Acheter une place assise spéciale","Le demander à l'accueil","Attendre la fin du parcours"],"correct":"C","explanation":"Le passage indique : « Le musée prête des sièges pliants pour suivre la visite. Demandez-les à l'accueil avant le départ du groupe. » Cela justifie la réponse : Le demander à l'accueil."},{"number":9,"points":9,"passage":"Je participerai à l'atelier de photographie plutôt qu'au concours. Je veux apprendre sans avoir à présenter immédiatement un résultat.\n\nL'animateur présentera plusieurs techniques et laissera chacun essayer à son rythme. Je pourrai ensuite décider si je souhaite montrer des images lors d'une prochaine rencontre.","question":"Quel besoin guide ce choix ?","options":["Exposer un travail déjà terminé","Gagner un prix dès la première séance","Éviter toute pratique","Se former sans compétition"],"correct":"D","explanation":"Le passage indique : « Je participerai à l'atelier de photographie plutôt qu'au concours. Je veux apprendre sans avoir à présenter immédiatement un résultat. » Cela justifie la réponse : Se former sans compétition."},{"number":10,"points":9,"passage":"Notre collecte de souvenirs accepte aussi des récits enregistrés. Il n'est pas nécessaire de posséder un document écrit.\n\nUne permanence permettra de choisir la forme de la contribution et de vérifier les informations associées. Les personnes restent libres de ne pas publier certains détails trop personnels.","question":"Qui peut contribuer ?","options":["Une personne ayant un souvenir à raconter","Uniquement un propriétaire d'archives papier","Un vendeur de matériel audio","Seulement un historien diplômé"],"correct":"A","explanation":"Le passage indique : « Notre collecte de souvenirs accepte aussi des récits enregistrés. Il n'est pas nécessaire de posséder un document écrit. » Cela justifie la réponse : Une personne ayant un souvenir à raconter."},{"number":11,"points":15,"passage":"Une ancienne halle devient une bibliothèque. Les grandes ouvertures sont conservées, tandis que l'intérieur est adapté aux collections et aux lecteurs.\n\nLes architectes ont prévu des espaces calmes et des tables de groupe, tout en gardant visible le volume de la halle. Les futurs lecteurs pourront visiter un secteur témoin avant l'ouverture complète. La ville souhaite éviter qu'une conservation purement décorative laisse le bâtiment inutilisé. Elle explique donc les choix techniques et les contraintes du nouvel accueil. Les éléments anciens ne seront pas tous maintenus au même endroit, mais ceux qui racontent le mieux le fonctionnement du lieu feront l'objet d'une présentation accessible au public.","question":"Quel type de transformation est réalisé ?","options":["Une fermeture au public","Un nouvel usage respectant des éléments du bâtiment","Une démolition complète","Un retour obligatoire au commerce d'origine"],"correct":"B","explanation":"Le passage indique : « Une ancienne halle devient une bibliothèque. Les grandes ouvertures sont conservées, tandis que l'intérieur est adapté aux collections et aux lecteurs. » Cela justifie la réponse : Un nouvel usage respectant des éléments du bâtiment."},{"number":12,"points":15,"passage":"Des habitants identifient les noms anciens des rues sur un plan. Le projet recueille aussi les usages populaires qui n'apparaissent pas dans les archives administratives.\n\nLes témoins indiquent où ils ont entendu un nom et à quelle période il était utilisé. Les animateurs rapprochent ces récits des plans conservés, sans effacer les différences. Le projet ne cherche pas à remplacer les noms actuels par une version unique supposée authentique.","question":"Quelle information complète les sources officielles ?","options":["La taille des dossiers municipaux","Les horaires des magasins uniquement","La mémoire des pratiques locales","Le prix des panneaux routiers"],"correct":"C","explanation":"Le passage indique : « Des habitants identifient les noms anciens des rues sur un plan. Le projet recueille aussi les usages populaires qui n'apparaissent pas dans les archives administratives. » Cela justifie la réponse : La mémoire des pratiques locales."},{"number":13,"points":15,"passage":"Un chantier restaure les joints d'un pont avec un matériau compatible avec la pierre. Un produit plus dur pourrait provoquer des dégradations au lieu de protéger l'ensemble.\n\nUne partie du chantier servira de test pour observer le résultat. Le responsable souhaite éviter qu'un produit paraissant plus solide soit considéré comme automatiquement meilleur. Les propriétés doivent être appréciées ensemble, avec les contraintes du bâtiment. Des informations seront proposées aux riverains, afin qu'ils comprennent pourquoi les travaux ne consistent pas simplement à remplacer un ancien matériau par le plus récent ou le plus résistant disponible chez un fournisseur.","question":"Quel critère guide le choix ?","options":["La compatibilité avec les matériaux existants","La dureté maximale à tout prix","La rapidité de la publicité","La couleur de l'emballage"],"correct":"A","explanation":"Le passage indique : « Un chantier restaure les joints d'un pont avec un matériau compatible avec la pierre. Un produit plus dur pourrait provoquer des dégradations au lieu de protéger l'ensemble. » Cela justifie la réponse : La compatibilité avec les matériaux existants."},{"number":14,"points":15,"passage":"Une ville éclaire moins fortement ses monuments la nuit. Les visiteurs peuvent encore les voir, mais la consommation et la gêne lumineuse diminuent.\n\nLes techniciens ont réalisé plusieurs essais et recueilli les remarques sur les principaux points de vue. Les riverains peuvent encore se repérer dans les rues, tandis que les projecteurs décoratifs fonctionnent moins longtemps. Le service distingue donc les besoins de circulation et la mise en scène des façades. Il ne veut pas présenter tous les éclairages comme également nécessaires ou également inutiles.","question":"Quel compromis est recherché ?","options":["Éteindre tous les services publics","Augmenter la puissance partout","Rendre les monuments invisibles en journée","Maintenir la visibilité avec moins d'éclairage"],"correct":"D","explanation":"Le passage indique : « Une ville éclaire moins fortement ses monuments la nuit. Les visiteurs peuvent encore les voir, mais la consommation et la gêne lumineuse diminuent. » Cela justifie la réponse : Maintenir la visibilité avec moins d'éclairage."},{"number":15,"points":15,"passage":"Une ancienne voie d'eau est remise en valeur comme promenade. Des panneaux expliquent son rôle dans le transport des marchandises, pas seulement ses qualités paysagères.\n\nDes photographies montrent les chargements, les chemins utilisés et les bâtiments liés à cette activité. Les promeneurs peuvent comparer ces repères avec ce qui reste visible aujourd'hui. Le projet veut éviter qu'un aménagement agréable efface entièrement le sens du site. Les informations ne demanderont pas aux visiteurs de suivre un cours complet, mais leur donneront des éléments pour comprendre pourquoi la voie existe et comment elle participait à la vie locale.","question":"Que souhaite transmettre l'aménagement ?","options":["Uniquement des conseils de jardinage","Une compréhension de l'histoire du lieu","Une interdiction de marcher","Le programme des trains actuels"],"correct":"B","explanation":"Le passage indique : « Une ancienne voie d'eau est remise en valeur comme promenade. Des panneaux expliquent son rôle dans le transport des marchandises, pas seulement ses qualités paysagères. » Cela justifie la réponse : Une compréhension de l'histoire du lieu."},{"number":16,"points":15,"passage":"Un atelier recueille les souvenirs d'ouvriers d'une usine fermée. Les organisateurs veulent conserver l'expérience des personnes, au-delà des machines déjà exposées.\n\nLes personnes décrivent des horaires, des gestes et des relations que les objets seuls ne permettent pas de connaître. Les récits sont datés et préparés avec les participants, afin d'éviter une image uniforme de toutes les périodes. Le musée souhaite conserver les désaccords et les changements importants lorsqu'ils aident à comprendre l'activité. Il ne présente pas un souvenir individuel comme le résumé de toute l'usine.","question":"Quel aspect du patrimoine est complété ?","options":["Le stock de produits à vendre","Les plans des parkings actuels","La mémoire du travail vécu","Les tarifs des visites"],"correct":"C","explanation":"Le passage indique : « Un atelier recueille les souvenirs d'ouvriers d'une usine fermée. Les organisateurs veulent conserver l'expérience des personnes, au-delà des machines déjà exposées. » Cela justifie la réponse : La mémoire du travail vécu."},{"number":17,"points":15,"passage":"Un immeuble ancien accueille un ascenseur dans une extension discrète. L'objectif est de permettre l'accès tout en limitant les transformations des espaces historiques.\n\nLe parcours d'entrée et les passages entre les salles ont été examinés avec plusieurs usagers. Les spécialistes souhaitent éviter une solution annoncée comme accessible mais difficile à utiliser au quotidien. Le projet ne demande pas de choisir entre l'accueil actuel et la valeur du bâtiment : il cherche une intervention qui réponde réellement aux besoins en limitant les effets sur ce qui doit être préservé pour les visiteurs et les habitants des prochaines années.","question":"Quels besoins sont associés ?","options":["Démolition et publicité","Accessibilité et préservation","Stationnement et circulation rapide","Fermeture et abandon"],"correct":"B","explanation":"Le passage indique : « Un immeuble ancien accueille un ascenseur dans une extension discrète. L'objectif est de permettre l'accès tout en limitant les transformations des espaces historiques. » Cela justifie la réponse : Accessibilité et préservation."},{"number":18,"points":15,"passage":"Une carte présente les fontaines de la ville et indique celles qui délivrent de l'eau potable. Les visiteurs ne doivent pas déduire cette possibilité de leur seule apparence.\n\nCertains bassins ont seulement une fonction décorative, tandis que d'autres sont entretenus pour cet usage précis. Les agents mettront la carte à jour si une installation doit être temporairement arrêtée. Les visiteurs pourront retrouver les indications sur place et signaler un problème. Le service souhaite que l'information reste simple sans encourager une déduction fondée sur le seul aspect de la pierre ou sur la présence d'un robinet.","question":"Quelle précaution est demandée ?","options":["Vérifier la fonction de la fontaine","Boire à toutes les fontaines décoratives","Ignorer les indications","Se fier uniquement à la forme"],"correct":"A","explanation":"Le passage indique : « Une carte présente les fontaines de la ville et indique celles qui délivrent de l'eau potable. Les visiteurs ne doivent pas déduire cette possibilité de leur seule apparence. » Cela justifie la réponse : Vérifier la fonction de la fontaine."},{"number":19,"points":15,"passage":"Une association propose des balades dans les quartiers récents. Elle estime que le patrimoine urbain ne se limite pas aux centres très anciens.\n\nLes guides présentent les choix de construction, les espaces partagés et les transformations demandées par les résidents. Ils recueillent aussi les souvenirs de personnes arrivées lors des premières années. L'association ne prétend pas que chaque bâtiment doit devenir un monument protégé. Elle souhaite ouvrir un regard sur des lieux souvent considérés comme ordinaires et sans histoire.","question":"Quelle idée défend-elle ?","options":["Des constructions récentes méritent aussi d'être comprises","Les quartiers modernes sont tous identiques","Les promenades doivent éviter les habitants","Seuls les châteaux ont une histoire"],"correct":"A","explanation":"Le passage indique : « Une association propose des balades dans les quartiers récents. Elle estime que le patrimoine urbain ne se limite pas aux centres très anciens. » Cela justifie la réponse : Des constructions récentes méritent aussi d'être comprises."},{"number":20,"points":21,"passage":"Une ville transforme une place après une phase d'essai. Les bancs provisoires ont révélé que certains emplacements étaient trop exposés au soleil. Le plan définitif est modifié en conséquence. Les usagers ont pu déplacer les sièges et noter les heures où ils évitaient certains secteurs. Les agents ont également observé les trajets des livraisons et des personnes se déplaçant lentement. Ces retours ont révélé des contraintes absentes des premières images du projet. La ville souhaite que la phase provisoire serve à apprendre quelque chose, et pas seulement à faire accepter un plan déjà arrêté sans possibilité de modification.","question":"À quoi a servi l'essai ?","options":["Confirmer automatiquement le premier plan","Éviter toute consultation","Observer les usages avant de fixer l'aménagement","Réduire le nombre d'arbres sans raison"],"correct":"C","explanation":"Le passage indique : « Une ville transforme une place après une phase d'essai. Les bancs provisoires ont révélé que certains emplacements étaient trop exposés au soleil. Le plan définitif est modifié en conséquence. » Cela justifie la réponse : Observer les usages avant de fixer l'aménagement."},{"number":21,"points":21,"passage":"Un musée raconte l'histoire d'un palais en mentionnant aussi les personnes qui l'entretenaient. Le récit ne se limite plus à ses propriétaires célèbres. Les commissaires souhaitent éviter qu'un grand bâtiment soit raconté uniquement par la vie de quelques figures connues. Les visiteurs pourront relier les pièces à des usages précis et découvrir les tâches nécessaires à leur entretien. Le musée garde les récits célèbres, mais les replace dans une organisation plus large dont dépendait le fonctionnement quotidien du palais.","question":"Quelle évolution du regard est proposée ?","options":["Inclure des acteurs longtemps peu visibles","Remplacer l'histoire par une liste de prix","Présenter uniquement les visiteurs actuels","Supprimer toute information sur le palais"],"correct":"A","explanation":"Le passage indique : « Un musée raconte l'histoire d'un palais en mentionnant aussi les personnes qui l'entretenaient. Le récit ne se limite plus à ses propriétaires célèbres. » Cela justifie la réponse : Inclure des acteurs longtemps peu visibles."},{"number":22,"points":21,"passage":"Une commune garde une ancienne enseigne après la fermeture du commerce. Elle la documente pour qu'elle reste compréhensible aux générations qui n'ont pas connu la boutique. La notice indiquera le type d'activité, sa période et les sources utilisées pour la décrire. Les habitants pourront apporter une précision lors d'une rencontre. Le service ne cherche pas à promettre le retour d'un commerce disparu, mais à garder des repères dans une rue qui change.","question":"Pourquoi ajouter des informations ?","options":["Éviter de mentionner son origine","Préserver le sens de l'objet conservé","Augmenter automatiquement sa valeur","Garantir la réouverture du commerce"],"correct":"B","explanation":"Le passage indique : « Une commune garde une ancienne enseigne après la fermeture du commerce. Elle la documente pour qu'elle reste compréhensible aux générations qui n'ont pas connu la boutique. » Cela justifie la réponse : Préserver le sens de l'objet conservé."},{"number":23,"points":21,"passage":"Des riverains acceptent des événements sur une place historique, mais demandent des horaires et une gestion du bruit. Leur proposition ne vise pas à transformer le lieu en espace sans vie. Ils proposent des jours et des limites discutés avec les organisateurs. Les associations pourront continuer à préparer des fêtes, mais devront prévoir le rangement et l'accès aux logements. Le comité veut éviter un débat réduit à accepter toute activité ou à réclamer le silence permanent.","question":"Quelle position adoptent-ils ?","options":["Réserver la place aux voitures","Interdire toute présence humaine","Accepter toute nuisance","Organiser les usages plutôt que les supprimer"],"correct":"D","explanation":"Le passage indique : « Des riverains acceptent des événements sur une place historique, mais demandent des horaires et une gestion du bruit. Leur proposition ne vise pas à transformer le lieu en espace sans vie. » Cela justifie la réponse : Organiser les usages plutôt que les supprimer."},{"number":24,"points":21,"passage":"La rénovation d'une gare conserve des éléments anciens et améliore l'orientation. Les panneaux patrimoniaux sont placés sans masquer les informations nécessaires aux voyageurs. Les premiers voyageurs essaieront le parcours avec leurs bagages et pourront signaler les points difficiles à comprendre. Les panneaux historiques resteront consultables dans des zones où l'on peut s'arrêter sans bloquer les passages. Le projet souhaite rendre l'histoire visible, sans demander à un usager pressé de traverser une exposition pour trouver sa correspondance.","question":"Quelle priorité pratique demeure ?","options":["Transformer tous les quais en exposition","Permettre aux usagers de se repérer","Limiter l'accès aux historiens","Supprimer les horaires"],"correct":"B","explanation":"Le passage indique : « La rénovation d'une gare conserve des éléments anciens et améliore l'orientation. Les panneaux patrimoniaux sont placés sans masquer les informations nécessaires aux voyageurs. » Cela justifie la réponse : Permettre aux usagers de se repérer."},{"number":25,"points":21,"passage":"Une archive montre un projet jamais construit. Les médiateurs le présentent comme une intention de l'époque, pas comme la preuve d'un état ancien de la ville. La notice expliquera qui avait préparé le plan, dans quelles circonstances et pourquoi il n'a pas été réalisé. Le musée souhaite que les archives servent à comprendre des intentions et des débats, sans transformer toute représentation ancienne en preuve de ce qui a réellement existé sur le terrain.","question":"Quelle distinction est nécessaire ?","options":["Un projet dessiné n'est pas une réalisation","Tout dessin correspond à un bâtiment disparu","La ville n'a connu aucun changement","Une archive ne peut jamais être utile"],"correct":"A","explanation":"Le passage indique : « Une archive montre un projet jamais construit. Les médiateurs le présentent comme une intention de l'époque, pas comme la preuve d'un état ancien de la ville. » Cela justifie la réponse : Un projet dessiné n'est pas une réalisation."},{"number":26,"points":21,"passage":"Une rue reçoit des revêtements moins glissants à proximité d'un monument. L'équipe cherche une solution visuellement discrète, mais refuse que l'apparence rende le passage dangereux. Les essais seront menés avec des personnes utilisant des aides à la marche et avec le service chargé de l'entretien. Les spécialistes devront tenir compte de la pluie et de l'usure, pas seulement de l'aspect le jour de la pose. La commune veut une solution qui reste praticable et lisible, tout en respectant l'ensemble architectural.","question":"Quel équilibre est recherché ?","options":["La suppression de tous les visiteurs","Une imitation des défauts anciens","Un décor sans fonction","Compatibilité visuelle et sécurité d'usage"],"correct":"D","explanation":"Le passage indique : « Une rue reçoit des revêtements moins glissants à proximité d'un monument. L'équipe cherche une solution visuellement discrète, mais refuse que l'apparence rende le passage dangereux. » Cela justifie la réponse : Compatibilité visuelle et sécurité d'usage."},{"number":27,"points":21,"passage":"Une maison d'artiste conserve plusieurs pièces intactes et transforme une autre en espace d'accueil. Le projet distingue les besoins de présentation des conditions nécessaires à la visite. L'équipe prépare les flux de visiteurs, les possibilités de repos et les conditions de surveillance des œuvres. Elle souhaite éviter qu'une ouverture trop fragile oblige ensuite à fermer des salles ou à interrompre les visites.","question":"Pourquoi cette transformation limitée ?","options":["Accueillir le public sans modifier toutes les pièces","Supprimer les œuvres exposées","Reconstruire entièrement la maison","Réserver le lieu aux anciens propriétaires"],"correct":"A","explanation":"Le passage indique : « Une maison d'artiste conserve plusieurs pièces intactes et transforme une autre en espace d'accueil. Le projet distingue les besoins de présentation des conditions nécessaires à la visite. » Cela justifie la réponse : Accueillir le public sans modifier toutes les pièces."},{"number":28,"points":21,"passage":"Des habitants participent au choix de nouveaux noms de rues. Une commission vérifie les propositions pour éviter les doublons qui compliqueraient l'orientation et les secours. Les services vérifient aussi la lisibilité sur les plans et la prononciation possible lors d'un appel. Les propositions historiques ou culturelles seront examinées avec ces contraintes. La commission souhaite que le choix reste compréhensible, plutôt que donner l'impression de rejeter une contribution sans raison.","question":"Quel contrôle accompagne la consultation ?","options":["Le nombre de lettres des habitants","L'âge de tous les participants","La clarté pratique des noms choisis","Le prix des logements"],"correct":"C","explanation":"Le passage indique : « Des habitants participent au choix de nouveaux noms de rues. Une commission vérifie les propositions pour éviter les doublons qui compliqueraient l'orientation et les secours. » Cela justifie la réponse : La clarté pratique des noms choisis."},{"number":29,"points":21,"passage":"Une visite montre des traces de réparations successives sur un bâtiment. Elles témoignent de son histoire matérielle plutôt que d'un état originel resté inchangé. Les médiateurs montrent les différences de matière et expliquent les circonstances connues de chaque réparation. Ils ne cherchent pas à cacher toutes les interventions pour présenter un bâtiment resté inchangé. Le public pourra comprendre comment le lieu a été entretenu, abîmé et adapté selon les périodes.","question":"Que révèlent ces traces ?","options":["L'absence de tout entretien","La succession des interventions dans le temps","La disparition de tous les matériaux anciens","Une construction récente déguisée nécessairement"],"correct":"B","explanation":"Le passage indique : « Une visite montre des traces de réparations successives sur un bâtiment. Elles témoignent de son histoire matérielle plutôt que d'un état originel resté inchangé. » Cela justifie la réponse : La succession des interventions dans le temps."},{"number":30,"points":26,"passage":"La protection d'un centre ancien peut rendre certaines adaptations plus difficiles. Un urbaniste propose de discuter les effets concrets des règles : préserver des qualités ne suppose pas de refuser toute évolution des usages. Les personnes chargées du projet consulteront les usagers et les spécialistes avant de définir les interventions. Elles souhaitent distinguer une transformation nécessaire et une modification qui ne répondrait à aucun besoin clairement expliqué dans le dossier.","question":"Quelle approche est défendue ?","options":["Transformer tous les logements en vitrines","Abandonner toute protection","Appliquer un refus automatique à chaque changement","Examiner comment conservation et adaptation peuvent coexister"],"correct":"D","explanation":"Le passage indique : « La protection d'un centre ancien peut rendre certaines adaptations plus difficiles. Un urbaniste propose de discuter les effets concrets des règles : préserver des qualités ne suppose pas de refuser toute évolution des usages. » Cela justifie la réponse : Examiner comment conservation et adaptation peuvent coexister."},{"number":31,"points":26,"passage":"Un objet quotidien devient une pièce de musée. Sa conservation change le regard porté sur lui, mais peut aussi l'éloigner des gestes qui expliquaient son usage. Les médiateurs ajoutent des démonstrations pour rendre cette dimension perceptible. La démonstration sera présentée comme une interprétation appuyée sur des sources. Elle donnera des repères sur les gestes et les matières, sans faire croire que l'expérience d'un ancien utilisateur peut être entièrement reproduite dans une salle actuelle.","question":"Que cherchent à restituer les démonstrations ?","options":["Le prix actuel de tous les produits","Le contexte pratique de l'objet","La propriété du bâtiment","Une garantie de fabrication moderne"],"correct":"B","explanation":"Le passage indique : « Un objet quotidien devient une pièce de musée. Sa conservation change le regard porté sur lui, mais peut aussi l'éloigner des gestes qui expliquaient son usage. Les médiateurs ajoutent des démonstrations pour rendre cette dimension perceptible. » Cela justifie la réponse : Le contexte pratique de l'objet."},{"number":32,"points":26,"passage":"Les touristes photographient un monument depuis un même point, devenu célèbre en ligne. Le gestionnaire ouvre un second parcours pour montrer des aspects moins connus. Il ne conteste pas la première vue, mais veut éviter qu'elle résume toute l'expérience du lieu. Les nouveaux parcours expliquent d'autres usages et des points de vue complémentaires. Les visiteurs resteront libres de regarder l'image connue, mais disposeront de moyens pour ne pas réduire le site à ce seul cadrage déjà rencontré ailleurs.","question":"Quel objectif poursuit-il ?","options":["Élargir le regard au-delà d'une image dominante","Interdire toute photographie","Fermer les autres chemins","Reproduire partout le même point de vue"],"correct":"A","explanation":"Le passage indique : « Les touristes photographient un monument depuis un même point, devenu célèbre en ligne. Le gestionnaire ouvre un second parcours pour montrer des aspects moins connus. Il ne conteste pas la première vue, mais veut éviter qu'elle résume toute l'expérience du lieu. » Cela justifie la réponse : Élargir le regard au-delà d'une image dominante."},{"number":33,"points":26,"passage":"Une ville restaure un ancien lavoir tout en conservant les marques d'usure. Les pierres abîmées ne sont pas toutes remplacées : certaines portent les traces des gestes répétés. La valeur historique ne se réduit pas à une apparence parfaitement neuve. Le choix de garder une marque n'est donc pas une absence d'intervention, mais une décision à expliquer dans l'ensemble du travail de restauration.","question":"Pourquoi conserver certaines marques ?","options":["Elles témoignent des usages passés","Elles réduisent toujours le coût à zéro","Elles garantissent une meilleure étanchéité","Elles remplacent les informations historiques"],"correct":"A","explanation":"Le passage indique : « Une ville restaure un ancien lavoir tout en conservant les marques d'usure. Les pierres abîmées ne sont pas toutes remplacées : certaines portent les traces des gestes répétés. La valeur historique ne se réduit pas à une apparence parfaitement neuve. » Cela justifie la réponse : Elles témoignent des usages passés."},{"number":34,"points":26,"passage":"Une exposition sur l'urbanisme confronte plans officiels et récits de résidents. Les premiers montrent des intentions et des règles ; les seconds révèlent des usages parfois différents. Comprendre la ville suppose de regarder ce qui a été prévu et ce qui a été vécu. L'exposition ne cherche pas un gagnant entre ces sources, mais ce que leur rapprochement rend visible sur la construction et l'évolution des espaces urbains.","question":"Quelle démarche est proposée ?","options":["Écarter tous les témoignages","Considérer les intentions comme des résultats assurés","Croiser conception et expérience des lieux","Choisir uniquement les plans"],"correct":"C","explanation":"Le passage indique : « Une exposition sur l'urbanisme confronte plans officiels et récits de résidents. Les premiers montrent des intentions et des règles ; les seconds révèlent des usages parfois différents. Comprendre la ville suppose de regarder ce qui a été prévu et ce qui a été vécu. » Cela justifie la réponse : Croiser conception et expérience des lieux."},{"number":35,"points":26,"passage":"La réutilisation d'un bâtiment semble éviter une construction neuve. Son intérêt doit néanmoins être étudié avec les adaptations nécessaires et les besoins futurs. Conserver à tout prix une structure très inadaptée peut déplacer les coûts plutôt que résoudre le problème d'usage. Les études compareront les possibilités avant de choisir. Elles éviteront de considérer la seule présence d'un ancien bâtiment comme une réponse suffisante, sans examiner les travaux qu'il demande pour accueillir correctement les activités prévues.","question":"Quelle réserve est formulée ?","options":["Toute réutilisation est impossible","Une construction neuve est toujours préférable","Le réemploi doit être évalué selon la situation réelle","Les besoins futurs sont sans importance"],"correct":"C","explanation":"Le passage indique : « La réutilisation d'un bâtiment semble éviter une construction neuve. Son intérêt doit néanmoins être étudié avec les adaptations nécessaires et les besoins futurs. Conserver à tout prix une structure très inadaptée peut déplacer les coûts plutôt que résoudre le problème d'usage. » Cela justifie la réponse : Le réemploi doit être évalué selon la situation réelle."},{"number":36,"points":33,"passage":"Un quartier souhaite valoriser son histoire. Les habitants les plus anciens possèdent beaucoup de souvenirs, mais les nouveaux arrivants contribuent aussi à la vie actuelle du lieu. Le projet accueille les deux perspectives. Le patrimoine partagé peut se construire à partir d'héritages différents sans exiger une ancienneté identique pour participer. Les personnes arrivées récemment découvrent les récits anciens et peuvent apporter leurs propres repères. Le comité souhaite que la transmission crée des rencontres plutôt qu'un examen implicite de la légitimité à parler du quartier. Les archives restent importantes, mais ne résument pas toute la vie du lieu. Les prochaines activités associeront donc plusieurs générations et périodes d'installation. Cette ouverture permettra de discuter ce que les habitants partagent et ce qu'ils découvrent différemment, sans exiger qu'ils possèdent les mêmes souvenirs ou qu'un seul groupe définisse définitivement le sens de l'espace commun.","question":"Quelle conception du patrimoine est défendue ?","options":["Un récit sans aucun souvenir local","Une histoire qui efface tous les nouveaux usages","Un héritage ouvert à des contributions diverses","Une mémoire réservée aux résidents les plus anciens"],"correct":"C","explanation":"Le passage indique : « Le patrimoine partagé peut se construire à partir d'héritages différents sans exiger une ancienneté identique pour participer. » Cela justifie la réponse : Un héritage ouvert à des contributions diverses."},{"number":37,"points":33,"passage":"La reconstruction d'une façade disparue peut redonner une image familière à une place. Elle ne restitue pourtant ni tous les matériaux ni toutes les fonctions du bâtiment d'origine. Une ressemblance visuelle doit être distinguée d'une continuité historique complète. Les notices expliqueront la date et les matériaux de la nouvelle intervention. Les visiteurs pourront ainsi apprécier le travail sans le confondre avec un élément resté en place depuis l'origine. Les responsables souhaitent éviter aussi bien la promesse d'un retour complet dans le passé que le refus de reconnaître tout intérêt à la reconstruction. Celle-ci peut modifier une place et transmettre des repères, mais son statut doit rester lisible. Le débat gagnera en précision si chacun sait ce qui a été conservé, ce qui a été étudié et ce qui a été recréé aujourd'hui.","question":"Quelle prudence est recommandée ?","options":["Abandonner toute information sur les transformations","Ne pas confondre restitution d'une apparence et retour intégral du passé","Déduire l'usage actuel de la seule décoration","Considérer toute façade reconstruite comme strictement ancienne"],"correct":"B","explanation":"Le passage indique : « Une ressemblance visuelle doit être distinguée d'une continuité historique complète. » Cela justifie la réponse : Ne pas confondre restitution d'une apparence et retour intégral du passé."},{"number":38,"points":33,"passage":"Une ville veut attirer des visiteurs grâce à un label patrimonial. Certains ateliers et logements risquent de devenir des hébergements touristiques. Le conseil débat donc d'outils pour conserver des fonctions ordinaires. Valoriser un lieu peut fragiliser ce qui le rend habitable si l'attractivité devient son seul objectif. Les élus étudient notamment la place des commerces utiles au quotidien et les possibilités pour les salariés de se loger. Les associations rappellent qu'une rue attractive pour une visite courte peut devenir difficile à vivre si les fonctions ordinaires disparaissent. Le programme cherchera donc des indicateurs qui ne se limitent pas aux entrées dans les monuments. Il devra aussi regarder la stabilité des habitants et l'accès aux services. Le patrimoine est ici lié à une vie présente, dont l'affaiblissement pourrait finir par réduire la diversité et l'intérêt du quartier que l'on souhaite précisément mettre en valeur.","question":"Quel enjeu accompagne la valorisation ?","options":["Supprimer les services ordinaires devenus invisibles","Éviter toute visite extérieure","Préserver une vie locale au-delà de la fréquentation touristique","Transformer systématiquement tous les logements"],"correct":"C","explanation":"Le passage indique : « Valoriser un lieu peut fragiliser ce qui le rend habitable si l'attractivité devient son seul objectif. » Cela justifie la réponse : Préserver une vie locale au-delà de la fréquentation touristique."},{"number":39,"points":33,"passage":"Des archives numérisées rendent une collection plus largement consultable. Pourtant, certaines descriptions reflètent d'anciennes catégories contestées. L'équipe conserve la trace historique tout en ajoutant des explications. Faciliter l'accès à une source ne dispense pas d'aider à comprendre les conditions dans lesquelles elle a été produite. Les utilisateurs pourront voir le vocabulaire d'origine tout en disposant d'une note sur son contexte et sur les limites qu'il comporte aujourd'hui. Les archivistes ne veulent ni corriger silencieusement le passé ni laisser les descriptions anciennes fonctionner comme des catégories naturelles. Ils rendront leurs interventions identifiables pour permettre la recherche. Les documents restent des sources à examiner, pas des récits automatiquement fiables parce qu'ils sont anciens ou désormais disponibles sur un écran. La numérisation élargit les possibilités de consultation, mais elle augmente aussi l'importance des repères qui accompagnent leur lecture par un public nouveau.","question":"Quelle démarche documentaire est choisie ?","options":["Retirer toutes les sources difficiles","Présenter chaque ancienne catégorie comme une vérité actuelle","Remplacer les archives par des récits sans origine","Contextualiser les documents sans effacer leur histoire"],"correct":"D","explanation":"Le passage indique : « Faciliter l'accès à une source ne dispense pas d'aider à comprendre les conditions dans lesquelles elle a été produite. » Cela justifie la réponse : Contextualiser les documents sans effacer leur histoire."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-17','tcf-reading-2026-11-reference-v3',$paper${"id":"tcf-reading-17","version":"tcf-reading-2026-11-reference-v3","title":"TCF Reading · Test 17","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"L'accueil parents-enfants ouvre à neuf heures trente. Les poussettes doivent rester dans l'espace prévu près de l'entrée.\n\nL'équipe vous indiquera ensuite la salle de jeux. Merci de libérer le passage pour les autres familles.","question":"Où déposer les poussettes ?","options":["Dans chaque salle d'activité","Dans l'espace près de l'entrée","Sur l'escalier","Dans la cuisine"],"correct":"B","explanation":"Le passage indique : « L'accueil parents-enfants ouvre à neuf heures trente. Les poussettes doivent rester dans l'espace prévu près de l'entrée. » Cela justifie la réponse : Dans l'espace près de l'entrée."},{"number":2,"points":3,"passage":"La sortie intergénérationnelle est reportée à jeudi. Les inscriptions déjà confirmées restent valables.\n\nLe lieu de rendez-vous reste le même. Merci de prévenir les personnes qui vous accompagnent.","question":"Que doivent savoir les inscrits ?","options":["Ils doivent tous payer une seconde fois","Le groupe change de destination obligatoirement","Leur inscription est conservée","La sortie est annulée définitivement"],"correct":"C","explanation":"Le passage indique : « La sortie intergénérationnelle est reportée à jeudi. Les inscriptions déjà confirmées restent valables. » Cela justifie la réponse : Leur inscription est conservée."},{"number":3,"points":3,"passage":"La permanence familiale reçoit aussi sans enfant. Un parent peut venir seul poser ses questions.\n\nLes échanges sont gratuits et confidentiels. Aucune inscription préalable n'est demandée pour cette première rencontre.","question":"Qui peut être accueilli ?","options":["Seulement les enfants majeurs","Uniquement une famille au complet","Un parent non accompagné","Les professionnels exclusivement"],"correct":"C","explanation":"Le passage indique : « La permanence familiale reçoit aussi sans enfant. Un parent peut venir seul poser ses questions. » Cela justifie la réponse : Un parent non accompagné."},{"number":4,"points":3,"passage":"Le goûter partagé ne demande aucune préparation maison. Des fruits et de l'eau sont déjà prévus.\n\nVous pouvez simplement venir avec votre famille. Merci de signaler les allergies lors de votre inscription à l'accueil.","question":"Que doivent nécessairement préparer les participants ?","options":["Un gâteau chacun","Des boissons sucrées","Un repas complet","Aucun plat n'est obligatoire"],"correct":"D","explanation":"Le passage indique : « Le goûter partagé ne demande aucune préparation maison. Des fruits et de l'eau sont déjà prévus. » Cela justifie la réponse : Aucun plat n'est obligatoire."},{"number":5,"points":9,"passage":"Je garderai les enfants mardi, mais peux-tu les récupérer à dix-sept heures ? Mon rendez-vous suivant ne peut pas être déplacé.\n\nJe préparerai leurs affaires avant ton arrivée et laisserai les manteaux près de la porte. Préviens-moi si tu as besoin de l'adresse exacte.","question":"Quelle contrainte est exprimée ?","options":["Une heure de fin à respecter","Un changement d'école","Une obligation de rester jusqu'au soir","Un refus de toute garde"],"correct":"A","explanation":"Le passage indique : « Je garderai les enfants mardi, mais peux-tu les récupérer à dix-sept heures ? Mon rendez-vous suivant ne peut pas être déplacé. » Cela justifie la réponse : Une heure de fin à respecter."},{"number":6,"points":9,"passage":"Notre groupe de marche accueille aussi les grands-parents sans petits-enfants. Le thème rapproche les générations sans imposer de venir en famille.\n\nLe départ se fait devant le centre social. Le parcours est court et comprend une pause sur la place du village.","question":"Quelle condition n'est pas exigée ?","options":["Respecter le lieu de départ","Prendre connaissance de l'horaire","Être accompagné d'un enfant","Participer à la promenade"],"correct":"C","explanation":"Le passage indique : « Notre groupe de marche accueille aussi les grands-parents sans petits-enfants. Le thème rapproche les générations sans imposer de venir en famille. » Cela justifie la réponse : Être accompagné d'un enfant."},{"number":7,"points":9,"passage":"J'aimerais enregistrer les recettes de grand-mère avec ses explications. La liste des ingrédients seule ne raconte pas ses astuces.\n\nJe pourrais ensuite partager ces souvenirs avec mes cousins qui habitent loin. Veux-tu lui demander si elle accepte que nous venions dimanche avec un microphone ?","question":"Quel aspect veut-on conserver ?","options":["Les horaires de la cuisine","Uniquement les prix des ingrédients","Le nom des magasins","Les gestes et conseils associés à la recette"],"correct":"D","explanation":"Le passage indique : « J'aimerais enregistrer les recettes de grand-mère avec ses explications. La liste des ingrédients seule ne raconte pas ses astuces. » Cela justifie la réponse : Les gestes et conseils associés à la recette."},{"number":8,"points":9,"passage":"La ludothèque prête des jeux de plusieurs âges. L'équipe peut conseiller un jeu utilisable par des enfants de niveaux différents.\n\nLe prêt dure trois semaines. Pensez à vérifier le contenu de la boîte avant de la rapporter à l'accueil.","question":"Quel service est proposé ?","options":["Imposer un jeu unique à toutes les familles","Aider à choisir un jeu partagé","Remplacer les parents pendant une semaine","Vendre tous les jouets neufs"],"correct":"B","explanation":"Le passage indique : « La ludothèque prête des jeux de plusieurs âges. L'équipe peut conseiller un jeu utilisable par des enfants de niveaux différents. » Cela justifie la réponse : Aider à choisir un jeu partagé."},{"number":9,"points":9,"passage":"Je ne pourrai pas venir à la réunion en soirée. Existe-t-il un compte rendu ou un autre moment d'échange ?\n\nJe souhaite comprendre les décisions prises et donner mon avis sur la prochaine sortie. Tu peux me répondre par message.","question":"Que demande cette personne ?","options":["Une dispense de recevoir les informations","Une suppression de la réunion","Un autre accès aux informations et aux échanges","Un changement de tous les participants"],"correct":"C","explanation":"Le passage indique : « Je ne pourrai pas venir à la réunion en soirée. Existe-t-il un compte rendu ou un autre moment d'échange ? » Cela justifie la réponse : Un autre accès aux informations et aux échanges."},{"number":10,"points":9,"passage":"Merci de demander l'accord des familles avant de diffuser les photos de la fête. La présence à l'événement n'autorise pas toute publication.\n\nCertaines familles acceptent les images dans l'album privé du groupe mais pas sur un site accessible à tous. Vérifiez chaque autorisation.","question":"Quelle règle est rappelée ?","options":["Publier automatiquement chaque visage","Vérifier les autorisations de diffusion","Vendre les photos aux invités","Éviter toute prise de vue privée nécessairement"],"correct":"B","explanation":"Le passage indique : « Merci de demander l'accord des familles avant de diffuser les photos de la fête. La présence à l'événement n'autorise pas toute publication. » Cela justifie la réponse : Vérifier les autorisations de diffusion."},{"number":11,"points":15,"passage":"Un centre organise des ateliers où enfants et adultes construisent ensemble. Les tâches sont réparties selon les envies et les capacités, pas seulement selon l'âge.\n\nPour fabriquer une petite étagère, une personne peut mesurer, une autre tenir les pièces et une troisième préparer la peinture. Les animateurs présentent les outils et vérifient leur maniement avant chaque étape. Les rôles peuvent changer pendant la séance afin que chacun découvre plusieurs gestes. Les réalisations seront emportées par les participants après le séchage. Le centre demande simplement de porter des vêtements qui ne craignent pas les taches et de prévenir en cas de besoin particulier.","question":"Quel principe guide la répartition ?","options":["Le statut professionnel des parents","La diversité des contributions possibles","Une hiérarchie fixe par génération","La force physique uniquement"],"correct":"B","explanation":"Le passage indique : « Un centre organise des ateliers où enfants et adultes construisent ensemble. Les tâches sont réparties selon les envies et les capacités, pas seulement selon l'âge. » Cela justifie la réponse : La diversité des contributions possibles."},{"number":12,"points":15,"passage":"Des habitants proposent une bibliothèque de poussettes et de sièges. Le prêt limite l'achat d'objets utilisés pendant de courtes périodes.\n\nLes objets sont nettoyés et vérifiés entre deux prêts. Les familles réservent le matériel dont elles ont besoin pour une visite ou une période de croissance. Une fiche indique les conditions de retour et la disponibilité des équipements. Les réservations seront confirmées par un bénévole avant chaque retrait.","question":"Quel besoin ce service vise-t-il ?","options":["Des meubles définitifs pour chaque maison","Un transport scolaire permanent","Des équipements temporaires","Des réparations industrielles"],"correct":"C","explanation":"Le passage indique : « Des habitants proposent une bibliothèque de poussettes et de sièges. Le prêt limite l'achat d'objets utilisés pendant de courtes périodes. » Cela justifie la réponse : Des équipements temporaires."},{"number":13,"points":15,"passage":"Une association accueille les nouveaux parents sans programme imposé. Les échanges partent des questions du groupe, tout en respectant la confidentialité.\n\nLes rencontres se déroulent dans une salle où chacun peut parler ou simplement écouter. L'animatrice commence par rappeler que les situations sont différentes et qu'aucun témoignage ne sera transmis à l'extérieur. Certains participants évoquent les nuits difficiles, d'autres les démarches à réaliser après une naissance. Une information professionnelle peut être proposée lorsque le groupe le souhaite. Les coordonnées des services compétents restent disponibles à la fin de la séance, sans obligation de poursuivre un accompagnement.","question":"Quelle place est donnée aux participants ?","options":["Appliquer un questionnaire sans discussion","Présenter des informations personnelles obligatoires","Évaluer les autres familles publiquement","Définir les sujets utiles à partir de leurs besoins"],"correct":"D","explanation":"Le passage indique : « Une association accueille les nouveaux parents sans programme imposé. Les échanges partent des questions du groupe, tout en respectant la confidentialité. » Cela justifie la réponse : Définir les sujets utiles à partir de leurs besoins."},{"number":14,"points":15,"passage":"Une maison de retraite invite des lycéens à un atelier radio. Chacun choisit son sujet ; les résidents ne sont pas limités au récit du passé.\n\nLes participants préparent les questions, enregistrent les voix et choisissent les sons qui accompagneront l'émission. Une résidente souhaite parler de musique actuelle tandis qu'un élève s'intéresse aux transformations de son quartier. Le journaliste qui les accompagne explique comment vérifier une information et demander l'autorisation de diffuser une voix. L'émission finale sera écoutée ensemble avant publication. Cette étape permettra à chacun de commenter le montage et de préciser un propos qui aurait été mal compris.","question":"Quelle idée est évitée ?","options":["Accueillir des jeunes visiteurs","Réduire les personnes âgées à leurs souvenirs","Permettre des intérêts communs","Choisir des sujets actuels"],"correct":"B","explanation":"Le passage indique : « Une maison de retraite invite des lycéens à un atelier radio. Chacun choisit son sujet ; les résidents ne sont pas limités au récit du passé. » Cela justifie la réponse : Réduire les personnes âgées à leurs souvenirs."},{"number":15,"points":15,"passage":"Un club ouvre des activités familiales sans exiger un lien de parenté entre accompagnateurs et enfants. Les adultes responsables sont identifiés à l'inscription.\n\nUne tante, un voisin ou un ami peut ainsi accompagner un enfant avec l'autorisation nécessaire. Les organisateurs souhaitent accueillir les différents réseaux de soutien qui existent autour des jeunes. Ils demandent les coordonnées des responsables pour pouvoir les joindre pendant la séance. Les activités sont présentées à l'avance afin de choisir celles qui conviennent aux capacités du groupe. Le mot familial décrit ici une façon de participer ensemble, sans imposer un modèle unique de composition du foyer.","question":"Quelle souplesse est prévue ?","options":["La participation avec un accompagnateur non apparenté","La garde anonyme des enfants","La suppression des inscriptions","L'absence de tout adulte responsable"],"correct":"A","explanation":"Le passage indique : « Un club ouvre des activités familiales sans exiger un lien de parenté entre accompagnateurs et enfants. Les adultes responsables sont identifiés à l'inscription. » Cela justifie la réponse : La participation avec un accompagnateur non apparenté."},{"number":16,"points":15,"passage":"Un atelier aide les familles à organiser des documents communs. Il distingue les pièces utiles à partager et les informations personnelles à conserver séparément.\n\nLes participants classent notamment les contrats, les contacts utiles et les consignes concernant les personnes à prévenir. L'animatrice rappelle qu'une organisation pratique ne donne pas automatiquement le droit de consulter tous les dossiers d'un proche. Chaque personne décide des accès qu'elle souhaite autoriser. Une liste indique où se trouvent les documents sans nécessairement en reproduire le contenu.","question":"Quel apprentissage est proposé ?","options":["Supprimer les documents individuels","Confier toutes les décisions au groupe","Partager sans effacer toute confidentialité","Rendre tous les dossiers publics"],"correct":"C","explanation":"Le passage indique : « Un atelier aide les familles à organiser des documents communs. Il distingue les pièces utiles à partager et les informations personnelles à conserver séparément. » Cela justifie la réponse : Partager sans effacer toute confidentialité."},{"number":17,"points":15,"passage":"Une commune propose des réunions en journée et en soirée. Elle souhaite toucher des familles ayant des horaires de travail différents.\n\nLes premières rencontres avaient lieu à une heure qui convenait surtout aux personnes déjà présentes dans les associations. Les agents ont demandé aux absents quels moments seraient possibles pour eux. Une synthèse commune circulera après chaque séance pour que les échanges ne se divisent pas en deux groupes sans lien. Les familles pourront aussi envoyer une remarque écrite. Le conseil municipal comparera les propositions avant d'arrêter le calendrier du trimestre suivant.","question":"Quel obstacle cherche-t-elle à réduire ?","options":["La présence des nouveaux habitants","L'incompatibilité de certains horaires","Le nombre de salles seulement","Le manque de sujets à discuter"],"correct":"B","explanation":"Le passage indique : « Une commune propose des réunions en journée et en soirée. Elle souhaite toucher des familles ayant des horaires de travail différents. » Cela justifie la réponse : L'incompatibilité de certains horaires."},{"number":18,"points":15,"passage":"Des voisins échangent des heures de garde selon un calendrier. Chacun peut refuser un créneau sans perdre définitivement l'accès au réseau.\n\nLe règlement prévoit une confirmation écrite pour chaque garde et un échange préalable entre les adultes concernés. Les disponibilités sont mises à jour chaque semaine afin d'éviter les malentendus. Un membre peut être très présent pendant les vacances puis beaucoup moins disponible au moment d'un changement professionnel. Le réseau cherche à reconnaître ces variations plutôt qu'à imposer une contribution identique chaque mois.","question":"Quelle règle protège la souplesse du dispositif ?","options":["Le refus ponctuel reste possible","Le calendrier est fixé pour dix ans","Une absence entraîne une exclusion automatique","Toute demande doit être acceptée"],"correct":"A","explanation":"Le passage indique : « Des voisins échangent des heures de garde selon un calendrier. Chacun peut refuser un créneau sans perdre définitivement l'accès au réseau. » Cela justifie la réponse : Le refus ponctuel reste possible."},{"number":19,"points":15,"passage":"Un programme de lecture associe un adulte et un enfant autour d'un livre choisi ensemble. L'objectif est le plaisir de l'échange, pas une note scolaire.\n\nLes bénévoles proposent plusieurs albums, mais le duo peut aussi apporter un ouvrage déjà aimé. On peut s'arrêter sur une image, revenir à une page ou raconter un souvenir évoqué par l'histoire. Les organisateurs espèrent que cette liberté aidera les participants à prendre confiance et à retrouver, plus tard, le chemin de la bibliothèque.","question":"Quelle finalité est privilégiée ?","options":["Partager un moment autour de la lecture","Préparer un concours obligatoire","Mesurer la vitesse de lecture uniquement","Classer les familles"],"correct":"A","explanation":"Le passage indique : « Un programme de lecture associe un adulte et un enfant autour d'un livre choisi ensemble. L'objectif est le plaisir de l'échange, pas une note scolaire. » Cela justifie la réponse : Partager un moment autour de la lecture."},{"number":20,"points":21,"passage":"Une résidence intergénérationnelle prévoit des espaces communs, mais aussi des logements privés. Les relations ne doivent pas devenir une présence collective permanente imposée. Les habitants définissent ensemble les horaires des repas partagés et les modalités de réservation de la salle. Chacun conserve la possibilité de dîner chez soi ou de recevoir ses proches sans participer à l'activité annoncée. Une personne référente intervient en cas de désaccord sur le bruit ou l'entretien. Le projet repose ainsi sur des occasions régulières de se croiser et sur des limites claires qui permettent de choisir son degré de participation.","question":"Quel équilibre est recherché ?","options":["Obligation de participer chaque soir","Séparation complète de toutes les générations","Suppression de tous les espaces privés","Rencontres possibles et respect de l'intimité"],"correct":"D","explanation":"Le passage indique : « Une résidence intergénérationnelle prévoit des espaces communs, mais aussi des logements privés. Les relations ne doivent pas devenir une présence collective permanente imposée. » Cela justifie la réponse : Rencontres possibles et respect de l'intimité."},{"number":21,"points":21,"passage":"Un centre reçoit de moins en moins de familles malgré des activités appréciées. Les entretiens montrent que le trajet en bus a été compliqué par une nouvelle correspondance. Le questionnaire de satisfaction avait été distribué uniquement aux personnes encore présentes. Il ne permettait donc pas de comprendre pourquoi les autres avaient cessé de venir. L'équipe a rappelé plusieurs anciens participants avec leur accord. Ceux-ci ont expliqué que le nouvel itinéraire rendait le retour difficile à l'heure du repas.","question":"Quelle cause possible est identifiée ?","options":["Une difficulté d'accès au lieu","Une absence certaine d'intérêt","Un prix obligatoirement trop élevé","Un manque de jeux dans chaque foyer"],"correct":"A","explanation":"Le passage indique : « Un centre reçoit de moins en moins de familles malgré des activités appréciées. Les entretiens montrent que le trajet en bus a été compliqué par une nouvelle correspondance. » Cela justifie la réponse : Une difficulté d'accès au lieu."},{"number":22,"points":21,"passage":"Des adolescents participent à la conception d'un espace de quartier. Ils demandent un lieu où se rencontrer sans devoir consommer, pas seulement des équipements sportifs. Lors des premières réunions, les adultes avaient surtout discuté du choix des terrains et du matériel. Les jeunes ont décrit leurs habitudes après les cours et leurs difficultés à rester ensemble lorsqu'il pleut. Son fonctionnement sera discuté avec les riverains, afin que les règles répondent aux usages réels et aux contraintes du voisinage.","question":"Quel besoin expriment-ils ?","options":["Un centre commercial obligatoire","Une salle sans possibilité de discussion","Un espace de sociabilité accessible","Une compétition permanente"],"correct":"C","explanation":"Le passage indique : « Des adolescents participent à la conception d'un espace de quartier. Ils demandent un lieu où se rencontrer sans devoir consommer, pas seulement des équipements sportifs. » Cela justifie la réponse : Un espace de sociabilité accessible."},{"number":23,"points":21,"passage":"Une enquête sur les aidants mesure les tâches visibles, puis ajoute le temps consacré à organiser et anticiper. Cette charge moins matérielle était peu décrite dans les premiers résultats. Prendre les rendez-vous, vérifier les renouvellements de documents ou prévoir un remplacement mobilise l'attention même lorsqu'aucun soin n'est réalisé. Plusieurs personnes expliquent qu'elles doivent rester joignables pendant leur travail. La nouvelle enquête demande donc aussi qui coordonne les interventions et avec quelle fréquence.","question":"Quel aspect est mieux pris en compte ?","options":["Le travail d'organisation","La surface des logements uniquement","Le nombre de meubles","Les achats de loisirs"],"correct":"A","explanation":"Le passage indique : « Une enquête sur les aidants mesure les tâches visibles, puis ajoute le temps consacré à organiser et anticiper. Cette charge moins matérielle était peu décrite dans les premiers résultats. » Cela justifie la réponse : Le travail d'organisation."},{"number":24,"points":21,"passage":"Un atelier réunit des personnes qui accompagnent un proche. Les animateurs rappellent que les solutions d'une famille ne conviennent pas automatiquement à toutes les autres. Les horaires professionnels, la distance entre les logements ou l'état de santé du proche modifient ce qui est réalisable. Une proposition peut être discutée comme une piste à adapter, sans devenir une consigne. Les échanges permettent aussi d'identifier les questions qui nécessitent un avis spécialisé.","question":"Quelle prudence est recommandée ?","options":["Adapter les échanges aux situations particulières","Éviter tous les témoignages","Imposer une méthode unique","Considérer les contraintes comme identiques"],"correct":"A","explanation":"Le passage indique : « Un atelier réunit des personnes qui accompagnent un proche. Les animateurs rappellent que les solutions d'une famille ne conviennent pas automatiquement à toutes les autres. » Cela justifie la réponse : Adapter les échanges aux situations particulières."},{"number":25,"points":21,"passage":"Un quartier installe des bancs près de l'aire de jeux. Les adultes peuvent rester confortablement, ce qui facilite aussi la venue des grands-parents et les échanges entre accompagnateurs. Auparavant, plusieurs accompagnateurs partaient rapidement faute de pouvoir s'asseoir. Les nouveaux équipements sont placés à distance raisonnable des jeux, avec une vue dégagée. Elle observera les usages au cours des prochaines semaines avant de décider si d'autres installations sont nécessaires pour rendre le lieu plus accueillant.","question":"Quel effet dépasse le jeu des enfants ?","options":["La fermeture des espaces voisins","Une meilleure possibilité de présence et de rencontre des adultes","Une réduction obligatoire de la durée des sorties","La suppression des activités entre générations"],"correct":"B","explanation":"Le passage indique : « Un quartier installe des bancs près de l'aire de jeux. Les adultes peuvent rester confortablement, ce qui facilite aussi la venue des grands-parents et les échanges entre accompagnateurs. » Cela justifie la réponse : Une meilleure possibilité de présence et de rencontre des adultes."},{"number":26,"points":21,"passage":"Une association propose des conseils aux parents en plusieurs langues. Elle utilise aussi des exemples concrets plutôt que traduire uniquement des termes administratifs difficiles. Une demande d'inscription est ainsi présentée à partir d'un dossier fictif, étape par étape. Les personnes peuvent poser leurs questions oralement et repartir avec un résumé illustré. Les intervenants vérifient que les informations essentielles ont été comprises sans demander aux participants de raconter leur situation devant tout le groupe.","question":"Quelle adaptation complète la traduction ?","options":["Supprimer les informations pratiques","Réserver les échanges aux traducteurs","Ajouter des formulaires plus longs","Rendre le contenu plus compréhensible"],"correct":"D","explanation":"Le passage indique : « Une association propose des conseils aux parents en plusieurs langues. Elle utilise aussi des exemples concrets plutôt que traduire uniquement des termes administratifs difficiles. » Cela justifie la réponse : Rendre le contenu plus compréhensible."},{"number":27,"points":21,"passage":"Des résidents souhaitent un téléphone collectif pour les appels vidéo. L'équipe organise des créneaux accompagnés, car la présence du matériel ne suffit pas à garantir son utilisation. Une première séance permet de régler le volume, de comprendre l'image et d'apprendre à terminer un appel. Les proches reçoivent aussi les horaires auxquels ils peuvent contacter la résidence. Le personnel vérifie que chacun souhaite participer avant d'organiser une conversation.","question":"Quel besoin complémentaire est reconnu ?","options":["La suppression des échanges en personne","L'achat d'un second bâtiment","Un soutien à l'usage","Une obligation d'appeler chaque jour"],"correct":"C","explanation":"Le passage indique : « Des résidents souhaitent un téléphone collectif pour les appels vidéo. L'équipe organise des créneaux accompagnés, car la présence du matériel ne suffit pas à garantir son utilisation. » Cela justifie la réponse : Un soutien à l'usage."},{"number":28,"points":21,"passage":"Une commune associe les enfants à l'évaluation des trajets scolaires. Leur taille et leur expérience font apparaître des obstacles peu visibles pour les adultes. Ils photographient les endroits où leur vue est cachée par un véhicule ou un panneau. Les agents comparent ensuite ces observations avec les mesures de circulation. Cette démarche complète l'expertise technique sans demander aux élèves de décider seuls des travaux. Les premières propositions seront présentées aux familles et testées sur un trajet avant un éventuel élargissement.","question":"Pourquoi leur point de vue est-il utile ?","options":["Il révèle une expérience différente des aménagements","Il garantit l'absence de danger","Il remplace toutes les mesures techniques","Il ne concerne que la décoration des rues"],"correct":"A","explanation":"Le passage indique : « Une commune associe les enfants à l'évaluation des trajets scolaires. Leur taille et leur expérience font apparaître des obstacles peu visibles pour les adultes. » Cela justifie la réponse : Il révèle une expérience différente des aménagements."},{"number":29,"points":21,"passage":"Un groupe organise un échange de savoirs entre générations. Les jeunes ne sont pas toujours les élèves : ils présentent aussi des pratiques que les plus âgés souhaitent découvrir. Une personne âgée peut vouloir découvrir un logiciel et un adolescent apprendre à entretenir une plante. Les organisateurs constituent les petits groupes selon ces envies, plutôt qu'en distribuant les rôles à partir des dates de naissance.","question":"Quelle relation est mise en valeur ?","options":["Une égalité de toutes les expériences sans échange","Une séparation stricte des groupes","Un enseignement réservé aux aînés","Une transmission dans plusieurs sens"],"correct":"D","explanation":"Le passage indique : « Un groupe organise un échange de savoirs entre générations. Les jeunes ne sont pas toujours les élèves : ils présentent aussi des pratiques que les plus âgés souhaitent découvrir. » Cela justifie la réponse : Une transmission dans plusieurs sens."},{"number":30,"points":26,"passage":"La solidarité familiale est parfois supposée disponible sans limite. Elle dépend pourtant du temps, de la proximité et des ressources de chacun. Un service public qui compte uniquement sur elle risque de traiter différemment des personnes ayant les mêmes besoins mais des entourages très différents. Deux voisins âgés, par exemple, peuvent avoir des enfants qui habitent à des distances très différentes. Demander le même soutien à leurs familles ne crée pas les mêmes possibilités concrètes.","question":"Quelle limite de cette supposition est soulignée ?","options":["Les capacités d'aide des entourages sont inégales","Les besoins disparaissent avec des proches","La solidarité ne peut jamais exister","Toutes les familles vivent au même endroit"],"correct":"A","explanation":"Le passage indique : « La solidarité familiale est parfois supposée disponible sans limite. Elle dépend pourtant du temps, de la proximité et des ressources de chacun. Un service public qui compte uniquement sur elle risque de traiter différemment des personnes ayant les mêmes besoins mais des entourages très différents. » Cela justifie la réponse : Les capacités d'aide des entourages sont inégales."},{"number":31,"points":26,"passage":"Une activité dite familiale peut sembler ouverte à tous. Si elle suppose deux adultes disponibles le samedi et une voiture, certaines familles restent à l'écart. Les conditions concrètes de participation comptent autant que le nom accueillant donné au programme. Les organisateurs proposent désormais une inscription individuelle et indiquent les transports possibles. Ils vérifient aussi si le matériel peut être prêté.","question":"Que faut-il examiner ?","options":["La profession des animateurs seulement","Les contraintes implicites de l'organisation","Uniquement le mot utilisé sur l'affiche","Le nombre de couleurs du logo"],"correct":"B","explanation":"Le passage indique : « Une activité dite familiale peut sembler ouverte à tous. Si elle suppose deux adultes disponibles le samedi et une voiture, certaines familles restent à l'écart. Les conditions concrètes de participation comptent autant que le nom accueillant donné au programme. » Cela justifie la réponse : Les contraintes implicites de l'organisation."},{"number":32,"points":26,"passage":"La mémoire familiale se construit avec des récits qui évoluent selon ceux qui les racontent. Des versions différentes ne signifient pas nécessairement qu'une personne cherche à tromper. Elles peuvent refléter des positions, des âges et des expériences distincts dans un même événement. Lors d'un atelier, deux sœurs décrivent ainsi une même fête avec des détails différents. L'animatrice conserve les deux témoignages et précise les circonstances dans lesquelles ils ont été recueillis.","question":"Quelle lecture des désaccords est proposée ?","options":["Un souvenir doit être identique chez tous","L'âge n'influence jamais une perception","Toute différence prouve un mensonge","Des perspectives différentes peuvent expliquer des récits variés"],"correct":"D","explanation":"Le passage indique : « La mémoire familiale se construit avec des récits qui évoluent selon ceux qui les racontent. Des versions différentes ne signifient pas nécessairement qu'une personne cherche à tromper. Elles peuvent refléter des positions, des âges et des expériences distincts dans un même événement. » Cela justifie la réponse : Des perspectives différentes peuvent expliquer des récits variés."},{"number":33,"points":26,"passage":"Un service souhaite soutenir les aidants sans décider à leur place. Il propose des temps de relais et demande régulièrement si les besoins ont changé. L'accompagnement ne consiste pas à fixer une fois pour toutes une solution supposée convenir à toute la durée de la situation. Une aide adaptée à une courte convalescence peut devenir insuffisante lorsque la dépendance s'installe.","question":"Quelle caractéristique du soutien est valorisée ?","options":["L'absence de consultation","Sa capacité d'ajustement","Une disponibilité identique pour tous","Son caractère immuable"],"correct":"B","explanation":"Le passage indique : « Un service souhaite soutenir les aidants sans décider à leur place. Il propose des temps de relais et demande régulièrement si les besoins ont changé. L'accompagnement ne consiste pas à fixer une fois pour toutes une solution supposée convenir à toute la durée de la situation. » Cela justifie la réponse : Sa capacité d'ajustement."},{"number":34,"points":26,"passage":"Un projet rapproche des générations par des activités communes. Les organisateurs évitent de supposer d'avance que les jeunes veulent uniquement du numérique et les anciens uniquement raconter le passé. Les centres d'intérêt réels émergent des rencontres. Les premières séances laissent une place à la discussion et aux propositions spontanées. Un atelier peut ainsi réunir des amateurs de jardinage de plusieurs âges.","question":"Quelle erreur veulent-ils éviter ?","options":["Permettre de nouveaux apprentissages","Organiser des échanges réciproques","Découvrir des intérêts inattendus","Attribuer des goûts fixes selon l'âge"],"correct":"D","explanation":"Le passage indique : « Un projet rapproche des générations par des activités communes. Les organisateurs évitent de supposer d'avance que les jeunes veulent uniquement du numérique et les anciens uniquement raconter le passé. Les centres d'intérêt réels émergent des rencontres. » Cela justifie la réponse : Attribuer des goûts fixes selon l'âge."},{"number":35,"points":26,"passage":"Une consultation compte une réponse par foyer. Des participants soulignent que cette unité peut masquer les besoins différents des personnes qui y vivent. Un avis commun est utile pour certaines questions, mais ne remplace pas toujours l'écoute individuelle. Un adolescent peut demander un espace calme tandis qu'un adulte souhaite surtout un accès plus facile au stationnement. Le questionnaire distingue les avis individuels et les réponses communes.","question":"Quelle limite de la méthode est signalée ?","options":["Les besoins individuels sont impossibles à connaître","Toutes les personnes d'un foyer pensent pareil","Le foyer n'est pas nécessairement une voix homogène","Une réponse familiale est toujours sans intérêt"],"correct":"C","explanation":"Le passage indique : « Une consultation compte une réponse par foyer. Des participants soulignent que cette unité peut masquer les besoins différents des personnes qui y vivent. Un avis commun est utile pour certaines questions, mais ne remplace pas toujours l'écoute individuelle. » Cela justifie la réponse : Le foyer n'est pas nécessairement une voix homogène."},{"number":36,"points":33,"passage":"Une résidence promet de lutter contre la solitude en rapprochant des générations. Elle découvre que la proximité physique facilite certaines rencontres sans garantir la confiance. Des activités choisies et un respect du refus sont nécessaires. Créer les conditions d'une relation ne revient pas à pouvoir l'imposer. Lors des premières semaines, plusieurs habitants se sont sentis obligés d'assister à chaque repas annoncé, de peur de paraître peu sociables. L'équipe a donc précisé que les invitations pouvaient être refusées sans justification. Elle propose aussi des rencontres en petits groupes autour d'intérêts choisis, plutôt qu'un programme collectif quotidien. Les nouveaux arrivants disposent d'un interlocuteur pour poser leurs questions, mais restent libres d'organiser leurs journées. L'évaluation portera sur la qualité des liens décrits par les résidents et sur leur sentiment de pouvoir choisir, pas uniquement sur le nombre de personnes réunies dans la salle commune.","question":"Quelle distinction est essentielle ?","options":["Prévoir une salle et acheter des chaises seulement","Participer à une activité et sortir du bâtiment","Vivre près d'une personne et connaître son âge","Faciliter les liens et obliger à entretenir une relation"],"correct":"D","explanation":"Le passage indique : « Créer les conditions d'une relation ne revient pas à pouvoir l'imposer. » Cela justifie la réponse : Faciliter les liens et obliger à entretenir une relation."},{"number":37,"points":33,"passage":"Une campagne valorise les grands-parents très actifs, toujours disponibles et connectés. Des associations apprécient cette image positive, mais craignent qu'elle devienne une norme excluant les personnes fatiguées ou moins équipées. Combattre un stéréotype ne devrait pas consister à le remplacer par une exigence de performance identique pour tous. Les témoignages retenus montrent surtout des voyages, des activités sportives et des services rendus aux enfants. Ils rendent moins visibles les relations fondées sur une présence discrète, un appel régulier ou un souvenir partagé. Les associations proposent d'élargir la campagne à ces expériences, sans présenter les limitations physiques comme un échec personnel. Une image valorisante peut ouvrir des possibilités, à condition de laisser une place à la diversité des situations et au droit de ne pas correspondre au portrait le plus spectaculaire.","question":"Quelle réserve est exprimée ?","options":["Les personnes âgées ne peuvent jamais être actives","L'équipement numérique définit la valeur d'une personne","Toute campagne positive doit disparaître","Une image valorisante peut devenir une nouvelle norme contraignante"],"correct":"D","explanation":"Le passage indique : « Combattre un stéréotype ne devrait pas consister à le remplacer par une exigence de performance identique pour tous. » Cela justifie la réponse : Une image valorisante peut devenir une nouvelle norme contraignante."},{"number":38,"points":33,"passage":"Des parents sont invités à participer aux activités de l'école. Les personnes disponibles en journée deviennent les interlocuteurs les plus visibles. L'équipe organise d'autres moyens de contribution pour entendre aussi celles qui ne peuvent pas venir. La disponibilité ne doit pas être confondue avec l'intérêt porté à la scolarité. Un questionnaire accessible par téléphone et des entretiens à des horaires variés complètent désormais les réunions habituelles. Des familles peuvent aussi apporter une contribution à distance, par exemple en proposant une lecture ou en commentant une information envoyée par l'équipe. Les enseignants veillent à ne pas réserver les décisions importantes aux échanges informels de fin de matinée. Ils résument les propositions et expliquent les suites qui leur sont données. Cette organisation permet de distinguer les obstacles pratiques d'une absence de volonté, tout en maintenant des occasions de rencontre pour les personnes qui peuvent se déplacer.","question":"Quelle interprétation veut-on éviter ?","options":["Reconnaître des contraintes horaires","Proposer plusieurs façons de participer","Juger l'engagement à partir de la seule présence en journée","Demander l'avis de familles absentes"],"correct":"C","explanation":"Le passage indique : « La disponibilité ne doit pas être confondue avec l'intérêt porté à la scolarité. » Cela justifie la réponse : Juger l'engagement à partir de la seule présence en journée."},{"number":39,"points":33,"passage":"Un atelier réunit des aidants pour partager des pratiques. Les animateurs veillent à ce que l'échange ne transforme pas chacun en responsable de résoudre seul toutes les difficultés. L'entraide peut renforcer les personnes tout en faisant apparaître des besoins qui demandent une réponse collective ou professionnelle. Plusieurs participants décrivent des difficultés à obtenir un remplacement ou à comprendre les dispositifs existants. Le groupe peut partager des coordonnées et préparer des questions, mais il ne dispose ni des moyens ni de l'autorité nécessaires pour créer les services manquants. L'animateur propose donc de transmettre une synthèse anonyme aux organismes concernés, avec l'accord des personnes. Les rencontres restent aussi un espace où exprimer la fatigue sans devoir immédiatement trouver une solution. Reconnaître les limites de l'entraide protège les participants contre une nouvelle obligation de performance et permet de formuler plus clairement les demandes de soutien extérieur.","question":"Quelle complémentarité est défendue ?","options":["Écarter toute aide professionnelle","Associer soutien entre personnes et recours à d'autres ressources","Remplacer tous les services par des proches","Considérer les difficultés comme toujours individuelles"],"correct":"B","explanation":"Le passage indique : « L'entraide peut renforcer les personnes tout en faisant apparaître des besoins qui demandent une réponse collective ou professionnelle. » Cela justifie la réponse : Associer soutien entre personnes et recours à d'autres ressources."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-18','tcf-reading-2026-11-reference-v3',$paper${"id":"tcf-reading-18","version":"tcf-reading-2026-11-reference-v3","title":"TCF Reading · Test 18","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"Le départ vers l'île est avancé à sept heures à cause de la marée. Présentez-vous quinze minutes avant.\n\nLes billets déjà achetés restent valables. Le contrôle des réservations se fera directement sur le quai habituel.","question":"À quelle heure faut-il être présent ?","options":["Six heures","Six heures quarante-cinq","Huit heures","Sept heures quinze"],"correct":"B","explanation":"Le passage indique : « Le départ vers l'île est avancé à sept heures à cause de la marée. Présentez-vous quinze minutes avant. » Cela justifie la réponse : Six heures quarante-cinq."},{"number":2,"points":3,"passage":"Le refuge ne fournit pas de couverture cette semaine. Apportez un sac de couchage même si votre place est réservée.\n\nLe repas du soir est maintenu.","question":"Quel équipement reste nécessaire ?","options":["Une bouteille de gaz","Un sac de couchage","Un oreiller neuf","Une tente obligatoire"],"correct":"B","explanation":"Le passage indique : « Le refuge ne fournit pas de couverture cette semaine. Apportez un sac de couchage même si votre place est réservée. » Cela justifie la réponse : Un sac de couchage."},{"number":3,"points":3,"passage":"La plage surveillée ouvre à onze heures. Avant cet horaire, aucune surveillance de baignade n'est assurée.\n\nLes horaires seront affichés à l'entrée. Renseignez-vous au poste de secours avant de vous installer près de l'eau.","question":"Que précise l'annonce ?","options":["La surveillance est assurée par tous les visiteurs","La surveillance commence à onze heures","La baignade est surveillée toute la nuit","La plage ferme à onze heures"],"correct":"B","explanation":"Le passage indique : « La plage surveillée ouvre à onze heures. Avant cet horaire, aucune surveillance de baignade n'est assurée. » Cela justifie la réponse : La surveillance commence à onze heures."},{"number":4,"points":3,"passage":"Le chemin des falaises est interdit par vent fort. Le parcours intérieur reste accessible.\n\nSuivez les panneaux au départ du parking. La réouverture sera annoncée lorsque les conditions permettront de circuler sans danger.","question":"Quel itinéraire est proposé ?","options":["La route fermée","Le bord des falaises","Le sommet sans balisage","Le parcours intérieur"],"correct":"D","explanation":"Le passage indique : « Le chemin des falaises est interdit par vent fort. Le parcours intérieur reste accessible. » Cela justifie la réponse : Le parcours intérieur."},{"number":5,"points":9,"passage":"Je préfère rester deux nuits au même refuge. Nous pourrons observer le lac sans transporter les sacs toute la journée.\n\nNous pourrions laisser une partie de nos affaires dans la chambre et partir avec un petit sac. Réserve deux places si tu es d'accord.","question":"Quel avantage est recherché ?","options":["Parcourir le plus grand nombre de refuges","Explorer sans porter tout le matériel","Descendre immédiatement en ville","Éviter toute promenade"],"correct":"B","explanation":"Le passage indique : « Je préfère rester deux nuits au même refuge. Nous pourrons observer le lac sans transporter les sacs toute la journée. » Cela justifie la réponse : Explorer sans porter tout le matériel."},{"number":6,"points":9,"passage":"La sortie sur l'estran nécessite des chaussures fermées. Les coquillages observés seront laissés sur place.\n\nLe guide expliquera comment se déplacer sans abîmer le milieu. Pensez aussi à emporter de l'eau pour la promenade.","question":"Quelle règle concerne les animaux observés ?","options":["Ne pas les emporter","Les déposer au musée","Les conserver comme souvenirs","Les vendre au retour"],"correct":"A","explanation":"Le passage indique : « La sortie sur l'estran nécessite des chaussures fermées. Les coquillages observés seront laissés sur place. » Cela justifie la réponse : Ne pas les emporter."},{"number":7,"points":9,"passage":"Le guide propose de partir plus tard : le brouillard devrait se lever. Nous garderons le même parcours si les conditions le permettent.\n\nJe vous enverrai la nouvelle heure de rendez-vous ce soir. Attendez ma confirmation avant de rejoindre le parking de départ demain matin.","question":"Pourquoi modifier le départ ?","options":["Éviter de rencontrer le guide","Changer automatiquement de destination","Attendre une meilleure visibilité","Profiter d'un brouillard plus épais"],"correct":"C","explanation":"Le passage indique : « Le guide propose de partir plus tard : le brouillard devrait se lever. Nous garderons le même parcours si les conditions le permettent. » Cela justifie la réponse : Attendre une meilleure visibilité."},{"number":8,"points":9,"passage":"Pour la croisière d'observation, apportez des vêtements chauds. Le soleil au port ne garantit pas une température agréable en mer.\n\nUn vêtement coupe-vent est conseillé. Les sacs pourront être rangés sous les sièges pendant le trajet.","question":"Quelle précaution est recommandée ?","options":["Prévoir une tenue chaude","Renoncer à toute protection","Se fier uniquement au temps sur le quai","Acheter un vêtement à chaque escale"],"correct":"A","explanation":"Le passage indique : « Pour la croisière d'observation, apportez des vêtements chauds. Le soleil au port ne garantit pas une température agréable en mer. » Cela justifie la réponse : Prévoir une tenue chaude."},{"number":9,"points":9,"passage":"La visite du phare comprend un escalier étroit. Une présentation au pied de la tour est proposée aux personnes qui ne peuvent pas monter.\n\nVous pourrez choisir la formule qui vous convient avant d'acheter votre billet.","question":"Quelle solution alternative existe ?","options":["Un accès à tous les étages par ascenseur","Une fermeture complète aux visiteurs","Une montée en voiture","Une découverte sans ascension"],"correct":"D","explanation":"Le passage indique : « La visite du phare comprend un escalier étroit. Une présentation au pied de la tour est proposée aux personnes qui ne peuvent pas monter. » Cela justifie la réponse : Une découverte sans ascension."},{"number":10,"points":9,"passage":"Je vais louer des jumelles pour cette sortie, puis décider si j'en achète. Je ne connais pas encore le modèle adapté.\n\nLe magasin permet d'essayer plusieurs grossissements. Je demanderai aussi des conseils sur le poids et le confort pendant une longue marche.","question":"Pourquoi louer d'abord ?","options":["Essayer le matériel avant de choisir","Obtenir un achat définitif gratuit","Remplacer les conseils du guide par un tirage au sort","Éviter toute observation"],"correct":"A","explanation":"Le passage indique : « Je vais louer des jumelles pour cette sortie, puis décider si j'en achète. Je ne connais pas encore le modèle adapté. » Cela justifie la réponse : Essayer le matériel avant de choisir."},{"number":11,"points":15,"passage":"Une équipe suit l'évolution d'un glacier grâce à des photographies prises depuis des repères fixes. Des images sans localisation précise seraient plus difficiles à comparer.\n\nLes observateurs reviennent au même endroit à des périodes comparables et notent les conditions de prise de vue. Le cadrage permet de reconnaître les rochers autour de la glace et d'éviter de confondre un changement d'angle avec un recul réel. Les données sont ensuite rapprochées d'autres mesures réalisées sur le terrain. Une photographie spectaculaire prise par un visiteur peut être intéressante, mais elle ne remplace pas à elle seule cette série documentée.","question":"Pourquoi conserver les mêmes repères ?","options":["Garantir l'absence de changement","Modifier artificiellement la taille du glacier","Éviter de noter les dates","Rendre l'évolution observable de manière comparable"],"correct":"D","explanation":"Le passage indique : « Une équipe suit l'évolution d'un glacier grâce à des photographies prises depuis des repères fixes. Des images sans localisation précise seraient plus difficiles à comparer. » Cela justifie la réponse : Rendre l'évolution observable de manière comparable."},{"number":12,"points":15,"passage":"Des visiteurs ramassent des déchets sur la plage, mais laissent les algues échouées. Elles servent d'abri et de ressource à plusieurs espèces.\n\nLes bénévoles utilisent des sacs séparés pour le plastique, le verre et les autres déchets. Un animateur explique au départ ce qui appartient naturellement au milieu et doit y rester. Les enfants peuvent participer avec un adulte. Les organisateurs fourniront des gants et rappelleront les précautions nécessaires.","question":"Pourquoi ne pas retirer les algues ?","options":["Elles ont une fonction dans le milieu","Elles empêchent toute vie animale","Elles remplacent les poubelles","Elles sont toutes dangereuses à toucher"],"correct":"A","explanation":"Le passage indique : « Des visiteurs ramassent des déchets sur la plage, mais laissent les algues échouées. Elles servent d'abri et de ressource à plusieurs espèces. » Cela justifie la réponse : Elles ont une fonction dans le milieu."},{"number":13,"points":15,"passage":"Un port propose des visites de ses métiers. Les parcours changent selon les opérations en cours pour ne pas gêner les travailleurs.\n\nLe guide confirme l'itinéraire juste avant le départ après un échange avec les responsables des quais. Un chargement en cours peut conduire le groupe vers un autre secteur, où les visiteurs découvriront une activité différente. Le billet donne accès à une découverte du port en fonctionnement, sans promettre le passage devant chaque équipement. Le programme rappelle donc que les besoins du travail déterminent certaines étapes de la visite, même lorsque des photographies publicitaires montrent un parcours précis.","question":"Quel besoin encadre la visite ?","options":["Une reproduction identique chaque jour","L'absence de tout contact professionnel","Le maintien de l'activité portuaire","L'arrêt de tous les navires"],"correct":"C","explanation":"Le passage indique : « Un port propose des visites de ses métiers. Les parcours changent selon les opérations en cours pour ne pas gêner les travailleurs. » Cela justifie la réponse : Le maintien de l'activité portuaire."},{"number":14,"points":15,"passage":"Une réserve limite les groupes dans une grotte. Le passage répété modifie les conditions du lieu et peut fragiliser certaines formations.\n\nLes guides expliquent notamment que la présence des visiteurs peut modifier l'humidité et apporter des éléments extérieurs. Le nombre de places a été fixé à partir d'observations régulières, et sera révisé si l'état du site le nécessite. Une réservation évite aux groupes de se présenter tous au même moment. Les personnes qui ne peuvent pas entrer disposent d'une présentation filmée à l'accueil. La réserve souhaite ainsi rendre la découverte possible tout en surveillant les effets concrets de son ouverture au public.","question":"Pourquoi encadrer la fréquentation ?","options":["Accélérer la formation des roches","Préserver un milieu sensible","Transformer la grotte en parking","Garantir un éclairage permanent"],"correct":"B","explanation":"Le passage indique : « Une réserve limite les groupes dans une grotte. Le passage répété modifie les conditions du lieu et peut fragiliser certaines formations. » Cela justifie la réponse : Préserver un milieu sensible."},{"number":15,"points":15,"passage":"Une association enseigne la lecture d'une carte avant d'utiliser le téléphone en randonnée. Les participants doivent pouvoir s'orienter si la batterie se vide.\n\nL'atelier commence par le repérage de quelques éléments visibles autour du village. Les participants apprennent ensuite à relier ces repères au dessin et à utiliser la légende. Le téléphone reste utile pour préparer le trajet ou confirmer une position, mais ne constitue pas l'unique ressource du groupe. Chaque équipe emporte une carte imprimée protégée de la pluie. Le guide vérifie enfin que chacun comprend le chemin de retour et les points où il sera possible de demander de l'aide.","question":"Quel objectif est poursuivi ?","options":["Conserver une solution de repli","Suivre uniquement les autres marcheurs","Interdire tout appareil numérique","Éviter d'apprendre les repères"],"correct":"A","explanation":"Le passage indique : « Une association enseigne la lecture d'une carte avant d'utiliser le téléphone en randonnée. Les participants doivent pouvoir s'orienter si la batterie se vide. » Cela justifie la réponse : Conserver une solution de repli."},{"number":16,"points":15,"passage":"Des pêcheurs photographient certaines captures puis les relâchent selon le protocole de suivi. Les images servent à identifier les individus observés.\n\nLes participants reçoivent une fiche indiquant les angles de vue nécessaires et les informations à noter. Une image floue ou sans date peut être difficile à exploiter. Les données sont transmises à l'équipe scientifique, qui vérifie si le même animal a été signalé auparavant. Les pêcheurs ne doivent pas prolonger la manipulation pour obtenir une image plus esthétique.","question":"Quel usage est fait des photographies ?","options":["Vendre toutes les captures","Participer à un suivi des animaux","Décorer les billets de bateau","Remplacer les règles de navigation"],"correct":"B","explanation":"Le passage indique : « Des pêcheurs photographient certaines captures puis les relâchent selon le protocole de suivi. Les images servent à identifier les individus observés. » Cela justifie la réponse : Participer à un suivi des animaux."},{"number":17,"points":15,"passage":"Un parc conseille de rester sur les sentiers même lorsque les plantes semblent résistantes. Des passages dispersés peuvent fragiliser progressivement le sol.\n\nUne empreinte isolée paraît parfois sans conséquence, mais les passages répétés élargissent progressivement les zones dénudées. L'eau s'y écoule autrement et peut emporter les couches les plus fines. Des panneaux montrent l'évolution de plusieurs secteurs suivis depuis quelques années. Les visiteurs sont invités à utiliser les points d'arrêt aménagés pour observer le paysage ou prendre des photographies. Le parc vérifie également que les sentiers officiels restent praticables, afin que cette recommandation soit réellement facile à suivre.","question":"Quel effet veut-on limiter ?","options":["La lecture des panneaux","La croissance normale des fleurs","L'usure cumulée du milieu","La diversité des itinéraires autorisés"],"correct":"C","explanation":"Le passage indique : « Un parc conseille de rester sur les sentiers même lorsque les plantes semblent résistantes. Des passages dispersés peuvent fragiliser progressivement le sol. » Cela justifie la réponse : L'usure cumulée du milieu."},{"number":18,"points":15,"passage":"Une école de voile organise une séance à terre lorsque la météo empêche de sortir. Les élèves travaillent alors les nœuds et la préparation du bateau.\n\nLes moniteurs utilisent un mât d'entraînement et des cordages pour préparer les prochaines navigations. Les élèves repèrent aussi les éléments à contrôler avant le départ. La séance conserve ainsi un objectif pédagogique même sans déplacement sur l'eau. Le centre informe les familles dès que la décision est prise et explique les raisons du changement.","question":"Comment la formation continue-t-elle ?","options":["Par la vente des bateaux","Par l'arrêt définitif des cours","Par une sortie malgré l'interdiction","Par des apprentissages sans navigation"],"correct":"D","explanation":"Le passage indique : « Une école de voile organise une séance à terre lorsque la météo empêche de sortir. Les élèves travaillent alors les nœuds et la préparation du bateau. » Cela justifie la réponse : Par des apprentissages sans navigation."},{"number":19,"points":15,"passage":"Un musée du littoral présente les variations du trait de côte. Les cartes anciennes sont comparées aux relevés actuels, sans supposer que le rivage a toujours été fixe.\n\nL'exposition présente les sources utilisées et leurs limites de précision. Une ancienne carte peut décrire les accès d'un port sans relever chaque détail de la plage. Les visiteurs découvrent comment les spécialistes croisent plusieurs documents avant de parler d'un déplacement du rivage.","question":"Quelle idée est mise en évidence ?","options":["Les relevés actuels suffisent à décrire tous les siècles","Les cartes anciennes sont toutes inutiles","La côte reste identique partout","Le littoral évolue dans le temps"],"correct":"D","explanation":"Le passage indique : « Un musée du littoral présente les variations du trait de côte. Les cartes anciennes sont comparées aux relevés actuels, sans supposer que le rivage a toujours été fixe. » Cela justifie la réponse : Le littoral évolue dans le temps."},{"number":20,"points":21,"passage":"Une station de montagne diversifie ses activités au-delà du ski. Les parcours à pied et les rencontres culturelles utilisent des ressources différentes, mais demandent aussi une organisation adaptée. Les accompagnateurs doivent être formés et les itinéraires entretenus en dehors de la saison habituelle. Certains commerces adaptent leurs horaires pour accueillir un public différent. La commune consulte les habitants afin de ne pas concentrer toutes les nouveautés sur les lieux déjà très fréquentés. Elle veut aussi vérifier que les recettes et les emplois ne dépendent pas simplement d'un changement d'affiche.","question":"Quel enjeu accompagne cette diversification ?","options":["Fermer tous les équipements existants","Garantir de la neige toute l'année","Construire des offres qui ne dépendent pas uniquement du ski","Transformer chaque habitant en moniteur"],"correct":"C","explanation":"Le passage indique : « Une station de montagne diversifie ses activités au-delà du ski. Les parcours à pied et les rencontres culturelles utilisent des ressources différentes, mais demandent aussi une organisation adaptée. » Cela justifie la réponse : Construire des offres qui ne dépendent pas uniquement du ski."},{"number":21,"points":21,"passage":"Une commune aménage un accès à la mer sans retirer toute la végétation. Les plantes stabilisent certaines zones et participent au fonctionnement des dunes. Les visiteurs circuleront sur un passage qui évite les secteurs les plus fragiles. Les services techniques prévoient des contrôles après les tempêtes et une signalisation compréhensible depuis le parking. Des habitants avaient demandé un dégagement plus large pour voir directement l'eau ; le projet explique pourquoi cette demande ne peut pas être satisfaite partout.","question":"Quel équilibre est recherché ?","options":["Permettre l'accès en préservant des fonctions naturelles","Supprimer la végétation pour mieux la protéger","Interdire toute présence humaine","Remplacer toutes les dunes par du béton"],"correct":"A","explanation":"Le passage indique : « Une commune aménage un accès à la mer sans retirer toute la végétation. Les plantes stabilisent certaines zones et participent au fonctionnement des dunes. » Cela justifie la réponse : Permettre l'accès en préservant des fonctions naturelles."},{"number":22,"points":21,"passage":"Des chercheurs observent les oiseaux depuis un abri éloigné. Ils acceptent de voir moins de détails afin de réduire la perturbation des colonies. L'abri permet de rester longtemps au même endroit sans multiplier les déplacements près des nids. Les observations sont notées selon une méthode commune pour être comparées d'une séance à l'autre. Lorsque la visibilité est mauvaise, certaines informations restent inconnues et sont signalées comme telles. Les chercheurs préfèrent conserver cette limite plutôt que s'approcher davantage pour compléter chaque case.","question":"Quel compromis est choisi ?","options":["S'approcher toujours davantage","Faire sortir les oiseaux de leurs refuges","Limiter l'observation pour respecter les animaux","Éclairer les nids en continu"],"correct":"C","explanation":"Le passage indique : « Des chercheurs observent les oiseaux depuis un abri éloigné. Ils acceptent de voir moins de détails afin de réduire la perturbation des colonies. » Cela justifie la réponse : Limiter l'observation pour respecter les animaux."},{"number":23,"points":21,"passage":"Une promenade littorale est déplacée après l'érosion d'une portion de falaise. Les responsables expliquent que maintenir exactement l'ancien tracé serait coûteux et dangereux. Le nouveau parcours passe plus à l'intérieur des terres et rejoint le belvédère par une pente douce. Des panneaux expliquent les raisons du déplacement avec des photographies datées. Les habitants pourront signaler les difficultés d'accès rencontrées pendant les premières semaines. Les services surveilleront aussi la partie fermée, car l'installation d'une barrière ne met pas fin au phénomène naturel.","question":"Quelle réponse est adoptée ?","options":["Supprimer toute information de sécurité","Reconstruire systématiquement chaque mètre au même endroit","Garantir l'immobilité de la falaise","Adapter le parcours à l'évolution du site"],"correct":"D","explanation":"Le passage indique : « Une promenade littorale est déplacée après l'érosion d'une portion de falaise. Les responsables expliquent que maintenir exactement l'ancien tracé serait coûteux et dangereux. » Cela justifie la réponse : Adapter le parcours à l'évolution du site."},{"number":24,"points":21,"passage":"Un refuge mesure ses besoins en eau avant d'augmenter sa capacité. Accueillir plus de personnes n'est possible que si les ressources et les équipements suivent. Les responsables examinent les réserves disponibles en fin de saison et le fonctionnement de l'assainissement. Ils prennent en compte les visiteurs de passage, qui utilisent également les installations. Plusieurs solutions seront comparées avant de décider du nombre de lits supplémentaire. Le projet pourrait être revu à la baisse si les besoins dépassent les possibilités du lieu.","question":"Quelle condition limite l'agrandissement ?","options":["La longueur du nom du refuge","La couleur des couvertures","La capacité réelle des ressources et des services","Le nombre de photos en ligne"],"correct":"C","explanation":"Le passage indique : « Un refuge mesure ses besoins en eau avant d'augmenter sa capacité. Accueillir plus de personnes n'est possible que si les ressources et les équipements suivent. » Cela justifie la réponse : La capacité réelle des ressources et des services."},{"number":25,"points":21,"passage":"Une sortie d'observation annonce des espèces possibles, pas une rencontre garantie. Le guide rappelle que les animaux restent libres et que l'absence d'apparition ne signifie pas que le milieu est vide. L'itinéraire suit les conditions du jour et les observations récentes, sans poursuivre les animaux lorsqu'ils s'éloignent. Une partie de la séance est consacrée aux traces, aux habitats et aux techniques de repérage. Les participants repartent donc avec des connaissances même si aucune espèce spectaculaire ne se montre.","question":"Quelle attente est corrigée ?","options":["Accepter un parcours encadré","S'intéresser à la vie animale","Confondre possibilité d'observer et spectacle assuré","Prévoir des conditions météo"],"correct":"C","explanation":"Le passage indique : « Une sortie d'observation annonce des espèces possibles, pas une rencontre garantie. Le guide rappelle que les animaux restent libres et que l'absence d'apparition ne signifie pas que le milieu est vide. » Cela justifie la réponse : Confondre possibilité d'observer et spectacle assuré."},{"number":26,"points":21,"passage":"Une ville portuaire expose des objets trouvés lors d'un chantier. Leur emplacement de découverte est documenté, car un objet isolé de son contexte perd une partie des informations qu'il peut apporter. Les archéologues relèvent aussi les éléments proches et les couches dans lesquelles chaque découverte apparaît. Ces indications peuvent renseigner sur la date, les usages ou les échanges commerciaux. Dans l'exposition, une photographie du chantier accompagne les principales pièces.","question":"Pourquoi noter cet emplacement ?","options":["Garantir sa vente rapide","Éviter de décrire sa matière","Comprendre la relation entre l'objet et son contexte","Augmenter son poids"],"correct":"C","explanation":"Le passage indique : « Une ville portuaire expose des objets trouvés lors d'un chantier. Leur emplacement de découverte est documenté, car un objet isolé de son contexte perd une partie des informations qu'il peut apporter. » Cela justifie la réponse : Comprendre la relation entre l'objet et son contexte."},{"number":27,"points":21,"passage":"Un parc autorise certains accès en hiver et les ferme au printemps pendant la reproduction. La règle suit les besoins du milieu plutôt qu'un calendrier touristique identique toute l'année. Les gardes expliquent les périodes sensibles sur les panneaux et proposent des itinéraires de remplacement. Les dates sont réévaluées à partir des observations, car la reproduction ne commence pas toujours exactement au même moment.","question":"Quelle logique organise l'accès ?","options":["L'adaptation aux périodes sensibles","Le seul nombre d'hôtels","L'ouverture permanente sans condition","La fermeture selon le prix des billets"],"correct":"A","explanation":"Le passage indique : « Un parc autorise certains accès en hiver et les ferme au printemps pendant la reproduction. La règle suit les besoins du milieu plutôt qu'un calendrier touristique identique toute l'année. » Cela justifie la réponse : L'adaptation aux périodes sensibles."},{"number":28,"points":21,"passage":"Des habitants comparent les récits d'une grande tempête avec des relevés officiels. Les souvenirs décrivent les effets vécus ; les mesures situent l'événement dans une série plus longue. Les habitants situent les routes coupées, les maisons atteintes et les décisions prises pendant la nuit. Les relevés permettent de comparer la force du vent et la hauteur de l'eau avec d'autres épisodes. Le projet conserve la distinction entre ces sources au lieu de demander à chacune de fournir les mêmes informations.","question":"Pourquoi croiser ces sources ?","options":["Déclarer les souvenirs inutiles","Remplacer les mesures par une seule émotion","Associer expérience locale et comparaison temporelle","Garantir une prévision exacte de la prochaine tempête"],"correct":"C","explanation":"Le passage indique : « Des habitants comparent les récits d'une grande tempête avec des relevés officiels. Les souvenirs décrivent les effets vécus ; les mesures situent l'événement dans une série plus longue. » Cela justifie la réponse : Associer expérience locale et comparaison temporelle."},{"number":29,"points":21,"passage":"Une entreprise propose des excursions plus lentes en bateau. Elle réduit le nombre de sites visités pour consacrer davantage de temps à l'observation et à l'explication. Les guides peuvent arrêter le moteur à certains moments pour écouter les sons du milieu. Les clients sont informés du programme avant de réserver afin d'éviter de confondre cette formule avec un circuit rapide.","question":"Quel choix est assumé ?","options":["Garantir toutes les rencontres animales","Approfondir plutôt que multiplier les étapes","Voir chaque site le plus rapidement possible","Supprimer le rôle du guide"],"correct":"B","explanation":"Le passage indique : « Une entreprise propose des excursions plus lentes en bateau. Elle réduit le nombre de sites visités pour consacrer davantage de temps à l'observation et à l'explication. » Cela justifie la réponse : Approfondir plutôt que multiplier les étapes."},{"number":30,"points":26,"passage":"La beauté d'un paysage peut donner l'impression d'un espace sans travail humain. Pourtant, terrasses, pâtures et chemins résultent souvent d'un entretien continu. Une visite guidée rend ces activités visibles sans nier les processus naturels qui façonnent aussi le lieu. Des éleveurs expliquent par exemple comment leur activité maintient certains espaces ouverts. Les visiteurs découvrent aussi les difficultés d'accès aux parcelles et les changements liés aux saisons. Cette lecture du paysage fait apparaître des décisions économiques et sociales derrière une vue souvent présentée comme uniquement naturelle.","question":"Quel regard est proposé ?","options":["Réduire le paysage à une décoration immobile","Ignorer les pratiques d'entretien","Comprendre l'interaction entre activités humaines et milieu","Présenter toute montagne comme entièrement artificielle"],"correct":"C","explanation":"Le passage indique : « La beauté d'un paysage peut donner l'impression d'un espace sans travail humain. Pourtant, terrasses, pâtures et chemins résultent souvent d'un entretien continu. Une visite guidée rend ces activités visibles sans nier les processus naturels qui façonnent aussi le lieu. » Cela justifie la réponse : Comprendre l'interaction entre activités humaines et milieu."},{"number":31,"points":26,"passage":"Une carte de risques n'annonce pas qu'un événement touchera chaque parcelle à une date précise. Elle décrit des zones et des probabilités utiles à la décision. La lire comme une prédiction individuelle certaine conduirait à des attentes que l'outil ne peut pas satisfaire. Les services accompagnent donc la carte d'exemples et d'une explication des marges d'incertitude. Une zone peu exposée ne signifie pas que tout danger y est absent.","question":"Quelle distinction est nécessaire ?","options":["Prévention et interdiction de décider","Évaluation du risque et prédiction exacte","Carte et absence totale de données","Probabilité et certitude absolue"],"correct":"B","explanation":"Le passage indique : « Une carte de risques n'annonce pas qu'un événement touchera chaque parcelle à une date précise. Elle décrit des zones et des probabilités utiles à la décision. La lire comme une prédiction individuelle certaine conduirait à des attentes que l'outil ne peut pas satisfaire. » Cela justifie la réponse : Évaluation du risque et prédiction exacte."},{"number":32,"points":26,"passage":"Un équipement touristique peut faciliter la découverte d'un site tout en augmentant sa fréquentation. Les responsables étudient donc les effets de la nouvelle accessibilité avant d'agrandir davantage. Un aménagement utile individuellement peut créer une pression collective supplémentaire. Un parking plus grand peut ainsi modifier les heures d'arrivée et les déplacements sur les chemins. Les gestionnaires suivent ces changements pendant une saison avant de prévoir de nouvelles capacités. Ils cherchent à comprendre l'ensemble des effets du projet.","question":"Quel effet indirect faut-il examiner ?","options":["L'augmentation possible de la pression des visiteurs","La stabilité garantie du nombre de visiteurs","L'inutilité de toute observation","La disparition automatique du tourisme"],"correct":"A","explanation":"Le passage indique : « Un équipement touristique peut faciliter la découverte d'un site tout en augmentant sa fréquentation. Les responsables étudient donc les effets de la nouvelle accessibilité avant d'agrandir davantage. Un aménagement utile individuellement peut créer une pression collective supplémentaire. » Cela justifie la réponse : L'augmentation possible de la pression des visiteurs."},{"number":33,"points":26,"passage":"Un littoral évolue malgré des ouvrages de protection. Certains habitants demandent d'adapter les usages plutôt que renforcer sans cesse les mêmes défenses. Le débat ne sépare pas simplement ceux qui protègent et ceux qui abandonnent : il porte aussi sur ce qui peut être maintenu et à quel coût. Les propositions comparent les dépenses sur plusieurs années et les conséquences pour les habitants concernés.","question":"Quelle lecture du débat est défendue ?","options":["Écarter tous les habitants concernés","Opposer uniquement courage et abandon","Supposer les ouvrages sans limites","Comparer différentes manières de s'adapter"],"correct":"D","explanation":"Le passage indique : « Un littoral évolue malgré des ouvrages de protection. Certains habitants demandent d'adapter les usages plutôt que renforcer sans cesse les mêmes défenses. Le débat ne sépare pas simplement ceux qui protègent et ceux qui abandonnent : il porte aussi sur ce qui peut être maintenu et à quel coût. » Cela justifie la réponse : Comparer différentes manières de s'adapter."},{"number":34,"points":26,"passage":"Une station mesure sa réussite au nombre de nuitées. Une association propose aussi d'examiner les ressources consommées et la qualité des emplois. Une hausse de fréquentation peut produire des bénéfices tout en accentuant des contraintes mal décrites par le seul volume des séjours. Le bilan peut distinguer les emplois saisonniers des emplois durables et regarder les déplacements nécessaires pour travailler.","question":"Quelle évaluation est proposée ?","options":["Un bilan des bénéfices et des contraintes","Un classement fondé uniquement sur les nuitées","Une suppression de toutes les données","Un refus de tout séjour extérieur"],"correct":"A","explanation":"Le passage indique : « Une station mesure sa réussite au nombre de nuitées. Une association propose aussi d'examiner les ressources consommées et la qualité des emplois. Une hausse de fréquentation peut produire des bénéfices tout en accentuant des contraintes mal décrites par le seul volume des séjours. » Cela justifie la réponse : Un bilan des bénéfices et des contraintes."},{"number":35,"points":26,"passage":"La découverte d'un espace naturel peut sensibiliser à sa protection. Elle peut aussi l'abîmer si les conditions de visite sont mal organisées. Le lien entre fréquentation et préservation n'est donc ni automatique ni nécessairement impossible : il dépend des usages et de leur encadrement. Des visites limitées et accompagnées peuvent financer un suivi du site et transmettre des connaissances. À l'inverse, une publicité sans préparation peut concentrer trop de personnes sur des passages fragiles.","question":"Quelle position résume le texte ?","options":["Toute découverte détruit nécessairement le milieu","Aucune règle ne peut influencer les usages","Toute fréquentation protège forcément le site","La visite peut soutenir la protection sous certaines conditions"],"correct":"D","explanation":"Le passage indique : « La découverte d'un espace naturel peut sensibiliser à sa protection. Elle peut aussi l'abîmer si les conditions de visite sont mal organisées. Le lien entre fréquentation et préservation n'est donc ni automatique ni nécessairement impossible : il dépend des usages et de leur encadrement. » Cela justifie la réponse : La visite peut soutenir la protection sous certaines conditions."},{"number":36,"points":33,"passage":"Un sentier réputé facile attire de nombreux débutants. La description indique une faible distance, mais ne mentionne pas un passage très exposé. Des guides demandent de compléter l'information. Une difficulté globale ne se déduit pas d'un seul chiffre lorsque certaines portions exigent des capacités particulières. Le nouveau descriptif séparera la longueur, le dénivelé, la nature du sol et les passages où une chute aurait des conséquences importantes. Des photographies datées montreront les portions qui prêtent le plus à confusion. Les accompagnateurs rappellent aussi que la pluie, la chaleur ou la fatigue peuvent modifier l'expérience d'un même trajet. Ils souhaitent donner aux visiteurs les moyens de comparer le parcours à leurs capacités et à leur équipement. La mention facile pourra rester un repère, mais elle sera accompagnée d'informations qui permettent de comprendre à quelles conditions elle correspond et quand choisir un autre itinéraire.","question":"Quelle limite de l'annonce est soulignée ?","options":["Un débutant doit connaître tous les chemins","La distance ne suffit pas à apprécier la difficulté","Un trajet court est toujours sans risque","Le nombre de visiteurs remplace toute description"],"correct":"B","explanation":"Le passage indique : « Une difficulté globale ne se déduit pas d'un seul chiffre lorsque certaines portions exigent des capacités particulières. » Cela justifie la réponse : La distance ne suffit pas à apprécier la difficulté."},{"number":37,"points":33,"passage":"La restauration d'une dune peut sembler désordonnée : clôtures légères, plantes irrégulières, zones fermées. Certains visiteurs préfèrent un rivage entièrement dégagé. Les gestionnaires expliquent les fonctions du dispositif. Ce qui paraît moins soigné selon des critères décoratifs peut mieux répondre aux besoins du milieu. Les clôtures retiennent le sable et orientent les passages vers des accès précis. Certaines plantes installent leurs racines dans des secteurs qui semblaient auparavant vides, tandis que d'autres apparaissent plus lentement. Des panneaux présentent les étapes attendues de la restauration avec des images prises au même endroit. Les gestionnaires reconnaissent que le changement peut surprendre et organisent des visites pour répondre aux questions. Ils distinguent toutefois la perception esthétique immédiate du fonctionnement écologique observé sur plusieurs saisons.","question":"Quelle distinction est proposée ?","options":["Apparence ordonnée et fonctionnement écologique","Dune naturelle et lieu sans aucune évolution","Plantes et décoration nécessairement identiques","Accès gratuit et absence de végétation"],"correct":"A","explanation":"Le passage indique : « Ce qui paraît moins soigné selon des critères décoratifs peut mieux répondre aux besoins du milieu. » Cela justifie la réponse : Apparence ordonnée et fonctionnement écologique."},{"number":38,"points":33,"passage":"Une destination valorise des images de solitude et de nature intacte. Le succès de ces images attire pourtant une fréquentation importante vers quelques lieux précis. La promesse qui motive la visite peut être fragilisée par l'ampleur même du public qu'elle attire. Des files d'attente apparaissent désormais devant les points de vue les plus diffusés sur les réseaux. Les visiteurs cherchent souvent à reproduire exactement la photographie qui leur a donné envie de venir. Les responsables du territoire réfléchissent donc à une communication plus précise sur les périodes fréquentées et les possibilités de découverte ailleurs. Ils ne souhaitent pas simplement déplacer la foule vers un autre endroit fragile. Les habitants et les gestionnaires seront associés au choix des itinéraires et aux limites d'accueil. L'objectif est de rendre l'expérience annoncée compatible avec la capacité réelle des lieux et avec la vie locale.","question":"Quel paradoxe apparaît ?","options":["Les lieux très connus restent toujours déserts","La publicité n'influence aucun trajet","L'absence d'images garantit des visiteurs nombreux","La popularité menace parfois l'expérience annoncée"],"correct":"D","explanation":"Le passage indique : « La promesse qui motive la visite peut être fragilisée par l'ampleur même du public qu'elle attire. » Cela justifie la réponse : La popularité menace parfois l'expérience annoncée."},{"number":39,"points":33,"passage":"Un village de montagne veut conserver ses activités toute l'année. Il développe des offres nouvelles, mais vérifie aussi le logement des salariés et l'accès aux services. Diversifier les loisirs ne suffit pas si les personnes qui font fonctionner le territoire ne peuvent pas y vivre dans des conditions stables. Les commerçants expliquent qu'ils peuvent ouvrir plus longtemps seulement s'ils trouvent du personnel disponible. Les salariés évoquent pour leur part les loyers, les trajets et la fermeture de certains services hors saison. Le conseil municipal examine donc ces questions avec le programme touristique, plutôt que de les traiter après le lancement des nouvelles offres. Une activité supplémentaire peut renforcer le territoire si elle s'appuie sur des conditions de travail et d'habitat durables. Le bilan portera sur la continuité des emplois, l'accès aux besoins quotidiens et les retours des habitants, en complément des chiffres de fréquentation.","question":"Quelle condition complète la diversification touristique ?","options":["La multiplication des affiches uniquement","La fermeture des services ordinaires","La priorité absolue aux résidences vides","Le maintien de conditions de vie pour les travailleurs"],"correct":"D","explanation":"Le passage indique : « Diversifier les loisirs ne suffit pas si les personnes qui font fonctionner le territoire ne peuvent pas y vivre dans des conditions stables. » Cela justifie la réponse : Le maintien de conditions de vie pour les travailleurs."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-19','tcf-reading-2026-11-reference-v3',$paper${"id":"tcf-reading-19","version":"tcf-reading-2026-11-reference-v3","title":"TCF Reading · Test 19","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"L'électricité sera coupée dans le bâtiment de dix à onze heures. L'ascenseur ne pourra pas être utilisé pendant cette période.\n\nMerci de prévoir vos déplacements avant le début de l'intervention. Les escaliers resteront accessibles pendant toute la durée des travaux.","question":"Quel équipement sera indisponible ?","options":["L'ascenseur","La cour extérieure","Le portail piéton manuel","La boîte aux lettres"],"correct":"A","explanation":"Le passage indique : « L'électricité sera coupée dans le bâtiment de dix à onze heures. L'ascenseur ne pourra pas être utilisé pendant cette période. » Cela justifie la réponse : L'ascenseur."},{"number":2,"points":3,"passage":"Le conseiller énergie reçoit gratuitement samedi sur rendez-vous. Apportez une facture récente, sans vos coordonnées bancaires.\n\nLe rendez-vous permet de comprendre vos dépenses et de préparer vos questions sur le logement.","question":"Quel document est utile ?","options":["Une facture récente","Une carte de fidélité","Un devis de déménagement","Un relevé de tous les comptes"],"correct":"A","explanation":"Le passage indique : « Le conseiller énergie reçoit gratuitement samedi sur rendez-vous. Apportez une facture récente, sans vos coordonnées bancaires. » Cela justifie la réponse : Une facture récente."},{"number":3,"points":3,"passage":"Le test de chauffage aura lieu jeudi matin. Merci de ne pas fermer les robinets pendant l'intervention.\n\nL'équipe passera dans chaque étage. Un avis sera affiché dans le hall lorsque les vérifications seront terminées.","question":"Quelle consigne est donnée ?","options":["Laisser les robinets dans l'état demandé","Démonter les radiateurs","Couper tous les tuyaux","Ouvrir toutes les fenêtres obligatoirement"],"correct":"A","explanation":"Le passage indique : « Le test de chauffage aura lieu jeudi matin. Merci de ne pas fermer les robinets pendant l'intervention. » Cela justifie la réponse : Laisser les robinets dans l'état demandé."},{"number":4,"points":3,"passage":"Les panneaux de démonstration ne produisent pas d'électricité pour les visiteurs. Ils servent à expliquer le fonctionnement du système.\n\nUn animateur répondra à vos questions après la présentation. Merci de ne pas manipuler les câbles exposés sur la table.","question":"Quelle est leur fonction ?","options":["Une alimentation électrique personnelle","Un support pédagogique","Une vente automatique de batteries","Un chauffage de la rue"],"correct":"B","explanation":"Le passage indique : « Les panneaux de démonstration ne produisent pas d'électricité pour les visiteurs. Ils servent à expliquer le fonctionnement du système. » Cela justifie la réponse : Un support pédagogique."},{"number":5,"points":9,"passage":"Je préfère faire vérifier l'isolation avant de changer l'appareil de chauffage. Nous saurons mieux quelle puissance sera nécessaire.\n\nSi nous réduisons d'abord les pertes, nous pourrons comparer des modèles mieux adaptés au logement. Demande au conseiller un rendez-vous la semaine prochaine. Nous comparerons ensuite les devis.","question":"Pourquoi commencer par l'isolation ?","options":["Éviter toute analyse du logement","Évaluer les besoins avant de choisir l'équipement","Supprimer les factures existantes","Acheter l'appareil le plus puissant"],"correct":"B","explanation":"Le passage indique : « Je préfère faire vérifier l'isolation avant de changer l'appareil de chauffage. Nous saurons mieux quelle puissance sera nécessaire. » Cela justifie la réponse : Évaluer les besoins avant de choisir l'équipement."},{"number":6,"points":9,"passage":"L'atelier prête un appareil pour mesurer les consommations des petits équipements. Notez la durée d'utilisation avec la valeur affichée.\n\nUn tableau vous aidera à classer les relevés. Rapportez le matériel à la date indiquée sur votre fiche de prêt.","question":"Quelle information faut-il relever en plus ?","options":["Le nombre de pièces du magasin","Le temps d'usage","La couleur de la prise","La marque du carnet"],"correct":"B","explanation":"Le passage indique : « L'atelier prête un appareil pour mesurer les consommations des petits équipements. Notez la durée d'utilisation avec la valeur affichée. » Cela justifie la réponse : Le temps d'usage."},{"number":7,"points":9,"passage":"Votre visite conseil ne comprend pas la réalisation des travaux. Vous recevrez des pistes à comparer avec des devis professionnels.\n\nLe document résumera les points observés dans votre logement et les questions à poser aux entreprises. Vous resterez libre de choisir les interventions à engager.","question":"Quel résultat est proposé ?","options":["Une certification de tous les appareils","Une obligation d'acheter auprès du conseiller","Une orientation pour préparer les décisions","Un chantier immédiatement terminé"],"correct":"C","explanation":"Le passage indique : « Votre visite conseil ne comprend pas la réalisation des travaux. Vous recevrez des pistes à comparer avec des devis professionnels. » Cela justifie la réponse : Une orientation pour préparer les décisions."},{"number":8,"points":9,"passage":"Nous baisserons l'éclairage de la vitrine après la fermeture. L'enseigne restera visible sans garder toutes les lampes allumées.\n\nLe responsable vérifiera le résultat depuis la rue. Merci de conserver le nouvel horaire sur la fiche du magasin.","question":"Quelle modification est prévue ?","options":["Éteindre le magasin pendant ses heures d'ouverture","Supprimer l'enseigne","Réduire l'éclairage nocturne","Ajouter des lampes à l'intérieur"],"correct":"C","explanation":"Le passage indique : « Nous baisserons l'éclairage de la vitrine après la fermeture. L'enseigne restera visible sans garder toutes les lampes allumées. » Cela justifie la réponse : Réduire l'éclairage nocturne."},{"number":9,"points":9,"passage":"Je peux participer à l'achat collectif, mais je veux connaître les conditions d'entretien avant de confirmer.\n\nPeux-tu demander au fournisseur qui intervient en cas de panne et si des frais réguliers sont prévus dans le contrat ?","question":"Quelle information manque pour décider ?","options":["Le nombre de réunions passées","La couleur des affiches","La date de fondation du fabricant uniquement","Le suivi de l'équipement"],"correct":"D","explanation":"Le passage indique : « Je peux participer à l'achat collectif, mais je veux connaître les conditions d'entretien avant de confirmer. » Cela justifie la réponse : Le suivi de l'équipement."},{"number":10,"points":9,"passage":"La salle reste fraîche le matin. Fermez les volets des fenêtres exposées avant de partir pour limiter la chaleur de l'après-midi.\n\nLa personne qui ouvre le lendemain pourra les relever. Cette organisation doit être suivie par tous les utilisateurs de la salle.","question":"Quel objectif motive cette consigne ?","options":["Réduire l'entrée de chaleur","Empêcher toute aération nocturne","Refroidir le trottoir","Augmenter l'éclairage artificiel"],"correct":"A","explanation":"Le passage indique : « La salle reste fraîche le matin. Fermez les volets des fenêtres exposées avant de partir pour limiter la chaleur de l'après-midi. » Cela justifie la réponse : Réduire l'entrée de chaleur."},{"number":11,"points":15,"passage":"Une résidence suit ses consommations avant et après des travaux. Les températures extérieures sont aussi prises en compte pour comparer des périodes différentes.\n\nLe conseil syndical a d'abord constaté une baisse sur les factures et souhaitait l'attribuer entièrement à l'isolation. Le technicien rappelle qu'un hiver plus doux réduit également les besoins. Il rassemble donc les relevés et décrit les conditions de chaque période. Les habitants pourront lire les résultats avec une explication de la méthode et des limites de la comparaison. Cette présentation doit aider à comprendre ce qui semble lié aux interventions réalisées, sans transformer une simple différence entre deux factures en preuve suffisante.","question":"Pourquoi ajouter cette donnée ?","options":["Choisir la couleur des façades","Supprimer la mesure de consommation","Éviter d'attribuer tout changement aux travaux","Garantir des hivers identiques"],"correct":"C","explanation":"Le passage indique : « Une résidence suit ses consommations avant et après des travaux. Les températures extérieures sont aussi prises en compte pour comparer des périodes différentes. » Cela justifie la réponse : Éviter d'attribuer tout changement aux travaux."},{"number":12,"points":15,"passage":"Un installateur explique que l'orientation d'un toit influence la production solaire. Deux surfaces identiques ne produiront donc pas nécessairement la même quantité.\n\nLe conseiller observe également les ombres portées par les bâtiments voisins. Il prépare une estimation propre à chaque emplacement, au lieu d'appliquer un rendement unique à tous les projets. Les résultats seront présentés avec leurs hypothèses. Le propriétaire pourra poser ses questions avant de choisir un équipement.","question":"Quel facteur complète la superficie ?","options":["Le nom de la rue","Le nombre de voisins","La couleur des factures","L'exposition du toit"],"correct":"D","explanation":"Le passage indique : « Un installateur explique que l'orientation d'un toit influence la production solaire. Deux surfaces identiques ne produiront donc pas nécessairement la même quantité. » Cela justifie la réponse : L'exposition du toit."},{"number":13,"points":15,"passage":"Une bibliothèque d'outils prête une caméra thermique avec une initiation. Les images doivent être interprétées, car une zone colorée n'explique pas seule l'origine d'un défaut.\n\nUne paroi humide, un reflet ou les conditions extérieures peuvent influencer l'apparence d'une image. Le formateur montre plusieurs exemples pris dans des situations connues avant de prêter le matériel. Les utilisateurs notent les circonstances de leurs observations et évitent de conclure immédiatement qu'un élément doit être remplacé. Le prêt vise à mieux repérer les questions à examiner, sans transformer l'appareil en outil capable de fournir automatiquement un diagnostic complet du bâtiment.","question":"Quelle aide est nécessaire ?","options":["Déclarer tous les murs défectueux","Choisir uniquement la couleur la plus vive","Remplacer l'examen par une impression","Comprendre le sens des observations"],"correct":"D","explanation":"Le passage indique : « Une bibliothèque d'outils prête une caméra thermique avec une initiation. Les images doivent être interprétées, car une zone colorée n'explique pas seule l'origine d'un défaut. » Cela justifie la réponse : Comprendre le sens des observations."},{"number":14,"points":15,"passage":"Une école protège ses fenêtres exposées au soleil avant d'installer un refroidissement supplémentaire. Elle cherche d'abord à limiter la chaleur qui entre.\n\nDes stores extérieurs sont testés dans les classes les plus exposées. Les enseignants notent les moments où l'éblouissement et la température gênent les activités. Le projet prend aussi en compte la lumière nécessaire pour travailler et les conditions d'ouverture des fenêtres. Les résultats serviront à décider des interventions suivantes. La direction préfère vérifier l'effet des protections sur une saison avant de choisir de nouveaux équipements, afin que les dépenses répondent aux besoins effectivement observés dans les salles.","question":"Quelle priorité est donnée ?","options":["Augmenter la consommation immédiatement","Remplacer toutes les vitres par des écrans","Fermer l'école chaque été","Réduire le besoin avant d'ajouter un appareil"],"correct":"D","explanation":"Le passage indique : « Une école protège ses fenêtres exposées au soleil avant d'installer un refroidissement supplémentaire. Elle cherche d'abord à limiter la chaleur qui entre. » Cela justifie la réponse : Réduire le besoin avant d'ajouter un appareil."},{"number":15,"points":15,"passage":"Une entreprise répare des appareils dont les pièces restent disponibles. Elle publie les modèles acceptés pour éviter des déplacements inutiles.\n\nLa liste précise les références et les principales catégories de panne prises en charge. Les clients peuvent envoyer une photographie de l'étiquette avant de transporter un objet lourd. Le réparateur explique ensuite les limites du diagnostic à distance et annonce un devis après examen. Si une pièce indispensable n'est plus disponible, il le signale avant l'intervention. Le service cherche ainsi à prolonger la vie des équipements lorsque c'est possible, tout en donnant une information suffisamment claire sur les cas acceptés.","question":"Pourquoi publier cette liste ?","options":["Garantir la réparation de tout appareil","Informer sur les réparations réellement possibles","Vendre des pièces incompatibles","Refuser toute prise de contact"],"correct":"B","explanation":"Le passage indique : « Une entreprise répare des appareils dont les pièces restent disponibles. Elle publie les modèles acceptés pour éviter des déplacements inutiles. » Cela justifie la réponse : Informer sur les réparations réellement possibles."},{"number":16,"points":15,"passage":"Des habitants partagent une chaufferie. Le suivi distingue la consommation totale et sa répartition, car une variation du nombre d'occupants peut modifier le bilan.\n\nLe bilan indique les périodes d'occupation, les températures retenues et les interventions effectuées sur l'installation. Les habitants peuvent ainsi distinguer une évolution du fonctionnement et une variation des usages. Une réunion annuelle permet de poser des questions sur la facturation. Le responsable présente les règles de calcul avec des exemples, car un chiffre total ne suffit pas toujours à expliquer ce que chaque ménage doit payer.","question":"Quelle information complète le total ?","options":["Le nombre de décorations","L'évolution de l'occupation","La taille des boîtes aux lettres","Le prix des plantes"],"correct":"B","explanation":"Le passage indique : « Des habitants partagent une chaufferie. Le suivi distingue la consommation totale et sa répartition, car une variation du nombre d'occupants peut modifier le bilan. » Cela justifie la réponse : L'évolution de l'occupation."},{"number":17,"points":15,"passage":"Un logement rénové reçoit un guide de ventilation. L'amélioration de l'étanchéité ne dispense pas d'un renouvellement d'air correctement organisé.\n\nLe document explique les entrées d'air, les bouches d'extraction et les signes qui doivent conduire à demander une vérification. Les habitants sont invités à ne pas obstruer les dispositifs lorsqu'ils ressentent un courant d'air. Ils peuvent contacter le gestionnaire pour comprendre un réglage ou signaler un bruit anormal. Une séance de présentation est organisée après les travaux. L'équipe souhaite que les gains thermiques s'accompagnent de bonnes conditions d'usage, plutôt que de laisser les occupants découvrir seuls les changements apportés au logement.","question":"Quelle précaution accompagne la rénovation ?","options":["Supprimer toute entrée d'air","Maintenir une ventilation adaptée","Ouvrir tous les murs","Éviter de lire les consignes"],"correct":"B","explanation":"Le passage indique : « Un logement rénové reçoit un guide de ventilation. L'amélioration de l'étanchéité ne dispense pas d'un renouvellement d'air correctement organisé. » Cela justifie la réponse : Maintenir une ventilation adaptée."},{"number":18,"points":15,"passage":"Une commune récupère la chaleur d'un équipement public pour alimenter un bâtiment voisin. La proximité limite les pertes lors du transport.\n\nLes techniciens comparent les heures où la chaleur est disponible avec celles où le bâtiment voisin en a besoin. Ils étudient aussi le fonctionnement du réseau lorsque l'équipement principal s'arrête. Le projet comprend un système complémentaire pour assurer la continuité du service. Avant d'engager les travaux, la commune présentera les coûts, les économies attendues et les principales incertitudes.","question":"Quel avantage présente l'emplacement ?","options":["Un chauffage uniquement décoratif","Une indépendance totale de tous les équipements","Un trajet de chaleur plus court","Une production sans installation"],"correct":"C","explanation":"Le passage indique : « Une commune récupère la chaleur d'un équipement public pour alimenter un bâtiment voisin. La proximité limite les pertes lors du transport. » Cela justifie la réponse : Un trajet de chaleur plus court."},{"number":19,"points":15,"passage":"Un groupe compare des lampes en tenant compte des heures d'éclairage. Une pièce rarement utilisée ne présente pas les mêmes besoins qu'un accueil ouvert toute la journée.\n\nLes participants notent la puissance et la durée d'utilisation avant de calculer une consommation estimée. Ils regardent aussi la qualité de la lumière nécessaire dans chaque espace. Une lampe adaptée à un passage bref n'est pas forcément celle qui convient à un poste de travail.","question":"Quelle démarche est adoptée ?","options":["Adapter le choix à l'usage","Choisir selon le prix de l'emballage","Ignorer la durée d'éclairage","Installer partout la même puissance sans étude"],"correct":"A","explanation":"Le passage indique : « Un groupe compare des lampes en tenant compte des heures d'éclairage. Une pièce rarement utilisée ne présente pas les mêmes besoins qu'un accueil ouvert toute la journée. » Cela justifie la réponse : Adapter le choix à l'usage."},{"number":20,"points":21,"passage":"Une copropriété planifie ses travaux en plusieurs étapes. Elle vérifie que les premières interventions ne compliqueront pas les suivantes, notamment autour des façades et des fenêtres. Le maître d'œuvre présente un ordre possible et les points à vérifier avant chaque chantier. Les habitants comparent cette proposition avec leurs contraintes de financement et d'occupation. Certaines interventions pourront être regroupées pour éviter de reprendre un ouvrage récent. Le calendrier reste révisable, mais les décisions sont documentées pour que les équipes suivantes comprennent les choix déjà faits.","question":"Quelle attention guide le calendrier ?","options":["Le choix du devis le plus court uniquement","La cohérence entre les étapes","La suppression de toute anticipation","L'ordre alphabétique des entreprises"],"correct":"B","explanation":"Le passage indique : « Une copropriété planifie ses travaux en plusieurs étapes. Elle vérifie que les premières interventions ne compliqueront pas les suivantes, notamment autour des façades et des fenêtres. » Cela justifie la réponse : La cohérence entre les étapes."},{"number":21,"points":21,"passage":"Un système automatique baisse le chauffage dans les salles vides. Les utilisateurs peuvent signaler une occupation imprévue pour éviter un inconfort. Un bouton permet de prolonger temporairement la présence sans modifier le programme de toute la semaine. Les agents examinent les demandes répétées afin de repérer un horaire habituel qui aurait été mal enregistré. Ils expliquent le fonctionnement aux associations qui utilisent les locaux en soirée. L'automatisation reste ainsi liée aux usages réels, avec une possibilité de correction lorsque le calendrier ne décrit pas correctement la situation.","question":"Quel équilibre est recherché ?","options":["Maintien constant de la température maximale","Réduction fixe sans exception","Suppression de toute occupation","Économie et adaptation aux usages réels"],"correct":"D","explanation":"Le passage indique : « Un système automatique baisse le chauffage dans les salles vides. Les utilisateurs peuvent signaler une occupation imprévue pour éviter un inconfort. » Cela justifie la réponse : Économie et adaptation aux usages réels."},{"number":22,"points":21,"passage":"Un conseiller compare le coût initial et les dépenses d'entretien de deux solutions. Une installation moins chère peut demander davantage de suivi pendant sa durée de vie. Les documents incluent les contrôles périodiques, les consommables et les interventions possibles en cas de panne. Les ménages peuvent ainsi comparer plusieurs scénarios sur une même durée. L'objectif est de rendre visibles les engagements après l'achat, sans prétendre connaître exactement toutes les dépenses qui surviendront au cours des années suivantes.","question":"Quel critère élargit la comparaison ?","options":["Le nombre de pages du devis uniquement","Le nom du modèle seulement","Les dépenses futures","La taille de l'affiche"],"correct":"C","explanation":"Le passage indique : « Un conseiller compare le coût initial et les dépenses d'entretien de deux solutions. Une installation moins chère peut demander davantage de suivi pendant sa durée de vie. » Cela justifie la réponse : Les dépenses futures."},{"number":23,"points":21,"passage":"Des habitants testent une protection solaire mobile. Ils l'ouvrent en hiver pour laisser entrer la lumière et la ferment selon l'exposition en été. Les participants notent le confort, la luminosité et la facilité de manipulation à différents moments. Les essais ne portent donc pas seulement sur la température maximale. Une protection trop difficile à déplacer pourrait rester inutilisée malgré de bons résultats théoriques. Le groupe souhaite retenir une solution adaptée aux habitudes du logement.","question":"Quel intérêt offre sa mobilité ?","options":["Adapter la protection aux saisons","Éviter toute attention à l'orientation","Assombrir définitivement le logement","Remplacer toutes les fenêtres"],"correct":"A","explanation":"Le passage indique : « Des habitants testent une protection solaire mobile. Ils l'ouvrent en hiver pour laisser entrer la lumière et la ferment selon l'exposition en été. » Cela justifie la réponse : Adapter la protection aux saisons."},{"number":24,"points":21,"passage":"Une ville installe des capteurs dans ses bâtiments, puis forme les agents à lire les résultats. Les données seules n'auraient pas permis d'ajuster correctement les réglages. Les premières courbes montraient des écarts sans indiquer immédiatement leur cause. Les agents ont appris à rapprocher les heures de fonctionnement des réservations de salles et des opérations d'entretien. Ils peuvent désormais repérer un réglage oublié ou demander une vérification technique. Le dispositif prévoit un temps régulier pour examiner les informations.","question":"Quel complément est prévu ?","options":["Un remplacement de tous les agents","Une absence de décision","Une capacité d'interprétation humaine","Un affichage sans explication"],"correct":"C","explanation":"Le passage indique : « Une ville installe des capteurs dans ses bâtiments, puis forme les agents à lire les résultats. Les données seules n'auraient pas permis d'ajuster correctement les réglages. » Cela justifie la réponse : Une capacité d'interprétation humaine."},{"number":25,"points":21,"passage":"Un atelier montre comment détecter de petites fuites d'eau. Les participants apprennent aussi quand faire appel à un professionnel plutôt qu'intervenir eux-mêmes. L'animateur commence par montrer comment relever un compteur lorsque tous les points d'eau sont fermés. Il explique ensuite les limites des petites réparations accessibles avec des outils courants. Les participants repartent avec une liste de signes à surveiller et les informations utiles pour décrire un problème.","question":"Quel objectif accompagne l'autonomie ?","options":["Éviter tout recours à un spécialiste","Reconnaître les limites de l'intervention personnelle","Supprimer les contrôles","Réparer toutes les installations sans compétence"],"correct":"B","explanation":"Le passage indique : « Un atelier montre comment détecter de petites fuites d'eau. Les participants apprennent aussi quand faire appel à un professionnel plutôt qu'intervenir eux-mêmes. » Cela justifie la réponse : Reconnaître les limites de l'intervention personnelle."},{"number":26,"points":21,"passage":"Un collectif achète de l'électricité produite par plusieurs sources. Il demande des informations sur la méthode de comptage pour comprendre les engagements annoncés. Les responsables veulent savoir sur quelle période la production est rapprochée de la consommation et quels documents permettent de le vérifier. Ils souhaitent présenter ces informations aux membres avec des exemples simples. Le contrat sera discuté après cette clarification. Une promesse générale ne leur paraît pas suffisante pour comprendre ce qui sera réellement acheté ni pour comparer honnêtement plusieurs offres.","question":"Quelle démarche suit le collectif ?","options":["Confondre consommation et prix du matériel","Se fier uniquement au dessin du contrat","Ignorer toute origine de production","Vérifier ce que les garanties signifient réellement"],"correct":"D","explanation":"Le passage indique : « Un collectif achète de l'électricité produite par plusieurs sources. Il demande des informations sur la méthode de comptage pour comprendre les engagements annoncés. » Cela justifie la réponse : Vérifier ce que les garanties signifient réellement."},{"number":27,"points":21,"passage":"Une rénovation conserve les matériaux encore utilisables. L'équipe vérifie leur état et leur compatibilité avant de décider du réemploi. Les matériaux sont inventoriés avant le démontage, puis stockés de façon à éviter leur dégradation. Certains éléments pourront être utilisés directement, d'autres devront être adaptés ou écartés après contrôle. Le chantier documente ces décisions pour conserver la trace de leur origine et de leurs caractéristiques.","question":"Quelle condition encadre ce choix ?","options":["L'absence de toute inspection","Une préférence fondée uniquement sur l'âge","L'acceptation automatique de tout matériau","Une évaluation technique préalable"],"correct":"D","explanation":"Le passage indique : « Une rénovation conserve les matériaux encore utilisables. L'équipe vérifie leur état et leur compatibilité avant de décider du réemploi. » Cela justifie la réponse : Une évaluation technique préalable."},{"number":28,"points":21,"passage":"Un immeuble installe un espace de séchage collectif ventilé. Certains habitants réduisent l'usage d'appareils électriques, mais le service doit rester assez accessible pour être utilisé régulièrement. Le gestionnaire étudie les horaires, les modalités d'accès et la durée nécessaire pour libérer les emplacements. Une salle disponible seulement à des moments peu pratiques serait rapidement délaissée. Les résidents peuvent signaler les difficultés pendant une période d'essai. Les règles seront ajustées avant d'installer davantage de supports.","question":"Quel facteur compte au-delà de l'installation ?","options":["La facilité d'usage au quotidien","Le nombre de prospectus","La couleur des murs seulement","L'absence de règles d'accès"],"correct":"A","explanation":"Le passage indique : « Un immeuble installe un espace de séchage collectif ventilé. Certains habitants réduisent l'usage d'appareils électriques, mais le service doit rester assez accessible pour être utilisé régulièrement. » Cela justifie la réponse : La facilité d'usage au quotidien."},{"number":29,"points":21,"passage":"Une entreprise affiche ses économies d'énergie par unité produite. Le volume total de production ayant augmenté, elle publie aussi sa consommation globale. Les deux indicateurs sont présentés sur la même page avec une explication de leur différence. Les responsables souhaitent montrer les progrès réalisés dans les procédés sans donner l'impression que les besoins globaux ont forcément diminué. Le public peut ainsi examiner l'effet des gains techniques et celui de l'activité.","question":"Pourquoi ajouter le chiffre global ?","options":["Prouver que les deux valeurs sont identiques","Éviter toute comparaison","Masquer toute évolution de production","Distinguer efficacité unitaire et consommation totale"],"correct":"D","explanation":"Le passage indique : « Une entreprise affiche ses économies d'énergie par unité produite. Le volume total de production ayant augmenté, elle publie aussi sa consommation globale. » Cela justifie la réponse : Distinguer efficacité unitaire et consommation totale."},{"number":30,"points":26,"passage":"Un équipement très performant sur le papier peut donner des résultats décevants s'il est mal réglé ou utilisé dans un lieu inadapté. Une évaluation sérieuse doit donc articuler les caractéristiques techniques, l'installation et les usages. Les techniciens relèvent les températures, les horaires et les paramètres réellement employés. Ils vérifient ensuite si les conditions correspondent à celles retenues dans la documentation commerciale. Un écart peut venir de plusieurs facteurs et nécessite parfois plusieurs essais.","question":"Quelle approche est recommandée ?","options":["Regarder le système en situation réelle","Considérer le réglage comme inutile","Déduire tout résultat du prix d'achat","Comparer uniquement les brochures"],"correct":"A","explanation":"Le passage indique : « Un équipement très performant sur le papier peut donner des résultats décevants s'il est mal réglé ou utilisé dans un lieu inadapté. Une évaluation sérieuse doit donc articuler les caractéristiques techniques, l'installation et les usages. » Cela justifie la réponse : Regarder le système en situation réelle."},{"number":31,"points":26,"passage":"Des travaux réduisent les besoins de chauffage. Les occupants gagnent aussi en confort, parfois en chauffant un peu plus qu'avant. Ce bénéfice ne rend pas les travaux inutiles ; il invite à distinguer économie mesurée et amélioration des conditions de vie. Le suivi demande aux habitants de décrire leurs conditions avant et après l'intervention. Une pièce auparavant évitée en hiver peut désormais être utilisée normalement.","question":"Quelle nuance est apportée au bilan ?","options":["Les travaux ne changent jamais les besoins","Toute hausse du confort prouve un échec","La température intérieure reste forcément identique","Le confort peut absorber une partie du gain énergétique"],"correct":"D","explanation":"Le passage indique : « Des travaux réduisent les besoins de chauffage. Les occupants gagnent aussi en confort, parfois en chauffant un peu plus qu'avant. Ce bénéfice ne rend pas les travaux inutiles ; il invite à distinguer économie mesurée et amélioration des conditions de vie. » Cela justifie la réponse : Le confort peut absorber une partie du gain énergétique."},{"number":32,"points":26,"passage":"Une ville cherche à rafraîchir une place. Les arbres, l'ombre et les sols perméables demandent une conception commune. Additionner des éléments présentés comme vertueux ne garantit pas leur efficacité si leurs fonctions et leurs conditions d'entretien se contredisent. Un arbre a besoin d'un sol et d'un volume suffisants pour se développer. Une zone ombragée doit aussi correspondre aux endroits où les habitants s'arrêtent. Le projet sera donc examiné comme un ensemble avant le lancement des travaux.","question":"Quelle nécessité est soulignée ?","options":["Éviter de prévoir l'entretien","Compter seulement les équipements ajoutés","Concevoir un ensemble cohérent","Choisir chaque élément sans regarder les autres"],"correct":"C","explanation":"Le passage indique : « Une ville cherche à rafraîchir une place. Les arbres, l'ombre et les sols perméables demandent une conception commune. Additionner des éléments présentés comme vertueux ne garantit pas leur efficacité si leurs fonctions et leurs conditions d'entretien se contredisent. » Cela justifie la réponse : Concevoir un ensemble cohérent."},{"number":33,"points":26,"passage":"Le partage d'un équipement réduit parfois les achats individuels. Mais si sa réservation est compliquée, les utilisateurs finissent par acheter leur propre appareil. L'économie de matière dépend donc aussi d'une organisation suffisamment simple pour durer. Les gestionnaires simplifient les créneaux, précisent les conditions de retour et prévoient une réponse en cas de panne. Ils suivent les abandons de réservation pour repérer les obstacles.","question":"Quel facteur conditionne le bénéfice du partage ?","options":["La suppression des utilisateurs réguliers","Le nombre de slogans","La qualité de son organisation","La taille du logo"],"correct":"C","explanation":"Le passage indique : « Le partage d'un équipement réduit parfois les achats individuels. Mais si sa réservation est compliquée, les utilisateurs finissent par acheter leur propre appareil. L'économie de matière dépend donc aussi d'une organisation suffisamment simple pour durer. » Cela justifie la réponse : La qualité de son organisation."},{"number":34,"points":26,"passage":"Une aide publique couvre une part du coût des rénovations. Les ménages doivent néanmoins avancer le reste, parfois inaccessible à leur budget. Un taux d'aide identique ne produit donc pas la même possibilité d'agir pour tous. Les conseillers examinent les possibilités d'avance et les délais de versement. Ils observent aussi les dossiers abandonnés, qui n'apparaissent pas dans les chiffres des chantiers terminés.","question":"Quelle limite de l'égalité du taux est décrite ?","options":["Une aide proportionnelle supprime toute dépense","Les capacités de financement restantes sont inégales","Tous les ménages disposent du même budget","Le coût des travaux disparaît"],"correct":"B","explanation":"Le passage indique : « Une aide publique couvre une part du coût des rénovations. Les ménages doivent néanmoins avancer le reste, parfois inaccessible à leur budget. Un taux d'aide identique ne produit donc pas la même possibilité d'agir pour tous. » Cela justifie la réponse : Les capacités de financement restantes sont inégales."},{"number":35,"points":26,"passage":"Une démonstration compare deux fenêtres sous des conditions contrôlées. Elle aide à comprendre leurs performances respectives, mais ne permet pas d'annoncer directement l'économie exacte de chaque logement. Celle-ci dépend aussi des murs, des usages et du climat. Le conseiller utilise donc la démonstration comme point de départ pour expliquer les différences techniques. Une estimation individualisée demandera d'autres informations sur le bâtiment. Les résultats présentés au public précisent les conditions dans lesquelles la comparaison a été effectuée.","question":"Quelle portée faut-il donner à la démonstration ?","options":["Une comparaison utile mais limitée","Un diagnostic complet de chaque maison","Une facture future garantie pour tous","Une absence totale d'information"],"correct":"A","explanation":"Le passage indique : « Une démonstration compare deux fenêtres sous des conditions contrôlées. Elle aide à comprendre leurs performances respectives, mais ne permet pas d'annoncer directement l'économie exacte de chaque logement. Celle-ci dépend aussi des murs, des usages et du climat. » Cela justifie la réponse : Une comparaison utile mais limitée."},{"number":36,"points":33,"passage":"Une campagne encourage à remplacer les appareils anciens par des modèles efficaces. Pour un équipement encore peu utilisé, l'énergie et les matériaux nécessaires à la fabrication du nouveau peuvent peser dans le bilan. La décision doit donc considérer le cycle de vie et l'usage, plutôt qu'une comparaison limitée au fonctionnement instantané. Le conseiller propose de comparer plusieurs scénarios : continuer à utiliser l'appareil, le réparer si nécessaire ou le remplacer. Il demande combien de fois il fonctionne et pendant combien de temps. La disponibilité des pièces, les consommables et les possibilités de fin de vie entrent aussi dans l'examen. Un modèle récent peut être intéressant dans certaines situations, sans que le même choix soit préférable pour tous les ménages. Présenter ces conditions aide à décider à partir des besoins réels et des ressources engagées, au lieu de déduire automatiquement la meilleure solution de l'âge inscrit sur l'étiquette.","question":"Quelle comparaison est proposée ?","options":["Un bilan élargi incluant fabrication et usage","Le prix de la publicité","L'âge comme unique critère","La seule puissance affichée"],"correct":"A","explanation":"Le passage indique : « La décision doit donc considérer le cycle de vie et l'usage, plutôt qu'une comparaison limitée au fonctionnement instantané. » Cela justifie la réponse : Un bilan élargi incluant fabrication et usage."},{"number":37,"points":33,"passage":"Un immeuble rénové reçoit un système de commande complexe. Les occupants évitent certains réglages par peur de faire une erreur. L'équipe simplifie l'interface et organise un accompagnement. Une performance théorique ne devient réelle que si les personnes peuvent effectivement piloter les usages attendus. Les premières réunions avaient surtout présenté les capacités techniques du dispositif. Elles n'avaient pas montré les gestes ordinaires, comme modifier un horaire ou revenir à un réglage connu. Des essais avec les habitants révèlent des libellés difficiles à comprendre et des confirmations peu visibles. La nouvelle version distingue les actions courantes des paramètres réservés aux professionnels. Un guide court reste disponible près de la commande et un contact est prévu pour les questions. Les habitants pourront revenir poser leurs questions.","question":"Quelle condition est mise en évidence ?","options":["L'absence de toute commande","Une complexité toujours plus grande","La suppression des explications","La compréhension pratique du système"],"correct":"D","explanation":"Le passage indique : « Une performance théorique ne devient réelle que si les personnes peuvent effectivement piloter les usages attendus. » Cela justifie la réponse : La compréhension pratique du système."},{"number":38,"points":33,"passage":"Une ville annonce une baisse de consommation dans ses bâtiments. Plusieurs équipements ont pourtant été fermés pendant la période observée. Les responsables recalculent les résultats à usage comparable. Un chiffre peut être exact tout en donnant une interprétation trompeuse s'il ne précise pas ce qui a changé autour de la mesure. Une piscine fermée pour entretien et une salle inutilisée pendant plusieurs mois expliquent une partie de la différence annoncée. Ces fermetures ont bien réduit les dépenses, mais ne démontrent pas à elles seules une meilleure efficacité des installations. Le nouveau bilan sépare donc l'évolution liée aux surfaces et aux horaires de celle observée dans les équipements restés ouverts. Il conserve le chiffre initial en précisant sa signification. Les élus pourront ainsi discuter des économies techniques sur une base comparable, tandis que les habitants disposeront d'une présentation plus claire des services effectivement assurés pendant chacune des périodes étudiées.","question":"Pourquoi corriger la comparaison ?","options":["Ignorer les fermetures","Distinguer économies et réduction d'activité","Effacer une baisse réelle dans tous les cas","Rendre les chiffres identiques par principe"],"correct":"B","explanation":"Le passage indique : « Un chiffre peut être exact tout en donnant une interprétation trompeuse s'il ne précise pas ce qui a changé autour de la mesure. » Cela justifie la réponse : Distinguer économies et réduction d'activité."},{"number":39,"points":33,"passage":"Un projet collectif veut produire de l'énergie près des habitants. Il organise aussi les décisions sur l'investissement et la répartition des bénéfices. Les initiateurs refusent de définir le caractère citoyen du projet par sa seule localisation. La proximité physique ne remplace pas une participation réelle aux choix qui structurent le service. Les réunions abordent notamment l'entrée de nouveaux membres, les droits de vote et l'utilisation des recettes. Les documents financiers sont présentés dans un langage accessible, avec un temps pour poser des questions avant chaque décision. Les fondateurs veulent aussi éviter que seules les personnes ayant beaucoup de temps ou de capital puissent peser sur les orientations. Ils prévoient donc plusieurs formes de contribution et des modalités de représentation. Le projet sera évalué sur la production réalisée, mais également sur la manière dont les habitants peuvent comprendre, discuter et modifier les choix qui engagent leur participation dans la durée.","question":"Quel critère complète la localisation ?","options":["L'absence de tout contrat","La longueur du nom du projet","La gouvernance et la participation aux décisions","La couleur des installations"],"correct":"C","explanation":"Le passage indique : « La proximité physique ne remplace pas une participation réelle aux choix qui structurent le service. » Cela justifie la réponse : La gouvernance et la participation aux décisions."}]}$paper$::jsonb);
insert into academy_tcf_reading.papers(id,version,content) values('tcf-reading-20','tcf-reading-2026-11-reference-v3',$paper${"id":"tcf-reading-20","version":"tcf-reading-2026-11-reference-v3","title":"TCF Reading · Test 20","seconds":3600,"maxPoints":699,"questions":[{"number":1,"points":3,"passage":"L'atelier de jeux commence à quatorze heures. Vous pouvez arriver plus tard, mais aucune nouvelle partie ne sera lancée après seize heures.\n\nL'accueil vous indiquera les tables encore disponibles. Les parties déjà commencées pourront se terminer normalement après cette heure.","question":"Quelle limite est annoncée ?","options":["Le début des nouvelles parties après seize heures","L'arrivée de tous les visiteurs après quatorze heures","La présence des animateurs","La possibilité de jouer avant seize heures"],"correct":"A","explanation":"Le passage indique : « L'atelier de jeux commence à quatorze heures. Vous pouvez arriver plus tard, mais aucune nouvelle partie ne sera lancée après seize heures. » Cela justifie la réponse : Le début des nouvelles parties après seize heures."},{"number":2,"points":3,"passage":"Le parc reste ouvert pendant les travaux du kiosque. Seule la zone entourée de barrières est inaccessible.\n\nLes autres allées restent accessibles. Merci de suivre les panneaux temporaires pour rejoindre l'aire de jeux.","question":"Quel espace est fermé ?","options":["La zone balisée du chantier","Tout le parc","Le jardin voisin","Toutes les allées"],"correct":"A","explanation":"Le passage indique : « Le parc reste ouvert pendant les travaux du kiosque. Seule la zone entourée de barrières est inaccessible. » Cela justifie la réponse : La zone balisée du chantier."},{"number":3,"points":3,"passage":"Les inscriptions au stage ferment demain. Le paiement peut être effectué la semaine suivante.\n\nRemplissez le formulaire en ligne pour réserver votre place. Vous recevrez ensuite les indications nécessaires pour régler les frais.","question":"Quelle démarche est urgente ?","options":["Acheter le matériel","S'inscrire","Venir chercher son certificat","Payer immédiatement"],"correct":"B","explanation":"Le passage indique : « Les inscriptions au stage ferment demain. Le paiement peut être effectué la semaine suivante. » Cela justifie la réponse : S'inscrire."},{"number":4,"points":3,"passage":"Le rendez-vous de la promenade passe de la mairie à la gare. Le départ reste prévu à dix heures.\n\nLe groupe vous attendra devant l'entrée principale. Merci de transmettre ce changement aux personnes qui viennent avec vous.","question":"Qu'est-ce qui change ?","options":["Le lieu de rassemblement","La durée de la promenade","Le jour choisi","L'heure du départ"],"correct":"A","explanation":"Le passage indique : « Le rendez-vous de la promenade passe de la mairie à la gare. Le départ reste prévu à dix heures. » Cela justifie la réponse : Le lieu de rassemblement."},{"number":5,"points":9,"passage":"Je préfère réserver une soirée sans programme après notre voyage. Nous aurons besoin de temps pour nous reposer et ranger les affaires.\n\nOn pourra faire les courses le lendemain matin. Préviens simplement nos amis que nous préférons les retrouver un autre jour de la semaine.","question":"Quelle intention est exprimée ?","options":["Prolonger le trajet","Préserver un temps de récupération","Ajouter une visite obligatoire","Organiser une compétition"],"correct":"B","explanation":"Le passage indique : « Je préfère réserver une soirée sans programme après notre voyage. Nous aurons besoin de temps pour nous reposer et ranger les affaires. » Cela justifie la réponse : Préserver un temps de récupération."},{"number":6,"points":9,"passage":"Notre atelier fournit les outils de base. Vous pouvez apporter votre projet inachevé, même s'il est très simple.\n\nUn animateur vous aidera à choisir la prochaine étape. Pensez à apporter les pièces déjà réalisées.","question":"Qui est accueilli ?","options":["Une personne ayant déjà terminé","Seulement un vendeur d'outils","Uniquement un professionnel","Une personne avec un projet modeste"],"correct":"D","explanation":"Le passage indique : « Notre atelier fournit les outils de base. Vous pouvez apporter votre projet inachevé, même s'il est très simple. » Cela justifie la réponse : Une personne avec un projet modeste."},{"number":7,"points":9,"passage":"Je te propose d'échanger nos livres au café. Nous pourrons en parler avant de choisir ceux que nous emporterons.\n\nJ'apporterai les deux romans dont je t'ai parlé et tu pourras les feuilleter tranquillement. Dis-moi quel jour te conviendrait pour nous retrouver la semaine prochaine.","question":"Quel intérêt présente la rencontre ?","options":["Éviter tout échange","Choisir uniquement selon le poids","Vendre tous les ouvrages","Découvrir les livres par la discussion"],"correct":"D","explanation":"Le passage indique : « Je te propose d'échanger nos livres au café. Nous pourrons en parler avant de choisir ceux que nous emporterons. » Cela justifie la réponse : Découvrir les livres par la discussion."},{"number":8,"points":9,"passage":"Le centre propose des entrées sans abonnement pour les personnes qui viennent rarement. Le tarif à la séance reste distinct du forfait.\n\nLes prix sont affichés à l'accueil. Demandez conseil avant de choisir votre formule pour le trimestre.","question":"À quel besoin répond cette formule ?","options":["Une présence quotidienne obligatoire","Une fréquentation occasionnelle","Une activité réservée aux abonnés","Un accès sans horaire"],"correct":"B","explanation":"Le passage indique : « Le centre propose des entrées sans abonnement pour les personnes qui viennent rarement. Le tarif à la séance reste distinct du forfait. » Cela justifie la réponse : Une fréquentation occasionnelle."},{"number":9,"points":9,"passage":"Nous reportons le rangement collectif : trop de voisins sont absents dimanche. Une nouvelle date sera choisie par sondage.\n\nChacun pourra indiquer plusieurs disponibilités. Nous confirmerons ensuite le créneau retenu et la liste du matériel à apporter.","question":"Pourquoi le rendez-vous est-il reporté ?","options":["Parce que la salle a été vendue","Pour permettre davantage de participation","Parce que le rangement est terminé","Pour supprimer toute consultation"],"correct":"B","explanation":"Le passage indique : « Nous reportons le rangement collectif : trop de voisins sont absents dimanche. Une nouvelle date sera choisie par sondage. » Cela justifie la réponse : Pour permettre davantage de participation."},{"number":10,"points":9,"passage":"Je ne veux pas remplir toutes mes pauses avec des activités utiles. Certaines resteront simplement des moments de repos.\n\nJe me sens mieux lorsque je peux parfois marcher sans objectif ou regarder par la fenêtre. Cela m'aide à reprendre ensuite mes tâches.","question":"Quel choix est défendu ?","options":["Laisser du temps sans objectif productif","Transformer chaque pause en tâche","Renoncer à tout repos","Organiser toutes les journées de la même façon"],"correct":"A","explanation":"Le passage indique : « Je ne veux pas remplir toutes mes pauses avec des activités utiles. Certaines resteront simplement des moments de repos. » Cela justifie la réponse : Laisser du temps sans objectif productif."},{"number":11,"points":15,"passage":"Un atelier transforme des meubles récupérés. Les participants décident d'abord de l'usage recherché avant de choisir la décoration.\n\nUne petite armoire pourra par exemple devenir un rangement pour les chaussures ou un support pour des plantes. Les dimensions et la solidité sont vérifiées avant de commencer. Les animateurs montrent comment démonter une pièce et préparer les surfaces sans abîmer le reste du meuble. La couleur est discutée ensuite, en fonction du lieu où l'objet sera installé. Les participants repartent avec une fiche des gestes réalisés pour pouvoir entretenir leur réalisation. Le projet associe ainsi choix pratique, apprentissage technique et transformation esthétique.","question":"Quelle étape est prioritaire ?","options":["Définir la fonction du meuble","Acheter un meuble neuf","Vendre immédiatement les outils","Choisir une couleur au hasard"],"correct":"A","explanation":"Le passage indique : « Un atelier transforme des meubles récupérés. Les participants décident d'abord de l'usage recherché avant de choisir la décoration. » Cela justifie la réponse : Définir la fonction du meuble."},{"number":12,"points":15,"passage":"Une ville installe des tables d'échecs dans un parc. Les habitants peuvent apporter leurs pièces ; un prêt est aussi proposé à l'accueil voisin.\n\nLes tables sont accessibles sans réservation aux heures d'ouverture du parc. Un panneau explique comment emprunter le matériel et où le rapporter après la partie. Des bénévoles proposent parfois une initiation aux débutants. Les dates seront affichées sur le panneau près des tables.","question":"Quelle solution évite d'avoir son propre matériel ?","options":["Venir uniquement regarder","S'inscrire dans une autre ville","Emprunter les pièces","Acheter une table"],"correct":"C","explanation":"Le passage indique : « Une ville installe des tables d'échecs dans un parc. Les habitants peuvent apporter leurs pièces ; un prêt est aussi proposé à l'accueil voisin. » Cela justifie la réponse : Emprunter les pièces."},{"number":13,"points":15,"passage":"Un groupe propose des promenades sans destination spectaculaire. Les participants découvrent les détails des rues ordinaires à un rythme lent.\n\nLe guide invite le groupe à observer une façade, une plante entre les pavés ou les sons d'une place. Les arrêts sont choisis selon ce qui attire l'attention pendant la marche. Aucune liste de monuments à voir absolument n'est distribuée au départ. Les participants peuvent partager un souvenir lié au quartier ou demander de revenir sur un détail. La promenade propose ainsi une autre façon de regarder un environnement familier, sans exiger un long déplacement ni la recherche d'un événement exceptionnel à chaque étape.","question":"Quel regard est encouragé ?","options":["Le déplacement le plus rapide","L'attention au quotidien proche","La recherche exclusive de records","L'évitement de toute observation"],"correct":"B","explanation":"Le passage indique : « Un groupe propose des promenades sans destination spectaculaire. Les participants découvrent les détails des rues ordinaires à un rythme lent. » Cela justifie la réponse : L'attention au quotidien proche."},{"number":14,"points":15,"passage":"Une bibliothèque élargit ses horaires pendant les examens. Elle réserve cependant des espaces aux lecteurs qui ne préparent pas d'épreuve.\n\nLes étudiants disposent de davantage de tables pour réviser, mais le prêt, la lecture sur place et les visites habituelles continuent. Des panneaux distinguent les zones silencieuses des espaces où l'on peut discuter doucement. L'équipe observe les besoins à différents moments de la journée pour ajuster l'organisation. Elle souhaite répondre à l'affluence particulière de la période sans laisser penser que les autres usages doivent disparaître.","question":"Quel équilibre est recherché ?","options":["Supprimer les livres de loisir","Accueillir différents usages du lieu","Réserver tout le bâtiment aux candidats","Fermer pendant les examens"],"correct":"B","explanation":"Le passage indique : « Une bibliothèque élargit ses horaires pendant les examens. Elle réserve cependant des espaces aux lecteurs qui ne préparent pas d'épreuve. » Cela justifie la réponse : Accueillir différents usages du lieu."},{"number":15,"points":15,"passage":"Un centre de loisirs demande aux adolescents de proposer les activités. L'équipe vérifie ensuite les moyens nécessaires et les règles de sécurité.\n\nLes jeunes commencent par présenter ce qu'ils aimeraient découvrir et la manière dont ils souhaitent participer. Les animateurs les aident à estimer le budget, le temps de préparation et les besoins d'encadrement. Une proposition trop ambitieuse peut être adaptée plutôt que rejetée sans discussion. Le programme final indiquera ce qui a été retenu et les raisons des principaux choix. Cette étape doit permettre aux adolescents de voir les conséquences concrètes de leur contribution, tout en comprenant les responsabilités qui accompagnent l'organisation d'une activité collective.","question":"Quelle limite encadre la proposition ?","options":["Une réalisation automatique de chaque idée","Sa faisabilité dans le cadre du centre","L'absence de toute discussion","Le choix exclusif des adultes sans consultation"],"correct":"B","explanation":"Le passage indique : « Un centre de loisirs demande aux adolescents de proposer les activités. L'équipe vérifie ensuite les moyens nécessaires et les règles de sécurité. » Cela justifie la réponse : Sa faisabilité dans le cadre du centre."},{"number":16,"points":15,"passage":"Une entreprise expérimente une semaine de réunions plus courtes. Elle recueille ensuite les tâches reportées en dehors des réunions pour évaluer le résultat réel.\n\nCertains échanges supprimés de l'ordre du jour peuvent en effet réapparaître dans des messages individuels ou dans des discussions tardives. Les salariés notent ces déplacements pendant la période d'essai. L'équipe compare le temps total consacré à la coordination et la qualité des décisions obtenues. Elle cherche une organisation plus utile, sans considérer la seule durée inscrite au calendrier comme une preuve suffisante d'amélioration.","question":"Pourquoi regarder aussi ces tâches ?","options":["Éviter toute évaluation","Augmenter artificiellement le nombre de réunions","Mesurer uniquement la taille des salles","Vérifier si le travail a simplement été déplacé"],"correct":"D","explanation":"Le passage indique : « Une entreprise expérimente une semaine de réunions plus courtes. Elle recueille ensuite les tâches reportées en dehors des réunions pour évaluer le résultat réel. » Cela justifie la réponse : Vérifier si le travail a simplement été déplacé."},{"number":17,"points":15,"passage":"Des habitants partagent un agenda de quartier. Les événements annulés y restent visibles avec une mention claire, pour éviter les déplacements inutiles.\n\nUne couleur et une date de modification permettent de distinguer une annulation d'un événement encore confirmé. Les habitants peuvent consulter l'agenda sur leur téléphone ou sur un affichage à l'accueil du centre. L'équipe vérifie régulièrement les informations les plus proches, car une fiche oubliée peut rester visible longtemps. Le service vise à faciliter la participation en donnant des renseignements fiables, y compris lorsqu'une activité ne pourra finalement pas avoir lieu.","question":"Pourquoi conserver cette trace ?","options":["Encourager à venir malgré l'annulation","Remplacer les dates par des photos","Informer ceux qui avaient vu la première annonce","Masquer les changements"],"correct":"C","explanation":"Le passage indique : « Des habitants partagent un agenda de quartier. Les événements annulés y restent visibles avec une mention claire, pour éviter les déplacements inutiles. » Cela justifie la réponse : Informer ceux qui avaient vu la première annonce."},{"number":18,"points":15,"passage":"Un atelier de couture accueille les réparations courantes. Les animateurs conseillent aussi de renoncer lorsque le tissu est trop fragile pour supporter une nouvelle intervention.\n\nLes participants apportent leurs vêtements et expliquent l'usage qu'ils souhaitent en faire. L'équipe examine les coutures et la matière avant de proposer une technique. Une petite reprise peut suffire dans certains cas, tandis qu'une zone très usée risquerait de se déchirer juste à côté de la réparation. Les animateurs montrent comment reconnaître ces limites et envisager d'autres usages du tissu.","question":"Quelle compétence est également transmise ?","options":["Remplacer systématiquement chaque vêtement","Réparer tout objet sans exception","Éviter d'observer la matière","Reconnaître les limites d'une réparation"],"correct":"D","explanation":"Le passage indique : « Un atelier de couture accueille les réparations courantes. Les animateurs conseillent aussi de renoncer lorsque le tissu est trop fragile pour supporter une nouvelle intervention. » Cela justifie la réponse : Reconnaître les limites d'une réparation."},{"number":19,"points":15,"passage":"Une association propose des jeux coopératifs. Les participants cherchent une solution commune plutôt que l'élimination des autres.\n\nLes animateurs choisissent des règles où les informations et les ressources doivent être partagées. Certains groupes découvrent qu'une personne a organisé toutes les actions sans vraiment écouter les autres. La séance suivante peut alors modifier la répartition des rôles. Réussir ensemble ne signifie donc pas seulement atteindre un résultat, mais aussi apprendre comment chacun trouve sa place dans la recherche commune.","question":"Quel objectif organise le jeu ?","options":["Supprimer toute règle","Désigner un perdant obligatoire","Récompenser uniquement le plus rapide","Réussir ensemble"],"correct":"D","explanation":"Le passage indique : « Une association propose des jeux coopératifs. Les participants cherchent une solution commune plutôt que l'élimination des autres. » Cela justifie la réponse : Réussir ensemble."},{"number":20,"points":21,"passage":"Une enquête sur les loisirs distingue le temps libre apparent et le temps réellement disponible. Attendre un proche tout en restant responsable de son retour n'offre pas les mêmes possibilités qu'une période sans contrainte. Les chercheurs demandent ce que les personnes peuvent faire pendant ces périodes et si elles doivent pouvoir s'interrompre immédiatement. Une heure passée à attendre près d'un établissement ne permet pas toujours de rejoindre une activité éloignée. Le rapport distingue donc les durées sur le calendrier et les possibilités concrètes d'en disposer, pour éviter de présenter comme équivalentes des situations très différentes.","question":"Quelle distinction est faite ?","options":["Tout temps d'attente est totalement libre","Tous les loisirs demandent le même temps","Les responsabilités disparaissent hors du bureau","L'absence de travail visible ne signifie pas une liberté complète"],"correct":"D","explanation":"Le passage indique : « Une enquête sur les loisirs distingue le temps libre apparent et le temps réellement disponible. Attendre un proche tout en restant responsable de son retour n'offre pas les mêmes possibilités qu'une période sans contrainte. » Cela justifie la réponse : L'absence de travail visible ne signifie pas une liberté complète."},{"number":21,"points":21,"passage":"Un centre autorise les participants à assister à une séance avant de s'engager pour un trimestre. L'essai aide à apprécier l'ambiance autant que le contenu. La personne peut observer les échanges, essayer le matériel et poser des questions à l'animateur. Aucune décision immédiate n'est demandée à la sortie. Le centre présente également les horaires, les frais et les conditions d'absence afin que l'engagement soit bien compris. Les retours des visiteurs serviront à améliorer l'accueil.","question":"Quel aspect peut être évalué avant l'inscription ?","options":["La valeur de tous les équipements","Le programme de l'année suivante seulement","Le résultat garanti du trimestre","La manière de vivre l'activité dans le groupe"],"correct":"D","explanation":"Le passage indique : « Un centre autorise les participants à assister à une séance avant de s'engager pour un trimestre. L'essai aide à apprécier l'ambiance autant que le contenu. » Cela justifie la réponse : La manière de vivre l'activité dans le groupe."},{"number":22,"points":21,"passage":"Un quartier transforme une rue en espace de jeux quelques dimanches. Les aménagements restent démontables pour observer l'usage avant une décision plus durable. Les équipes relèvent les moments de forte présence et les difficultés signalées par les riverains. Elles observent aussi si des enfants de différents âges peuvent trouver leur place. Les barrières et les tables seront retirées après chaque journée. Le bilan permettra de discuter d'une éventuelle installation permanente avec davantage d'informations.","question":"Pourquoi choisir du matériel démontable ?","options":["Remplacer la rue chaque semaine","Garantir un projet définitif sans essai","Permettre une expérimentation réversible","Interdire toute participation"],"correct":"C","explanation":"Le passage indique : « Un quartier transforme une rue en espace de jeux quelques dimanches. Les aménagements restent démontables pour observer l'usage avant une décision plus durable. » Cela justifie la réponse : Permettre une expérimentation réversible."},{"number":23,"points":21,"passage":"Une équipe supprime les alertes non urgentes sur son outil commun. Les informations restent consultables, mais n'interrompent plus automatiquement chaque personne. Les messages nécessitant une réponse rapide gardent un canal identifié. Pour les autres, les membres consultent les nouvelles à des moments choisis dans la journée. Une période d'essai permettra de vérifier qu'aucune information importante n'est perdue. Les responsables souhaitent réduire les interruptions sans empêcher la coordination. Ils expliquent donc les nouvelles règles et les situations dans lesquelles une alerte reste nécessaire.","question":"Quel changement est recherché ?","options":["Mieux distinguer accès à l'information et interruption","Imposer une réaction immédiate à chacun","Rendre les informations confidentielles","Supprimer tous les messages"],"correct":"A","explanation":"Le passage indique : « Une équipe supprime les alertes non urgentes sur son outil commun. Les informations restent consultables, mais n'interrompent plus automatiquement chaque personne. » Cela justifie la réponse : Mieux distinguer accès à l'information et interruption."},{"number":24,"points":21,"passage":"Un lieu associatif ouvre des plages sans activité organisée. Les habitants peuvent s'y rencontrer sans devoir participer à un atelier. Des sièges, de l'eau et quelques documents sont disponibles, mais aucune production n'est attendue. Une personne de l'équipe accueille les nouveaux visiteurs et explique les règles du lieu. Certains viennent discuter quelques minutes, d'autres lisent ou attendent un voisin. Les responsables veulent conserver ces usages simples dans le programme, car toutes les rencontres ne commencent pas par une inscription à une activité précise.","question":"Quel besoin est reconnu ?","options":["La suppression des rencontres libres","Un accueil sans programme imposé","Une obligation permanente d'apprendre","Un accès réservé aux animateurs"],"correct":"B","explanation":"Le passage indique : « Un lieu associatif ouvre des plages sans activité organisée. Les habitants peuvent s'y rencontrer sans devoir participer à un atelier. » Cela justifie la réponse : Un accueil sans programme imposé."},{"number":25,"points":21,"passage":"Des bénévoles gèrent une collection de jeux. Ils notent les pièces manquantes avant le prêt, afin de distinguer un état ancien d'une perte récente. La fiche accompagne la boîte et peut être complétée au retour. Une pièce déjà absente est signalée clairement afin que le prochain emprunteur sache si le jeu reste utilisable. L'équipe peut ainsi rechercher une solution de remplacement sans attribuer automatiquement le problème au dernier utilisateur.","question":"À quoi sert ce suivi ?","options":["Supprimer les contrôles au retour","Garantir que rien ne sera jamais perdu","Éviter des responsabilités attribuées à tort","Fixer le nombre de joueurs"],"correct":"C","explanation":"Le passage indique : « Des bénévoles gèrent une collection de jeux. Ils notent les pièces manquantes avant le prêt, afin de distinguer un état ancien d'une perte récente. » Cela justifie la réponse : Éviter des responsabilités attribuées à tort."},{"number":26,"points":21,"passage":"Un magasin organise des ateliers de réparation gratuits. Il précise quels produits sont concernés et ne conditionne pas l'accès à un nouvel achat. Les participants peuvent vérifier leur modèle avant de se déplacer grâce à une liste disponible à l'accueil. Les animateurs précisent aussi les opérations qu'ils ne peuvent pas réaliser sur place. Le magasin espère faire connaître son service, mais les places ne sont pas réservées aux clients qui commandent un autre produit.","question":"Quelle règle évite une confusion commerciale ?","options":["Chaque participant doit s'abonner","Tous les produits seront remplacés gratuitement","L'atelier n'impose pas d'achat","La gratuité dépend d'une commande"],"correct":"C","explanation":"Le passage indique : « Un magasin organise des ateliers de réparation gratuits. Il précise quels produits sont concernés et ne conditionne pas l'accès à un nouvel achat. » Cela justifie la réponse : L'atelier n'impose pas d'achat."},{"number":27,"points":21,"passage":"Une commune consulte les usagers d'un parc en semaine et le week-end. Les profils présents diffèrent selon les horaires. Des retraités, des salariés et des familles ne fréquentent pas nécessairement les mêmes zones au même moment. Les enquêteurs varient donc les jours et les points de rencontre. Le projet d'aménagement s'appuiera sur ces observations et sur les contributions écrites, plutôt que sur un seul après-midi de consultation.","question":"Pourquoi varier les moments d'enquête ?","options":["Éviter les habitués du lieu","Obtenir des réponses identiques","Supprimer toute comparaison","Entendre des usages qui ne sont pas tous simultanés"],"correct":"D","explanation":"Le passage indique : « Une commune consulte les usagers d'un parc en semaine et le week-end. Les profils présents diffèrent selon les horaires. » Cela justifie la réponse : Entendre des usages qui ne sont pas tous simultanés."},{"number":28,"points":21,"passage":"Un club propose des sorties courtes proches des transports. Les nouveaux participants peuvent rejoindre facilement l'activité sans posséder de voiture. Le descriptif indique la distance à parcourir depuis l'arrêt et les horaires possibles pour le retour. Un contact est prévu en cas de changement. Le club souhaite ainsi que la facilité annoncée soit réelle pendant tout le trajet, pas seulement entre le point de départ de la marche et son arrivée.","question":"Quel obstacle est pris en compte ?","options":["Le prix des photographies","L'âge des arbres","La mobilité nécessaire pour participer","Le manque de matériel professionnel uniquement"],"correct":"C","explanation":"Le passage indique : « Un club propose des sorties courtes proches des transports. Les nouveaux participants peuvent rejoindre facilement l'activité sans posséder de voiture. » Cela justifie la réponse : La mobilité nécessaire pour participer."},{"number":29,"points":21,"passage":"Une bibliothèque d'objets prépare des fiches simples. Un prêt devient plus utile lorsque les personnes savent installer, utiliser et rapporter correctement l'équipement. Les bénévoles montrent les gestes essentiels lors de la première remise du matériel. Les fiches rappellent les vérifications et les situations où il faut demander de l'aide. Les emprunteurs peuvent signaler une consigne difficile à comprendre pour qu'elle soit reformulée.","question":"Quelle condition complète la mise à disposition ?","options":["Un accompagnement compréhensible de l'usage","Une absence de toute explication","Un matériel réservé aux experts","Une multiplication des règles cachées"],"correct":"A","explanation":"Le passage indique : « Une bibliothèque d'objets prépare des fiches simples. Un prêt devient plus utile lorsque les personnes savent installer, utiliser et rapporter correctement l'équipement. » Cela justifie la réponse : Un accompagnement compréhensible de l'usage."},{"number":30,"points":26,"passage":"Les loisirs sont parfois décrits comme un choix purement personnel. Les horaires, l'offre locale, le coût et les responsabilités familiales orientent pourtant les possibilités. Étudier les goûts sans regarder ces conditions risque de confondre préférence et adaptation à des contraintes. Une personne qui choisit une activité proche peut en apprécier le contenu tout en ayant renoncé à d'autres possibilités trop coûteuses ou éloignées. Les entretiens demandent donc aussi quelles propositions auraient intéressé les participants dans d'autres conditions.","question":"Quelle précaution d'analyse est proposée ?","options":["Supposer une liberté identique pour tous","Ignorer les coûts et les horaires","Déduire les goûts du seul âge","Relier les choix aux possibilités concrètes"],"correct":"D","explanation":"Le passage indique : « Les loisirs sont parfois décrits comme un choix purement personnel. Les horaires, l'offre locale, le coût et les responsabilités familiales orientent pourtant les possibilités. Étudier les goûts sans regarder ces conditions risque de confondre préférence et adaptation à des contraintes. » Cela justifie la réponse : Relier les choix aux possibilités concrètes."},{"number":31,"points":26,"passage":"Un service promet de faire gagner du temps. Il demande toutefois à l'utilisateur de saisir régulièrement des données et de corriger les erreurs. Le gain doit être évalué sur l'ensemble des tâches, pas seulement sur celle que le service accomplit automatiquement. L'évaluation note aussi le temps nécessaire pour apprendre le fonctionnement et vérifier les résultats. Une tâche réalisée en quelques secondes peut déplacer une partie du travail vers d'autres moments.","question":"Quelle comparaison est nécessaire ?","options":["Ignorer toutes les corrections","Regarder uniquement la vitesse annoncée","Compter aussi le travail demandé à l'utilisateur","Comparer seulement les logos"],"correct":"C","explanation":"Le passage indique : « Un service promet de faire gagner du temps. Il demande toutefois à l'utilisateur de saisir régulièrement des données et de corriger les erreurs. Le gain doit être évalué sur l'ensemble des tâches, pas seulement sur celle que le service accomplit automatiquement. » Cela justifie la réponse : Compter aussi le travail demandé à l'utilisateur."},{"number":32,"points":26,"passage":"Une place publique accueille des usages variés qui ne s'accordent pas spontanément : repos, jeux, passage et manifestations. Un aménagement réussi ne supprime pas forcément les différences ; il peut organiser leur coexistence par des espaces, des horaires et des règles discutées. Les habitants discutent des nuisances, des accès et des moments où certaines activités peuvent se dérouler. Il cherche à rendre les usages compatibles, sans supposer qu'un même espace répondra spontanément à toutes les attentes.","question":"Quelle approche de l'espace public est défendue ?","options":["Permettre plusieurs usages compatibles","Éviter toute règle commune","Choisir un seul public définitif","Rendre la place inaccessible"],"correct":"A","explanation":"Le passage indique : « Une place publique accueille des usages variés qui ne s'accordent pas spontanément : repos, jeux, passage et manifestations. Un aménagement réussi ne supprime pas forcément les différences ; il peut organiser leur coexistence par des espaces, des horaires et des règles discutées. » Cela justifie la réponse : Permettre plusieurs usages compatibles."},{"number":33,"points":26,"passage":"Un atelier valorise le fait de terminer un projet lentement. Les participants découvrent des gestes qu'une solution rapide aurait évités. La durée n'est pas automatiquement un défaut lorsqu'elle fait partie de ce que l'activité permet d'apprendre ou d'éprouver. Les animateurs laissent une place aux essais et aux reprises, sans fixer un objectif identique pour chaque séance. Les participants peuvent expliquer ce qu'ils ont découvert pendant le travail.","question":"Quelle valeur du temps est mise en avant ?","options":["Toute lenteur prouve une mauvaise méthode","L'activité doit toujours être raccourcie","Une durée peut contribuer à l'expérience","Apprendre exige d'éviter les gestes"],"correct":"C","explanation":"Le passage indique : « Un atelier valorise le fait de terminer un projet lentement. Les participants découvrent des gestes qu'une solution rapide aurait évités. La durée n'est pas automatiquement un défaut lorsqu'elle fait partie de ce que l'activité permet d'apprendre ou d'éprouver. » Cela justifie la réponse : Une durée peut contribuer à l'expérience."},{"number":34,"points":26,"passage":"Un agenda collectif rend visibles les activités d'un groupe, mais peut devenir envahissant si chaque créneau libre paraît disponible pour une nouvelle tâche. Les membres décident de protéger aussi des périodes sans rendez-vous. Une absence de rendez-vous peut correspondre à un besoin de repos ou à une réserve pour les imprévus. Le calendrier indique désormais les périodes qui doivent rester protégées.","question":"Quel risque veulent-ils éviter ?","options":["Remplacer le repos par des réunions","Transformer toute disponibilité apparente en obligation","Supprimer toutes les informations utiles","Rendre les tâches impossibles à prévoir"],"correct":"B","explanation":"Le passage indique : « Un agenda collectif rend visibles les activités d'un groupe, mais peut devenir envahissant si chaque créneau libre paraît disponible pour une nouvelle tâche. Les membres décident de protéger aussi des périodes sans rendez-vous. » Cela justifie la réponse : Transformer toute disponibilité apparente en obligation."},{"number":35,"points":26,"passage":"Une enquête mesure le nombre d'activités pratiquées. Des participants ayant peu d'activités déclarent pourtant y être très attachés. La richesse d'un loisir ne se confond pas toujours avec la diversité ou la fréquence mesurable des sorties. Les entretiens demandent ce que l'activité apporte : une relation, une découverte ou un moment attendu dans la semaine. Ces réponses complètent les données de fréquentation.","question":"Quelle nuance est apportée ?","options":["Les loisirs rares sont nécessairement inutiles","La diversité garantit la satisfaction","L'importance vécue dépasse parfois le nombre d'activités","Tous les participants souhaitent multiplier les sorties"],"correct":"C","explanation":"Le passage indique : « Une enquête mesure le nombre d'activités pratiquées. Des participants ayant peu d'activités déclarent pourtant y être très attachés. La richesse d'un loisir ne se confond pas toujours avec la diversité ou la fréquence mesurable des sorties. » Cela justifie la réponse : L'importance vécue dépasse parfois le nombre d'activités."},{"number":36,"points":33,"passage":"La multiplication des activités proposées peut donner l'impression d'un choix toujours plus large. Mais si toutes exigent réservation anticipée et présence régulière, les personnes aux horaires imprévisibles restent exclues. La diversité des contenus ne garantit pas une diversité des conditions de participation. Les responsables interrogent les personnes qui ont abandonné une inscription ou qui consultent les programmes sans jamais réserver. Certaines travaillent sur des créneaux changeants, d'autres ne peuvent pas prévoir longtemps à l'avance leurs possibilités de déplacement. Le centre teste donc des séances indépendantes, des places accessibles le jour même et des engagements plus courts. Ces formules seront évaluées avec les activités régulières, qui répondent à d'autres besoins. Il ne s'agit pas d'imposer un modèle unique, mais d'offrir plusieurs manières d'entrer dans les propositions et de rendre les contraintes visibles dès la présentation du programme.","question":"Quelle limite de l'offre est décrite ?","options":["Des règles d'accès semblables peuvent exclure malgré un programme varié","La variété des sujets supprime les contraintes horaires","Tous les participants disposent du même emploi du temps","Une inscription anticipée convient nécessairement à chacun"],"correct":"A","explanation":"Le passage indique : « La diversité des contenus ne garantit pas une diversité des conditions de participation. » Cela justifie la réponse : Des règles d'accès semblables peuvent exclure malgré un programme varié."},{"number":37,"points":33,"passage":"Un lieu de rencontre souhaite rester ouvert sans obligation d'achat. Pour durer, il doit néanmoins financer le local et l'accueil. Les organisateurs rendent ces coûts visibles et recherchent plusieurs soutiens. L'absence de paiement à l'entrée ne signifie pas l'absence de ressources nécessaires à l'existence du service. Le budget distingue le loyer, les charges, l'entretien et le temps des personnes qui assurent la présence sur place. Une partie peut être soutenue par la commune et une autre par des contributions volontaires ou des partenariats. Les décisions doivent toutefois préserver l'accueil des visiteurs qui ne peuvent pas donner. Les organisateurs publient donc des informations régulières sur les besoins et sur l'utilisation des aides reçues. Cette transparence permet de discuter des choix, notamment des horaires d'ouverture, sans faire peser silencieusement toute la continuité du lieu sur quelques bénévoles ou sur des dépenses personnelles invisibles.","question":"Quelle distinction est essentielle ?","options":["Local partagé et bâtiment sans entretien","Financement multiple et achat obligatoire","Gratuité pour l'usager et coût de fonctionnement","Accueil libre et absence de toute organisation"],"correct":"C","explanation":"Le passage indique : « L'absence de paiement à l'entrée ne signifie pas l'absence de ressources nécessaires à l'existence du service. » Cela justifie la réponse : Gratuité pour l'usager et coût de fonctionnement."},{"number":38,"points":33,"passage":"Une équipe mesure le temps gagné par un nouvel outil et souhaite remplir immédiatement les minutes libérées. Certains salariés proposent d'en conserver une partie pour traiter les imprévus. Un planning occupé en permanence devient fragile face à la moindre variation. Une marge non affectée peut contribuer au bon fonctionnement plutôt que représenter un temps perdu. Les salariés décrivent des demandes urgentes, des absences et des problèmes techniques impossibles à prévoir précisément. Lorsque toutes les heures sont attribuées, ces événements déplacent les tâches vers la fin de journée ou obligent à abandonner une priorité sans discussion. L'équipe teste donc une réserve et observe comment elle est utilisée. Les responsables regarderont les délais, la qualité du travail et la fatigue, plutôt que le seul taux d'occupation du calendrier.","question":"Quelle utilité est attribuée aux marges ?","options":["Absorber les variations et les imprévus","Garantir que rien ne changera","Prouver une absence de travail","Supprimer la nécessité de s'organiser"],"correct":"A","explanation":"Le passage indique : « Une marge non affectée peut contribuer au bon fonctionnement plutôt que représenter un temps perdu. » Cela justifie la réponse : Absorber les variations et les imprévus."},{"number":39,"points":33,"passage":"Un quartier lance une initiative temporaire qui rencontre un grand succès. Les habitants veulent la prolonger, mais les bénévoles n'ont pas prévu un engagement permanent. Le projet doit être réorganisé et financé autrement. Le succès d'une expérience ne garantit pas que les conditions qui l'ont rendue possible puissent durer sans transformation. Pendant l'essai, les organisateurs avaient utilisé du matériel prêté et consacré plusieurs week-ends exceptionnels à la préparation. Ces ressources ne seront pas disponibles chaque mois. Le groupe établit donc un budget, clarifie les responsabilités et recherche des relais avant d'annoncer un calendrier durable. Les habitants seront informés des changements nécessaires, y compris d'une éventuelle réduction de fréquence. Cette préparation ne retire rien à la valeur de l'expérience initiale : elle distingue ce qu'une mobilisation ponctuelle a permis de réaliser et ce qu'une organisation régulière devra pouvoir soutenir sans épuiser les personnes qui la font vivre.","question":"Quelle transition devient nécessaire ?","options":["Exiger la même disponibilité sans discussion","Passer d'un essai ponctuel à une organisation soutenable","Supprimer tout rôle aux participants","Considérer les ressources comme illimitées"],"correct":"B","explanation":"Le passage indique : « Le succès d'une expérience ne garantit pas que les conditions qui l'ont rendue possible puissent durer sans transformation. » Cela justifie la réponse : Passer d'un essai ponctuel à une organisation soutenable."}]}$paper$::jsonb);
